-- quest_extra.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[1578] = {id=1578,name="Supplying the Front",level=5,requiredLevel=5,faction="alliance",expansion=7,zoneID=38,mapID=48,description="The mountaineers of Loch Modan are fighting troggs, and having a busy time of it! They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs. That's why my colleague Thorvald is there, trying to keep the mountaineers in good gear. So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged. He might even share his knowledge with you. Thorvald is in Loch Modan's southern guard tower.",starts={{npcID=6031,x=0.49,y=0.424,mapID=87}},ends={{npcID=6030,x=0.236,y=0.744,mapID=48}},coords={x=0.49,y=0.424,source="quest_giver",mapID=48},questType="standard"},
[1582] = {id=1582,name="Moonglow Vest",level=0,requiredLevel=0,faction="alliance",expansion=7,zoneID=1657,mapID=89,description="We in Darnassus, especially we craftsman, are quite busy. Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies. If you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.",starts={{npcID=6034,x=0.604,y=0.37,mapID=89}},ends={{npcID=6034,x=0.604,y=0.37,mapID=89}},coords={x=0.604,y=0.37,source="quest_giver",mapID=89},questType="standard"},
[9897] = {id=9897,name="I'm Saved!",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=3518,mapID=107,description="I don't mind sharing. I'm just glad to be saved from that creep, Gankly! And I collected tons of skins from Zangarmarsh, so it's no problem at all!",starts={{npcID=18294,x=0.714,y=0.406,mapID=107}},ends={{npcID=18218,x=0.714,y=0.406,mapID=107}},coords={x=0.714,y=0.406,source="quest_giver",mapID=107},questType="standard"},
[9999] = {id=9999,name="Buying Time",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=3518,mapID=107,description="As long as the transporters stand, nothing we do to the forge camps will have any permanence. We must find a way to destroy the Legion structures. I need time to devise a plan of attack. If you can keep their engineers and tinkerers busy, it would greatly slow down their progress, buying me the time I need.",starts={{npcID=18417,x=0.274,y=0.43,mapID=107}},ends={{npcID=18417,x=0.274,y=0.43,mapID=107}},coords={x=0.274,y=0.43,source="quest_giver",mapID=107},questType="standard"},
[10004] = {id=10004,name="Patience and Understanding",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=3703,mapID=111,description="Take the blueprints and travel to Shattrath City in the Terokkar Forest. Once at Shattrath, go to the Lower City and look for a mo'arg by the name Sal'salabim . He'll probably be at the bar, drinking away his sorrows. By the way, you may need to convince him to lend his assistance. Try to approach him with patience and understanding. If that does not work, use your fists.",starts={{npcID=18417,x=0.274,y=0.43,mapID=107}},ends={{npcID=18584,x=0.772,y=0.348,mapID=111}},coords={x=0.274,y=0.43,source="quest_giver",mapID=111},questType="standard"},
[11650] = {id=11650,name="Just a Few More Things...",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=4273,description="As you may have noticed, we created the airstrip on the southern border of a magnataur den! The old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb! That's where you come in. I want you to get me everything on this shopping list. Please.",starts={{npcID=25477,x=0.582,y=0.184,mapID=114}},ends={{npcID=25477,x=0.582,y=0.184,mapID=114}},coords={x=0.582,y=0.184,source="quest_giver",zoneID=3537},questType="standard"},
[11679] = {id=11679,name="Reforging the Key",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=3537,description="Delays, delays... the one thing we cannot afford right now! As much as I hate to disturb Lord Surristrasz , he's our only hope of saving our beloved Evanor. Bring him the key fragments and hope that his mood is favorable. Hurry, , our assault team is waiting.",starts={{npcID=25262,x=0.452,y=0.334,zoneID=3537}},ends={{npcID=24795,x=0.452,y=0.344,zoneID=3537}},coords={x=0.452,y=0.334,source="quest_giver",zoneID=3537},questType="standard"},
[11797] = {id=11797,name="The Siege",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=3537,mapID=114,description="Well, well, well. It's good to see Arlos bring out the big guns. Don't get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us. I'm not sure how much longer we can hold out against these undead Nerubians. What do you say you get out there and kill me some creepers? Show these boys how it's done.",starts={{npcID=25816,x=0.564,y=0.696,mapID=114}},ends={{npcID=25816,x=0.564,y=0.696,mapID=114}},coords={x=0.564,y=0.696,source="quest_giver",mapID=114},questType="standard"},
[12047] = {id=12047,name="Something That Doesn't Melt",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=65,mapID=115,description="No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel. I know! I'm brilliant. Bone splinters. There are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.",starts={{npcID=26661,x=0.546,y=0.232,mapID=115}},ends={{npcID=26661,x=0.546,y=0.232,mapID=115}},coords={x=0.546,y=0.232,source="quest_giver",mapID=115},questType="standard"},
[12076] = {id=12076,name="Messy Business",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=65,mapID=115,description="Even at first glance, the sample you brought me shows obvious signs of some kind of corrosive spit. It would be a natural assumption that the same substance these worms use to burrow through the ground has allowed them a formidable weapon against the Ice Giants. Take this scraper and pick a fight with some of the worms. When they spit on you, use the scraper to remove it and bring it back to me. Get me a couple samples - I'm going to have to use it as the base for an elixir.",starts={{npcID=26659,x=0.594,y=0.18,mapID=115}},ends={{npcID=26659,x=0.594,y=0.18,mapID=115}},coords={x=0.594,y=0.18,source="quest_giver",mapID=115},questType="standard"},
[12151] = {id=12151,name="Wanton Warlord",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=65,mapID=115,description="There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this. Follow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge. When Grom'thar the Thunderbringer arrives, kill him and bring me his head.",starts={{npcID=26983,x=0.6,y=0.552,mapID=115}},ends={{npcID=26983,x=0.6,y=0.552,mapID=115}},coords={x=0.6,y=0.552,source="quest_giver",mapID=115},questType="standard"},
[12469] = {id=12469,name="Return to Sender",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=65,mapID=115,description="Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate. It appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner's fate.",starts={{npcID=26896,x=0.484,y=0.24,mapID=115}},ends={{npcID=26660,x=0.55,y=0.234,mapID=115}},coords={x=0.484,y=0.24,source="quest_giver",mapID=115},questType="standard"},
[12507] = {id=12507,name="Strange Mojo",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=66,mapID=121,description="This bottle of strange mojo may be the key to what is truly going on here. The Zandalari troll Hexxer Ubungo , back at The Argent Stand, may want to take a look at it.",ends={{npcID=28062,x=0.406,y=0.656,mapID=121}},questType="standard"},
[12524] = {id=12524,name="Venture Co. Misadventure",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=3711,mapID=119,description="Ever since we arrived, the Venture Company has hampered our efforts to secure our campsite and survey the area. Normally, we wouldn't care what they were up to, but they've started antagonizing our scouts and shooting down supply flights. We can't allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it shall. Go to Swindlegrin's Dig, on the far side of the crystal pillar to the northeast, and kill any Venture Company employee you see!",starts={{npcID=28032,x=0.272,y=0.598,mapID=119}},ends={{npcID=28032,x=0.272,y=0.598,mapID=119}},coords={x=0.272,y=0.598,source="quest_giver",mapID=119},questType="standard"},
[12597] = {id=12597,name="Something for the Pain",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=66,description="Gritty as my men are, they're still mortal. Wounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life. Thankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience. The salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.",starts={{npcID=28042,x=0.488,y=0.788,zoneID=66}},ends={{npcID=28042,x=0.488,y=0.788,zoneID=66}},coords={x=0.488,y=0.788,source="quest_giver",zoneID=66},questType="standard"},
[12712] = {id=12712,name="The Key of Warlord Zol'Maz",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=66,mapID=121,description=", we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter. The Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast. The warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.",starts={{npcID=28401,x=0.636,y=0.702,mapID=121}},ends={{npcID=28401,x=0.636,y=0.702,mapID=121}},coords={x=0.636,y=0.702,source="quest_giver",mapID=121},questType="standard"},
[12713] = {id=12713,name="Betrayal",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=66,mapID=121,description="The time has come to end this charade, . As valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed. We've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him. Fight well.",starts={{npcID=28518,x=0.14,y=0.738,mapID=121}},ends={{npcID=28518,x=0.14,y=0.738,mapID=121}},coords={x=0.14,y=0.738,source="quest_giver",mapID=121},questType="standard"},
[12819] = {id=12819,name="Just Around the Corner",level=25,requiredLevel=25,faction="both",expansion=7,zoneID=67,mapID=120,description="Blast it! Where are my tools? I had them here just a moment ago. Oh! I probably forgot them when I was setting up that minefield in the west. That's mildly inconvenient. I'd be quite appreciative if you could go get them for me. You'll need to watch your step though... you should be able to use the same path that I did to get out. Oh, and don't try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren't very discerning in who they target.",starts={{npcID=29431,x=0.41,y=0.864,mapID=120}},ends={{npcID=29431,x=0.41,y=0.864,mapID=120}},coords={x=0.41,y=0.864,source="quest_giver",mapID=120},questType="standard"},
[12890] = {id=12890,name="If Size Mattered...",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=67,mapID=120,questType="standard"},
[12980] = {id=12980,name="The Armor's Secrets",level=25,requiredLevel=25,faction="both",expansion=7,zoneID=67,mapID=120,description="The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes. He's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal. To the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.",starts={{npcID=30152,x=0.312,y=0.38,mapID=120}},ends={{npcID=30152,x=0.312,y=0.38,mapID=120}},coords={x=0.312,y=0.38,source="quest_giver",mapID=120},questType="standard"},
[13011] = {id=13011,name="Culling Jorcuttar",level=25,requiredLevel=25,faction="both",expansion=7,zoneID=67,mapID=120,description="The jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire. They have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region. She cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.",starts={{npcID=30105,x=0.654,y=0.602,mapID=120}},ends={{npcID=30105,x=0.654,y=0.602,mapID=120}},coords={x=0.654,y=0.602,source="quest_giver",mapID=120},questType="standard"},
[13058] = {id=13058,name="Changing the Wind's Course",level=25,requiredLevel=25,faction="horde",expansion=7,zoneID=67,mapID=120,description="At last, we have all that we need to right the wrongs of the North Wind and its followers. You have attuned the Lorehammer to Stormhoof's time and his persona. Take the hammer again, head to the Temple of Life in the plains to the northwest. Use the hammer to assume the role of Stormhoof. Face the North Wind as Stormhoof, but realize that for the timeline to be restored, Stormhoof must die as the North Wind weakens. Then, you must find and use the Horn of Elemental Fury to destroy the North Wind.",starts={{npcID=30381,x=0.656,y=0.514,mapID=120}},ends={{npcID=30381,x=0.656,y=0.514,mapID=120}},coords={x=0.656,y=0.514,source="quest_giver",mapID=120},questType="standard"},
[13270] = {id=13270,name="Cloth Scavenging",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=3537,mapID=114,starts={{npcID=26969,x=0.416,y=0.534,mapID=114}},ends={{npcID=26969,x=0.416,y=0.534,mapID=114}},coords={x=0.416,y=0.534,source="quest_giver",mapID=114},questType="standard"},
[13272] = {id=13272,name="Cloth Scavenging",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=4395,mapID=125,questType="standard"},
[13528] = {id=13528,name="Buzzbox 723",level=5,requiredLevel=5,faction="alliance",expansion=7,zoneID=148,mapID=62,description="There are a couple other forms of wildlife that we've verified infected. It's actually good news that the crabs appear to have caught this from the bears - hopefully that means this all stems from one source. We need to focus our attention on those bears now. Buzzbox 723 is near the waterfalls to the east. It's going to be messy work, but it's necessary - I'll need you to bring some fresh bear guts to that buzzbox for analysis. We'll go from there once I have the information.",starts={{npcID=32977,x=0.512,y=0.196,mapID=62}},ends={{npcID=194122,x=0.542,y=0.293,mapID=62}},coords={x=0.512,y=0.196,source="quest_giver",mapID=62},questType="standard"},
[13566] = {id=13566,name="Ritual Materials",level=5,requiredLevel=5,faction="alliance",expansion=7,zoneID=148,mapID=62,description="While we tend to Grimclaw, I would like you to peacefully gather some ritual materials for me from the nearby wildlife. I need whiskers from the moonstalkers to the west- pluck them from the sleeping ones and move away quickly. I need hair from the doe to the east, just avoid the stags. Finally, I need fur from the bears along the water to the northeast. Wait until they catch a fish, then get the sample quickly and get away before they finish eating. Please do not harm any of them.",starts={{npcID=33048,x=0.43,y=0.39,mapID=62}},ends={{npcID=33048,x=0.43,y=0.39,mapID=62}},coords={x=0.43,y=0.39,source="quest_giver",mapID=62},questType="standard"},
[13871] = {id=13871,name="Security!",level=7,requiredLevel=7,faction="horde",expansion=7,zoneID=331,mapID=63,description="It's not as like I haven't got enough to think about here! Keeping this place operational is hard enough without constant elf and draenei harassment. Now, on top of everything, there's an assassin lurking around the camp who's killed an important diplomat... on my watch! Whoever it is couldn't have gotten far, . Scour the camp until you find her and then avenge the diplomat! At least I can bring the assassin's head with me when I have to answer to Hellscream.",starts={{npcID=17304,x=0.908,y=0.582,mapID=63}},ends={{npcID=17304,x=0.908,y=0.582,mapID=63}},coords={x=0.908,y=0.582,source="quest_giver",mapID=63},questType="standard"},
[25552] = {id=25552,name="Brood of Evil",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=616,mapID=198,description="This egg you recovered is an alarming sign, . The Twilight dragons are usually raised from stolen eggs from other dragonflights, which are then modified through dark magic. This \"natural\" egg is evidence that one of their matriarchs has become a viable broodmother. We must destroy her before her brood spreads. Go to the Ascendant's Rise where they claim these aberrations are kept and slay one of the juvenile drakes. We will use its skull to lure out its mother.",starts={{npcID=40816,x=0.722,y=0.738,mapID=198}},ends={{npcID=40816,x=0.722,y=0.738,mapID=198}},coords={x=0.722,y=0.738,source="quest_giver",mapID=198},questType="standard"},
[26415] = {id=26415,name="Questflag for Captain's Log",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=5042,mapID=207,questType="standard"},
[26453] = {id=26453,name="A Helping Hand",level=7,requiredLevel=7,faction="alliance",expansion=7,zoneID=331,mapID=63,description="Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale . The task of building won't be easy, , for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested his way. Speak to me again and I will arrange for fast transport for you to their location.",starts={{npcID=17106,x=0.35,y=0.498,mapID=63}},ends={{npcID=17291,x=0.868,y=0.448,mapID=63}},coords={x=0.35,y=0.498,source="quest_giver",mapID=63},questType="standard"},
[26630] = {id=26630,name="Looks Like a Tauren Pirate to Me",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=5287,description="Firallon wants MY head? Now that's interesting. But it's nothing we can't work around. This Yancey character probably doesn't know my face too well. Most non-tauren find us tauren indistinguishable from one another. In fact... most non-tauren find us indistinguishable from... a certain four-legged farm creature. Rikqiz the leatherworker keeps one of these creatures here in Booty Bay, and Narkk is my chief supplier for pirate hats. Get a replacement head and a hat, then return with both.",starts={{npcID=2487,x=0.41,y=0.732,zoneID=5287}},ends={{npcID=2487,x=0.41,y=0.732,zoneID=5287}},coords={x=0.41,y=0.732,source="quest_giver",zoneID=5287},questType="standard"},
[26710] = {id=26710,name="Lost In The Deeps",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,mapID=207,description="Pebble has gotten himself lost again, somewhere deep in the Crumbling Depths. He's fortunate that his size makes him unworthy of the effort for those gyreworms, but it's only a matter of time before he stumbles too close to one and gets eaten. Whatever he's so intent on down there is certainly not worth it. He seems to like you. Please, go and find him and bring him out of those tunnels to safer playing grounds.",starts={{npcID=44945,x=0.554,y=0.14,mapID=207}},ends={{npcID=44945,x=0.554,y=0.14,mapID=207}},coords={x=0.554,y=0.14,source="quest_giver",mapID=207},questType="standard"},
[26755] = {id=26755,name="Keep Them off the Front",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,mapID=207,description="Oh good, you brought another catapult with you! Clay might be older than dirt, but he makes a mean war machine. Well, you didn't bring it all the way out here for your health, flesh bag. Get in one of those things and bombard the fungal terrors and reinforcements streaming out of Needlerock Slag. We have to keep them off the front!",starts={{npcID=43897,x=0.226,y=0.52,mapID=207}},ends={{npcID=43897,x=0.226,y=0.52,mapID=207}},coords={x=0.226,y=0.52,source="quest_giver",mapID=207},questType="standard"},
[26771] = {id=26771,name="Testing the Trap",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,mapID=207,description="You must set the trap for the matriarch now. Go to the western end of the Alabaster Shelf and place the trapped basilisk meat in the center of the feeding grounds.",starts={{npcID=44010,x=0.644,y=0.822,mapID=207}},ends={{npcID=44010,x=0.644,y=0.822,mapID=207}},coords={x=0.644,y=0.822,source="quest_giver",mapID=207},questType="standard"},
[26871] = {id=26871,name="A Rock Amongst Many",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,description="You've done as I've asked. Turn back and escape the cave in one piece. Don't forget the gemstone.",starts={{npcID=204959,x=0.664,y=0.206,zoneID=5042}},ends={{npcID=42467,x=0.564,y=0.426,zoneID=5042}},coords={x=0.664,y=0.206,source="quest_giver",zoneID=5042},questType="standard"},
[26876] = {id=26876,name="The World Pillar Fragment",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,description="It is time, . We have spotted Abyssion making his way to the lair. The Twilight's Hammer might've thought the fragment would be safe if a dragon guarded it, but I've met enough dragons to know their one weakness. Pride. Abyssion's not going to run from a fight with us puny mortals. Place the banner of the Earthen Ring in the middle of his lair. Once we defeat him, bring the fragment to Maruut. We need to repair the World Pillar as soon as possible.",starts={{npcID=44010,x=0.644,y=0.822,zoneID=5042}},ends={{npcID=43065,x=0.496,y=0.53,zoneID=5042}},coords={x=0.644,y=0.822,source="quest_giver",zoneID=5042},questType="standard"},
[27742] = {id=27742,name="A Little on the Side",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5892,description="You know, it's our moral obligation to save all of this Elementium from the shale spiders. Those creepy things eat the stuff! What a waste! So, what do you say? 90/10 my way?",questType="standard"},
[27787] = {id=27787,name="Skullcrusher the Mountain",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=4922,mapID=241,description="It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off. Survive and slay Skullcrusher the Mountain !",starts={{npcID=46717,x=0.452,y=0.878,mapID=241}},ends={{npcID=45668,x=0.434,y=0.574,mapID=241}},coords={x=0.452,y=0.878,source="quest_giver",mapID=241},questType="standard"},
[28162] = {id=28162,name="Swamp Bait",level=35,requiredLevel=35,faction="alliance",expansion=7,zoneID=5389,description="Supplies are never easy to find in a place like this, . We have been scouting since we captured the island but things are not looking good. Fortunately, we just received a scouting report that a swamp full of crocs is just west of our base camp here. The hides off those crocs will come in handy for our leatherworkers. Bring back as many as you can.",starts={{npcID=48066,x=0.508,y=0.496,zoneID=5095}},ends={{npcID=48066,x=0.508,y=0.496,zoneID=5095},{npcID=52015,x=0.748,y=0.602,zoneID=5389}},coords={x=0.508,y=0.496,source="quest_giver",zoneID=5095},questType="standard"},
[28658] = {id=28658,name="Swamp Bait",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=5389,description="Supplies are never easy to find in a place like this, . We have been scouting since we captured the island but things are not looking good. Fortunately, we just received a scouting report that a swamp full of crocs is just west of our base camp here. The hides off those crocs will come in handy for our leatherworkers. Bring back as many as you can.",starts={{npcID=48069,x=0.508,y=0.496,zoneID=5095}},ends={{npcID=48069,x=0.508,y=0.496,zoneID=5095},{npcID=52016,x=0.548,y=0.812,zoneID=5389}},coords={x=0.508,y=0.496,source="quest_giver",zoneID=5095},questType="standard"},
[28661] = {id=28661,name="The Imprisoned Archmage",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=5389,description="We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad . It seems that everytime we get close, that archmage shows up and pushes us back. Now that we have claimed the island, it's time we take another shot. Head down there and bring me back his staff as proof that you have finished the job.",starts={{npcID=48071,x=0.514,y=0.496,zoneID=5095}},ends={{npcID=48071,x=0.514,y=0.496,zoneID=5095},{npcID=52016,x=0.548,y=0.812,zoneID=5389}},coords={x=0.514,y=0.496,source="quest_giver",zoneID=5095},questType="standard"},
[28664] = {id=28664,name="Svarnos",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=5389,description="Excellent work on the island capture, . Now that we have claimed the island, we need to make these cellblocks useable for prisoners. D-Block has been especially hard to clear out. Unfortunately it has become overrun with demons of all sorts. We have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there. I need you to kill him and bring back his collar.",starts={{npcID=48070,x=0.514,y=0.496,zoneID=5095}},ends={{npcID=48070,x=0.514,y=0.496,zoneID=5095},{npcID=52016,x=0.548,y=0.812,zoneID=5389}},coords={x=0.514,y=0.496,source="quest_giver",zoneID=5095},questType="standard"},
[28665] = {id=28665,name="Cursed Shackles",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=5389,description="Have you been down in the D-Block yet, ? Every time we clear that infested cellblock out, the demons seem to return rather quickly. We learned that they regenerate from the cursed shackles scattered around the area. That's where you come in to the picture . I need you to retrieve as many of those shackles as you can and bring them back to me. We will destroy them immediately.",starts={{npcID=48070,x=0.514,y=0.496,zoneID=5095}},ends={{npcID=48070,x=0.514,y=0.496,zoneID=5095},{npcID=52016,x=0.548,y=0.812,zoneID=5389}},coords={x=0.514,y=0.496,source="quest_giver",zoneID=5095},questType="standard"},
[28669] = {id=28669,name="The Warden",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=5389,description="We have almost finished clearing out the revolting prisoners in the hole, but one last problem remains. The warden. Warden Silva is their master and they will do anything for him. If we take him out, we take them all out. Finish him off and bring me back his keys. We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.",starts={{npcID=48062,x=0.514,y=0.496,zoneID=5095}},ends={{npcID=48062,x=0.514,y=0.496,zoneID=5095},{npcID=52016,x=0.548,y=0.812,zoneID=5389}},coords={x=0.514,y=0.496,source="quest_giver",zoneID=5095},questType="standard"},
[28670] = {id=28670,name="Food From Below",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=5389,description="Supplies are running low here in camp, . We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use. We need you to gather as many of those as you can and bring them back to camp. One more thing, the entire cellblock is overrun with prisoners so be careful.",starts={{npcID=48062,x=0.514,y=0.496,zoneID=5095}},ends={{npcID=48062,x=0.514,y=0.496,zoneID=5095},{npcID=52016,x=0.548,y=0.812,zoneID=5389}},coords={x=0.514,y=0.496,source="quest_giver",zoneID=5095},questType="standard"},
[28712] = {id=28712,name="Enter the Dragon Queen",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=4922,mapID=241,description="Hello, . I wish we could meet in more favorable circumstances. The world hangs by a thread, and all that the Titans have wrought may be in jeopardy. It saddens me greatly, but my judgment is final. Deathwing - the horrific creature that was once the Earth Warder and once my friend - must be destroyed. I have prepared a site atop the Highlands, to the west of the Vermillion Redoubt, where I can bring about his end. Seek out the Circle of Life and speak with Lirastrasza within. I will join you there.",starts={{npcID=47603,x=0.218,y=0.57,mapID=241}},ends={{npcID=49417,x=0.148,y=0.162,mapID=241}},coords={x=0.218,y=0.57,source="quest_giver",mapID=241},questType="standard"},
[28732] = {id=28732,name="This Can Only Mean One Thing...",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=25,description="Raz and I were enlisted by the Guardians of Hyjal to investigate the re-emergence of Ragnaros into our world. Let me go ahead and confirm that he is back and he is angry! We also have evidence that these Twilight's Hammer cultists are moving elementals from here to Blackrock Caverns , over in the Eastern Kingdoms. Raz and I were about to head over there to investigate. We've got room for another in the mole machine if you're interested. Just meet us on the inside and we'll begin our journey.",starts={{npcID=49444,x=0.426,y=0.28,mapID=198}},coords={x=0.426,y=0.28,source="quest_giver",zoneID=616},questType="standard"},
[28755] = {id=28755,name="Annals of the Silver Hand",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=139,description="Do you know who the Knights of the Silver Hand were? They were the original paladins of the Light, and from their ranks came knights who would later join the Argent Dawn or the Scarlet Crusade. Though many have gone astray, they still possess valuable relics of the Silver Hand. Deep in Stratholme , under the watchful eye of Instructor Galford, volumes of the Annals of the Silver Hand survive. Any volumes you could recover would be a fitting addition to the rededicated Light's Hope Chapel.",starts={{npcID=49856,x=0.76,y=0.51,zoneID=139}},ends={{npcID=49856,x=0.76,y=0.51,zoneID=139}},coords={x=0.76,y=0.51,source="quest_giver",zoneID=139},questType="dungeon"},
[28869] = {id=28869,name="Pebble",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,mapID=207,description="If you hadn't noticed, there's a very small elemental that has taken a liking to you. If you stay on the ground for even a few moments, I'm sure you'll spot him. You seem to be quite adept at making friends down here. A good talent to have.",questType="standard"},
[28876] = {id=28876,name="To the Mor'shan Rampart",level=7,requiredLevel=7,faction="horde",expansion=7,zoneID=17,mapID=10,description="Kadrak at the Mor'shan Rampart to the north is calling for aid. The rampart rests on the border between the Northern Barrens and Ashenvale . It is the front line in the fight against the Alliance. We're driving the night elves out of the forest. We'll claim its resources for the Horde! To get there, take the Gold Road north out of the Crossroads. Destiny calls!",starts={{npcID=3429,x=0.486,y=0.596,mapID=10}},ends={{npcID=8582,x=0.426,y=0.15,mapID=10}},coords={x=0.486,y=0.596,source="quest_giver",mapID=10},questType="standard"},
[29123] = {id=29123,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",starts={{npcID=52669,x=0.272,y=0.624,mapID=198}},ends={{npcID=52669,x=0.272,y=0.624,mapID=198}},coords={x=0.272,y=0.624,source="quest_giver",mapID=198},questType="standard"},
[29127] = {id=29127,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",starts={{npcID=52669,x=0.272,y=0.624,mapID=198}},ends={{npcID=52669,x=0.272,y=0.624,mapID=198}},coords={x=0.272,y=0.624,source="quest_giver",mapID=198},questType="standard"},
[29149] = {id=29149,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",starts={{npcID=52669,x=0.272,y=0.624,mapID=198}},ends={{npcID=52669,x=0.272,y=0.624,mapID=198}},coords={x=0.272,y=0.624,source="quest_giver",mapID=198},questType="standard"},
[29163] = {id=29163,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",starts={{npcID=52669,x=0.272,y=0.624,mapID=198}},ends={{npcID=52669,x=0.272,y=0.624,mapID=198}},coords={x=0.272,y=0.624,source="quest_giver",mapID=198},questType="standard"},
[29255] = {id=29255,name="Embergris",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=5733,description="The Crimson Lasher has developed some cracking blisters on its vines. Without treatment, this condition could be life threatening. Luckily, the Charred Soldiers and Charred Vanquishers in the area produce a waxy substance known as Embergris , which should soothe the Lasher's pain. Bring me some of this substance, and kill those nasty fire elementals while you're at it.",starts={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},ends={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},coords={x=0.506,y=0.87,source="quest_giver",zoneID=5733},questType="standard"},
[29257] = {id=29257,name="Steal Magmolias",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=5733,description="We've discovered a new species of flower growing in the Magma Springs to the north. Amazingly, they sustain themselves in pure molten lava! Please go and retrieve some specimens for me. I'm sure that further study of these plants will shed some light on your little friend here. Speaking of which, he seems quite eager to go with you. Let's hope he behaves himself.",starts={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},ends={{npcID=52489,x=0.506,y=0.87,zoneID=5733}},coords={x=0.506,y=0.87,source="quest_giver",zoneID=5733},questType="standard"},
[29265] = {id=29265,name="Fire Flowers",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=5733,description="My fellow druid, Choluna , has asked us to collect any specimens of plant life that we might find here in the Firelands... ...I don't know whose idea it was to bring scholars to a warfront. Nevertheless, you will already be in the cave - killing things - so be on the lookout for anything growing out of the ground.",starts={{npcID=52444,x=0.424,y=0.598,zoneID=5733}},ends={{npcID=52467,x=0.486,y=0.86,zoneID=5733},{npcID=52492,x=0.36,y=0.566,zoneID=5733}},coords={x=0.424,y=0.598,source="quest_giver",zoneID=5733},questType="standard"},
[29270] = {id=29270,name="Time Grows Short",level=35,requiredLevel=35,faction="both",expansion=7,zoneID=3537,mapID=114,description="Tarecgosa is bound to you, , but only temporarily. An aspect's power is required to permanently seal her essence. Malygos's successor will not be chosen until Azeroth's moons next eclipse, and the bond you share will not last until then. Fortunately, there is a way to buy us the time we need. Powerful elements exist that can extend the ritual's effects. Some of these can be found in the Plane of Fire, with which you've become familiar. Obtain them, , and sustain Tarecgosa until the eclipse.",starts={{npcID=53210,x=0.31,y=0.24,mapID=114}},ends={{npcID=53215,x=0.23,y=0.308,mapID=114}},coords={x=0.31,y=0.24,source="quest_giver",mapID=114},questType="raid"},
[29281] = {id=29281,name="Additional Armaments",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=616,mapID=198,description="These druids be lackin' the tools ta properly handle the job out 'ere. I got meself a buddy back at day ol' stag shrine through the portal though. If we were ta be gettin' reunited, we'd sure have some real toys ta use against ol' Ragboy and 'is cronies. Take some of dem mark things an' go find Matoclaw . Ask her fer Ricket. We need'r here so we can be causin' some real trouble.",starts={{npcID=53214,x=0.47,y=0.9,mapID=198}},ends={{npcID=52669,x=0.272,y=0.624,mapID=198}},coords={x=0.47,y=0.9,source="quest_giver",mapID=198},questType="standard"},
[46700] = {id=46700,name="Armor of the Ancients",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="It is not just the hammers and my careful research that we need, . We also need a lot of the very highest quality of ancient metal to make the final hammer. Enemies across Broken Shore that are able to wear armor often collect bits of Ancient Demonsteel here and there. Collect enough of it in your battles for our purposes.",starts={{npcID=120221,x=0.412,y=0.594,zoneID=7543}},ends={{npcID=120221,x=0.412,y=0.594,zoneID=7543}},coords={x=0.412,y=0.594,source="quest_giver",zoneID=7543},questType="standard"},
[46701] = {id=46701,name="Hammer of Forgotten Heroes",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description=", this is exciting, I have to admit. I've put everything you've gathered into this chest of supplies and the only place with the power and magic to handle the creation of the final hammer is the Firmament Stone. I believe that blacksmiths of your rarified skills will know it? I realize that there are dwarf stereotypes out there about smithing but I really don't care for all of the banging and heat. Suppose that is why I followed the scholarly path. Good luck to you!",starts={{npcID=120221,x=0.412,y=0.594,zoneID=7543}},ends={{npcID=120221,x=0.412,y=0.594,zoneID=7543}},coords={x=0.412,y=0.594,source="quest_giver",zoneID=7543},questType="standard"},
[46705] = {id=46705,name="Retaliation",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7637,description="Of course I will help you! Although to be honest, I am not certain where a new arcane shield generator can be found these days. So many of our craftspeople have been executed... I will think on it. Would you mind helping me as well? I have been observing a nearby group of Felborne for some time. Their activities have become increasingly brazen of late. I think it's time to teach them how it feels to be violently suppressed.",starts={{npcID=121357,x=0.558,y=0.42,zoneID=7637}},ends={{npcID=121358,x=0.546,y=0.392,zoneID=7637}},coords={x=0.558,y=0.42,source="quest_giver",zoneID=7637},questType="standard"},
[46719] = {id=46719,name="Amal'thazad's Message",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Deathlord, Amal'thazad has requested your presence at Acherus. He has been in contact with the Lich King, and making improvements on the citadel. For his benefit, or yours, I know not.",questType="standard"},
[46720] = {id=46720,name="Frozen Memories",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8672,description="Close your eyes, Deathlord. Can't you feel his presence already? Stand in the rune circle atop Acherus, Deathlord. I will show you what I have seen.",questType="standard"},
[46722] = {id=46722,name="Nothing Up My Sleeve",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7879,description="Now, you may think that a sack of gold would be a good reward for your troubles, but I've got something better in mind for you. I'm gonna teach you my best trick! I know, I know, I'm a very generous goblin. Let me show you how it's done!",questType="standard"},
[46723] = {id=46723,name="Down the Rabbit Hole",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7879,description="Alright, bub. I'm gonna need you to go in there and find out what's going wrong. I'd go in myself, but... well, it's complicated. Anyway, we got no time to lose! Just jump in the hat and find out what's goin on. I'll be ready to pull you out once you've got everything handled.",questType="standard"},
[46724] = {id=46724,name="Champion: The Great Akazamzarak",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7879,description="You know, you're a useful to have around, . Tell ya what, I think I'll accompany you on your adventures. Seems to be good gold in it, and I think it'll be a good way to scout out some new business opportunities around the Broken Isles. What do you say?",questType="standard"},
[46725] = {id=46725,name="Power Outage",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Kor'vass asked for a bunch of other stuff, but it won't hurt her to learn a bit of patience. Don't you agree? She did mentioned that the ship'ss weaponss array is severely damaged and dangerously low on power. Knowing her, I'm sure that'ss an exaggeration. I suppose you may as well take this power core I confiscated. You can replenish it from those disgusting Legion geyserss and energy globess floating around the Tomb.",starts={{npcID=117709,x=0.52,y=0.212,zoneID=7543}},ends={{npcID=117709,x=0.52,y=0.212,zoneID=7543}},coords={x=0.52,y=0.212,source="quest_giver",zoneID=7543},questType="standard"},
[46727] = {id=46727,name="Battle for Azeroth: Tides of War",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1657,description="Champion! An urgent War Council is underway. Your presence is requested in Stormwind Keep.",starts={{npcID=49748,x=0.628,y=0.718,zoneID=1519},{npcID=142930,x=0.276,y=0.214,zoneID=1519},{npcID=49748,x=0.264,y=0.7,zoneID=1537},{npcID=49748,x=0.452,y=0.504,zoneID=1657}},ends={{npcID=120756,x=0.85,y=0.324,zoneID=1519}},coords={x=0.628,y=0.718,source="quest_giver",zoneID=1519},questType="standard"},
[46728] = {id=46728,name="The Nation of Kul Tiras",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore. Many have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father. Perhaps she feels the time has come to atone for this. Loath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance. Good luck.",starts={{npcID=120756,x=0.85,y=0.324,zoneID=1519},{npcID=165395,x=0.858,y=0.316,zoneID=1519}},ends={{npcID=120922,x=0.656,y=0.506,zoneID=8568}},coords={x=0.85,y=0.324,source="quest_giver",zoneID=1519},questType="standard"},
[46729] = {id=46729,name="The Old Knight",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="These days Cyrus is the Harbormaster, but he used to be one of Daelin Proudmoore's most trusted knights! I lost my mother when the Scourge hit Lordaeron. My father sent me here to be raised away from the war. I don't know much about him... just that he was a Stormwind knight who gave his life fighting the Lich King. Daelin hand-picked Cyrus to raise me and forced him to take a desk job. It's the only reason he wasn't at Theramore. He's probably checking in that other Alliance ship. Let's go!",ends={{npcID=121235,x=0.68,y=0.22,zoneID=8568}},questType="standard"},
[46730] = {id=46730,name="Armies of Legionfall",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,description="Thanks to your leadership, the order has grown even mightier than I had dared hope. Alongside champions of the other orders, we now have a fighting force capable of driving the Burning Legion from our world. It's time to end this invasion! Using the Pillars of Creation, we will dissipate the Felstorm and seal the Tomb of Sargeras.",questType="standard"},
[46732] = {id=46732,name="The Prophet's Gambit",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="I can feel their presence just ahead. It is as faint as the lightest breeze that once rolled across these hills, but it is not of the Legion, of that I am certain. We must see if these broken are potential allies. It is a great risk, but our numbers are too few to ignore the chance.",starts={{npcID=121345,x=0.598,y=0.692,zoneID=8574}},ends={{npcID=121345,x=0.598,y=0.692,zoneID=8574}},coords={x=0.598,y=0.692,source="quest_giver",zoneID=8574},questType="standard"},
[46734] = {id=46734,name="Assault on Broken Shore",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="It has been a long and costly war, . It is time we put an end to it. We will drive the Burning Legion from their seat of power and close their gateway into Azeroth. Our first step is to gain a foothold on the Broken Shore. Divided, the Alliance and Horde faced defeat. But united as the Armies of Legionfall, we will claim victory!",ends={{npcID=116302,x=0.446,y=0.632,zoneID=7543}},questType="standard"},
[46735] = {id=46735,name="Contribute to Command Center",level=45,requiredLevel=45,faction="none",expansion=7,questType="standard"},
[46736] = {id=46736,name="Contribute to Nether Disruptor",level=45,requiredLevel=45,faction="none",expansion=7,questType="standard"},
[46743] = {id=46743,name="Supplies From Highmountain",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7731,description="Champion, your help to our people has far exceeded any of our expectations, and has provided us some much needed breathing space. Please, take these supplies to aid you in the war against the Legion. With your continued aid, we should be able to gather more and prepare them for you.",ends={{npcID=106902,x=0.382,y=0.458,zoneID=7731}},questType="standard"},
[46745] = {id=46745,name="Supplies From the Court",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7334,description="Prince Farondis has asked me to thank you for your continued efforts to aid our lands. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",ends={{npcID=107376,x=0.468,y=0.414,zoneID=7334}},questType="standard"},
[46746] = {id=46746,name="Supplies From the Valarjar",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7541,description="Greetings, little hero. The mighty Odyn has proclaimed that you should receive these gifts of war. At every turn you continue to prove your valor and your efforts to aid the Valarjar have not gone unnoticed. For the Valarjar! For Odyn! For !",ends={{npcID=106904,x=0.602,y=0.512,zoneID=7541}},questType="standard"},
[46747] = {id=46747,name="Supplies From the Dreamweavers",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7558,description="Hero! Your dedication to defending Val'sharah has given us a much needed respite from the vile influence of the Legion. We were able to scavenge some supplies as a result of your efforts. Here, take them and know that, should you continue to aid us, we will set aside more rewards such as these as we find them.",ends={{npcID=106901,x=0.546,y=0.732,zoneID=7558}},questType="standard"},
[46748] = {id=46748,name="Supplies From the Nightfallen",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7637,description="Outlander, I have some supplies for you. These goods are yours, earned by your continued efforts to our forces here in Suramar . I shall set aside similar treasures should you choose to aid our people more. You have my deepest thanks.",ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637},{npcID=115736,x=0.364,y=0.458,zoneID=7637}},questType="standard"},
[46749] = {id=46749,name="Supplies From the Wardens",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7334,description="Your dedication to our efforts has yielded results. We have supplies for you. Continue your dedication and there will be more.",ends={{npcID=107379,x=0.482,y=0.738,zoneID=7334}},questType="standard"},
[46751] = {id=46751,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7543,mapID=646,questType="standard"},
[46753] = {id=46753,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7543,mapID=646,questType="standard"},
[46765] = {id=46765,name="The Broken Shore: Investigating the Legion",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="While we focus efforts on the Broken Shore, we must be careful to guard against other threats. We have been getting disturbing reports on the Legion starting or supporting indirect threats to Azeroth. While you are on the Broken Shore, please keep an eye out for strange objects or intelligence that could give us a clue as to what and where these threats are. I know it is not a lot to go on, we will do our best from here as well.",starts={{npcID=116302,x=0.446,y=0.632,zoneID=7543}},ends={{npcID=116302,x=0.446,y=0.632,zoneID=7543}},coords={x=0.446,y=0.632,source="quest_giver",zoneID=7543},questType="standard"},
[46769] = {id=46769,name="Relieved of Their Valuables",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Not all demons on this shore stomp around in the open. Some slink about in the shadows, finding more subtle ways to advance the Legion's cause. I have been observing the behavior of smaller demons, these wyrmtongues. They seem to spend considerable time acquiring objects of power. We cannot allow them to use these items against us. The wyrmtongues stash their goods in chests spread around the Broken Shore. I suggest you relieve them of their ill-gotten gain.",starts={{npcID=116302,x=0.446,y=0.632,zoneID=7543}},ends={{npcID=116302,x=0.446,y=0.632,zoneID=7543}},coords={x=0.446,y=0.632,source="quest_giver",zoneID=7543},questType="standard"},
[46772] = {id=46772,name="The Mage Tower",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Well done . In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Mage Tower. All that remains is for you to inspect our work, and complete the construction.",starts={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},coords={x=0.446,y=0.632,source="quest_giver",zoneID=7543},questType="standard"},
[46773] = {id=46773,name="The Command Center",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Well done . In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Command Center. All that remains is for you to inspect our work, and complete the construction.",starts={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},coords={x=0.446,y=0.632,source="quest_giver",zoneID=7543},questType="standard"},
[46774] = {id=46774,name="The Nether Disruptor",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Well done . In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Nether Disruptor. All that remains is for you to inspect our work, and complete the construction.",starts={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},coords={x=0.446,y=0.632,source="quest_giver",zoneID=7543},questType="standard"},
[46777] = {id=46777,name="The Bounties of Legionfall",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="t, thanks to your efforts, our forces have been able to secure additional resources from the battlefield. The more you continue to dominate the battlefield the more resources our forces can spare.",ends={{npcID=120414,x=0.422,y=0.588,zoneID=7543}},questType="standard"},
[46779] = {id=46779,name="Further Advancement",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,description="As the war against our enemies progresses, so must we. We are now able to perform new research. Seek out Winstone Wolfe to continue advancing the Order Hall.",questType="standard"},
[46782] = {id=46782,name="Further Advancement",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7879,description="As the war against our enemies progresses, so must we. We are now able to perform new research. Seek out Chronicler Elrianne to continue advancing the Order Hall.",questType="standard"},
[46783] = {id=46783,name="Further Advancement",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7877,description="As the war against our enemies progresses, so must we. We are now able to perform new research. Seek out Survivalist Bahn to continue advancing the Order Hall.",starts={{npcID=103023,x=0.43,y=0.468,zoneID=7877}},ends={{npcID=103023,x=0.43,y=0.468,zoneID=7877}},coords={x=0.43,y=0.468,source="quest_giver",zoneID=7877},questType="standard"},
[46786] = {id=46786,name="Further Advancement",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7846,description="As the war against our enemies progresses, so must we. We are now able to perform new research. Seek out Leafbeard the Storied to continue advancing the Order Hall.",starts={{npcID=98002,x=0.528,y=0.514,zoneID=7846}},ends={{npcID=98002,x=0.528,y=0.514,zoneID=7846}},coords={x=0.528,y=0.514,source="quest_giver",zoneID=7846},questType="standard"},
[46787] = {id=46787,name="Further Advancement",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=139,mapID=23,description="As the war against our enemies progresses, so must we. We are now able to perform new research. Seek out Sir Alamande Graythorn to continue advancing the Order Hall.",questType="standard"},
[46789] = {id=46789,name="Further Advancement",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="As the war against our enemies progresses, so must we. We are now able to perform new research. Seek out Archivist Zubashi to continue advancing the Order Hall.",questType="standard"},
[46791] = {id=46791,name="Carried On the Wind",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7745,description="Farseer $p, Consular Celestos has requested your presence back at the Maelstrom. Please see him at your earliest convenience.",starts={{npcID=117888,x=0.446,y=0.616,zoneID=7543}},ends={{npcID=106521,x=0.284,y=0.45,zoneID=7745}},coords={x=0.446,y=0.616,source="quest_giver",zoneID=7543},questType="standard"},
[46794] = {id=46794,name="Paragon of the Court",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7334,description="The grateful Court of Farondis has requested your presence. They wish to reward you for your exceptional aid.",ends={{npcID=107376,x=0.468,y=0.414,zoneID=7334}},questType="standard"},
[46795] = {id=46795,name="Ship - Azsuna",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[46796] = {id=46796,name="Paragon of Highmountain",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7731,mapID=650,description="The grateful Highmountain Tribes have requested your presence. They wish to reward you for your exceptional aid.",ends={{npcID=106902,x=0.382,y=0.458,mapID=650}},questType="standard"},
[46797] = {id=46797,name="Paragon of the Dreamweavers",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7558,description="The grateful druids of the Dreamweavers have requested your presence. They wish to reward you for your exceptional aid.",ends={{npcID=106901,x=0.546,y=0.732,zoneID=7558}},questType="standard"},
[46798] = {id=46798,name="Paragon of the Valarjar",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7541,description="The impressed vrykul of the Valarjar have requested your presence. They wish to reward you for your exceptional aid.",ends={{npcID=106904,x=0.602,y=0.512,zoneID=7541}},questType="standard"},
[46799] = {id=46799,name="Paragon of the Nightfallen",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7637,description="A very grateful Thalyssra has requested your presence. She wishes to reward you for your exceptional aid.",ends={{npcID=97140,x=0.368,y=0.466,zoneID=7637},{npcID=115736,x=0.364,y=0.458,zoneID=7637}},questType="standard"},
[46800] = {id=46800,name="Paragon of the Wardens",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7334,description="The impressed Wardens have requested your presence. They wish to reward you for your exceptional aid.",ends={{npcID=107379,x=0.482,y=0.738,zoneID=7334}},questType="standard"},
[46801] = {id=46801,name="Ship - Val'sharah",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[46802] = {id=46802,name="Paragon of the Legionfall Armies",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Your loyal forces in the Armies of Legionfall have requested your presence. They wish to reward you for your exceptional aid.",ends={{npcID=120414,x=0.422,y=0.588,zoneID=7543}},questType="standard"},
[46804] = {id=46804,name="Fashion History and a Philosophy of Style",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Greetings, . I am a fashion historian and I have astonishing advancements in tailoring, leatherworking, and blacksmithing that I must share with you. Why? A true legend is only as good as their ability to form an epic silhouette on the battlefield and--let's be honest--this is not where you shine. Speak to me again if you wish to learn.",starts={{npcID=120221,x=0.412,y=0.594,zoneID=7543}},ends={{npcID=120221,x=0.412,y=0.594,zoneID=7543}},coords={x=0.412,y=0.594,source="quest_giver",zoneID=7543},questType="standard"},
[46805] = {id=46805,name="The Deceiver's Downfall",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Once he was as a brother to me. Then he bartered the soul of my world for his own power. Hounded my people across the stars. Twisted my son into a monster. Now he has come to oversee the final assault on Azeroth. To end this world as he has countless others. Kil'jaeden. We must ensure he does not escape our grasp this time, . Storm the tomb. Break the Legion's hold. End the Deceiver's reign.",starts={{npcID=120372,x=0.446,y=0.632,zoneID=7543}},ends={{npcID=120372,x=0.446,y=0.632,zoneID=7543}},coords={x=0.446,y=0.632,source="quest_giver",zoneID=7543},questType="standard"},
[46808] = {id=46808,name="Ship - Highmountain",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[46812] = {id=46812,name="Draconic Secrets",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8672,description="Arthas never found the prize he sought, Deathlord. It is ours by right. The dragons must know where the resting place of their kin resides. Find a member of the bronze flight, the tenders of history. Do not be merciful.",questType="standard"},
[46813] = {id=46813,name="The Lost Glacier",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8676,description="Do you know why the red dragonflight seeks to prevent us from finding our prize? The bones of a great red dragon teem with the essence of life, even decades after its passing. You will consume this life essence, blight it, and turn it to undeath. And then you will raise a dragon. Fly now into the north. Find this glacier, and your destiny.",questType="standard"},
[46815] = {id=46815,name="Eredath, Jewel of Argus",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="The shattered ruin below us is all that remains of Eredath . We called it the Jewel of Argus. It was here that my fellows in the triumvirate guided our people to prosperity. That was a long time ago. Join me on the surface. We will begin our search for the Crown of the Triumvirate.",questType="standard"},
[46816] = {id=46816,name="Rendezvous",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="There is much to be done before this nightmare can end, but we need to regroup before we draw more attention from the Legion. I managed to retain a signal crystal during the crash used to call transport beacons from the Xenedar. With luck, we should be able to use it to establish a link between here and your forces as well.",starts={{npcID=120529,x=0.566,y=0.674,zoneID=8574}},ends={{npcID=120529,x=0.566,y=0.674,zoneID=8574}},coords={x=0.566,y=0.674,source="quest_giver",zoneID=8574},questType="standard"},
[46818] = {id=46818,name="Defenseless and Afraid",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="This is the battle that raged while I awaited the Genedar. So many ran to join me, but Kil'jaeden inspired still more to stand in their way. My people were slaughtered without mercy. To cover our retreat I ordered for this arena's defenses to be activated. It is clear that they were unable. To turn the tide in this battle, to give these spirits rest, we must do what they could not. Find a way to activate the pylons.",starts={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},ends={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},coords={x=0.544,y=0.778,source="quest_giver",zoneID=8701},questType="standard"},
[46819] = {id=46819,name="Wrecked Cart",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7558,mapID=641,questType="standard"},
[46820] = {id=46820,name="REUSE",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7558,mapID=641,questType="standard"},
[46827] = {id=46827,name="Meld Into the Shadows",level=45,requiredLevel=45,faction="horde",expansion=7,zoneID=7502,description="We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.",starts={{npcID=117259,x=0.768,y=0.398,zoneID=7543}},coords={x=0.768,y=0.398,source="quest_giver",zoneID=7543},questType="standard"},
[46830] = {id=46830,name="Battlefield",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7558,mapID=641,questType="standard"},
[46832] = {id=46832,name="Aalgen Point",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="You wanna hold territory on this chunder puddle of an island, right? Right. That means linkin' up with camps on the outskirts, mate. I know this bloke called Heidirk. Scrappy fella, loves to get into the thick of it. Headed out to the eastern coast with those drakes of his. Have a look for him. Remind him he owes me a pint or two!",starts={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},ends={{npcID=120118,x=0.706,y=0.476,zoneID=7543}},coords={x=0.446,y=0.632,source="quest_giver",zoneID=7543},questType="standard"},
[46834] = {id=46834,name="Khazaduum, First of His Name",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="The Argunite Matrix that powered this part of Eredath was shattered by a hulking beast. We had never seen another like him. He was called Khazaduum and he was a most faithful servant of the Legion. He volunteered to undergo an experimental transformation to become the first of his kind. His arrival was the end of this battle. As a prize he took the Argunite Keystone from the shattered matrix. Take it back and we can finally end this bloodshed.",starts={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},ends={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},coords={x=0.544,y=0.778,source="quest_giver",zoneID=8701},questType="standard"},
[46835] = {id=46835,name="Whispers of a Frightened World Tracking",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=7502,mapID=627,questType="standard"},
[46839] = {id=46839,name="From Darkness",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="I'm afraid it's only a matter of time before our presence is known. We must begin our preparations at once.",starts={{npcID=120529,x=0.566,y=0.674,zoneID=8574}},ends={{npcID=120760,x=0.598,y=0.664,zoneID=8574}},coords={x=0.566,y=0.674,source="quest_giver",zoneID=8574},questType="standard"},
[46840] = {id=46840,name="Prisoners No More",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Hatuun's people have endured arduous times. Their numbers dwindle as those ripped from beyond the walls of their sanctuary become servants to the annihilan lords in the pits just beyond, sentenced to a life of labor, torture and ultimately, death. Seek out these captives, release them from their bonds and show our allies we stand as one against the Burning Legion.",starts={{npcID=120760,x=0.598,y=0.664,zoneID=8574}},ends={{npcID=120953,x=0.504,y=0.538,zoneID=8574}},coords={x=0.598,y=0.664,source="quest_giver",zoneID=8574},questType="standard"},
[46841] = {id=46841,name="Threat Reduction",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="In time, Hatuun and his people will set aside their bitterness and become valuable allies. But their trust must be earned. He says their village is beset by a demon called Aggonar and his cruel kin. We need these fiends out of the way before we can seek out Alleria and the others. The chieftain lent us his horn. Use it to call down his people's vengeance upon the demon lieutenants while I carve a path to Aggonar's lair.",starts={{npcID=120760,x=0.598,y=0.664,zoneID=8574}},ends={{npcID=120953,x=0.504,y=0.538,zoneID=8574}},coords={x=0.598,y=0.664,source="quest_giver",zoneID=8574},questType="standard"},
[46842] = {id=46842,name="A Strike at the Heart",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="These pits have long been a blight upon the lives of our new allies. The demons hunt them down and torture the poor souls for sport. It is time to make them pay for their cruelty and restore hope to this Light-forsaken place. We strike on your mark, .",starts={{npcID=120953,x=0.504,y=0.538,zoneID=8574}},ends={{npcID=120738,x=0.514,y=0.528,zoneID=8574},{npcID=124995,x=0.514,y=0.528,zoneID=8574}},coords={x=0.504,y=0.538,source="quest_giver",zoneID=8574},questType="group"},
[46843] = {id=46843,name="Return to the Vindicaar",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="That pit lord won't trouble our new allies any longer. Until another takes its place, at least. If there's one thing I've learned in our endless war against the Legion, it's to savor victories as you find them. Come, let us take a moment to regroup back at your vessel. Alleria and I have been waiting a long time for a reunion with our son.",starts={{npcID=120738,x=0.514,y=0.528,zoneID=8574},{npcID=124995,x=0.514,y=0.528,zoneID=8574}},ends={{npcID=120844,x=0.62,y=0.87,zoneID=8574},{npcID=120844,x=0.432,y=0.268,zoneID=8574}},coords={x=0.514,y=0.528,source="quest_giver",zoneID=8574},questType="standard"},
[46845] = {id=46845,name="Vengeance Point",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="On my way here, I ran across a squad of demon hunters headed northwest to Vengeance Point. You can bet the Legion will try to stop them from establishing a forward position. I spoke to an elf named Izal Whitemoon . Not the friendliest sort, but I'm sure she'd be grateful if you lent the Illidari a hand... whether she admits it or not.",starts={{npcID=120118,x=0.706,y=0.476,zoneID=7543}},ends={{npcID=111323,x=0.496,y=0.21,zoneID=7543}},coords={x=0.706,y=0.476,source="quest_giver",zoneID=7543},questType="standard"},
[46846] = {id=46846,name="The Word of Zul",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="I have a mundane task for you. Our esteemed Prophet Zul has words to distribute to very specific individuals in de port. And he requested you be de one to deliver dem. Don't ask me why he didn't just have you deliver these when you were here de first time. De prophet is notorious for not sharing all of his visions.",starts={{npcID=126684,x=0.5,y=0.848,mapID=1165}},ends={{npcID=126684,x=0.5,y=0.848,mapID=1165}},coords={x=0.5,y=0.848,source="quest_giver",mapID=1165},questType="standard"},
[46904] = {id=46904,name="Boon of the Command Center",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,mapID=646,starts={{npcID=120183,x=0.446,y=0.632,mapID=646}},ends={{npcID=120183,x=0.446,y=0.632,mapID=646}},coords={x=0.446,y=0.632,source="quest_giver",mapID=646},questType="standard"},
[46924] = {id=46924,name="The Wolf's Tale",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=493,description="Goldrinn sure didn't take any time getting out of here, did he? Let's go see if we can find him outside.",starts={{npcID=120041,x=0.681,y=0.547,zoneID=493}},ends={{npcID=115750,x=0.694,y=0.478,zoneID=493}},coords={x=0.681,y=0.547,source="quest_giver",zoneID=493},questType="standard"},
[46926] = {id=46926,name="Shakedown",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Where are de guards? Princess Talanji has convinced King Rastakhan to permit outsiders in our port. For de first time in centuries, we have allowed non-trolls to set foot on our shores and peddle their wares. And now trolls of lesser tribes seem to think dey can take advantage of these merchants? I will not allow dis sort of behavior. While I investigate why de merchants are not protected, I want you to work your way through de bazaar and slay any thugs you find. Send dem a message.",starts={{npcID=135441,x=0.5,y=0.85,mapID=1165}},ends={{npcID=135441,x=0.5,y=0.85,mapID=1165}},coords={x=0.5,y=0.85,source="quest_giver",mapID=862},questType="standard"},
[46927] = {id=46927,name="Punishment of Tal'aman",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Look, Zolani is going about dis all wrong. If you want de Amani, or anyone, to pay attention, take out their leaders. Go into Tal'aman and look for their mighty gong. Challenge four of their disciples to combat and slay dem.",starts={{npcID=126684,x=0.5,y=0.848,mapID=1165}},ends={{npcID=126684,x=0.5,y=0.848,mapID=1165}},coords={x=0.5,y=0.848,source="quest_giver",mapID=1165},questType="standard"},
[46928] = {id=46928,name="Punishment of Tal'farrak",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="De Sandfury tribe may have had a hand in some crime around here, but it is really their false belief system dat makes dem do dis sort of thing. Enter Tal'farrak, bang de gong within, and face de hydra dey keep as a sacred pet. Bring me dis thing's tongues.",starts={{npcID=126684,x=0.5,y=0.848,mapID=1165}},ends={{npcID=126684,x=0.5,y=0.848,mapID=1165}},coords={x=0.5,y=0.848,source="quest_giver",mapID=1165},questType="standard"},
[46929] = {id=46929,name="Deterrent",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="General Jakra'zet had orders to ensure dis place had protection. Guard protection. I see none of dat. Jakra'zet is a stubborn general, and one I have had my eye on for a while now. Regardless, we must remind dese lesser tribes who rules dis city with a message dey will understand. I charge you with collecting heads. Enter Tal'farrak and Tal'aman, and collect a quota of heads.",starts={{npcID=135441,x=0.5,y=0.85,mapID=1165}},ends={{npcID=135441,x=0.5,y=0.85,mapID=1165}},coords={x=0.5,y=0.85,source="quest_giver",mapID=862},questType="standard"},
[46930] = {id=46930,name="Rastakhan",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="You stand before General Jakra'zet , lord of de armies of Zandalar, enforcer of her seas and bringer of war. And I do not like you. It took years to earn my place here after your Horde laid waste to my people. You will not undo what I have built. I will see you kneel before King Rastakhan . I will watch you beg as he lets me take your head for a trophy. I will fling your corpse into de wastes of Vol'dun. Her \"Highness\" may object... but she is not queen yet. Come. Let us fly to your fate.",starts={{npcID=122661,x=0.5,y=0.824,mapID=1165}},ends={{npcID=120740,x=0.498,y=0.464,mapID=1165}},coords={x=0.5,y=0.824,source="quest_giver",mapID=1165},questType="standard"},
[46931] = {id=46931,name="Speaker of the Horde",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Your Horde has grown powerful, eclipsing some of de troll empires in its magnitude. For saving my daughter, you have earned de right to a presence in my city. Since my daughter has taken such a fondness to you, you may join her in de Great Seal beneath us. De servants there will answer to you now. Talanji seems excited by whatever she has planned for your people. I look forward to being amused by it later. Zolani can show you a way down dat does not involve falling.",starts={{npcID=120740,x=0.498,y=0.464,mapID=1165}},ends={{npcID=120168,x=0.344,y=0.416,mapID=1165},{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=120168,x=0.682,y=0.47,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165},{npcID=120168,x=0.344,y=0.414,mapID=1165},{npcID=120168,x=0.688,y=0.452,mapID=1165},{npcID=133050,x=0.396,y=0.688,mapID=1165}},coords={x=0.498,y=0.464,source="quest_giver",mapID=862},questType="standard"},
[46935] = {id=46935,name="The Shadow of the Sentinax",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="This device appears to be used to relay messages to the large demon ship up above. Unfortunately, it is cracked and unresponsive. Perhaps someone at Deliverance Point will know more about these beacons.",ends={{npcID=120898,x=0.444,y=0.622,zoneID=7543}},questType="standard"},
[46938] = {id=46938,name="Alone in the Abyss",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Champion, we will suffer the same fate as the Army of the Light if the Legion fires that infernal weapon upon us. We must descend into the siege camp below and destroy it while we still can!",starts={{npcID=126307,x=0.618,y=0.868,zoneID=8574},{npcID=126307,x=0.406,y=0.246,zoneID=8574}},ends={{npcID=119543,x=0.608,y=0.794,zoneID=8574}},coords={x=0.618,y=0.868,source="quest_giver",zoneID=8574},questType="standard"},
[46941] = {id=46941,name="The Path Forward",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="We must continue on, but I feel Eredath is far from finished with us. We should take advantage of this relative safety while we still can. I will place a signal beacon that will allow the Vindicaar to lock onto our location. Romuul will send us our means of returning to the Vindicaar if there is a need.",starts={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},ends={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},coords={x=0.544,y=0.778,source="quest_giver",zoneID=8701},questType="standard"},
