[47017] = {id=47017,name="Only the Best",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,mapID=646,starts={{npcID=121081,x=0.436,y=0.64,mapID=646}},ends={{npcID=121081,x=0.436,y=0.64,mapID=646}},coords={x=0.436,y=0.64,source="quest_giver",mapID=646},questType="standard"},
[47018] = {id=47018,name="Beast Mastery: Rumblings Near Feltotem",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=7503,description="The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later. The drogbar chieftain, Navarrogg , is handling this personally and we'd like you to meet him near the Feltotem village. Specialization: Beast Mastery Hunter",ends={{npcID=117225,x=0.356,y=0.238,zoneID=7503}},questType="standard"},
[47019] = {id=47019,name="Windwalker: Rumblings Near Feltotem",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=7503,description="The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later. The drogbar chieftain, Navarrogg , is handling this personally and we'd like you to meet him near the Feltotem village. Specialization: Windwalker Monk",ends={{npcID=117225,x=0.356,y=0.238,zoneID=7503}},questType="standard"},
