[47054] = {id=47054,name="Touched By Fate",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,mapID=646,starts={{npcID=121137,x=0.412,y=0.644,mapID=646}},ends={{npcID=121137,x=0.412,y=0.644,mapID=646}},coords={x=0.412,y=0.644,source="quest_giver",mapID=646},questType="standard"},
[47055] = {id=47055,name="Fire: The Folly of Levia Laurence",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=7502,description="Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Fire Mage",questType="standard"},
[47056] = {id=47056,name="Fury: The Folly of Levia Laurence",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=7502,description="Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Fury Warrior",questType="standard"},
