[47066] = {id=47066,name="Consecrating Ground",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="We have everything we need. In the alcove below you will find the shattered remains of the Argunite Matrix . Replacing the Keystone will restore it to full capacity. The pylons you activated will then be able to repel those who still hunt my people. At long last this battle will be over. I hope it brings them peace.",starts={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},ends={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},coords={x=0.544,y=0.778,source="quest_giver",zoneID=8701},questType="standard"},
