[47118] = {id=47118,name="Tomb of Sargeras: Free The Tormented",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="The souls inside the Tomb are being twisted by an Engine of Horror. Destroy it, and free them from this torment.",ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},questType="raid"},
[47119] = {id=47119,name="Tomb of Sargeras: Free The Tormented",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="The souls inside the Tomb are being twisted by an Engine of Horror. Destroy it, and free them from this torment.",ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},questType="raid"},
