[47122] = {id=47122,name="Tomb of Sargeras: The Fallen Avatar",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Only the Fallen Avatar stands in our way to the final battle. Slay him, and be done with it.",ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},questType="raid"},
[47123] = {id=47123,name="Tomb of Sargeras: The Fallen Avatar",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Only the Fallen Avatar stands in our way to the final battle. Slay him, and be done with it.",ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},questType="raid"},
