[47126] = {id=47126,name="Tomb of Sargeras: The Deceiver",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Carried by only the most powerful of his servants, the Seal indicates the presence of the Deceiver, Kil'Jaeden. He must be defeated.",ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},questType="raid"},
[47127] = {id=47127,name="Tomb of Sargeras: The Deceiver",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Carried by only the most powerful of his servants, the Seal indicates the presence of the Deceiver, Kil'Jaeden. He must be defeated.",ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},questType="raid"},
[47128] = {id=47128,name="Tomb of Sargeras: The Deceiver",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Carried by only the most powerful of his servants, the Seal indicates the presence of the Deceiver, Kil'Jaeden. He must be defeated.",ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},questType="raid"},
[47129] = {id=47129,name="Tomb of Sargeras: The Deceiver",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="Carried by only the most powerful of his servants, the Seal indicates the presence of the Deceiver, Kil'Jaeden. He must be defeated.",ends={{npcID=120183,x=0.446,y=0.632,zoneID=7543}},questType="raid"},
[47130] = {id=47130,name="Improper Burial",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De blood trolls are gathering de corpses of my people for their blood magic. Dis ends today. I will take care of de corpses here. Take dis torch. Its fires are blessed by priests of Bwonsamdi, de loa of death. Burn any corpses of my people dat you see. Each corpse burned means less power for dese monsters' blood magic.",starts={{npcID=121241,x=0.456,y=0.748,mapID=863},{npcID=130844,x=0.452,y=0.71,mapID=863}},ends={{npcID=121241,x=0.456,y=0.748,mapID=863}},coords={x=0.456,y=0.748,source="quest_giver",mapID=863},questType="standard"},
[47134] = {id=47134,name="Foiling the Legion's Jailbreak",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8911,description="High Inquisitor Raalgar has some connection to the fel here on Argus that makes him unkillable. Long ago, the naaru imprisoned him on the Arcatraz. When the forces of Kael'thas Sunstrider attacked the citadel, we were forced to flee on the Exodar. Some Legion prisoners escaped the Arcatraz when last the Legion invaded Azeroth, but Raalgar did not. Stop them from freeing him and I will study the source of his immortality so it can be broken. I can get you close. The rest is up to you.",starts={{npcID=121263,x=0.62,y=0.868,zoneID=8574},{npcID=121263,x=0.428,y=0.238,zoneID=8574}},ends={{npcID=121263,x=0.62,y=0.868,zoneID=8574},{npcID=121263,x=0.428,y=0.238,zoneID=8574}},coords={x=0.62,y=0.868,source="quest_giver",zoneID=8574},questType="standard"},
[47137] = {id=47137,name="Champions of Legionfall",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="The battle to reclaim the Broken Shore is straining our resources. We cannot afford to relent, lest the Legion undo all that we have accomplished. The members of your order have given much, but more is needed. Rally your champions and do what you must to bolster their ranks. There may be untapped power in this land that will turn the tide of war in our favor.",starts={{npcID=116576,x=0.446,y=0.634,zoneID=7543}},ends={{npcID=116576,x=0.446,y=0.634,zoneID=7543}},coords={x=0.446,y=0.634,source="quest_giver",zoneID=7543},questType="standard"},
[47139] = {id=47139,name="Mark of the Sentinax",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,description="The Sentinax rains down terror upon the Broken Shore, unleashing hordes of demons that menace our forces. The fiends seek to stop us from taking the Tomb. They will fail. Lure out the strongest among their vile ranks. Slay them and seize the marks they bear. Make the Legion fear our strength!",starts={{npcID=117873,x=0.446,y=0.632,zoneID=7543}},ends={{npcID=117873,x=0.446,y=0.632,zoneID=7543}},coords={x=0.446,y=0.632,source="quest_giver",zoneID=7543},questType="standard"},
[47148] = {id=47148,name="Something Different",level=90,requiredLevel=90,faction="both",expansion=7,zoneID=14771,description="Even the most bloodthirsty combatants eventually grow weary and turn their backs to the unending struggle of war. They seek a new way to test their mettle and destroy their enemies. Join the Brawl in progress and fight your opponents in a limited time event that tosses traditional rules aside.",starts={{npcID=254971,x=0.362,y=0.81,zoneID=15969}},ends={{npcID=254971,x=0.362,y=0.81,zoneID=15969},{npcID=144383,x=0.74,y=0.144,zoneID=8568},{npcID=144384,x=0.566,y=0.886,zoneID=8670},{npcID=196191,x=0.432,y=0.422,zoneID=13862},{npcID=219260,x=0.588,y=0.752,zoneID=14771}},coords={x=0.362,y=0.81,source="quest_giver",zoneID=15969},questType="standard"},
[47180] = {id=47180,name="The Pulsing Madness",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="This broken still retains some of his sanity, though not all of it. I can sense some Void influence nearby, but it is isolated to small pockets. Dispelling these manifestations should help our friend here clear his mind. Perhaps we can use the prayer fragments you found, as they still contain some Light energy. I will try and make sense of his chattering in the meantime. Maybe we can learn something about what is happening here.",starts={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574},{npcID=121230,x=0.434,y=0.676,zoneID=8701}},ends={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574},{npcID=121230,x=0.434,y=0.676,zoneID=8701}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47181] = {id=47181,name="The Smoking Gun",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8978,description="The Ashvane Company doesn't know it yet, but throwing you into Tol Dagor was the biggest mistake they've ever made. That new powder we swiped could be the key to bringing them down. First, how about we give everyone a little demonstration of just how powerful this stuff is? Go ahead, take a shot at that barrel over there.",starts={{npcID=121239,x=0.564,y=0.616,zoneID=8567},{npcID=121239,x=0.676,y=0.222,zoneID=8568},{npcID=121239,x=0.472,y=0.462,zoneID=8978}},ends={{npcID=121239,x=0.564,y=0.616,zoneID=8567},{npcID=121239,x=0.676,y=0.222,zoneID=8568},{npcID=121239,x=0.472,y=0.462,zoneID=8978}},coords={x=0.564,y=0.616,source="quest_giver",zoneID=8567},questType="standard"},
[47182] = {id=47182,name="Long Overdue",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8911,description="I have learned much. High Inquisitor Raalgar has moved to a base near the Legion citadel across the mountains. This is where he keeps the Fel Heart of Argus , the source of his immortality, and it is powered by wells leading directly to the core of Argus. He is preparing to attack so you will strike first. Mark the location of the wells and I will rain holy fire upon them with the Vindicaar's guns. With that connection to the fel on Argus broken, Raalgar can be killed and the Fel Heart retrieved.",starts={{npcID=121263,x=0.62,y=0.868,zoneID=8574},{npcID=121263,x=0.428,y=0.238,zoneID=8574}},ends={{npcID=121263,x=0.62,y=0.868,zoneID=8574},{npcID=121263,x=0.428,y=0.238,zoneID=8574}},coords={x=0.62,y=0.868,source="quest_giver",zoneID=8574},questType="standard"},
[47183] = {id=47183,name="Arkhaan's Plan",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Arkhaan remembers. He remembers something that will... yes... will save us. Follow Arkhaan . Isolon calls! We will offer soft words to the Light. The Light will banish the darkness. Arkhaan eyes Alleria warily.> Arkhaan will watch that one closely.",starts={{npcID=121518,x=0.434,y=0.676,zoneID=8701}},ends={{npcID=121230,x=0.434,y=0.676,zoneID=8701},{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574}},coords={x=0.434,y=0.676,source="quest_giver",zoneID=8701},questType="standard"},
[47184] = {id=47184,name="Arkhaan's Peril",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Whatever called to him, it cannot have good intentions. We need to go in after him. Before we step through this portal, ... ensure you are prepared to fight. The Void's influence is rarely peaceful.",starts={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574},{npcID=121230,x=0.434,y=0.676,zoneID=8701}},ends={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574},{npcID=121230,x=0.434,y=0.676,zoneID=8701}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47186] = {id=47186,name="Sanctum of the Sages",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="Sounds like you'll be working with us for awhile. Cyrus will charter a naval transport between here and Stormwind, but I expect you'll want something a bit faster for day to day use. Head back upstairs and take a left when you get outside. You'll find an old study where the Tidesages used to conduct their magic rituals. Surely your Alliance mages have already sensed its power. Inform them they may open their portals there. The harbor guards will keep the room secure.",starts={{npcID=120788,x=0.68,y=0.22,zoneID=8568},{npcID=121235,x=0.68,y=0.22,zoneID=8568}},ends={{npcID=120788,x=0.68,y=0.22,zoneID=8568},{npcID=121235,x=0.68,y=0.22,zoneID=8568}},coords={x=0.68,y=0.22,source="quest_giver",zoneID=8568},questType="standard"},
[47188] = {id=47188,name="The Aid of the Loa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De blood trolls are stronger than ever, thanks to dis G'huun... and now dey are empowering a giant construct! We need a plan to destroy dat construct, G'huun, and de blood trolls. It is not going to be easy. But I have an idea.",starts={{npcID=121288,x=0.392,y=0.79,mapID=863}},ends={{npcID=121288,x=0.392,y=0.79,mapID=863}},coords={x=0.392,y=0.79,source="quest_giver",mapID=863},questType="standard"},
[47189] = {id=47189,name="A Nation Divided",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="Kul Tiras must be unified before it can be of any help to the Alliance. Let's get you briefed on the current situation in each of our major territories. Then you can take a look at the map behind me and make the call on where you want to go first.",starts={{npcID=121235,x=0.68,y=0.22,zoneID=8568}},ends={{npcID=121235,x=0.68,y=0.22,zoneID=8568}},coords={x=0.68,y=0.22,source="quest_giver",zoneID=8568},questType="standard"},
[47193] = {id=47193,name="Battle for Azsuna",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[47194] = {id=47194,name="Battle for Highmountain",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[47195] = {id=47195,name="Battle for Stormheim",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[47196] = {id=47196,name="Battle for Val'sharah",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[47198] = {id=47198,name="They Want Us Alive",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Blood troll poisons are made to paralyze, not kill. See, dey want us alive. I do not feel good thinking about why. I am making antitoxins as quickly as I can, but I need someone like yourself to get out dere and test dem. Take what I have made so far and see if we can get those soldiers back on their feet.",starts={{npcID=121599,x=0.604,y=0.22,zoneID=8499}},ends={{npcID=121599,x=0.604,y=0.22,zoneID=8499}},coords={x=0.604,y=0.22,source="quest_giver",zoneID=8499},questType="standard"},
[47199] = {id=47199,name="The Blood Gate",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="We just received word that the Northern border is under heavy attack by an army of blood trolls. King Rastakhan has called for reinforcements. You are more familiar with that threat than any of us. Go and do what you can to help them.",ends={{npcID=121599,x=0.604,y=0.22,zoneID=8499}},questType="standard"},
[47200] = {id=47200,name="Ticks",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Kill those bloodbellies before dey take off with all of my soldiers! I will have my troops prepare for a flanking charge.",starts={{npcID=121599,x=0.604,y=0.22,zoneID=8499}},ends={{npcID=121599,x=0.604,y=0.22,zoneID=8499}},coords={x=0.604,y=0.22,source="quest_giver",zoneID=8499},questType="standard"},
[47201] = {id=47201,name="Rokhan",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="My scouts have informed me dat your Darkspear shadow hunter, Rokhan , has returned from Nazmir. He is pinned down at de far side of de gate. We need to break dis onslaught with a flanking maneuver. Old Rotana is in position. Mount up and smash through de side of those blood troll ranks. Once down dere, try to find Rokhan . Oh, and $p, be careful. A lot of dark magic is being tossed around down dere.",starts={{npcID=121599,x=0.604,y=0.22,zoneID=8499}},ends={{npcID=121601,x=0.57,y=0.19,zoneID=8499}},coords={x=0.604,y=0.22,source="quest_giver",zoneID=8499},questType="standard"},
[47202] = {id=47202,name="A Personal Message",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=7543,description="The time has come for me to travel to the Broken Shore and see, for myself, the place where my father died. If I am to be the king my father was... the king Stormwind deserves, I must know firsthand the threat my people face. Please tell my advisors that I've gone to the Broken Shore. If I told them myself they'd only try and stop me. I'll wait for you at Deliverance Point. Farewell.",starts={{npcID=120268,x=0.862,y=0.35,zoneID=1519}},ends={{npcID=119340,x=0.864,y=0.356,zoneID=1519},{npcID=119340,x=0.604,y=0.25,zoneID=7543}},coords={x=0.862,y=0.35,source="quest_giver",zoneID=1519},questType="standard"},
[47203] = {id=47203,name="Throwing Shade",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="That was Locus-Walker. He taught me all that I know about the Void, and he still has more to teach me. If he is here, then the ethereals' presence only intrigues me further. I had thought him the only one of his kind, but now that I have seen another tangling with the Void... Come, we must play his game if we want to learn what he knows. He appears to have gone toward the Umbra Hollows to the north.",starts={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574},{npcID=121230,x=0.434,y=0.676,zoneID=8701}},ends={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574},{npcID=121230,x=0.434,y=0.676,zoneID=8701}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47204] = {id=47204,name="The New Frontline",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Kill anything ya see dat not a Zandalari!",starts={{npcID=121601,x=0.57,y=0.19,zoneID=8499}},ends={{npcID=121601,x=0.57,y=0.19,zoneID=8499}},coords={x=0.57,y=0.19,source="quest_giver",zoneID=8499},questType="standard"},
[47205] = {id=47205,name="Warmother",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Old Rotana be cursed by da warmother dese vile blood trolls brought with dem. We need to take her down so we can get dis old direhorn back in da field.",starts={{npcID=121601,x=0.57,y=0.19,zoneID=8499}},ends={{npcID=121601,x=0.57,y=0.19,zoneID=8499}},coords={x=0.57,y=0.19,source="quest_giver",zoneID=8499},questType="standard"},
[47217] = {id=47217,name="Sources of Darkness",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="I think I understand what he was trying to show us, . I feel a surge of power building ahead. They must be cultivating the Void, calling it here. We need to stop them before they plunge this entire city into shadow. Find the source and cut it off by any means necessary. Locus-Walker and I have unfinished business to attend to.",starts={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574},{npcID=121230,x=0.434,y=0.676,zoneID=8701}},ends={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574},{npcID=121230,x=0.434,y=0.676,zoneID=8701}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47218] = {id=47218,name="The Shadowguard Incursion",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="As you have surely gathered by now, a certain subset of my people have tragically succumbed to the call of the Void. I had hoped to find more who possess the necessary strength of mind. I am disappointed to find such an utter lack of resistance. It cannot be helped. To advance your cause, and mine, we will need to eradicate these weak-willed beings.",starts={{npcID=121597,x=0.318,y=0.374,zoneID=8701}},ends={{npcID=121597,x=0.318,y=0.374,zoneID=8701}},coords={x=0.318,y=0.374,source="quest_giver",zoneID=8701},questType="standard"},
[47219] = {id=47219,name="A Vessel Made Ready",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="After some consideration, I have decided to allow Alleria another opportunity to pursue her destiny. I suppose you want to know what that means, mortal. Locus-Walker laughs.> Meet us deep in the Shadowguard camp ahead- my brethren are preparing a summons that will provide adequate energy for Windrunner to begin again. Witness what happens when you harness the Void's power.",starts={{npcID=121597,x=0.318,y=0.374,zoneID=8701}},ends={{npcID=121230,x=0.434,y=0.676,zoneID=8701},{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574}},coords={x=0.318,y=0.374,source="quest_giver",zoneID=8701},questType="standard"},
[47220] = {id=47220,name="A Beacon in the Dark",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="That was... an intense experience. It is difficult to focus. I need you to return to Velen. Give him this. I feel as though he should have it, though I am not sure why. Tell him all that we have learned. I am sure Romuul will have been watching our progress. With any luck, a beacon is already headed our way.",starts={{npcID=121230,x=0.616,y=0.87,zoneID=8574},{npcID=121230,x=0.394,y=0.262,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47221] = {id=47221,name="The Hand of Fate",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=1519,description="$p, We have won many battles against the Burning Legion, but it is time to end this war once and for all. Final preparations have begun to depart for Argus. Make haste to Stormwind Harbor. A ship awaits you there to grant you and your allies passage to Azuremyst.",ends={{npcID=121754,x=0.214,y=0.304,zoneID=1519}},questType="standard"},
[47222] = {id=47222,name="Two If By Sea",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=8840,description="The Tomb of Sargeras was only the beginning. If we do not destroy the Legion utterly, they will return even stronger. We will travel to Azuremyst by sea to avoid drawing unnecessary attention. The less time the Legion has to react to our assault, the better. Just say the word when you are ready to depart.",starts={{npcID=121754,x=0.214,y=0.304,zoneID=1519}},ends={{npcID=121756,x=0.206,y=0.532,zoneID=8840}},coords={x=0.214,y=0.304,source="quest_giver",zoneID=1519},questType="standard"},
[47223] = {id=47223,name="Light's Exodus",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8840,description="Prophet Velen and the others have gathered within the Vault of Lights below. There is an entrance just down this path. We should find the Prophet at once so that we do not stall the invasion.",starts={{npcID=121756,x=0.206,y=0.532,zoneID=8840}},ends={{npcID=120977,x=0.34,y=0.66,zoneID=8840},{npcID=120977,x=0.396,y=0.78,zoneID=8840}},coords={x=0.206,y=0.532,source="quest_giver",zoneID=8840},questType="standard"},
[47224] = {id=47224,name="The Vindicaar",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8840,description="Everything is prepared for our assault. We need only establish the beacon to transport us to the vessel. Once the beacon arrives, place your hand upon its surface to board the Vindicaar, the instrument of our retribution.",questType="standard"},
[47226] = {id=47226,name="The Orphaned Hatchling",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,starts={{npcID=122939,x=0.642,y=0.446,zoneID=8499}},ends={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},coords={x=0.642,y=0.446,source="quest_giver",zoneID=8499},questType="standard"},
[47228] = {id=47228,name="Xibalan Ecology",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="I had really hoped this area would be more hospitable. The Zandalari have been no help whatsoever in clearing this space for archaeological exploration. Before we can even begin to uncover Xibala's secrets, we must make it safe for those less combat savvy to do their work. You will find the ruins ahead infested with all manner of carnivorous beasts. The few intrepid explorers who ventured within have all failed to return. Local ecology will not stand in the way of progress, . Understand?",starts={{npcID=131582,x=0.438,y=0.72,zoneID=8499}},ends={{npcID=131582,x=0.438,y=0.72,zoneID=8499}},coords={x=0.438,y=0.72,source="quest_giver",zoneID=8499},questType="standard"},
[47229] = {id=47229,name="Bulwark of Torcali",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="We got Old Rotana up on her feet again. Load up an' take her reins. Give us some cover so Talanji can fight her way in from her side.",starts={{npcID=121601,x=0.57,y=0.19,zoneID=8499}},ends={{npcID=135708,x=0.58,y=0.178,zoneID=8499}},coords={x=0.57,y=0.19,source="quest_giver",zoneID=8499},questType="standard"},
[47235] = {id=47235,name="Scrying for the Eye",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="On behalf of the Horde we seek a relic called the Eye of Xibala. The locals have been no help whatsoever and Miss Tae'shara insists that we use her survey equipment. I abhor guesswork. Instead we shall use a more direct method: scrying. I will mark three locations on your map. I would like you to place a scrying vessel at each of them. I will use their measurements to isolate the relic's location and we will be on our way.",starts={{npcID=131580,x=0.4,y=0.764,zoneID=8499}},ends={{npcID=131580,x=0.4,y=0.764,zoneID=8499}},coords={x=0.4,y=0.764,source="quest_giver",zoneID=8499},questType="standard"},
[47238] = {id=47238,name="The Seat of the Triumvirate",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Even with the Sigil of Awakening in hand, the Crown cannot save us until it is whole. That is why we must enter the Seat of the Triumvirate, even knowing that L'ura awaits us there. This is a dire task, one that I would not ask if it were not completely necessary. We will descend together. Come.",questType="standard"},
[47241] = {id=47241,name="The Shadow of Death",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We have four loa, but we only know where one is: Bwonsamdi. As uncomfortable as it makes me, I am prepared to do anything to stop de blood trolls... even if it means dealing with de loa of death. Ages ago, Bwonsamdi had a temple here in Nazmir . My scrying has revealed a few locations to de north where I sense a magical presence. Search dem for clues. Hurry, . Zuldazar will fall if we cannot obtain Bwonsamdi's help!",starts={{npcID=121288,x=0.392,y=0.79,mapID=863}},ends={{npcID=122102,x=0.366,y=0.538,mapID=863}},coords={x=0.392,y=0.79,source="quest_giver",mapID=863},questType="standard"},
[47244] = {id=47244,name="A Culling of Souls",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Only two types enter Bwonsamdi's temple anymore: those looking to make a deal with death, and de dead. You do not stink, so I guess you are de former. I am headed to de temple myself, so how about a trade? See de land across de bridge? Dere is a witch named Najima dat I have been tracking. De blood trolls are corrupt to de core, but their souls are useful as offerings to Bwonsamdi. She is too strong for me to deal with, but if you can slay her, I will take you to de temple. I give you my word.",starts={{npcID=122102,x=0.366,y=0.538,mapID=863}},ends={{npcID=124428,x=0.396,y=0.438,mapID=863}},coords={x=0.366,y=0.538,source="quest_giver",mapID=863},questType="standard"},
[47245] = {id=47245,name="Getting the Message",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Da loa be powerful, but we be needin' soldiers if we gonna have a chance of stopping dem blood trolls from building dat giant of theirs. If we not be able ta destroy dat thing before it be finished, den Zuldazar and all of our people gonna be dead! We need da help of da Horde! Word of da situation already be sent to da warchief. As soon as we be hearin' her reply, we can mov-- Wait... what be dat noise?",starts={{npcID=121289,x=0.392,y=0.79,mapID=863},{npcID=131213,x=0.674,y=0.422,mapID=863}},ends={{npcID=131213,x=0.674,y=0.422,mapID=863}},coords={x=0.392,y=0.79,source="quest_giver",mapID=863},questType="standard"},
[47246] = {id=47246,name="Remnants of the Damned",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Ever since da spirits have begun calling upon this \"G'huun\" me temple has been covered with the unbearable taint of the undead. Da undead be an abomination, but da bloodstones that create them be powerful. They could be of use ta Bwonsamdi. If you wish ta show me your fervor, then cleanse me temple of their filth and bring me their bloodstones.",questType="standard"},
[47247] = {id=47247,name="That Which Haunts the Dead",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Bwonsamdi knows why ya be here. Ya be seekin' me favor. Bwonsamdi ponders you silently.> A test, ta see if ya be worth Bwonsamdi 's time. Dere be spirits whose prayers sing of something called \"G'huun.\" Dey pay me homage no more. I will not allow da desecration of me own temple! Go and subdue da strongest of da ancient spirits. If ya do dis for me, ya may be worth da trouble after all.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=122688,x=0.396,y=0.246,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[47248] = {id=47248,name="'Til Death Do Us Part",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,description="I don't know who you are, but I need your help. My precious Valjabu always told me he didn't care dat he took de vows of a priest... we would be together forever. Well, my time came to pass, and I knew I'd not be able to go on without him. I came back and have been waiting in dis spot for... it seems forever, and Valjabu never showed! I've been walking around dis world for far too long. Please, I beg you, bring a memento of my Valjabu back to me!",starts={{npcID=122706,x=0.366,y=0.274,zoneID=8500}},ends={{npcID=122706,x=0.366,y=0.274,zoneID=8500}},coords={x=0.366,y=0.274,source="quest_giver",zoneID=8500},questType="standard"},
[47249] = {id=47249,name="Soulbound",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Ya did well with me tasks. I be thinkin' ya show promise. Ya might be worthy of a deal. Very well, I pledge ta lend ya me powers ta use against ya foes. In exchange, ya be sendin' one million souls ta Bwonsamdi ! No need ta look shocked, ya be plenty capable of doing dis. Come, meet with me at da Court of Spirits. Dere, we will finalize our agreement.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=122766,x=0.394,y=0.302,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[47250] = {id=47250,name="We'll Meet Again",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Now, it be time for ya ta leave. Dere be many of dem blood troll souls for ya ta be sendin' to da Other Side for Bwonsamdi , and ya not gonna find any more of dem here.",starts={{npcID=122766,x=0.394,y=0.302,mapID=863}},ends={{npcID=127004,x=0.394,y=0.438,mapID=863}},coords={x=0.394,y=0.302,source="quest_giver",mapID=863},questType="standard"},
[47251] = {id=47251,name="Interesting Times",level=1,requiredLevel=1,faction="horde",expansion=7,zoneID=1637,description=", I don't mean to alarm you, but we may be experiencing some... temporal disturbances. Have you ever heard the phrase 'I hope the past doesn't come back to haunt you?' Come visit me in the Valley of Spirits and we can speak more.",ends={{npcID=110035,x=0.364,y=0.744,zoneID=1637}},questType="standard"},
[47252] = {id=47252,name="Interesting Times",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=1519,description=", I don't mean to alarm you, but we may be experiencing some... temporal disturbances. Have you ever heard the phrase 'I hope the past doesn't come back to haunt you?' Come visit me in the Stormwind Royal Library and we can speak more.",ends={{npcID=110034,x=0.846,y=0.25,zoneID=1519}},questType="standard"},
[47254] = {id=47254,name="The Originals",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=10,description="Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism. I speak, of course, about Lord Kazzak , Azuregos , and the Dragons of Nightmare. Legends have it that so sought after were their treasures, that armies would camp overnight to hunt them down. The dragons have felt disturbances in the timeways, coincidentally located where these giants once roamed. They have tasked me with finding champions to investigate.",starts={{npcID=110035,x=0.364,y=0.744,zoneID=1637}},ends={{npcID=110035,x=0.364,y=0.744,zoneID=1637}},coords={x=0.364,y=0.744,source="quest_giver",zoneID=1637},questType="standard"},
[47257] = {id=47257,name="The Bones of Xibala",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Far to the south you will find the bones of an ancient creature. This is Xibala, the progenitor, first of the devilsaurs. She was mother to Rezan, mother to all that came after. The Zandalari do not live there, as it belongs to beasts now. I have heard rumors of some of your Horde arriving in search of something among her bones. This is ill advised. Look into it, won't you?",starts={{npcID=120168,x=0.344,y=0.416,zoneID=8670},{npcID=120168,x=0.682,y=0.47,zoneID=8670},{npcID=120168,x=0.344,y=0.414,zoneID=9598},{npcID=120168,x=0.688,y=0.452,zoneID=9598}},ends={{npcID=131582,x=0.438,y=0.72,zoneID=8499}},coords={x=0.344,y=0.416,source="quest_giver",zoneID=8670},questType="standard"},
[47258] = {id=47258,name="Prepare for a Siege",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,description="It would seem we must make ready for a siege. For now, return to your Horde in Dazar'alor. Prepare for de coming conflict. Should de forces of Nazmir surge, I will send word.",starts={{npcID=135890,x=0.6,y=0.222,zoneID=8499}},coords={x=0.6,y=0.222,source="quest_giver",zoneID=8499},questType="standard"},
[47259] = {id=47259,name="Direhorn Daycare",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Handler Bazkoji had a real gift with de little ones. If dis hatchling is following you, it must mean Bazkoji is dead. I don't have time to find another handler. Are you up to de task? It's a lot of work, and de little ones get attached real fast. If you're going to care for it, it will be a commitment. That baby will be depending on you. I hope you will be up to de task of feeding and protecting it. First things first: food. Dere is plenty of fodder in de pens and river below.",starts={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},ends={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},coords={x=0.668,y=0.424,source="quest_giver",zoneID=8499},questType="standard"},
[47260] = {id=47260,name="Side Effects May Include...",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,starts={{npcID=141952,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[47261] = {id=47261,name="How to Train Your Direhorn",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="I have to get some of whatever you fed your baby! Wow! Now dat it's bigger, it is time to teach it to be a reliable battle companion. Let's see how it does against a tougher challenge, hmm? Talk to Kraal Master B'khor when you are ready to begin.",starts={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},ends={{npcID=122009,x=0.676,y=0.434,zoneID=8499}},coords={x=0.668,y=0.424,source="quest_giver",zoneID=8499},questType="standard"},
[47262] = {id=47262,name="Ending the Blood Trolls",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De loa are smiling on us today. De \"matriarch\" of dese blood trolls, a sick monster named Ateena, is up ahead. We have a change in plans, . We will end dis threat now. We kill Ateena and de blood trolls will be thrown into chaos. She is a powerful hexxer. Go start de fight and I will ambush and catch her off guard. Let us get moving. We will be back in Zuldazar before de day is over.",starts={{npcID=121241,x=0.456,y=0.748,mapID=863}},ends={{npcID=130844,x=0.452,y=0.71,mapID=863}},coords={x=0.456,y=0.748,source="quest_giver",mapID=863},questType="standard"},
[47263] = {id=47263,name="A Time of Revelation",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I can feel Ateena's dark voodoo up ahead. We need to stop whatever she is planning with dis \"G'huun\". Be ready for anything, . We do not know what power Ateena truly has. I do know one thing. If G'huun is threatening my people, den it will die, just like Ateena.",starts={{npcID=130844,x=0.452,y=0.71,mapID=863}},ends={{npcID=121288,x=0.392,y=0.79,mapID=863}},coords={x=0.452,y=0.71,source="quest_giver",mapID=863},questType="standard"},
[47264] = {id=47264,name="Leave None Standing",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Now you see what my father refuses to acknowledge. De blood trolls are slaughtering us, and dey need to be stopped. Our plan is simple, . We will go out dere and kill as many of dese blood trolls as we can. You go east, I go north. Meet with me after and we will see what is left to do. We will teach dese blood trolls to fear de Zandalari!",starts={{npcID=130844,x=0.452,y=0.71,mapID=863}},ends={{npcID=121241,x=0.456,y=0.748,mapID=863}},coords={x=0.452,y=0.71,source="quest_giver",mapID=863},questType="standard"},
[47272] = {id=47272,name="Direhorn Growth Hormone",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Nice little critter you got there. Seems a tad too small to be much more than a nuisance though. Wanna help a friend make a profit? There's an abundance of opportunity here, but these trolls won't listen to me! Tell you what, I can make a supplement of sorts that'll make hair grow on your chest! Er, your hatchling's chest! I know direhorn are vegetarians and all, but there's a reason all the biggest predators eat meat! Rapid growth requires protein. LOTS of protein. You interested?",starts={{npcID=122129,x=0.668,y=0.426,zoneID=8499}},ends={{npcID=122129,x=0.668,y=0.426,zoneID=8499}},coords={x=0.668,y=0.426,source="quest_giver",zoneID=8499},questType="standard"},
[47283] = {id=47283,name="Chop, Chop!",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9439,mapID=14,description="Throm-ka, . I'm always looking for someone who thinks they can swing an axe with the best of them. If you can remove that sapling without much trouble, I'm sure we can find a better use for your skills.",starts={{npcID=129107,x=0.46,y=0.196,mapID=14}},ends={{npcID=129107,x=0.46,y=0.196,mapID=14}},coords={x=0.46,y=0.196,source="quest_giver",mapID=14},questType="standard"},
[47287] = {id=47287,name="The Vindicaar Matrix Core",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="Much has happened on Argus that concerns me but none moreso than Xe'ra's fate. I wonder sometimes if we are doing the right thing? But we must carry on. I can rig the Matrix Core that powers the Vindicaar to allow you to call on the power of our guns when you have need of them on the planet. Go to the Matrix Core in the room at the heart of our ship. Once linked, whatever powers the core has installed now and in the future will be at your disposal.",starts={{npcID=121263,x=0.62,y=0.868,zoneID=8574},{npcID=121263,x=0.428,y=0.238,zoneID=8574}},ends={{npcID=121263,x=0.62,y=0.868,zoneID=8574},{npcID=121263,x=0.428,y=0.238,zoneID=8574}},coords={x=0.62,y=0.868,source="quest_giver",zoneID=8574},questType="standard"},
[47288] = {id=47288,name="Valuable Fossils",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[47289] = {id=47289,name="Teddies and Tea",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=8721,description="There's nobody to play with here anymore. But you'll play with me, right ? It's time for tea! Help me find the other guests, please!",starts={{npcID=121603,x=0.544,y=0.392,zoneID=8721}},coords={x=0.544,y=0.392,source="quest_giver",zoneID=8721},questType="standard"},
[47290] = {id=47290,name="World Event Dungeon - Hummel",level=1,requiredLevel=1,faction="none",expansion=7,questType="standard"},
[47310] = {id=47310,name="Naptime",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Your not-so-little guy is looking a bit ragged after such an exciting day. I bet you both need a rest, hm? Come back later when you're a bit stronger.",starts={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},ends={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},coords={x=0.668,y=0.424,source="quest_giver",zoneID=8499},questType="standard"},
[47311] = {id=47311,name="Headbutting 101",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Your beast is looking well fed. Good. Try and keep it dat way. Now, next you need to teach your little one to defend itself. Direhorns in de wild are prey for much larger creatures and de young are easy pickings for saurid and their like. Go out into de Savagelands and show your little one how to fend dem off. It's all in de horn, .",starts={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},ends={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},coords={x=0.668,y=0.424,source="quest_giver",zoneID=8499},questType="standard"},
[47312] = {id=47312,name="Queenfeather",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Ah, so you are de one who inherited Bazkoji's herd. What is left of it, anyway. I know what killed him, and I tried to warn him. Queenfeather is a vicious ravasaur, bigger than de rest and smarter as well. Most of de eggs around here are hers. Usually I praise de strength of such a beast, but she has become a nuisance. You will find her guarding her nests in de feeding grounds. Kill her and bring back one of her head feathers as proof dat de deed is done.",starts={{npcID=125486,x=0.69,y=0.406,zoneID=8499}},ends={{npcID=125486,x=0.69,y=0.406,zoneID=8499}},coords={x=0.69,y=0.406,source="quest_giver",zoneID=8499},questType="standard"},
[47313] = {id=47313,name="Discreet Discussions",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=9598,description="General Jakra'zet cannot be trusted. He is up to something, but I do not know what. Any who question his actions earn demselves a trip to de sands. As long as he remains in power, my city will never be safe. Speak to his guards. See what you can find out, but be discreet. We do not want to alert Jakra'zet to our actions.",starts={{npcID=133050,x=0.498,y=0.422,zoneID=8670},{npcID=133050,x=0.396,y=0.692,zoneID=8670}},ends={{npcID=122817,x=0.516,y=0.318,zoneID=8670}},coords={x=0.498,y=0.422,source="quest_giver",zoneID=8670},questType="standard"},
[47314] = {id=47314,name="Rumors of Exile",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8670,description="Talanji sent you, didn't she? De princess needs to know dat it is no longer safe to ask such questions so openly. Warguard Rakera spoke out, and no one has heard from her since. Rumor has it she was exiled to Vol'dun .",starts={{npcID=122817,x=0.516,y=0.318,zoneID=8670}},ends={{npcID=122320,x=0.516,y=0.318,zoneID=8670}},coords={x=0.516,y=0.318,source="quest_giver",zoneID=8670},questType="standard"},
[47315] = {id=47315,name="Into the Dunes",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8500,description="Whatever Rakera uncovered, it was important enough to earn her a death sentence to de sands. We must head into Vol'dun to find her. We cannot let whatever she knows about Jakra'zet die with her in de dunes.",starts={{npcID=122320,x=0.516,y=0.318,zoneID=8670}},ends={{npcID=130455,x=0.66,y=0.366,zoneID=8501}},coords={x=0.516,y=0.318,source="quest_giver",zoneID=8670},questType="standard"},
[47316] = {id=47316,name="Secrets in the Sand",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="I found this journal buried in the sand. Kiro tried to toss it in the fire. \"Our wagon has no space for a diary, Meerah . What practical use does it have?\" Don't tell him I said so, but I think it's fascinating! Can you imagine what kinds of secrets it holds? Quite a few pages are missing, but I bet you can recover them out on the dunes!",starts={{npcID=122583,x=0.568,y=0.504,zoneID=8501}},ends={{npcID=130341,x=0.568,y=0.504,zoneID=8501}},coords={x=0.568,y=0.504,source="quest_giver",zoneID=8501},questType="standard"},
[47317] = {id=47317,name="Searching for Survivors",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="It is good to see you are safe, but what of de others? Have dey been lost to de sands? You need to head back to de crash site and see if de others survived. I will ask around and see if these fox people can tell us anything about Rakera.",starts={{npcID=130341,x=0.568,y=0.504,zoneID=8501}},ends={{npcID=130341,x=0.568,y=0.504,zoneID=8501}},coords={x=0.568,y=0.504,source="quest_giver",zoneID=8501},questType="standard"},
[47319] = {id=47319,name="Restorative Venom",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Meerah here found your friend in the dunes. The lightning strike nearly killed her. It might still, without treatment. The wasps within the grove have a painful sting, but their venom also has restorative properties. I can extract what I need from their glands. With an ample amount of venom, we should be able to soothe your friend's wounds.",starts={{npcID=123586,x=0.568,y=0.504,zoneID=8501}},ends={{npcID=123586,x=0.568,y=0.504,zoneID=8501}},coords={x=0.568,y=0.504,source="quest_giver",zoneID=8501},questType="standard"},
[47320] = {id=47320,name="A Balm to Calm",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="As promised, here is the balm that should remedy your companion's injuries. Apply it liberally to any bits of exposed flesh. Its effects should be felt immediately.",starts={{npcID=123586,x=0.568,y=0.504,zoneID=8501}},ends={{npcID=130341,x=0.568,y=0.504,zoneID=8501}},coords={x=0.568,y=0.504,source="quest_giver",zoneID=8501},questType="standard"},
[47321] = {id=47321,name="Knickknack Takeback",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Nisha told me you came here in search of an exile. One named Rakera? We don't know her, but we might be able to help you find her. You help us, and we help you. Deal? We survive by scavenging. We trade what we find, but the sethrak that raided our burrows made away with many of our knickknacks . I always knew they were ruthless, but never imagined they'd be so greedy. Take back what the sethrak have taken, and I'll see that you are provided safe passage through the dunes.",starts={{npcID=123586,x=0.568,y=0.504,zoneID=8501}},ends={{npcID=123586,x=0.568,y=0.504,zoneID=8501}},coords={x=0.568,y=0.504,source="quest_giver",zoneID=8501},questType="standard"},
[47322] = {id=47322,name="Aided Escape",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8500,description="The sethrak may be strong, but we're quick. Well, at least Mekaru and I are. We just barely made it back to the wagon with our tails attached. The others weren't so lucky, I guess. We've been waiting a while, and still no sign of them. If you're headed into the thick of it, would you mind looking for our friends?",starts={{npcID=137631,x=0.546,y=0.424,zoneID=8501}},ends={{npcID=137631,x=0.546,y=0.424,zoneID=8501}},coords={x=0.546,y=0.424,source="quest_giver",zoneID=8501},questType="standard"},
[47324] = {id=47324,name="Unlikely Allies",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="I believe this is one of the Keepers' keys! Only Vorrik would know for sure. We need to head to the temple at once. My pterrordax can take us there when you're ready, but we need to hurry.",starts={{npcID=134533,x=0.47,y=0.756,zoneID=8501}},ends={{npcID=128687,x=0.272,y=0.54,zoneID=8501}},coords={x=0.47,y=0.756,source="quest_giver",zoneID=8501},questType="standard"},
[47327] = {id=47327,name="Answering Their Attacks",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="The sethrak's attacks on our burrows cannot go unanswered. They need to learn that not all within the desert will give up so easily. The only thing the sethrak understand is blood, so that's the language we'll use to teach them. Nisha pauses and looks at you, skeptical that you understood her.> I'm saying we need to kill the sethrak here. All of them.",starts={{npcID=130455,x=0.66,y=0.366,zoneID=8501}},coords={x=0.66,y=0.366,source="quest_giver",zoneID=8501},questType="standard"},
[47329] = {id=47329,name="The Bloodwatcher Legacy",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="Greetings, . I have been sent on behalf of my father, High Examiner Tae'thelan Bloodwatcher, to oversee the extraction of all fossils, relics, and artifacts from this area. My sources inform me that an object that could advance the Horde's cause may be buried beneath this very site. I will require your help extracting it. You see, these nightborne are not precisely good with their hands. Nor do they enjoy getting dirty. Could you be a dear and set a good example?",starts={{npcID=131582,x=0.438,y=0.72,zoneID=8499}},ends={{npcID=131580,x=0.4,y=0.764,zoneID=8499}},coords={x=0.438,y=0.72,source="quest_giver",zoneID=8499},questType="standard"},
[47330] = {id=47330,name="Whispers of a Frightened World",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,description="Champion, Magni needs your help! The Speaker has a message for you, perhaps from Azeroth herself. He seems to be having trouble understanding her, but I'm sure he can explain everything better. He said he was in Sholazar Basin, in Northrend. He should be contacting you shortly.",questType="standard"},
[47332] = {id=47332,name="Your Next Move",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,questType="standard"},
[47416] = {id=47416,name="Shadow of the Triumvirate",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Talgath's words carry more gravity than I think he knew. In an attempt to hurt me one final time, he has given us the answer. The Crest of Knowledge is hidden away in the Seat of the Triumvirate, and it is not unguarded. If my suspicions are correct, we may be facing a greater threat than any of us dared imagine. A dark naaru. Let us return to the Vindicaar. We will plan our next steps there.",questType="standard"},
[47418] = {id=47418,name="Growing Pains",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="These trolls are missing a real opportunity here! They complain about not having enough beasts to go around, yet have they really tried to mass produce them? Nope! With my Direhorn Growth Hormone , they'll be able to fill these pens to overflowing! Sure, the overcrowding might lead to disease and excess waste issues, but I'm sure those are solvable. Ha ha ha this is gonna be great!",starts={{npcID=122129,x=0.668,y=0.426,zoneID=8499}},ends={{npcID=122129,x=0.668,y=0.426,zoneID=8499}},coords={x=0.668,y=0.426,source="quest_giver",zoneID=8499},questType="standard"},
[47422] = {id=47422,name="Dire Situation",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Good news, we found de source of de corruption. De bad news, it is a ritual on de apex of Zanchul. Blood magic wielding heretics are empowering some sort of dire troll up dere. How it made it all de way to de apex without us catching it is something I am sure Raal and I will be arguing about for de next year. Come, let us stop dis heresy.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165},{npcID=127101,x=0.424,y=0.09,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47423] = {id=47423,name="Forbidden Practices",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="You come at a good time, $p. I have need of a weapon such as yourself. Yazma's spies say dere are blood cultists in our ranks. King Rastakhan has charged me with tracking down any trolls guilty of practicing blood magic and purging dem. Take dis totem, route out those with de stench of blood magic, and cleanse dem from dis holy place. When you are done, tell dat lazy Hexlord Raal to get off his perch and help keep dis place secure.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126564,x=0.408,y=0.114,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47428] = {id=47428,name="Kitty?",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=8721,description="You have to find our last guest before it's time for tea! Smoochums really likes the woods, I bet we'll find him there!",ends={{npcID=121684,x=0.556,y=0.41,zoneID=8721}},questType="standard"},
[47430] = {id=47430,name="Moonkin Monitoring",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=493,description="Makkaw motions for you to observe the other moonkin in the area.>",starts={{npcID=122134,x=0.454,y=0.62,zoneID=493}},ends={{npcID=122134,x=0.454,y=0.62,zoneID=493}},coords={x=0.454,y=0.62,source="quest_giver",zoneID=493},questType="standard"},
[47431] = {id=47431,name="Gathering Light",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Alleria and I long for more time with our son, but we cannot afford to wait any longer, . We must strike now. The Army of the Light is scattered, but not defeated. Any survivors should have stayed near the crash site of the Xenedar. If there is any hope of victory, we must rally them and rescue Xe'ra. With the pit lords dealt with, we should have a safer route to the Xenedar. Meet me in the krokul hovel as soon as you can.",starts={{npcID=122378,x=0.618,y=0.87,zoneID=8574},{npcID=122378,x=0.428,y=0.256,zoneID=8574}},ends={{npcID=122621,x=0.404,y=0.634,zoneID=8574}},coords={x=0.618,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47432] = {id=47432,name="The Bargain is Struck",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Now dat you have declared a patron loa for your time here in Zuldazar , you should inform de king of your decision. He will appreciate dat you chose to follow de great Pa'ku.",starts={{npcID=127489,x=0.498,y=0.334,mapID=1165}},ends={{npcID=120740,x=0.498,y=0.464,mapID=1165}},coords={x=0.498,y=0.334,source="quest_giver",mapID=1165},questType="standard"},
[47433] = {id=47433,name="Offensively Defensive",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Let me guess, Loti had you kill any trolls dat smelled of blood magic, yes? Well, dat is barely a half measure. See, blood magic comes from de old ways, and our people have only been giving in to its allure since de walls fell on our northern border. Come, we will go for a little ride and patrol de border to Nazmir. Dat is where all dese bad ideas are coming from.",starts={{npcID=126564,x=0.408,y=0.114,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165}},coords={x=0.408,y=0.114,source="quest_giver",mapID=1165},questType="standard"},
[47434] = {id=47434,name="Restraining Order",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="\"Something feels different\"? Dat was all Raal said? His flock of pterrordaxes have swarmed de courtyard of Zanchul. Dey are being driven mad. Shoo dem away before dey hurt demselves or others.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126564,x=0.408,y=0.114,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47435] = {id=47435,name="Pterrortorial Dispute",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="De courtyard of Zanchul has been overrun by pterrordaxes driven mad by some dark ritual. Power is coalescing here, and it is hard to tell who or what is causing it. I need to track down de source. In de meantime, you take dis, de power of Gonk, and call his allies to help you in battle. Slay dese maddened pterrordaxes. When you are done, tell Raal to get his flock under control.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126564,x=0.408,y=0.114,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47437] = {id=47437,name="Competitive Devotion",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="Okay, I know dis situation is serious, but she gave you de power of her loa? Sounds to me like Loti is more big on recruiting than on dealing with dis blood troll threat. Inside de temple behind me are three guardians. When I walked in dere, de things tried to kill me. Me! Someone has corrupted our own guardians. Here, I will lend you de voice of my own loa, Pa'ku, de pterrordax. Use it to crush dis corruption.",starts={{npcID=126564,x=0.408,y=0.114,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165}},coords={x=0.408,y=0.114,source="quest_giver",mapID=1165},questType="standard"},
[47438] = {id=47438,name="Picking a Side",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Look, dis has gone on long enough, $p. I am not one to hold a grudge, but I will be damned if I let you double dip with Raal's loa and my own. Time has come to pick a loa. De loa are not de sharing type.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47439] = {id=47439,name="Gonk, Lord of the Pack",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="You can find Gonk in his lair west of here, in de Garden of the Loa. You should be able to see his totems. Run near dem to improve your speed. I will continue to purge de heretics from dis temple. Mind your manners around de loa, or he may rip your throat out.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=127576,x=0.498,y=0.334,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=862},questType="standard"},
[47440] = {id=47440,name="Pa'ku, Master of Winds",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Come, ride Ata de Winglord with me, and he will take us to Pa'ku . Oh, and mind your manners around dat loa. Pa'ku has been known to drop followers she is not fond of from a really great height onto really hard stone.",starts={{npcID=126564,x=0.408,y=0.114,mapID=1165}},ends={{npcID=127489,x=0.498,y=0.334,mapID=1165}},coords={x=0.408,y=0.114,source="quest_giver",mapID=862},questType="standard"},
[47441] = {id=47441,name="Pests",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,description="Let me guess, de saurid stole something of yours as well, eh? Look, I don't have de time to run down every little thing dese ankle-biters snap off with. You want some coin? Help me kill some of dese snappers. Otherwise, leave me be.",starts={{npcID=127665,x=0.402,y=0.192,zoneID=8670}},ends={{npcID=126334,x=0.354,y=0.078,zoneID=8670}},coords={x=0.402,y=0.192,source="quest_giver",zoneID=8670},questType="standard"},
[47442] = {id=47442,name="Curse of Jani",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,description="Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets. Ya be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn. I tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.",starts={{npcID=126334,x=0.354,y=0.078,zoneID=8670}},ends={{npcID=126334,x=0.354,y=0.078,zoneID=8670}},coords={x=0.354,y=0.078,source="quest_giver",zoneID=8670},questType="standard"},
[47445] = {id=47445,name="The Zanchuli Council",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="You there, Speaker of de Horde. My spies have told me of dark heresies being practiced in our sacred temple of Zanchul. De king sent Loti and Raal to deal with de situation, but those two bickering council members are soft on their own followers. We need someone more... ruthlessly neutral. Go meet Wardruid Loti down at de Zocalo and she can tell you de rest.",starts={{npcID=122641,x=0.498,y=0.464,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165}},coords={x=0.498,y=0.464,source="quest_giver",mapID=1165},questType="standard"},
[47473] = {id=47473,name="Sizing Up The Opposition",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Turalyon was no doubt hoping for better news, but I fear I cannot provide it. Attempting to drive into the heart of the Legion now would cost us everything. There must be another way. I do not know what it is, but I trust that we will find it. Best not keep Turalyon waiting. We must move forward.",ends={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},questType="standard"},
[47485] = {id=47485,name="The Ashvane Trading Company",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="So, Ashvane's goons are walking around with a new powder that can blow a galleon clean in half and the military has no idea. We need to find out how much of this powder they have and where it's going. An old buddy of mine works the ferry down by the Ashvane Foundry. He may know something about this. You can take the ferry from Tradewinds Market to Eastpoint Station. Once you get there, look for a man named Cagney . Tell him I sent you. He owes me a favor.",starts={{npcID=122370,x=0.68,y=0.22,zoneID=8568}},ends={{npcID=122671,x=0.768,y=0.434,zoneID=8567}},coords={x=0.68,y=0.22,source="quest_giver",zoneID=8568},questType="standard"},
[47486] = {id=47486,name="Suspicious Shipments",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8978,description="Normally I wouldn't tell you nothin'... but I'll spill it for Cyrus. Ashvane's onto somethin' big. They got guys workin' round the clock in there. Even brought in some muscle to keep everyone uh... \"motivated.\" I don't know anything about what they're makin', but I know it ain't passin' through here to Boralus. If I were dumb enough to go snooping around in there, I'd look at the goods themselves. See if they got shipping labels. But I ain't that dumb, so you gotta do it.",starts={{npcID=122671,x=0.768,y=0.434,zoneID=8567}},ends={{npcID=121239,x=0.564,y=0.616,zoneID=8567},{npcID=121239,x=0.676,y=0.222,zoneID=8568},{npcID=121239,x=0.472,y=0.462,zoneID=8978}},coords={x=0.768,y=0.434,source="quest_giver",zoneID=8567},questType="standard"},
[47487] = {id=47487,name="Labor Dispute",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="The Ashvane Company has been workin' their people so hard they even tried to strike! The company brought in a bunch of goons to break it up and get everyone back to work. Heard they even shot a couple guys who tried to walk off the job. What say you give 'em a taste of their own brutality while you're in there?",starts={{npcID=122671,x=0.768,y=0.434,zoneID=8567}},ends={{npcID=122671,x=0.768,y=0.434,zoneID=8567}},coords={x=0.768,y=0.434,source="quest_giver",zoneID=8567},questType="standard"},
[47488] = {id=47488,name="Small Haulers",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8978,description="They said they would feed us. Said they'd keep us warm. Olive runs the sleeve of her coat across her nose.> But they were mean! And it was really hard work. And when we tried to rest, they yelled at us! I got away, but my friends are still in there.",starts={{npcID=122672,x=0.768,y=0.434,zoneID=8567}},ends={{npcID=121239,x=0.564,y=0.616,zoneID=8567},{npcID=121239,x=0.676,y=0.222,zoneID=8568},{npcID=121239,x=0.472,y=0.462,zoneID=8978}},coords={x=0.768,y=0.434,source="quest_giver",zoneID=8567},questType="standard"},
[47489] = {id=47489,name="Stow and Go",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="You see that ship? I know that ship. Let's just say her captain and I have a little history. It's a smuggling vessel. Our illegal weapons are on there for sure. I'd bet my coat on it... and I love this coat. We need to find out where it's going... How are you in tight spaces?",starts={{npcID=134166,x=0.758,y=0.49,zoneID=8567}},ends={{npcID=128377,x=0.856,y=0.836,zoneID=8567}},coords={x=0.758,y=0.49,source="quest_giver",zoneID=8567},questType="standard"},
[47491] = {id=47491,name="Remnants of the Damned",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Ever since da spirits have begun calling upon dis \"G'huun,\" me temple has been covered with da unbearable taint of da undead. Da undead be an abomination, but da bloodstones dat create dem be powerful. Dey could be of use ta Bwonsamdi . If ya wish ta show me ya fervor, den cleanse me temple of their filth and bring me their bloodstones.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=122688,x=0.396,y=0.246,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[47493] = {id=47493,name="A Lonely Spirit",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Da spirit of a child named Keula be wanderin' me temple grounds. Her ma'da gave her child up ta me long ago, she be thinkin' that a great sacrifice would spare her from me call, from going to da other side. Well she be right, I not claim her yet. But she be wrong too. Her child be da one to decide when ta be reunited with her ma'da, and it seem ta me dat da child be no longer be content ta wait. Dey both belong in my realm. Go, bring da child to her ma'da.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=126588,x=0.426,y=0.314,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[47495] = {id=47495,name="Insatiable Appetite [UNUSED]",level=1,requiredLevel=1,faction="horde",expansion=7,zoneID=8499,mapID=862,description="That was incredible! I've never seen such rapid growth! Your strange friend here be welcome to stay as long as he likes if he be willing to share his secret with the Kraal. As for you and your beast, he be looking awfully hungry again. I suspect you'll find it will take a lot more food to satisy him now. Good luck, Apprentice!",questType="standard"},
[47497] = {id=47497,name="Meet the Goldtusk Gang",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Greetings, traveler, and welcome to de Goldtusk Inn! Unless you're here to kill us... In which case, get out. Otherwise, sit down and enjoy de mess! I mean, don't mind de mess. EAT DE MESS! No, don't eat de mess. Ignore it! Rhan'ka turns to the skull with the eyepatch and shouts furiously in Zandalari.> Ha, don't mind him. All exiles are welcome to rest at de Goldtusk Inn, de only luxury lodge in dese harsh dunes. Come, let me introduce you to de staff.",starts={{npcID=122723,x=0.436,y=0.602,zoneID=8501}},ends={{npcID=122723,x=0.436,y=0.602,zoneID=8501}},coords={x=0.436,y=0.602,source="quest_giver",zoneID=8501},questType="standard"},
[47498] = {id=47498,name="Rhan'ka's Lost Friend",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="When you head up to Dead Man's Pass, be sure to say hello to Zulsan. He's my best friend, even if he doesn't want to be near me most of de time. Ha! Seriously, though, he's been up on de cliffs for days. If you find him, convince him to come back down to de inn. We need him to restock our breakfast buffet. Oh, and a completely unrelated question dat has nothing to do with you not being able to find Zulsan and my needing to replace him: How wide is ya head?",starts={{npcID=122723,x=0.436,y=0.602,zoneID=8501},{npcID=138749,x=0.374,y=0.51,zoneID=8501}},ends={{npcID=138749,x=0.374,y=0.51,zoneID=8501}},coords={x=0.436,y=0.602,source="quest_giver",zoneID=8501},questType="standard"},
[47499] = {id=47499,name="The Grinning Idols",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Before de curse, we were a loyal crew to a good captain. But de curse corrupted Pirate-King Zem'lan, made him cruel and controlling. Now, he treats us more like slaves than crewmates. Forced to fight and die for his gain, no treasure for ourselves. No speakin' up without punishment. Well, us four, we ain't gonna be his slaves no more. A few of de crew hold onto de idols dat Zem'lan used to curse us. Kill dem and take de idols. I wanna see if we can break dem. Just for fun.",starts={{npcID=136309,x=0.354,y=0.832,zoneID=8501}},ends={{npcID=136309,x=0.354,y=0.832,zoneID=8501},{npcID=136310,x=0.332,y=0.816,zoneID=8501}},coords={x=0.354,y=0.832,source="quest_giver",zoneID=8501},questType="standard"},
[47501] = {id=47501,name="Dirty Work for Dirty Drinks",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Guests gotta earn their keep at de Goldtusk Inn. What say you help me clear out some scorpids at one of our off-site excursion locations? De delightful Dead Man's Pass! Normally, you'd need to purchase our Warlord Package to be allowed access, but I'll make an exception dis time. I'll even throw in our Scorpid King Package. Unlimited scorpid blood drinks all day, every day! Dere's one catch: we're out of scorpid blood. Bring some back and I'll whip up a batch of drinks for us.",starts={{npcID=122723,x=0.436,y=0.602,zoneID=8501},{npcID=138749,x=0.374,y=0.51,zoneID=8501}},ends={{npcID=138749,x=0.374,y=0.51,zoneID=8501}},coords={x=0.436,y=0.602,source="quest_giver",zoneID=8501},questType="standard"},
[47502] = {id=47502,name="The Great Cranium Caper",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Sandfury thugs attacked de inn after you left and kidnapped de whole Goldtusk Gang! We gotta get dem back. Man'zul was usually de brains behind our thefts back in Zuldazar, but I'll try to come up with a plan to get dem outta dis mess. Rhan'ka thinks for awhile.> I got it! You rescue 'em all!",starts={{npcID=122723,x=0.436,y=0.602,zoneID=8501},{npcID=138749,x=0.374,y=0.51,zoneID=8501}},ends={{npcID=122723,x=0.436,y=0.602,zoneID=8501}},coords={x=0.436,y=0.602,source="quest_giver",zoneID=8501},questType="standard"},
[47503] = {id=47503,name="Gozda'kun the Slaver",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Dat's it. De Sandfury are officially banned from de Goldtusk Inn! You can't just ransack a place, kidnap its staff, and mock its owner with an assortment of fruits and vegetables and expect to get away with it! We gotta teach those thugs what happens when you mess with de Goldtusk Gang! Gozda'kun de Slaver was bossing around de rest of de Sandfury during de attack. Take him out, and leave some Sandfury behind to spread de word.",starts={{npcID=138749,x=0.374,y=0.51,zoneID=8501}},ends={{npcID=122723,x=0.436,y=0.602,zoneID=8501}},coords={x=0.374,y=0.51,source="quest_giver",zoneID=8501},questType="standard"},
[47506] = {id=47506,name="REUSE",level=1,requiredLevel=1,faction="alliance",expansion=7,questType="standard"},
[47508] = {id=47508,name="Fire At Will",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Look out there, the wings of the bats fill the sky. We must offer what ranged support we can, but our hands are full here. It looks like the Legion has not yet destroyed all of the artillery batteries. If you can get to one, you should be able to show those flying fiends the Light.",starts={{npcID=121578,x=0.318,y=0.718,zoneID=8574}},ends={{npcID=121578,x=0.318,y=0.718,zoneID=8574}},coords={x=0.318,y=0.718,source="quest_giver",zoneID=8574},questType="standard"},
[47509] = {id=47509,name="Terrace of the Chosen",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="This betrayal has cut deep into the heart of Zandalar. Half of the Zanchuli Council and their followers have sided with Zul and his... blood god. Lucky for us not all of Zandalar is behind this betrayal. We need to topple Zul's cultists before they can rally too many to their cause. Zanchul is the place to start. Go and see if you can muster any of the Zandalari still loyal to their king.",questType="standard"},
[47512] = {id=47512,name="Nazmir",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="The blood trolls within the cursed swamp Nazmir threaten to destroy all of Zuldazar . Princess Talanji wants the Horde's help in an expedition to strike at the heart of the blood trolls and end their threat to Zuldazar .",ends={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=146335,x=0.498,y=0.464,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},questType="standard"},
[47513] = {id=47513,name="Vol'dun",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=9598,description="General Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe. We are not alone in our suspicions. Speak to Princess Talanji to follow up.",ends={{npcID=133050,x=0.498,y=0.422,zoneID=8670},{npcID=146335,x=0.498,y=0.464,zoneID=8670},{npcID=133050,x=0.396,y=0.692,zoneID=8670}},questType="standard"},
[47514] = {id=47514,name="Zuldazar",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="King Rastakhan is an ancient ruler who is not quick to trust new allies. We must earn his trust if we are to earn his fleet. Zuldazar is the seat of power for the Zandalar empire and a good place to start in winning over these potential allies.",ends={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},questType="standard"},
[47518] = {id=47518,name="Raal",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="Crazzak is a traitor in priest's clothing who thinks if he tortures enough of us it will hurt our loa. Dey even have my husband Raal up on de apex of Zanchul. Normally I would say dey could have him, but dey are using his connection to Pa'ku to weaken de loa. Can't have dat. Let's get to de top of Zanchul and rescue my worthless husband.",starts={{npcID=123335,x=0.394,y=0.138,mapID=1165},{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},ends={{npcID=133324,x=0.436,y=0.074,mapID=1165}},coords={x=0.394,y=0.138,source="quest_giver",mapID=1165},questType="standard"},
[47520] = {id=47520,name="Walls Have Ears",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="Yazma, mistress of spies. Bah! A traitor who is into creepy crawlies. She chose to side with Zul, and she uses de children of her loa, Shadra, to watch and track everything we do. We have to kill all de spiders we see, or dat traitor Yazma will know every move we make.",starts={{npcID=123335,x=0.394,y=0.138,mapID=1165},{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},ends={{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},coords={x=0.394,y=0.138,source="quest_giver",mapID=1165},questType="standard"},
[47521] = {id=47521,name="Midnight in the Garden of the Loa",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Yazma and her henchtroll Vol'kaal have pulled most of their forces back to de Garden of de Loa. Something bad is afoot, I can feel it in my spirit. Pa'ku is in danger, along with all de loa who have followers dere. Come, let's fly dere and put an end to dese heresies.",starts={{npcID=133324,x=0.436,y=0.074,mapID=1165}},ends={{npcID=122760,x=0.506,y=0.296,mapID=862}},coords={x=0.436,y=0.074,source="quest_giver",mapID=862},questType="standard"},
[47522] = {id=47522,name="The Hunter",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Gonk is in danger. I can hear his call. My loa has saved my life so many times, it is about time I return de favor. Come, join me at de Lair of Gonk on de west side of de Garden of the Loa, and we will save a god.",starts={{npcID=122760,x=0.506,y=0.296,mapID=862}},ends={{npcID=124827,x=0.484,y=0.32,mapID=862}},coords={x=0.506,y=0.296,source="quest_giver",mapID=862},questType="standard"},
[47523] = {id=47523,name="Disturbance Detected: Black Temple",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=3959,description=", right on time, as always. Good news first, because they're happening at the same time for me anyway. Thanks to the various timewarped objects past and future you discovered, we've figured out how to detect when a new one turns up. The bad news is, we know our technique works because something has changed in the Black Temple , and it's wreaking havoc across the timescape! We need you to ensure the fateful raid turns out exactly like it did before, and to remove the source of this disturbance.",starts={{npcID=123252,x=0.546,y=0.39,zoneID=3703}},ends={{npcID=123252,x=0.546,y=0.39,zoneID=3703}},coords={x=0.546,y=0.39,source="quest_giver",zoneID=3703},questType="standard"},
[47525] = {id=47525,name="Staying Hidden",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Dere be trouble brewin', mon. Da blood trolls be on da move! Dey set up a large camp nearby and have been sending a small force to da isle south of here. If dey discover our position while we be havin' no defenses, it gonna be game over! We need ta see what dey be up to and get rid of dem. Our best bet be ta investigate da isle south a here. Ya want ta join me? I be ready ta head out.",starts={{npcID=122991,x=0.674,y=0.42,mapID=863}},ends={{npcID=124376,x=0.686,y=0.466,mapID=863}},coords={x=0.674,y=0.42,source="quest_giver",mapID=863},questType="standard"},
[47526] = {id=47526,name="Bringing the Big Guns",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Light's Judgment has a security feature to prevent it from falling into enemy hands. We can trigger its recall mechanism, which will teleport it back to a vessel. With the Xenedar out of commission, the gun should recall to your ship instead. You can make good use of its firepower. The process takes time, though, and will likely attract the Legion's attention. Be on your guard.",starts={{npcID=121517,x=0.314,y=0.636,zoneID=8574}},ends={{npcID=271124,x=0.317,y=0.579,zoneID=8574}},coords={x=0.314,y=0.636,source="quest_giver",zoneID=8574},questType="standard"},
[47528] = {id=47528,name="Mistress of Lies",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="If you are done dealing with dese peasant loa, den perhaps you can help with my own loa: Shadra. My \"high\" priestess, Yazma , is behind all of dis. If she is having her minions slay other loa, den I can only guess she is also trying to sacrifice my own loa as well. Shadra's shrine is on de northwest side of de Garden of the Loa. You must stop her from slaying de Mistress of Spies.",ends={{npcID=122760,x=0.506,y=0.296,mapID=862}},questType="standard"},
[47529] = {id=47529,name="Supernatural Support",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="The loa can bestow powerful boon's to their followers, aid that can be the difference between victory or defeat in our efforts here. Think carefully which of the two you would like to ask for their blessing. The loa will not give their assistance to those who are currently pledged to another loa.",questType="standard"},
[47540] = {id=47540,name="Totemic Restoration",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I am fed and my body is prepared. I can now be instilled with my power of old and for a time will be immune to their blood curses and leeching powers. Use the magic of the glowflies to channel my power from the totems into me. Soon you will see me restored. Then we will destroy the army that prepares across the river to take all that is mine by force.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47541] = {id=47541,name="The Best Prevention",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="If you've brought the High Exarch back to us, you are a welcome ally indeed. More is needed of you. You see our soldiers out there, fighting against all odds? Defend them. Slay the enemy. Strong words for a priest, perhaps, but every dead man'ari is one less blade at our throats. Show them that the Light protects its chosen even as it scorches the unfaithful. When you are finished, seek out Y'mera. She will have fewer troops, and more need of your abilities.",starts={{npcID=121520,x=0.406,y=0.642,zoneID=8574}},ends={{npcID=121578,x=0.318,y=0.718,zoneID=8574}},coords={x=0.406,y=0.642,source="quest_giver",zoneID=8574},questType="standard"},
[47543] = {id=47543,name="The Day That Chromie Dies",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=65,description="Oh, ! I was just thinking about you! Talk about being at the right time in the right place! I was just reviewing some aberrations in the timeways, when I discovered something... unexpected. Something not-so-great. I'm going to die in the near future. Bad times. I was just about to jump ahead and see if I can figure out why, how, who... but I'd feel better with |5 like you by my side. Care to join me?",starts={{npcID=27856,x=0.6,y=0.544,zoneID=65}},ends={{npcID=27856,x=0.6,y=0.544,zoneID=65}},coords={x=0.6,y=0.544,source="quest_giver",zoneID=65},questType="standard"},
[47545] = {id=47545,name="Rewind",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=65,description="Now we know when the attack happens, and vaguely where it's coming from. Progress! All we need to do now is to find out more details and stop that attack! Let me know when you're ready to try again.",starts={{npcID=27856,x=0.6,y=0.544,zoneID=65}},ends={{npcID=27856,x=0.6,y=0.544,zoneID=65}},coords={x=0.6,y=0.544,source="quest_giver",zoneID=65},questType="standard"},
[47550] = {id=47550,name="The Many Advantages of Being a Time Dragon",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=65,description="Well, unfortunately for... whomever is fixated on blasting me into oblivion, I am a fairly skilled master of the timeways! We have the advantage of trying that again, and again, and again, until I'm not dead anymore. We're going to need a little more than a few seconds to stop this attack. How does four hours sound?",starts={{npcID=27856,x=0.6,y=0.544,zoneID=65}},coords={x=0.6,y=0.544,source="quest_giver",zoneID=65},questType="standard"},
[47554] = {id=47554,name="Intercepting the Legion's Plans",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Our scout Skara writes in the missive that she learned of a major Legion initiative. She was after two encoded orders held by Legion troops near us to get the details and this must be when she was killed. The Legion splits their messages into encoded parts so that we cannot read them. Skara also writes that her partner Brae, a codebreaker, was slain trying to reach our lines with a code book that we will need to translate the Legion's orders. It is vital you find the orders and that code book!",starts={{npcID=121519,x=0.404,y=0.634,zoneID=8574}},ends={{npcID=121519,x=0.404,y=0.634,zoneID=8574}},coords={x=0.404,y=0.634,source="quest_giver",zoneID=8574},questType="standard"},
[47564] = {id=47564,name="Restocking the Buffet",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Imagine for a moment, $p. You wake up in de Goldtusk Inn after a long day of drinking scorpid blood, slaughtering Sandfury, and sharing jokes with your best friend Zulsan . Ya not fully awake yet, and not feeling ya best. What do you need most at dat exact moment? An all-you-can-eat breakfast buffet, of course! I'm working on it, but I need some fruit to balance out my menu. Luckily, I've seen some in de oasis outside. Bring me some, and I'll give you lifetime access to de buffet.",starts={{npcID=122725,x=0.436,y=0.602,zoneID=8501}},ends={{npcID=122725,x=0.436,y=0.602,zoneID=8501}},coords={x=0.436,y=0.602,source="quest_giver",zoneID=8501},questType="standard"},
[47570] = {id=47570,name="Hidden Motives",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="I do not understand why the naga would bother attacking a small fishing village. Why waste their time on our simple tribe? The naga seek power and we have none. It makes no sense! They must be after something else entirely... Search Darkwood Shoal and learn of their plans. Whatever the naga are after, it must be quite powerful. Perhaps if we find it first, we can use it against them!",starts={{npcID=134098,x=0.62,y=0.222,zoneID=8501}},ends={{npcID=134098,x=0.62,y=0.222,zoneID=8501}},coords={x=0.62,y=0.222,source="quest_giver",zoneID=8501},questType="standard"},
[47571] = {id=47571,name="The Elder's Wisdom",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="The naga are searching for a powerful artifact called the Ring of Tides. According to the invasion plans, the ring was lost long ago in a battle with Eraka no Kimbul, the great tiger loa. The temple of Eraka no Kimbul is just to the north. If the loa was strong enough to defeat the naga before, maybe he can do it again! We must let the tribe know what we've found! Take the invasion plans to Elder Kuppaka . He is the oldest, and wisest member of our tribe. He will know what to do.",starts={{npcID=134098,x=0.62,y=0.222,zoneID=8501}},ends={{npcID=123063,x=0.616,y=0.206,zoneID=8501}},coords={x=0.62,y=0.222,source="quest_giver",zoneID=8501},questType="standard"},
[47573] = {id=47573,name="Jungleweb Infestation",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="The walls of the temple could provide us with vital protection against the naga, but the temple is overrun with jungle spiders. We'll need to clear out the infestation before the tribe can take refuge at the temple. Venture into the lower ruins and lay waste to the spiders that have nested there.",starts={{npcID=134134,x=0.584,y=0.118,zoneID=8501}},ends={{npcID=134134,x=0.584,y=0.118,zoneID=8501}},coords={x=0.584,y=0.118,source="quest_giver",zoneID=8501},questType="standard"},
[47574] = {id=47574,name="All Webbed Up",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="The lower ruins of the temple are covered in thick webs and spider egg sacs. Some of our tribesman went down to the lower ruins to clear out the spiders, but they haven't come back. I fear for their safety. Please head into the lower ruins and free our brethren before it's too late.",starts={{npcID=134134,x=0.584,y=0.118,zoneID=8501}},ends={{npcID=134134,x=0.584,y=0.118,zoneID=8501}},coords={x=0.584,y=0.118,source="quest_giver",zoneID=8501},questType="standard"},
[47576] = {id=47576,name="Wrath of the Tiger",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="The Tortaka shall have my protection. Even as we speak, an army of the naga have risen from the depths to attack my temple. How soon the naga have forgotten their previous defeat! They seek to reclaim the Ring of Tides, a powerful artifact that I took as my trophy when I killed Azshara's previous champion, Mepjila. I will send you to the battlefield as my avatar to rain destruction upon the naga. They have forgotten what happens to those who trespass against my followers. Remind them.",starts={{npcID=123052,x=0.566,y=0.104,zoneID=8501}},ends={{npcID=123052,x=0.566,y=0.104,zoneID=8501}},coords={x=0.566,y=0.104,source="quest_giver",zoneID=8501},questType="standard"},
[47577] = {id=47577,name="They Came From The Sea",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="You are free to rest your weary legs in our camp, but I'm afraid we have little more to offer you. Naga have driven us from our village by the sea. We can no longer fish or hunt crabs. I fear we may not survive long if we cannot take back our lagoon. But taking back the lagoon will not be enough. We must find out why the naga attacked us. What is it they are looking for? Take this ancient scroll and use it summon the spirits of the naga. They will only speak truth while under its spell.",starts={{npcID=134098,x=0.62,y=0.222,zoneID=8501}},ends={{npcID=134098,x=0.62,y=0.222,zoneID=8501}},coords={x=0.62,y=0.222,source="quest_giver",zoneID=8501},questType="standard"},
[47578] = {id=47578,name="Mark of the Loa",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="You have proven worthy of my blessing, . This means should you choose me as your loa, you can call upon my power when needed. Commune at my shrine and make your decision. Know that whatever you choose, you will always be welcome within these walls.",starts={{npcID=123052,x=0.566,y=0.104,zoneID=8501}},ends={{npcID=123052,x=0.566,y=0.104,zoneID=8501}},coords={x=0.566,y=0.104,source="quest_giver",zoneID=8501},questType="standard"},
[47580] = {id=47580,name="The Curse of Mepjila",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Centuries ago, the sea witch Mepjila attacked my temple with an army of naga invaders. My followers fought bravely, but I arrived too late to save them. I defeated the naga army with ease. But as I closed my jaws around Mepjila, she placed a curse upon the spirits of my followers, locking them in an eternal battle they can never win. This mask will give you the power to enter the spirit realm and end their nightmare. Defeat the spirit of Mepjila and the curse will be broken.",starts={{npcID=123052,x=0.566,y=0.104,zoneID=8501}},ends={{npcID=123052,x=0.566,y=0.104,zoneID=8501}},coords={x=0.566,y=0.104,source="quest_giver",zoneID=8501},questType="standard"},
[47581] = {id=47581,name="Blessing of Kimbul",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="The entrance to the temple is sealed by a magical barrier. According to my scrolls, the barrier can only be lowered by one who has gained the Ring of Tides . There is a statue somewhere in the temple grounds with the power to bestow the ring, but the ruins are overrun with jungle spiders. Tulu and I are not strong enough to explore the lower ruins ourselves. If you can gain the Ring of Tides and enter the temple, we may finally be able to face the naga head on!",starts={{npcID=134133,x=0.584,y=0.118,zoneID=8501}},ends={{npcID=134133,x=0.584,y=0.118,zoneID=8501}},coords={x=0.584,y=0.118,source="quest_giver",zoneID=8501},questType="standard"},
[47583] = {id=47583,name="Die, Die, Diemetradon",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,description="We are competing, you and I and these other savages. I find this... amusing. South of here you will find a number of diemetradons. I challenge you, , to slay more of these creatures than I. Do you accept my wager?",starts={{npcID=123022,x=0.674,y=0.176,zoneID=8499}},ends={{npcID=291013,x=0.675,y=0.189,zoneID=8499}},coords={x=0.674,y=0.176,source="quest_giver",zoneID=8499},questType="standard"},
[47584] = {id=47584,name="A Thorn in the Side",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,description="You fools speak of \"big game\" hunting like it is a thing of wonder. Bah! None know big game hunting like my kin. Mastery of the hunt, passed down from parent to child, for generations. I am here to prove it. I wager that you could not slay more than eleven of the ankylodon beasts that wander this region.",starts={{npcID=123026,x=0.674,y=0.176,zoneID=8499}},coords={x=0.674,y=0.176,source="quest_giver",zoneID=8499},questType="standard"},
[47585] = {id=47585,name="Predatory",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,starts={{npcID=123118,x=0.688,y=0.194,zoneID=8499}},ends={{npcID=123019,x=0.674,y=0.176,zoneID=8499}},coords={x=0.688,y=0.194,source="quest_giver",zoneID=8499},questType="standard"},
[47586] = {id=47586,name="Hunting the Hunter",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=9042,description="Your hunter king, Nesingwary, is a mighty fine bit of prey here. I even thought of hunting him myself. But someone else is on his trail now. And dat hunter, he is a dangerous one. If you wish to save your hunter king, you best start tracking quickly. If he made camp, you may be too late already. You cannot paint a target and wonder why you were shot! I believe he was last seen heading west...",starts={{npcID=123019,x=0.674,y=0.176,zoneID=8499}},ends={{npcID=138669,x=0.634,y=0.16,zoneID=8499}},coords={x=0.674,y=0.176,source="quest_giver",zoneID=8499},questType="standard"},
[47587] = {id=47587,name="Headhunter Jo",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,description="He said he's hunting you. I'm not the prey, I'm the bait! Behind ye!",starts={{npcID=138669,x=0.634,y=0.16,zoneID=8499}},ends={{npcID=138669,x=0.634,y=0.16,zoneID=8499}},coords={x=0.634,y=0.16,source="quest_giver",zoneID=8499},questType="standard"},
[47588] = {id=47588,name="King of the Hunt",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=8499,mapID=862,questType="standard"},
[47589] = {id=47589,name="Righteous Fury",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="The devastators bombarding our forces prevent us from advancing any further. I can only protect us from their blasts for so long. Champion, you must pierce their lines and remove the barriers protecting the devastators. If you can destroy the anchors that maintain the shields, I can cleanse them from afar.",starts={{npcID=119543,x=0.608,y=0.794,zoneID=8574}},ends={{npcID=123149,x=0.542,y=0.754,zoneID=8574}},coords={x=0.608,y=0.794,source="quest_giver",zoneID=8574},questType="standard"},
[47591] = {id=47591,name="Wanna Buy a Lamp?",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="Ey dere, wanna buy a lamp? You be not regrettin' it.",questType="standard"},
[47592] = {id=47592,name="Shine Bright Like a Diamond",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="Oh, I be sorry. Dat lamp look like it could use some shinin'. I happen to have just da ting.",questType="standard"},
[47594] = {id=47594,name="I'll Take Those, Thanks!",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="These coins, dey be vanishin' inta air ya say? Dat be soundin' perfect, as I have jus the fella ta give dem to.",questType="standard"},
[47595] = {id=47595,name="I Don't Need Them, But I'll Take Them",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="If you wanna collect more, Griftah not gonna argue with dat. Dat bein' said, I don't need dem as much anymore, so I be givin' you less for dem.",questType="standard"},
[47596] = {id=47596,name="There Is No Plan \"B\"",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Look, I'll be honest with you. Our mech, the A.M.O.D., was the best we've ever made. It was mobile. It was powerful. It was one of a kind! What I'm trying to say is, without it, our whole plan is ruined! We have to salvage and rebuild it! That big oaf of a sea giant broke the A.M.O.D. apart and scattered its pieces all over the shore. Find its parts and I'll try to hammer them back together.",starts={{npcID=123548,x=0.822,y=0.272,mapID=863}},ends={{npcID=123548,x=0.822,y=0.272,mapID=863}},coords={x=0.822,y=0.272,source="quest_giver",mapID=863},questType="standard"},
[47597] = {id=47597,name="No Goblin Left Behind",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Our mission is dead in the water unless we move fast! I've found the perfect spot for a new base. While I secure the location, I need you to rescue the team and bring them back. We've trained for this a million times. Just direct them toward the rendezvous point and they'll find the way. We don't have much time, let's go!",starts={{npcID=123178,x=0.746,y=0.388,mapID=863}},ends={{npcID=123544,x=0.822,y=0.272,mapID=863}},coords={x=0.746,y=0.388,source="quest_giver",mapID=863},questType="standard"},
[47598] = {id=47598,name="Pilfering and Fencing",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Our ships are sunk. Our A.M.O.D.'s gone. We've lost a LOT on this mission... and the Bilgewater Cartel don't offer insurance. The debt collectors will be all over us! We gotta make up for these losses. The beach is swarmin' with naga tryin' to collect artifacts from the ruins. How 'bout we grab some of that treasure and make back our money? I'm sure we could find a buyer willing to take 'em off our hands. We'll split the proceeds 80/20. Sounds fair to me.",starts={{npcID=123545,x=0.822,y=0.272,mapID=863}},ends={{npcID=123545,x=0.822,y=0.272,mapID=863}},coords={x=0.822,y=0.272,source="quest_giver",mapID=863},questType="standard"},
[47599] = {id=47599,name="Revenge: Served Hot",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Look, the boss might be keeping a level head here, but we should show these naga what happens when you mess with the Gob Squad. Don't you agree? The naga are sending their behemoths to destroy what's left of our ship. Why don't you take my rocket launcher and make an example out of them. That'll send the message loud and clear!",starts={{npcID=123436,x=0.746,y=0.39,mapID=863},{npcID=123526,x=0.746,y=0.39,mapID=863}},ends={{npcID=123548,x=0.822,y=0.272,mapID=863}},coords={x=0.746,y=0.39,source="quest_giver",mapID=863},questType="standard"},
[47601] = {id=47601,name="Field Evaluation",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We got the A.M.O.D. back together. It's a fine piece of equipment, but we're gonna have to give it a tune up. We don't want to end up digging shrapnel out of our rears. Lucky for us, there are a few naga camps remaining along with the giant that broke the gun in the first place. They'll be great for target practice. We'll deploy the A.M.O.D. just outside the building here. After we deploy, go man it. I'll have you fire a few rounds while I tune its gun. Everything'll be fine... unless it isn't.",starts={{npcID=123544,x=0.822,y=0.272,mapID=863}},ends={{npcID=123878,x=0.814,y=0.26,mapID=863}},coords={x=0.822,y=0.272,source="quest_giver",mapID=863},questType="standard"},
[47602] = {id=47602,name="Ready For Action",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="It's gonna take a bit to get the gun chassis set up. Who knew lifting big equipment could be so hard? In the meantime, why don't you go check back with your friends. Make sure everything's ready on their end. I'd hate to drive this gun into ANOTHER ambush because they're not ready.",starts={{npcID=123878,x=0.814,y=0.26,mapID=863}},ends={{npcID=126213,x=0.674,y=0.422,mapID=863}},coords={x=0.814,y=0.26,source="quest_giver",mapID=863},questType="standard"},
[47603] = {id=47603,name="The Mysterious, Magnificent Al'Abas",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="I see you, puny mortal! I appreciate your concern for my lamp!",questType="standard"},
[47604] = {id=47604,name="In the Land of Magic",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="I think I see the problem. Your puny eyes are too weak to detect the mana-infused finery that these elves have spread throughout the land. They've been wearing jewelry the entire time, and you simply couldn't see it. I propose a partnership, my newly minted associate. My lamp currently suffers from an embarrassing lack of magic and could always use more beautiful decorations. I propose a trade. I shall pierce this sinister veil, and you shall give me the spoils of your theft.",questType="standard"},
[47605] = {id=47605,name="Coins of Air",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="I would be much interested in these magical trinkets that reside in the pockets of the denizens of this land, and humbly offer my services in helping you acquire them, . However, I sadly cannot pay you in the coin of this realm. What I can offer are ephemera - coins of purest air. They're better than nothing, though! Carry my lamp with you. Drop the treasures you steal within, and I will grant you these coins. Perhaps the former owner of my lamp would have a use for them.",questType="standard"},
[47606] = {id=47606,name="Loyalty Is Its Own Reward",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="I offer you a challenge, mortal. Obtain a thousand of my coins, and I believe that I can empower my lamp and the vision within.",questType="standard"},
[47607] = {id=47607,name="High Fash-Djinn",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7502,description="With my newly empowered lamp, I sense further, more valuable trinkets in the pockets of these elves and demons. Fetch them for me!",questType="standard"},
[47621] = {id=47621,name="A True Loa Feast",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="The blood troll attacks have not stopped until now. They have weakened me significantly and I need to get my strength back. My followers used to bring me offerings of meat from the nearby lands. Go and bring back a mighty feast. My strength will return and we will stop these attacks once and for all.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47622] = {id=47622,name="A Magical Glow",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Long ago when the trolls began listening to the whispering darkness, I instilled portions of my power into the totems that surround my lair. I need that power now. In the swamps north of here are glowflies. Their magical essence will aid me in drawing the stored power from the totems. Collect them and return. Then you will see what I was capable of at the height of my strength.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47623] = {id=47623,name="The Last Witch Doctor of Krag'wa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I am Krag'wa, the once mighty. Curse the blood trolls and their dark god! They have slain my worshippers until only Zentimo remained, and now even he is gone. I want revenge on the blood trolls, but first I must honor the last of my witch doctors. As I have no others, I must request you perform the ritual. Then we can talk of revenge.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47627] = {id=47627,name="Vengeance",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="The Army of the Light will not have fallen in vain. Our forces will assault the main encampment while we destroy their siege weapon. This will be but the beginning of our vengeance.",starts={{npcID=123148,x=0.542,y=0.752,zoneID=8574}},ends={{npcID=119535,x=0.608,y=0.792,zoneID=8574},{npcID=123148,x=0.542,y=0.752,zoneID=8574}},coords={x=0.542,y=0.752,source="quest_giver",zoneID=8574},questType="standard"},
[47631] = {id=47631,name="Rendezvous with the Libation",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I be honest wit' ya, mon. I be havin' little patience for goblins and their antics. Go meet with their leader and ensure dat his crew and da weapon be ready for da assault. Zuldazar gonna be overrun by da blood trolls if we fail. Good luck, !",starts={{npcID=131213,x=0.674,y=0.422,mapID=863}},ends={{npcID=123178,x=0.746,y=0.388,mapID=863}},coords={x=0.674,y=0.422,source="quest_giver",mapID=863},questType="standard"},
[47638] = {id=47638,name="Powerful Spirits",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="You prove your worth, $p. We be willin' to initiate you into de ranks of de Goldtusk Gang, if you wanna join. De ritual drink is ready. Boiled scorpid blood spiked with bilewing honey! Don't mind de smell, it's mostly delicious. It's not terrible. It won't kill you. Usually. When you are ready to join de Goldtusk Gang, let me know. I'll unite you with de whole gang. It's time you see what we see.",starts={{npcID=122723,x=0.436,y=0.602,zoneID=8501}},ends={{npcID=122723,x=0.436,y=0.602,zoneID=8501}},coords={x=0.436,y=0.602,source="quest_giver",zoneID=8501},questType="standard"},
[47641] = {id=47641,name="Signs of Resistance",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Our forces sustained heavy losses defending the Vindicaar, . We require allies. The Army of the Light was known to take in survivors of the Legion's crusade to bolster their ranks. We must do the same. I sense the presence of the Legion slaves you freed nearby. I suspect that they have carved out a resistance against their masters. I would appreciate your company, $p.",starts={{npcID=119543,x=0.608,y=0.794,zoneID=8574},{npcID=123149,x=0.542,y=0.754,zoneID=8574}},ends={{npcID=121345,x=0.598,y=0.692,zoneID=8574}},coords={x=0.608,y=0.794,source="quest_giver",zoneID=8574},questType="standard"},
[47642] = {id=47642,name="Soul Crystal",level=45,requiredLevel=45,faction="both",expansion=7,description="Keep the Ruby Shrinewardens occupied. I shall carry out our master's attack from within the great tree itself.",questType="standard"},
[47643] = {id=47643,name="The Ancients' Wisdom",level=45,requiredLevel=45,faction="both",expansion=7,description="The three ancients left three clues: \"...the great nightmare...\" \"...by the water...\" \"...within the dragon's palm...\" Perhaps Chromie 's attacker lies in the place the ancients describe?",questType="standard"},
[47644] = {id=47644,name="Demonic Corestone",level=45,requiredLevel=45,faction="both",expansion=7,description="Yes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.",questType="standard"},
[47645] = {id=47645,name="Voidcallers' Scroll",level=45,requiredLevel=45,faction="both",expansion=7,description="The time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.",questType="standard"},
[47652] = {id=47652,name="The Light Mother",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="We must know for sure whether the Light Mother survived, . Xe'ra was weakened by sending her heart to Azeroth, but she is the prime naaru. She is the Light, and she cannot fade. Let's head into the Xenedar and look for her. Light willing, she will return to guide us once more.",starts={{npcID=122621,x=0.404,y=0.634,zoneID=8574}},ends={{npcID=122621,x=0.404,y=0.634,zoneID=8574}},coords={x=0.404,y=0.634,source="quest_giver",zoneID=8574},questType="standard"},
[47653] = {id=47653,name="Light's Return",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Xe'ra has been saved! We have won an important victory here. The Light Mother should be back on the Vindicaar. No doubt she will want to speak with you. There is so much to explain... Romuul should be able to teleport us back to the ship now. Let me know when you are ready.",starts={{npcID=122621,x=0.404,y=0.634,zoneID=8574}},ends={{npcID=122378,x=0.618,y=0.87,zoneID=8574},{npcID=122378,x=0.428,y=0.256,zoneID=8574}},coords={x=0.404,y=0.634,source="quest_giver",zoneID=8574},questType="standard"},
[47654] = {id=47654,name="Seat of the Triumvirate: The Crest of Knowledge",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8910,description="We have all that we need now, . Alleria Windrunner awaits your arrival at the Seat of the Triumvirate . Do not go alone, my friend. You will need allies to recover the Crest of Knowledge ... and endure what L'ura has become. I will prepare the Vindicaar and await your return. Light be with you in that dark place.",questType="dungeon"},
[47659] = {id=47659,name="Hunt the Hunter",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Please, help us. De Frogmarsh is under siege! My master, de great loa, Krag'wa, is not willing to bend to de will of de blood trolls and their dark god. So now, dey are taking his power by force! Dey are slaying his children and taking his totems of power. Dey will even take Krag'wa and sacrifice him if we are not able to end dis madness! Stop dem! Slay their leader. Perhaps dat will slow dem down for a while. It will give me time to find a more permanent solution.",starts={{npcID=124376,x=0.686,y=0.466,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.686,y=0.466,source="quest_giver",mapID=863},questType="standard"},
[47660] = {id=47660,name="Fallen Idols",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De blood trolls seek to weaken Krag'wa and take his power. Dey steal his idols of power to crack open and feed their magic. Salvage what idols you can. Dey will be needed to make Krag'wa strong. Strong enough to fight dem off once and for all.",starts={{npcID=124376,x=0.686,y=0.466,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.686,y=0.466,source="quest_giver",mapID=863},questType="standard"},
[47663] = {id=47663,name="A Timely Summons from Shattrath",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=3959,description="The blazing star holds a peculiar alignment this cycle, calling out across the heavens. Seek out the sage Vormu in Shattrath City , and lend her your aid.",ends={{npcID=123252,x=0.546,y=0.39,zoneID=3703}},questType="standard"},
[47685] = {id=47685,name="Gatekeeper's Challenge: Cunning",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Archimonde expected greatness from his pupils. Only the most imaginative minds, the most adroit of intellects, could ever truly fathom the deepest reaches of our magic. I doubt you can relate. The path to the left will take you to a set of three statues. Use them to collect a Mark of Cunning. To preserve the integrity of this trial, I will not be able to provide hints. If you do, by some miracle, happen to succeed, I will formally recognize your... brilliance.",starts={{npcID=124070,x=0.598,y=0.504,zoneID=8701}},ends={{npcID=124070,x=0.598,y=0.504,zoneID=8701}},coords={x=0.598,y=0.504,source="quest_giver",zoneID=8701},questType="standard"},
[47686] = {id=47686,name="Not-So-Humble Beginnings",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Now we may begin our search for the Crown of the Triumvirate. We will start with the fragment Archimonde carried: the Sigil of Awakening. To the east and north you will find all that remains of the greatest school of magic on Argus. It was there that Archimonde gained his mastery of the arcane. I can think of no other place he would stow his treasures. It will be guarded, no doubt. We will leverage the expertise of Fareeya's forces here to follow this trail.",starts={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},ends={{npcID=123413,x=0.632,y=0.398,zoneID=8701}},coords={x=0.544,y=0.778,source="quest_giver",zoneID=8701},questType="standard"},
[47687] = {id=47687,name="Gatekeeper's Challenge: Mastery",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Archimonde was an individual consumed by the pursuit of power. Only those who could match his lust would fare well under his tutelage. You will fight what remains of Archimonde's greatest pupils. These three once held such power in their own disciplines that the Conservatory remembers them now. Their echoes will try to kill you. Best all three with all your limbs intact and I will recognize your strength.",starts={{npcID=124070,x=0.598,y=0.504,zoneID=8701}},ends={{npcID=124070,x=0.598,y=0.504,zoneID=8701}},coords={x=0.598,y=0.504,source="quest_giver",zoneID=8701},questType="standard"},
[47688] = {id=47688,name="Invasive Species",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="We should seek out an alternate source of energy just in case I am wrong about the conduits. Luckily enough, I think I know where we can find one. The panthara native to Argus are solitary creatures, but it seems whatever magic the Wakeners possessed has drawn them here in great numbers. This is no time to be gentle with the environment--panthara devour energy to survive. Slay them and see if you cannot reclaim some of the power they have consumed.",starts={{npcID=123413,x=0.632,y=0.398,zoneID=8701}},ends={{npcID=123413,x=0.632,y=0.398,zoneID=8701}},coords={x=0.632,y=0.398,source="quest_giver",zoneID=8701},questType="standard"},
[47689] = {id=47689,name="Gatekeeper's Challenge: Tenacity",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="My master Archimonde was not known for his willingness to suffer indecision. He preferred to teach by rewarding frustration with more frustration-- punishment with more punishment. Absolute conviction was required to succeed under him. At the opposite end of the Conservatory you will find a large structure. Once inside, your goal is to overcome all the obstacles placed before you. Emerge unscathed and I will be forced to consider your will strong enough to proceed.",starts={{npcID=124070,x=0.598,y=0.504,zoneID=8701}},ends={{npcID=124070,x=0.598,y=0.504,zoneID=8701}},coords={x=0.598,y=0.504,source="quest_giver",zoneID=8701},questType="standard"},
[47690] = {id=47690,name="The Defiler's Legacy",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="It seems you are not so easily deterred. Very well. Your deeds qualify you to seek the Sigil. To be clear, I am only permitting you to move on. This does not guarantee your success. The greatest of your challenges lies before you. You must go to the Praetorium and face Archimonde himself. Only by defeating the master of the Conservatory will you be worthy of the Sigil. Few have overcome this obstacle. I hope he does not make too much of a mess of you.",starts={{npcID=124070,x=0.598,y=0.504,zoneID=8701}},ends={{npcID=123413,x=0.632,y=0.398,zoneID=8701}},coords={x=0.598,y=0.504,source="quest_giver",zoneID=8701},questType="standard"},
[47691] = {id=47691,name="A Non-Prophet Organization",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="I have complete faith that Velen is nearby. We would know if he had been captured. All the same, we must not delay. The Legion has a vested interest in finding him after all he has done to resist them. I shudder to think what they might do, given the chance. That is why I am going with you. We will find Velen and help him track down the Crest of Knowledge. We must have faith in his mission or all will be lost.",starts={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},ends={{npcID=120533,x=0.398,y=0.246,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47695] = {id=47695,name="Sound the Alarm",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,mapID=895,description="Sirens are nothing but trouble! All they do is capture our men, never to be seen again. How is anybody supposed to get their goods to Boralus quickly with them around? Since you're already going down there... mind culling their numbers a bit?",questType="standard"},
[47696] = {id=47696,name="Krag'wa the Terrible",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Your previous attack has angered the blood trolls. They now send an army to take everything. They are too late! I am Krag'wa! I will not be eaten, I do the eating! Meet me at the edge of Razorjaw River. You will bear witness to my power, and I will bear witness to yours.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47697] = {id=47697,name="Krag'wa's Aid",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Well done, ! Before we left, I heard dat Princess Talanji be headed ta Gloom Hollow . She should be dere by now. We better be headin' back. She would want ta hear da tale of ya success!",starts={{npcID=124641,x=0.752,y=0.566,mapID=863}},ends={{npcID=126213,x=0.674,y=0.422,mapID=863}},coords={x=0.752,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47706] = {id=47706,name="Hunt for King K'tal",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,description="Hunters! Dis challenge be for de King of de Preserves. King K'tal is a mighty predator, smart and fast. Gold and honor await de hunter who brings me de head of de King.",starts={{npcID=271706,x=0.675,y=0.179,zoneID=8499}},ends={{npcID=123019,x=0.674,y=0.176,zoneID=8499}},coords={x=0.675,y=0.179,source="quest_giver",zoneID=8499},questType="group"},
[47709] = {id=47709,name="The Great Gnomeregan Run",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=5287,description="Ready for the big race today, ? Every year, gnomes from near and far gather to run all the way from Gnomeregan to Booty Bay! It reminds us that no goal is too tall, even for us! Whether you run fast or slow, alone or with friends, you'll make it as long as you keep trying! So make sure to stretch, then get out there and show the world what we gnomes are made of!",starts={{npcID=124280,x=0.364,y=0.364,zoneID=6457}},ends={{npcID=124257,x=0.4,y=0.728,zoneID=5287},{npcID=156018,x=0.4,y=0.728,zoneID=5287}},coords={x=0.364,y=0.364,source="quest_giver",zoneID=6457},questType="standard"},
[47711] = {id=47711,name="Head of the Viper",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="While I was scouting out the area, I saw a big armored naga bossing the rest of the snakes around. Call it a hunch, but I'm pretty sure he's their leader. As long as the Naga have a commander our operations here will be threatened. Take him out.",starts={{npcID=123544,x=0.822,y=0.272,mapID=863}},ends={{npcID=123544,x=0.822,y=0.272,mapID=863}},coords={x=0.822,y=0.272,source="quest_giver",mapID=863},questType="standard"},
[47716] = {id=47716,name="Searching the Ruins",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Dese dunes are crawling with assassins. Nowhere is safe, but we must press on. De ruins aren't far from here. Let's continue our search on foot.",ends={{npcID=134162,x=0.47,y=0.756,zoneID=8501}},questType="standard"},
[47725] = {id=47725,name="Tomb of Sargeras: Aegwynn's Path",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8524,description="As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.",questType="raid"},
[47726] = {id=47726,name="Tomb of Sargeras: Aegwynn's Path",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8524,description="As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.",questType="raid"},
[47727] = {id=47727,name="Tomb of Sargeras: Aegwynn's Path",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8524,description="As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.",questType="raid"},
[47733] = {id=47733,name="The Loa-Speaker's Betrayal",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Listen, stranger. I don't have a lot of time left. I was in de village when Zolani brought de king to us. Said to keep it a secret, or else Zul would find us. Look around. Dey found us! But I know... I know it was not de prophet's doing. Our loa-speaker gave Zolani her pretty words, said she would help, then turned around and sold us out. It is Kihara's fault dat we are dying now. She brought dis upon us! Kill her... Make her pay!",starts={{npcID=138520,x=0.792,y=0.166,mapID=862}},ends={{npcID=124083,x=0.766,y=0.162,mapID=862}},coords={x=0.792,y=0.166,source="quest_giver",mapID=862},questType="standard"},
[47734] = {id=47734,name="Partners in Heresy",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Rezan struggles against his bonds, but we cannot reach him. De mogu dat Zul called here have raised a shield dat rejects my magic. Find and kill de creatures dat stand between me and my loa. I must gather myself for de fight to come. They will know de wrath of TWO kings before dis day is done.",starts={{npcID=124655,x=0.72,y=0.21,mapID=862}},ends={{npcID=124655,x=0.72,y=0.21,mapID=862}},coords={x=0.72,y=0.21,source="quest_giver",mapID=862},questType="standard"},
[47735] = {id=47735,name="Ancient Tortollan Remedies",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Ah, yes, the situation is urgent. We must act quickly, but not hastily. There is a way to save Rastakhan, but it will require three very specific ingredients. Listen well, young one. The first, foam bubbling from the mouth of a crab. The older, the better. The second, the spine of a puffer fish. Venomous! The third, a brutosaur scale . Why? These are the secrets of my people, . Longevity is cultivated like the rarest of flowers... carefully, and with much practice.",starts={{npcID=124063,x=0.764,y=0.16,mapID=862}},ends={{npcID=124063,x=0.764,y=0.16,mapID=862}},coords={x=0.764,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[47736] = {id=47736,name="Heads Will Roll",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Zul's forces try to lay claim to de loa of kings's temple. You must teach dese traitors de meaning of their actions. Sweep de temple of de filth dat defiles it. Destroy those who spit in de face of de loa. Bring me their heads so I may remind others of what happens to those who betray their faith and their king. When you are finished dealing with de unworthy, come find us. Rezan's altar lies deep within de temple grounds. In Rastakhan's name, heads will roll!",starts={{npcID=124656,x=0.748,y=0.248,mapID=862}},ends={{npcID=124656,x=0.748,y=0.248,mapID=862}},coords={x=0.748,y=0.248,source="quest_giver",mapID=862},questType="standard"},
[47737] = {id=47737,name="The Temple of Rezan",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="De chronicler's words are dire. If Zul truly does wish to sacrifice Rezan... Dis will not come to pass! I will defend my loa with my life. Come, , we go to de Temple of Rezan. We must stop dis heresy at once!",starts={{npcID=124062,x=0.766,y=0.16,mapID=862}},ends={{npcID=124655,x=0.72,y=0.21,mapID=862}},coords={x=0.766,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[47738] = {id=47738,name="The Will of the Loa",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Jol's remedy healed Rastakhan's flesh. But his spirit is still lost. Dere is only one thing stopping him now. Death. He is walking in Bwonsamdi's shadow. For most, dere would be nothing to be done. But... he is bound to another loa. A loa who gives life to his faithful. You must call on Rezan , loa of kings, and ask him to claim back Rastakhan's soul. Up de path, you will find my tent. Place dis idol and wait dere. If we are lucky, he will aid us. If not... It was nice knowing you.",starts={{npcID=132637,x=0.764,y=0.16,mapID=862}},ends={{npcID=124062,x=0.766,y=0.16,mapID=862}},coords={x=0.764,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[47739] = {id=47739,name="The Scent of Vengeance",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I know my king, and I know he is not weak willed. His spirit struggles under de weight of dis betrayal, and confusion roots his spirit too close to death for my comfort. We will need to remind him of his purpose. His anger. I have heard shouts of terror from de village below. Zul's followers torment Zeb'ahari while dey hunt for him. Slay those who would harm his people and bring me their blood. Perhaps de scent of vengeance can revive de devilsaur inside ol' Rastakhan.",starts={{npcID=132637,x=0.764,y=0.16,mapID=862}},ends={{npcID=132637,x=0.764,y=0.16,mapID=862}},coords={x=0.764,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[47740] = {id=47740,name="House of the King",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I hear Rezan's call. I will answer, but first you must help me. Our loa give us many boons, and we repay dem in worship. Offerings, sacrifices, and idols are our tools to earn favor, but dey are much more to our loa. Dey are sources of strength. Zul's dogs have begun to corrupt de great golden statues dedicated to Rezan. Even now, I can feel his power dwindling. Stop dem. Cleanse de idols to de great hunter. Teach dem to respect de house of de king.",starts={{npcID=124655,x=0.72,y=0.21,mapID=862}},ends={{npcID=124655,x=0.72,y=0.21,mapID=862}},coords={x=0.72,y=0.21,source="quest_giver",mapID=862},questType="standard"},
[47741] = {id=47741,name="To Sacrifice a Loa",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Rezan 's power is fading. My usurpers have nearly completed their task. I have read of de horrors of Zul'Drak, and I have seen de results of dese acts. To think one of my own people would bring dis heresy here is... unimaginable. Come! We will end dis traitor who spits in de face of all loa! Di chuka Rezan !",starts={{npcID=124655,x=0.72,y=0.21,mapID=862}},ends={{npcID=124948,x=0.708,y=0.298,mapID=862}},coords={x=0.72,y=0.21,source="quest_giver",mapID=862},questType="standard"},
[47742] = {id=47742,name="Zul's Mutiny",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9772,description="A ship such as Rastakhan's Might does not readily sail without her crew. Dat means de Zandalari aboard have succumbed to Zul's machinations and have betrayed their king as surely as he has. Board my ship. Kill those who think to rise against their king. We will take no prisoners. De punishment for de crime of mutiny is death!",starts={{npcID=124062,x=0.766,y=0.16,mapID=862}},ends={{npcID=124062,x=0.766,y=0.16,mapID=862}},coords={x=0.766,y=0.16,source="quest_giver",zoneID=8499},questType="standard"},
[47743] = {id=47743,name="The Child of Light and Shadow",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="It is time, . Xe'ra is returned to us. We have Light's Heart. We have her Chosen One. Come, let us restore her. Let us forge a bright new path against our foes. Speak to me when you are ready to begin.",starts={{npcID=122378,x=0.618,y=0.87,zoneID=8574},{npcID=122378,x=0.428,y=0.256,zoneID=8574}},ends={{npcID=126307,x=0.618,y=0.868,zoneID=8574},{npcID=126307,x=0.406,y=0.246,zoneID=8574}},coords={x=0.618,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47744] = {id=47744,name="Smoke, Meat, and Pretty Flowers",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="Back of town's on lockdown, kid. And yes, I do have a key, but you're a stranger. Listen, I'd like to help you out. You've got an honest look to you. Fetch me some venison, some pipe tobacco, and a bundle o' yellow flowers, and I might be able to make an exception.",questType="standard"},
[47745] = {id=47745,name="Yeah, Definitely for the Kids",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="I don't know if you've ever seen Orphan Matron Meliana before, but she is a goddess come down to humble Lordaeron. Her hair, those cheekbones, and... ...and anyhow, these flowers are for the kids at the orphanage where she works. Tell Meliana that they're from me. For the kids.",questType="standard"},
[47746] = {id=47746,name="Holing Up",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="Did... did you see that? Prince Arthas just struck that person down in cold blood! Right in the middle of the street! I need to protect the children. Please, help us, visitors. I need a gun, bandages, and some venison jerky. Children! Everybody, get into the house!",questType="standard"},
[47747] = {id=47747,name="Fight Plague with Fire",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="One final request of you, stranger. I've seen what's happening outside, and I've heard about this \"plague\". I don't want to go down without a fight. I have enough rum in the back of this bar to set this whole tavern on fire, but I don't have the tools to do it safely. Fetch me a flint and some rope, and I'll give you my key to the backstreets of Stratholme.",questType="standard"},
[47748] = {id=47748,name="FLAG - Holing Up Complete",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[47749] = {id=47749,name="FLAG - Fight Plague With Fire Complete",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[47750] = {id=47750,name="For Emery",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="We do have plenty of food here, however. If you're braving the streets, please deliver this venison to that big dummy at the tavern. Tell him it's from the kids.",questType="standard"},
[47751] = {id=47751,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="none",expansion=7,questType="standard"},
[47752] = {id=47752,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[47753] = {id=47753,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[47754] = {id=47754,name="Lightly Roasted",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Can you hear me, ? Good. Light's Judgment has been installed on the Vindicaar. We should be able to harness its power immediately. We can use it both to clear the rubble blocking the Xenedar as well as destroy our enemies. As with any new piece of technology, we should test it out. Thoroughly. I trust you have plenty of targets down there.",starts={{npcID=124906,x=0.316,y=0.58,zoneID=8574}},ends={{npcID=122621,x=0.404,y=0.634,zoneID=8574}},coords={x=0.316,y=0.58,source="quest_giver",zoneID=8574},questType="standard"},
[47755] = {id=47755,name="Captured and Enraptured",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="You gotta help me! Me and my crew were running late on a delivery, so we decided to take a detour through this grotto ahead. Boy... that was a mistake. This place is crawling with sirens! If there's one thing my men like more than women, it's grog! Here, take some. Use it to bring them back to their senses. Might be best to rough 'em up a bit to weaken the enchantment.",starts={{npcID=123415,x=0.502,y=0.372,zoneID=8567}},ends={{npcID=123415,x=0.502,y=0.372,zoneID=8567}},coords={x=0.502,y=0.372,source="quest_giver",zoneID=8567},questType="standard"},
[47767] = {id=47767,name="Death Metal Knight",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=7541,mapID=634,questType="standard"},
[47771] = {id=47771,name="Locating the Longshot",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="We're going to need a bigger gun if we hope to free Xe'ra. One of the other bunkers crashed closer to the Xenedar. If Baraat was on it, he will have already begun surveying the area. Perhaps he's found the main cannon of the ship. If you head over that way, make sure he hasn't died, will you?",starts={{npcID=121578,x=0.318,y=0.718,zoneID=8574}},ends={{npcID=121517,x=0.314,y=0.636,zoneID=8574}},coords={x=0.318,y=0.718,source="quest_giver",zoneID=8574},questType="standard"},
[47772] = {id=47772,name="Sky Ablaze With Cannonfire",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=9051,description="Oh! It's me! And , was it? I remember this! I seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away. Think you could take it out for me?",questType="standard"},
[47773] = {id=47773,name="Sky Ablaze With Cannonfire",level=45,requiredLevel=45,faction="horde",expansion=7,zoneID=9051,description="Oh! It's me! And , was it? I remember this! I seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away. Think you could take it out for me?",questType="standard"},
[47807] = {id=47807,name="Worried About My Friends",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="I've heard about some trouble over at the black dragonshrine. I know, I'm a bronze dragon, but still! I worry about them sometimes! They weren't ALWAYS so grumpy. If you're going there anyways, would you mind taking care of... whatever's causing so much of a disturbance?",starts={{npcID=122510,x=0.6,y=0.544,zoneID=9051}},ends={{npcID=122510,x=0.6,y=0.544,zoneID=9051}},coords={x=0.6,y=0.544,source="quest_giver",zoneID=9051},questType="standard"},
[47808] = {id=47808,name="The Dead Walk",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="Greetings, . I know you are here in the service of the bronze, but I have a request of you. The Ruby Dragonshrine is plagued by undead. My shrine's wardens were unprepared, and we risk losses if an intervention is not done quickly. Would you assist us?",starts={{npcID=122511,x=0.598,y=0.546,zoneID=9051}},ends={{npcID=122511,x=0.598,y=0.546,zoneID=9051}},coords={x=0.598,y=0.546,source="quest_giver",zoneID=9051},questType="standard"},
[47809] = {id=47809,name="Darkness in the Ley",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="A strange, dark disturbance perturbs the ley lines in my flight's dragonshrine. Do you have the time to investigate?",starts={{npcID=122514,x=0.596,y=0.542,zoneID=9051}},ends={{npcID=122514,x=0.596,y=0.542,zoneID=9051}},coords={x=0.596,y=0.542,source="quest_giver",zoneID=9051},questType="standard"},
[47810] = {id=47810,name="Darkened Dreams",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=9051,description="The ancients at the Emerald Dragonshrine suffer in their dreams. With Ysera gone, I am shorthanded and unable to investigate the matter myself. Would you help me cleanse the nightmare from the Emerald Dragonshrine?",starts={{npcID=122513,x=0.596,y=0.544,zoneID=9051}},ends={{npcID=122513,x=0.596,y=0.544,zoneID=9051}},coords={x=0.596,y=0.544,source="quest_giver",zoneID=9051},questType="standard"},
[47829] = {id=47829,name="FLAG - Hyjal Complete",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[47830] = {id=47830,name="FLAG - Andorhal Complete",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[47831] = {id=47831,name="FLAG - Stratholme Complete",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[47832] = {id=47832,name="FLAG - Well of Eternity Complete",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[47835] = {id=47835,name="The Hand of Fate",level=45,requiredLevel=45,faction="horde",expansion=7,zoneID=14,description="$p, We have won many battles against the Burning Legion, but it is time to end this war once and for all. Final preparations have begun to depart for Argus. Make haste to Bladefist Bay. A ship awaits you there to grant you and your allies passage to Azuremyst.",ends={{npcID=122065,x=0.582,y=0.12,zoneID=14}},questType="standard"},
[47851] = {id=47851,name="Sealing Fate: Marks of Honor",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,questType="standard"},
[47853] = {id=47853,name="Flanking Maneuvers",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="I will take command of Fareeya's lieutenants and we will escort Velen to the Crest of Knowledge. His mission must not fail. We face an old foe-- one the Army of the Light has encountered on numerous occasions. Talgath will try to block us in and prevent our retreat. You must not let that happen. Find out how he is bringing in his forces and cut them off. All we need is time to get in and get out. We are counting on you.",starts={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},ends={{npcID=120533,x=0.398,y=0.246,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47854] = {id=47854,name="Wrath of the High Exarch",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Where the Legion is concerned, violence is always the answer. They are between us and Velen. Nothing will stop them from finding him unless we act. Now is not the time to hold back. Together we will sow chaos among their ranks.",starts={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},ends={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47855] = {id=47855,name="What Might Have Been",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Thousands of years ago, when I was young, I made a choice. A choice that allowed my world to fall to ruin. A choice that made my people exiles. A choice that forever separated me from my beloved brothers. I cannot leave, not yet. Not until I have had a chance to reflect.",starts={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},ends={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},coords={x=0.544,y=0.778,source="quest_giver",zoneID=8701},questType="standard"},
[47856] = {id=47856,name="Across the Universe",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Talgath . There was a time I called him an ally, a friend. I put my trust in him when it came time to leave Argus. I asked him to call out to the others who would join me. I gave him all that he needed to betray me and slaughter my followers. I do not know what brought this hatred to lurk in his heart, but his machinations repeatedly forced my people to flee world after world. He made it his mission to hunt us across the universe. This must end, . Talgath must die.",starts={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},ends={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},coords={x=0.544,y=0.778,source="quest_giver",zoneID=8701},questType="standard"},
[47857] = {id=47857,name="REUSE ME",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8701,mapID=882,description="Hey you've finished part 1 of the Velen arc. Stop here. Nothing past this point is done.",questType="standard"},
[47864] = {id=47864,name="Sealing Fate: Additional Marks of Honor",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,questType="standard"},
[47865] = {id=47865,name="Sealing Fate: Piles of Marks of Honor",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,questType="standard"},
[47867] = {id=47867,name="Two If By Sea",level=45,requiredLevel=45,faction="horde",expansion=7,zoneID=8840,description="The draenei have crafted a vessel to take us to Argus safely. They are gathering the invasion force on Azuremyst Isle as we speak. We will join them there by sea. The Legion is no doubt keeping a close eye on the gateway to their world. We must retain the element of surprise. Let me know when you are ready.",starts={{npcID=122065,x=0.582,y=0.12,zoneID=14}},ends={{npcID=121756,x=0.206,y=0.532,zoneID=8840}},coords={x=0.582,y=0.12,source="quest_giver",zoneID=14},questType="standard"},
[47868] = {id=47868,name="The Necropolis",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="A deal is a deal, and I pay my debts. Bwonsamdi is a mighty loa and you are going to need a powerful ritual to obtain his attention. You are in luck. I already know exactly what needs to be done. Bwonsamdi's temple, de Necropolis, is just to de north. Meet me in de courtyard and we shall see about obtaining an audience with de loa of death.",starts={{npcID=124428,x=0.396,y=0.438,mapID=863}},ends={{npcID=124513,x=0.396,y=0.326,mapID=863}},coords={x=0.396,y=0.438,source="quest_giver",mapID=863},questType="standard"},
[47870] = {id=47870,name="Dead Men Tell No Tales",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=8501,description="I'm an employee of the Ashvane Company. We're number one in the Azerite trade. When I took this job, no one told me it would be a one-way trip! I'd do just about anything to escape these dunes, including working with you. Maybe we can help each other out? I'd be willing to part with the code to the captain's lockbox, if you're willing to help me escape this wretched desert. For my plan to succeed, my expedition party needs to die. Can't have them telling anyone I'm missing...",starts={{npcID=124468,x=0.456,y=0.824,zoneID=8501}},ends={{npcID=124468,x=0.456,y=0.824,zoneID=8501}},coords={x=0.456,y=0.824,source="quest_giver",zoneID=8501},questType="standard"},
[47871] = {id=47871,name="Seafaring Necessities",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=8501,description="She might not be much to look at, but this boat will take me back to Boralus. Before my voyage can begin, I'll need a few seafaring necessities. Luckily, everything I need can be found in the Ashvane encampment.",starts={{npcID=124468,x=0.456,y=0.824,zoneID=8501}},ends={{npcID=124468,x=0.456,y=0.824,zoneID=8501}},coords={x=0.456,y=0.824,source="quest_giver",zoneID=8501},questType="standard"},
[47873] = {id=47873,name="The Captain's Cache",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=8501,description="Well, I'm sure you've figured it out by now, eh? I never was fixing to abandon the crew, I just wanted to move up the ranks. You've helped me out a great deal in that respect. Speaking of respect, I believe there's the matter of Captain Hartford's lockbox ... Here's the code, courtesy of the fallen captain. Just as I promised. It's all yours! Now, don't go telling anyone about our little arrangement, okay? I wouldn't want something like that to spoil such a profitable partnership!",starts={{npcID=139070,x=0.432,y=0.908,zoneID=8501}},ends={{npcID=282746,x=0.432,y=0.908,zoneID=8501}},coords={x=0.432,y=0.908,source="quest_giver",zoneID=8501},questType="standard"},
[47874] = {id=47874,name="Clearing the Fog",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Did you lead Kaja here? I told her not to come after me. It isn't safe... My mind remains fogged, but de memories are slowly returning. Jakra'zet... de weapon... Come, let us find some fresh air. I will tell you what I've discovered.",starts={{npcID=130660,x=0.536,y=0.916,zoneID=8501}},ends={{npcID=130667,x=0.536,y=0.916,zoneID=8501}},coords={x=0.536,y=0.916,source="quest_giver",zoneID=8501},questType="standard"},
[47880] = {id=47880,name="A Tribute for Death",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Everything for de ritual is together. Now, it is time to begin. For dis to work, I must chant de words of old. It is an exhausting task, so I need you to take my mojo fetish and draw de ritual circle, then beat upon de drums. If all goes well, Bwonsamdi may invite us into de temple. If not, our souls are forfeit. Let's not make any mistakes.",starts={{npcID=124513,x=0.396,y=0.326,mapID=863}},ends={{npcID=122688,x=0.396,y=0.246,mapID=863}},coords={x=0.396,y=0.326,source="quest_giver",mapID=863},questType="standard"},
[47882] = {id=47882,name="Conservation of Magic",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="I have an idea. This construct will be of use to us. We simply need to jolt it awake. We once stored great quantities of energy in conduits throughout the Conservatory. They are still functional, but only just. Take this. It will provide a small burst of magic that should help stabilize an erratic conduit. I think I have enough stored for eight or so. Stabilizing a few should allow us to access the whole network.",starts={{npcID=123413,x=0.632,y=0.398,zoneID=8701}},ends={{npcID=123413,x=0.632,y=0.398,zoneID=8701}},coords={x=0.632,y=0.398,source="quest_giver",zoneID=8701},questType="standard"},
[47883] = {id=47883,name="The Longest Vigil",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="It was a good thing we sought two sources of energy. Even with the conduits active, the construct has not stirred. It has likely been inactive a long while. Perhaps as long as Eredath has floated above Argus. What a long, lonely vigil it must have been. Go ahead and jostle it a little. That combined with one last burst of magic ought to do the trick.",starts={{npcID=123413,x=0.632,y=0.398,zoneID=8701}},ends={{npcID=124070,x=0.598,y=0.504,zoneID=8701}},coords={x=0.632,y=0.398,source="quest_giver",zoneID=8701},questType="standard"},
[47889] = {id=47889,name="The Speaker Calls",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="Magni sent for you to meet him in the Krokul Hovel. He has found something that he believes could help us overcome the Legion's infinite armies. We need every advantage we can muster if we are to see this war through. You should seek him out.",starts={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},ends={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47890] = {id=47890,name="Visions of Torment",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="I've been hearin' whispers ever since we got to Argus. They're just like Azeroth's, only... they ain't hers. I'm convinced that Argus has a titan of its own that's reachin' out to us! The broken have a relic stowed away that's darn near holy to 'em. Hatuun says they hear whispers from it... I think it might have some sort o' link to Argus itself! It's just in this chamber. Let's see what we can learn.",starts={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},ends={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},coords={x=0.57,y=0.656,source="quest_giver",zoneID=8574},questType="standard"},
[47891] = {id=47891,name="Dire News",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="Azeroth was right in sendin' us here, . We have to stop whatever it is Sargeras is plannin', or we may not have a home left to save when this is all over. Ye should go back to Turalyon and let him know what ye've seen. I'll stay here and see if I can't glean anything else that might help us.",starts={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},ends={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},coords={x=0.57,y=0.656,source="quest_giver",zoneID=8574},questType="standard"},
[47892] = {id=47892,name="Storming the Citadel",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="We have already secured ground near Nath'raxas Hold. It is one of the Legion's chief military fortifications on Argus. Striking it now, and hard, may be our only opportunity to tip the scales in our favor.",starts={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},ends={{npcID=120763,x=0.608,y=0.472,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[47895] = {id=47895,name="Bert's Bots",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=1,mapID=27,description="If I'm going to clean up Gnomeregan, I've got to be ready to battle all manner of rat, roach, and potentially even the dreaded mutant rat-roach. What I'm saying is that I need to put these bots to the test! A real, live-action field demo. Are your pets up for a code review?",questType="standard"},
[47897] = {id=47897,name="Zanchuli Traitors",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dey are trying to cast down our loa, claiming dem to be false gods. Dey have turned to de old ways of blood, sacrifice, and subjugation. I cannot even begin to say how offensive dis is. Kill any of dese traitors you find.",starts={{npcID=124629,x=0.426,y=0.216,mapID=1165}},ends={{npcID=123335,x=0.394,y=0.138,mapID=1165},{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},coords={x=0.426,y=0.216,source="quest_giver",mapID=862},questType="standard"},
[47904] = {id=47904,name="Preserve the True Future",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=65,description="I know how this looks, . I'm not asking for your help simply because I don't want to get killed. I need your help because this isn't how I'm SUPPOSED to die. I will die - I've seen it! - but it happens much later than this. Besides, meddling with the timeways for personal reasons - well, it goes against pretty much everything my dragonflight stands for. Let's stop all four of the dragonshrine attacks. That should do the trick.",starts={{npcID=27856,x=0.6,y=0.544,zoneID=65}},ends={{npcID=27856,x=0.6,y=0.544,zoneID=65}},coords={x=0.6,y=0.544,source="quest_giver",zoneID=65},questType="standard"},
[47906] = {id=47906,name="The Deaths of Chromie",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=65,description="It looks like we're going to have to stop all eight attacks on me. In one fifteen-minute span. Even to me, that doesn't seem like a lot of time. Still, if anybody can do it, it's us. Are you ready, ?",starts={{npcID=27856,x=0.6,y=0.544,zoneID=65}},ends={{npcID=27856,x=0.6,y=0.544,zoneID=65}},coords={x=0.6,y=0.544,source="quest_giver",zoneID=65},questType="standard"},
[47915] = {id=47915,name="Rescuing the Taken",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="We are doing our best to contain de fighting in Zanchul and not let it spill out into de other terraces, but we can't hold for long. If you are going to help, start by freeing Wardruid Loti . Dey are trying to break her on de platform above with a dark ritual. Her soul is bound to a fetish. You must find dat fetish if you are going to free her.",starts={{npcID=124629,x=0.426,y=0.216,mapID=1165}},ends={{npcID=123335,x=0.394,y=0.138,mapID=1165},{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},coords={x=0.426,y=0.216,source="quest_giver",mapID=1165},questType="standard"},
[47918] = {id=47918,name="To Serve Krag'wa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,description="There are other forces who seek to disturb my frogs. The vile naga attack my shores and drain my frogs of their magic! They seek to use my followers as a feast for their thirst for mana. It must be stopped! A powerful shadow hunter named Narez is currently fighting them. You must go aid her and stop the naga from feasting on my frogs!",starts={{npcID=120551,x=0.754,y=0.566,zoneID=8500}},ends={{npcID=125317,x=0.776,y=0.532,zoneID=8500}},coords={x=0.754,y=0.566,source="quest_giver",zoneID=8500},questType="standard"},
[47919] = {id=47919,name="Just Say No to Cannibalism",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=8500,description="Of course the Natha'vor trolls have Shoak! Why would it be easy? I'm sick and tired of running from these trolls. That's why you're going in to end this. The Natha'vor trolls have three powerful troll witch doctors called \"corpse mongers\". Take them out and you'll send the tribe into disarray. Of course, this could all fail spectacularly and make my terrible day even worse.",starts={{npcID=124933,x=0.518,y=0.332,zoneID=8500},{npcID=125024,x=0.558,y=0.322,zoneID=8500}},ends={{npcID=125024,x=0.558,y=0.322,zoneID=8500}},coords={x=0.518,y=0.332,source="quest_giver",zoneID=8500},questType="standard"},
[47920] = {id=47920,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=10,mapID=47,questType="standard"},
[47921] = {id=47921,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=10,mapID=47,questType="standard"},
[47922] = {id=47922,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=10,mapID=47,questType="standard"},
[47923] = {id=47923,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=10,mapID=47,questType="standard"},
[47924] = {id=47924,name="Profanity Filter",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=8500,description="I hate this place! I just want to go home, but I can't because that oaf, Shoak, is missing. Listen, t, I'll make it worth your while if you help me find that dunce. I've got a way to find Shoak, but of COURSE these stupid totems are blocking my magic! Why wouldn't they? Take this scroll and use its magic to burn these totems. I'm going to look around to see if that bonehead is just sleeping somewhere.",starts={{npcID=124666,x=0.552,y=0.366,zoneID=8500}},ends={{npcID=124933,x=0.518,y=0.332,zoneID=8500}},coords={x=0.552,y=0.366,source="quest_giver",zoneID=8500},questType="standard"},
[47925] = {id=47925,name="Shoak's on the Menu",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=8500,description="I don't know what stupid thing Shoak did to get captured by the Natha'vor trolls, we'll find out once you rescue him. I bet they're getting ready to make a meal out of Shoak . You need to work fast and get him out! Shoak 's one of the largest oafs that I know, those trolls won't be happy that you're taking their \"meal\" away.",starts={{npcID=124933,x=0.518,y=0.332,zoneID=8500},{npcID=125024,x=0.558,y=0.322,zoneID=8500}},ends={{npcID=124737,x=0.558,y=0.322,zoneID=8500}},coords={x=0.518,y=0.332,source="quest_giver",zoneID=8500},questType="standard"},
[47928] = {id=47928,name="Offering for the Loa",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="The time has come for you to make contact with the great loa Eraka no Kimbul . I can only imagine what it will be like to be in the presence of such an ancient and powerful deity. You have earned the Ring of Tides, so it must be you that addresses the loa. Please present the loa with this offering from our tribe. Tell him of our plight against the naga. Eraka no Kimbul is our only hope of survival now.",starts={{npcID=134133,x=0.584,y=0.118,zoneID=8501}},ends={{npcID=123052,x=0.566,y=0.104,zoneID=8501}},coords={x=0.584,y=0.118,source="quest_giver",zoneID=8501},questType="standard"},
[47939] = {id=47939,name="If the Key Fits...",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="These Ashvane are unreasonable. I've tried to bargain for my release, but they refuse any offer I bring to the table. All they want is whatever's bubbling up in that mine. My kind know better than to go near that stuff. It's volatile. There are prisoners in the mine being forced to extract it. Us in the cages? We're back up. When someone dies in the mines, they just send another in. If you release me, I'll make sure you're rewarded! We just need to find the right key for this cage...",starts={{npcID=128422,x=0.476,y=0.862,zoneID=8501}},ends={{npcID=128422,x=0.476,y=0.862,zoneID=8501}},coords={x=0.476,y=0.862,source="quest_giver",zoneID=8501},questType="standard"},
[47943] = {id=47943,name="Crab Trapping",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="We are trapped here with little in the way of food and supplies. The territorial sethrak control the land to the west, and the spiteful naga the waters to the east. We are caught between a barren desert and a hostile ocean. If you are headed to the lagoon to face the naga, will you bring us back some crabs to eat? I fear that our tribe will soon perish without food...",starts={{npcID=134128,x=0.62,y=0.222,zoneID=8501}},ends={{npcID=134128,x=0.62,y=0.222,zoneID=8501}},coords={x=0.62,y=0.222,source="quest_giver",zoneID=8501},questType="standard"},
[47945] = {id=47945,name="To Market, To Market",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="Thanks heaps for getting us out of that pickle, mainlander. I'd hate to ask, but would you be willing to help with another matter? Even before this curse struck the village, our sausage shipments from Carver's Harbor started slowing down. If we don't get them sausages, I won't be able to feed my family! Can you help an honest sausage merchant out? Carver's Harbor is just down the road from here.",starts={{npcID=128467,x=0.556,y=0.348,zoneID=8721}},ends={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},coords={x=0.556,y=0.348,source="quest_giver",zoneID=8721},questType="standard"},
[47946] = {id=47946,name="Save Their Bacon",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="This is going to sound strange, , but some of my workers were turned into pigs! Lucky I was out on an errand, or I'd have been caught too! Now my people are tied up awaiting... processing. I can't get past those monsters, but you look like the sort who could. Not sure if this helps, but I coulda sworn I heard some wild cackling coming from the warehouse. Please... save my people!",starts={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},ends={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},coords={x=0.632,y=0.27,source="quest_giver",zoneID=8721},questType="standard"},
[47947] = {id=47947,name="Big Bad Wolves",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="Wolves with strange, glowing eyes have taken over the area! I don't know what they are or why they're glowing but it cannot mean anything good. They have to be removed! Please, , slay them before more of my friends are killed.",starts={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},ends={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},coords={x=0.632,y=0.27,source="quest_giver",zoneID=8721},questType="standard"},
[47948] = {id=47948,name="Pork Chop",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="Roland Hacksaw was the best butcher I've ever worked with... but he's gone insane! He's still processing pigs into sausage! You have to stop him!",starts={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},ends={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},coords={x=0.632,y=0.27,source="quest_giver",zoneID=8721},questType="standard"},
[47949] = {id=47949,name="That's Not My Fetish",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="pig fetish seem to follow you as you approach. The dark power emanating from the witch's fetish must be what is keeping the workers transformed. Perhaps Thomas Staughton might have some idea what to do with it.>",starts={{npcID=277459,x=0.634,y=0.302,zoneID=8721}},ends={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},coords={x=0.634,y=0.302,source="quest_giver",zoneID=8721},questType="standard"},
[47950] = {id=47950,name="Cured Ham",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="That foul thing has to be what's keeping my men transformed into pigs. Hmm. Well there isn't too much that can withstand a good cleansing fire! I say we burn it! Toss it into the campfire!",starts={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},ends={{npcID=124786,x=0.632,y=0.27,zoneID=8721}},coords={x=0.632,y=0.27,source="quest_giver",zoneID=8721},questType="standard"},
[47952] = {id=47952,name="The Missing Fleet",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="The tidesage order has a sizable monastery right here in Boralus. I say we start our search for the fleet there. Someone there has to know something, right? You don't just lose the entire legendary Kul Tiran fleet on accident! We'll need to take a ferry over to the monastery. Make sure you bring your pass with you!",starts={{npcID=121235,x=0.68,y=0.22,mapID=1161}},ends={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},coords={x=0.68,y=0.22,source="quest_giver",mapID=942},questType="standard"},
[47959] = {id=47959,name="The Warguard's Trail",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="Rakera's journal suggested she moved south. It's de only lead we have. Meerah is headed dat way, and has invited us to travel with her. These vulpera know de desert better than any troll I've ever met. Our chances of survival are highest if we travel together.",starts={{npcID=130341,x=0.568,y=0.504,zoneID=8501}},ends={{npcID=126696,x=0.532,y=0.662,zoneID=8501}},coords={x=0.568,y=0.504,source="quest_giver",zoneID=8501},questType="standard"},
[47960] = {id=47960,name="Tiragarde Sound",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="We must convince Katherine Proudmoore to pledge Kul Tiras to the Alliance. Flynn believes the Ashvane Trading Company's new gunpowder is our best lead.",ends={{npcID=121235,x=0.68,y=0.22,zoneID=8568}},questType="standard"},
[47961] = {id=47961,name="Drustvar",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8568,description="The stalwart protectors of House Waycrest hold fast along the western border, but recently all contact with them has been lost. We must secure their aid in order to bring Kul Tiras together under the Proudmoore banner.",ends={{npcID=121235,x=0.68,y=0.22,zoneID=8568}},questType="standard"},
[47962] = {id=47962,name="Stormsong Valley",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="The Kul Tiran fleet has been lost at sea. The tidesages of Stormsong, with their mystical oceanic magic, may be our only way to locate the fleet of legend.",ends={{npcID=121235,x=0.68,y=0.22,mapID=1161}},questType="standard"},
[47963] = {id=47963,name="The Ancient One",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dis is far worse than I thought. Pa'ku is crying out in my mind. Dey are doing something to her. Something old and terrible, smelling of de old ways. She is nearby, just south of here. Come, $p, meet me at Pa'ku 's roost and we'll rescue her.",starts={{npcID=133653,x=0.506,y=0.296,mapID=862}},ends={{npcID=124756,x=0.496,y=0.266,mapID=862}},coords={x=0.506,y=0.296,source="quest_giver",mapID=862},questType="standard"},
[47965] = {id=47965,name="The Ruined Temple",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="The loa may be our only hope against the naga, but the temple lies abandoned and broken. Two of my tribe have gone ahead to scout the ruins. They may be able to help you make contact with Eraka no Kimbul. If the spirit of the loa remains at the temple, we must find a way for him to hear our plight.",starts={{npcID=123063,x=0.616,y=0.206,zoneID=8501}},ends={{npcID=134133,x=0.584,y=0.118,zoneID=8501}},coords={x=0.616,y=0.206,source="quest_giver",zoneID=8501},questType="standard"},
[47967] = {id=47967,name="An Argus Roper",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="My warriors stand no chance against even the smallest of the Legion's forces without our Cragscalers. If you can capture a few and bring them here, my warriors can better defend our people.",starts={{npcID=126160,x=0.644,y=0.626,zoneID=8574}},ends={{npcID=126160,x=0.644,y=0.626,zoneID=8574}},coords={x=0.644,y=0.626,source="quest_giver",zoneID=8574},questType="standard"},
[47968] = {id=47968,name="Signs and Portents",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,starts={{npcID=272179,x=0.561,y=0.353,zoneID=8721}},ends={{npcID=278669,x=0.556,y=0.357,zoneID=8721}},coords={x=0.561,y=0.353,source="quest_giver",zoneID=8721},questType="standard"},
[47978] = {id=47978,name="The Wayward Crone",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="Helena Gentle recently took up residence in a house down the road from the town. The villagers' writings point to her being involved somehow with a variety of maladies that struck the village recently. It's possible that she may know what's behind this spell, if it hasn't afflicted her as well.>",starts={{npcID=278669,x=0.556,y=0.357,zoneID=8721}},ends={{npcID=124922,x=0.604,y=0.316,zoneID=8721}},coords={x=0.556,y=0.357,source="quest_giver",zoneID=8721},questType="standard"},
[47979] = {id=47979,name="Witch Hunt",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="A curse on the villagers? Oh my, how dreadful! Although, to be honest, there have been some strange happenings around Fallhaven of late. I wonder if these could be culprit? Take a seat and have a spot of tea. I'll tell you all that I know.",starts={{npcID=124922,x=0.604,y=0.316,zoneID=8721}},ends={{npcID=278675,x=0.559,y=0.351,zoneID=8721}},coords={x=0.604,y=0.316,source="quest_giver",zoneID=8721},questType="standard"},
[47980] = {id=47980,name="Furious Familiars",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,starts={{npcID=125093,x=0.608,y=0.306,zoneID=8721}},coords={x=0.608,y=0.306,source="quest_giver",zoneID=8721},questType="standard"},
[47981] = {id=47981,name="Cracking the Curse",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,starts={{npcID=272422,x=0.606,y=0.315,zoneID=8721}},ends={{npcID=278675,x=0.559,y=0.351,zoneID=8721}},coords={x=0.606,y=0.315,source="quest_giver",zoneID=8721},questType="standard"},
[47982] = {id=47982,name="The Final Effigy",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,starts={{npcID=278675,x=0.559,y=0.351,zoneID=8721}},ends={{npcID=124417,x=0.558,y=0.35,zoneID=8721}},coords={x=0.559,y=0.351,source="quest_giver",zoneID=8721},questType="standard"},
[47986] = {id=47986,name="Scars of the Past",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="The Army of the Light's warframes have won countless battles on Argus. Despite their power, not all who descend into the fray return. My modifications to this frame should give us the edge we need, but several critical components are still missing. There are remains of battles past in Nath'raxas that we can still scavenge. If you can find the pieces I need, the Legion will feel our fury yet.",starts={{npcID=124975,x=0.608,y=0.472,zoneID=8574}},ends={{npcID=124975,x=0.608,y=0.472,zoneID=8574}},coords={x=0.608,y=0.472,source="quest_giver",zoneID=8574},questType="standard"},
[47987] = {id=47987,name="Preventive Measures",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="There is no end to the Legion's depravity. Every battle won, every world conquered, yields more souls to fuel their war machine. They have not yet defiled all of the fallen warriors in the hold, but I fear it is only a matter of time. Please, take this talisman with you into the hold and use it to sanctify any corpses you encounter. They deserve a better fate.",starts={{npcID=124974,x=0.61,y=0.476,zoneID=8574}},ends={{npcID=124974,x=0.61,y=0.476,zoneID=8574}},coords={x=0.61,y=0.476,source="quest_giver",zoneID=8574},questType="standard"},
[47988] = {id=47988,name="Chaos Theory",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Despite their strength and their numbers, even the Burning Legion requires order to fight. Disrupt that order... and they fall like the rabble they are. The plan is simple. Let chaos reign in their ranks, and the day will be ours.",starts={{npcID=124972,x=0.606,y=0.44,zoneID=8574}},ends={{npcID=124972,x=0.606,y=0.44,zoneID=8574}},coords={x=0.606,y=0.44,source="quest_giver",zoneID=8574},questType="standard"},
[47989] = {id=47989,name="Heralds of Apocalypse",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="We've been presented with a rare opportunity. Our scouts have spotted two shivarra priestesses in the western fel pools enhancing the Legion's war effort. The inner circle of Sargeras' chosen never leave the walls of Antorus. If we take them out, we might be able to sow fear among those closest to the Dark Titan.",starts={{npcID=125443,x=0.616,y=0.466,zoneID=8574}},ends={{npcID=125443,x=0.616,y=0.466,zoneID=8574}},coords={x=0.616,y=0.466,source="quest_giver",zoneID=8574},questType="standard"},
[47990] = {id=47990,name="A Touch of Fel",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7705,description="Our warframe is almost operational! It just needs a good jolt to revitalize its systems. Warlocks in the pools below infuse pieces of Argus with fel energy to create living siege weapons. If you can extract one, we can use it to jumpstart the warframe's Judgment Core!",questType="standard"},
[47991] = {id=47991,name="Dark Machinations",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Eredar are adept at manipulating the fel that courses through this world. Those who do not shape it into living weapons build other armaments, like the Spires of Woe. The spires will make it difficult for even a small force to penetrate the main stronghold. We must dismantle enough of them to clear the way before we advance upon it.",starts={{npcID=124972,x=0.606,y=0.44,zoneID=8574}},ends={{npcID=124972,x=0.606,y=0.44,zoneID=8574}},coords={x=0.606,y=0.44,source="quest_giver",zoneID=8574},questType="standard"},
[47992] = {id=47992,name="Dawn of Justice",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Thanks to your efforts, our enemy is in disarray and their defenses inoperable. We must take the ground at the spire's base and tighten the noose around their commander's neck. You have more than earned the honor to take the warframe into battle. We will follow your lead once the way is clear.",questType="standard"},
[47993] = {id=47993,name="Lord of the Spire",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="Lord Nath'raxas rules over this hold as thanks for his role in delivering Argus to the Legion many years ago. Make no mistake, he is powerful, but he has also grown overconfident in his seat. Take advantage of his hubris and make use of the warframe's firepower while you can. We will storm the courtyard shortly!",questType="standard"},
[47994] = {id=47994,name="Forming a Bond",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,starts={{npcID=121263,x=0.62,y=0.868,mapID=830},{npcID=121263,x=0.428,y=0.238,mapID=830}},ends={{npcID=121263,x=0.62,y=0.868,mapID=830},{npcID=121263,x=0.428,y=0.238,mapID=830}},coords={x=0.62,y=0.868,source="quest_giver",mapID=885},questType="standard"},
[47995] = {id=47995,name="Overt Ops",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="My soldiers are out there, . I need you to find Baraat, Sorvos, and Telaamon. They were in the process of securing this area for Velen when the Legion came down on top of our heads. Inform them that their orders are to regroup with the Prophet at once. The time for subtlety has passed. There is a small army between us and them. Do what you must. Light keep you safe.",questType="standard"},
[47997] = {id=47997,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[47998] = {id=47998,name="Killing Cannibals",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=8500,description="Shoak and I have had a few run-ins with the Natha'vor trolls. Must be why they wanted to capture that idiot. The women in that tribe actually eat the men... and anyone else they can get their hands on. I'm sure they're getting ready to eat Shoak. Do us all a favor and kill some of those cannibals. The world would be a better place without them.",starts={{npcID=124933,x=0.518,y=0.332,zoneID=8500}},ends={{npcID=125024,x=0.558,y=0.322,zoneID=8500}},coords={x=0.518,y=0.332,source="quest_giver",zoneID=8500},questType="standard"},
[47999] = {id=47999,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[48000] = {id=48000,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[48002] = {id=48002,name="Limited Supplies",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Hello, . It's good to see a fellow alchemist again. I've been supplying our camp with necessary potions to deal with the demons, but lately I've been running low on supplies. Normally when scouting parties go out, they return with empty vials, but as of late fewer have been returning. I try to recycle as much as I can, so you see, those vials are precious to me. If you'd be willing to go out and retrieve them, I could show you what I've been making to help combat the demons.",starts={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},ends={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},coords={x=0.562,y=0.668,source="quest_giver",zoneID=8574},questType="standard"},
[48003] = {id=48003,name="The Lord's Behest",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="Lord Norwington will want to thank you for saving his son himself. Why don't you come to the estate? We're preparing for a festival, and everybody's welcome. We'll go ahead and tell him of all that has happened. See you there!",starts={{npcID=127144,x=0.544,y=0.194,zoneID=8567}},ends={{npcID=124802,x=0.516,y=0.272,zoneID=8567}},coords={x=0.544,y=0.194,source="quest_giver",zoneID=8567},questType="standard"},
[48004] = {id=48004,name="Beginner Equitation",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="You may know how to ride already, but you don't know how to ride like a Kul Tiran! We'll let you borrow a horse for the festivities. Take one of our lesson masters, Cooper . He's trained many a beginner in his day! Mount up, get in the ring, and show us what you've got! I'm sure you'll be a quick learner!",starts={{npcID=124802,x=0.516,y=0.272,zoneID=8567}},ends={{npcID=124802,x=0.516,y=0.272,zoneID=8567}},coords={x=0.516,y=0.272,source="quest_giver",zoneID=8567},questType="standard"},
[48005] = {id=48005,name="Be Our Guest",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="My dear friend , I do hope you enjoy the festival. I throw it every year to bring riders from all over Kul Tiras together for a grand celebration of the sport! In fact, you deserve the whole nine yards. Please, tour the estate at your leisure and partake in the delicious food and drink, introduce yourself to the people. I insist!",starts={{npcID=124802,x=0.516,y=0.272,zoneID=8567}},ends={{npcID=124802,x=0.516,y=0.272,zoneID=8567}},coords={x=0.516,y=0.272,source="quest_giver",zoneID=8567},questType="standard"},
[48008] = {id=48008,name="Dangerous Cargo",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="By the time I realized what was happening, it was too late. People had been acting strange, but I thought nothing of it. After all, they seemed to still be doing their jobs. While inspecting some of the cargo, this grub jumped out in an attempt to latch onto my face. I managed to take it out, but it was too late. All of the shipments are infected. Take this torch. Destroy them.",starts={{npcID=125962,x=0.376,y=0.296,zoneID=8567}},ends={{npcID=125962,x=0.376,y=0.296,zoneID=8567}},coords={x=0.376,y=0.296,source="quest_giver",zoneID=8567},questType="standard"},
[48009] = {id=48009,name="Betrayal of the Guard",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="My boys have gotten in too deep. They've given in to whatever dark forces are at work here. Do not hesitate to do what you need to and put them down. They knew what they were signing up for when they picked the wrong side.",starts={{npcID=126308,x=0.352,y=0.242,zoneID=8567}},ends={{npcID=126308,x=0.352,y=0.242,zoneID=8567}},coords={x=0.352,y=0.242,source="quest_giver",zoneID=8567},questType="standard"},
[48013] = {id=48013,name="Tracking the Trackers",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description=", have I told you about my tracking potion? Our scouts use it to track demons, especially their \"fiends\". Those particular creatures tend to consume the astral glory in the area, making it difficult to replenish our stores of the herb. If you could help thin their numbers out, it would greatly help us from having to search elsewhere for supplies. You can find many of them in the Annihilan Pits. I could also teach you the recipe for this potion for your effort.",starts={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},ends={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},coords={x=0.562,y=0.668,source="quest_giver",zoneID=8574},questType="standard"},
[48014] = {id=48014,name="Clear the Riffraff",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,description="The naga sent their tiny, foul, muck-smelling minions into our camp. They are quite bothersome. If we do nothing, and their numbers continue to grow, they could pose a threat. You look quick and handy. Could you perhaps expunge a few for us?",starts={{npcID=125047,x=0.814,y=0.458,zoneID=8499}},ends={{npcID=125039,x=0.792,y=0.422,zoneID=8499}},coords={x=0.814,y=0.458,source="quest_giver",zoneID=8499},questType="standard"},
[48015] = {id=48015,name="The Scrolls of Gral",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,description="These gilblins are ridiculous! They are like a swarm of angry bees, buzzing around. Hmm, maybe not bees. Bees are useful, and make honey, and don't steal things. They ransacked our scrolls. Most were unusable, but there were three that are quite... potent. It would be most unfortunate if those made it back to their masters, the naga. Please clean up their mess and bring back our scrolls.",starts={{npcID=125047,x=0.814,y=0.458,zoneID=8499}},ends={{npcID=125041,x=0.792,y=0.42,zoneID=8499}},coords={x=0.814,y=0.458,source="quest_giver",zoneID=8499},questType="standard"},
[48016] = {id=48016,name="Ascending Alchemy",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="I've seen other alchemists come through our camp carrying interesting looking trinkets. I believe they refer to them as... \"alchemist stones\"? I can sense the power they radiate, but they appear fel-tainted. The herb that grows on this planet is particularly good at cleansing corruption. I use it to purify the primal sargerite that's often found amongst the herbs. I'm certain that if we used a purified sargerite with one of those stones, we could elevate the power within it.",starts={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},ends={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},coords={x=0.562,y=0.668,source="quest_giver",zoneID=8574},questType="standard"},
[48021] = {id=48021,name="Chromie",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,description=". Is that you? I'm convinced that something unusual has happened in the timelines. I need your help! Come find me at Wyrmrest Temple, in Dragonblight, and I'll show you.",questType="standard"},
[48023] = {id=48023,name="Orders Received",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We need ta be knowin' who be leadin' da naga in snatchin' all dese cute frogs. Dey got chests around here dat have some kind of scroll dey be readin'. Da ladies be tellin' da men to remember dem orders. Get me some of dem scrolls so we can be seein' who be callin' da shots.",questType="standard"},
[48025] = {id=48025,name="Saving for Later",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,description="We need time to recover the artifacts from this place. Time the naga will not let us have. However, we do have a plan. We simply hide what we don't want them to find, and then come back in a decade or two. They will have forgotten about this place by then. Take this illusion scroll and use it to conceal the notable artifacts of power.",starts={{npcID=125041,x=0.792,y=0.42,zoneID=8499}},ends={{npcID=125041,x=0.792,y=0.42,zoneID=8499}},coords={x=0.792,y=0.42,source="quest_giver",zoneID=8499},questType="standard"},
[48026] = {id=48026,name="Beneath the Waves",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,description="Those witches dare! In my temple? Siavass is stretching past the realm of that which she can comprehend. There is a darkness seeking them, and they call to it! Her kind will become no more than a hollow tool to those who may answer. I feel it moving beneath us, around us. I feel it like a tremor through my being. There is a pressure there, it has a weight greater than that of the deepest ocean. We must stop them. They are not welcome here!",ends={{npcID=131461,x=0.837,y=0.442,zoneID=8499}},questType="standard"},
[48027] = {id=48027,name="The Glory of Argus",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,ends={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},questType="standard"},
[48028] = {id=48028,name="Youthful Resistance",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,ends={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},questType="standard"},
[48029] = {id=48029,name="The Heart of It",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,ends={{npcID=125346,x=0.562,y=0.668,zoneID=8574}},questType="standard"},
[48030] = {id=48030,name="FLAG - Stratholme Scene Seen",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[48031] = {id=48031,name="FLAG - Andorhal Scene Seen",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[48032] = {id=48032,name="FLAG - Hyjal Scene Seen",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[48033] = {id=48033,name="FLAG - Well of Eternity Scene Seen",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[48034] = {id=48034,name="Empyrium Deposit Chunk",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,questType="standard"},
[48035] = {id=48035,name="Angling For a Better Strike",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,description="empyrium dust from taking down this deposit, you wonder if there's a way to prevent part of the deposit from shattering with each impact.> Khamir will know something further that he can share with you.>",questType="standard"},
[48036] = {id=48036,name="Precision Perfected",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,description="Khamir might be needed to correct this problem.>",questType="standard"},
[48037] = {id=48037,name="Empyrium Seam Chunk",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,questType="standard"},
[48038] = {id=48038,name="Don't Just Pick At It",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,description="Khamir can show you a way to remove the ore from these sections of the seam.>",questType="standard"},
[48039] = {id=48039,name="Balancing the Break",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,description="Khamir might know a way to prevent this from happening.>",questType="standard"},
[48040] = {id=48040,name="Tainted Scraps",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,questType="standard"},
[48041] = {id=48041,name="A Larger Cut",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,description="Enstraa might have a better idea of how to remove more of the hide before it becomes tainted.>",questType="standard"},
[48042] = {id=48042,name="Order of Operations",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,description="Enstraa back at the Vindicaar.>",questType="standard"},
[48043] = {id=48043,name="FLAG - Plating Cleared",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[48044] = {id=48044,name="FLAG - Shields Cleared",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[48053] = {id=48053,name="Weigh Anchor",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=1519,description=", I was hoping to ask you for a small favor. The naval fleet at Stormwind Harbor have been requesting large amounts of felslate to help construct supplies for their ships. I'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them? I heard there's a portal to Stormwind in the Greyfang Enclave here in Dalaran so it shouldn't be a long trip or anything.",ends={{npcID=125210,x=0.31,y=0.122,zoneID=1519}},questType="standard"},
[48054] = {id=48054,name="Weigh Anchor",level=45,requiredLevel=45,faction="horde",expansion=7,zoneID=16,description=", I was hoping to ask you for a small favor. The naval fleet at Bilgewater Harbor have been requesting large amounts of felslate to help construct supplies for their ships. I'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them? I heard there's a portal to Orgrimmar in the Windrunner's Sanctuary here in Dalaran so it shouldn't be a long trip or anything.",ends={{npcID=125216,x=0.552,y=0.534,zoneID=16}},questType="standard"},
[48055] = {id=48055,name="Empyrial Strength",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="I see my armor's caught your interest. It's made from the finest material on Argus: empyrium. I actually specialize in crafting breastplates. I could show you how to craft one, but you'll need to bring your own supplies, I'm afraid. Our stores of the ore are low and we need all that we have. But here are the plans so you'll know what you need to find...",questType="standard"},
[48056] = {id=48056,name="A Harsh Mistress",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,description="So there I was thinkin' about how to get everyone ready for movin' around Argul or whatever it's called, since I figure its gravity is different than ours, and I come up with a design for a device you slip onto your shoes, or hooves or whatever you're wearin' down there. Next thing I hear, the gravity on that planet? Completely the same as ours! Regardless, I figure I could get the prototype workin'. Mind givin' me a hand? Maybe when we're done you can like, sell 'em to kids or somethin'.",questType="standard"},
[48065] = {id=48065,name="Extraterrestrial Exploration",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,description=", I hear you've been over to that large green planet in the sky already. Swarming with demons too, I hear. I was thinking maybe we could put together another wormhole generator for it. Make it easier to zip around the planet. Problem is we need to get readings on the landscape, and I'd go, but uh... well I need to stay here and run the shop. Can't leave it to these bozos to handle. Here, take this and get some readings for me, will ya?",questType="standard"},
[48066] = {id=48066,name="A Feast for Our Kin",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=1638,description="Ah, the Highmountain tauren. They have been our allies ever since we felled the Legion. Are you interested in hearing how they joined the Horde? It is quite the tale! It all began with Baine Bloodhoof and Mayla Highmountain. Baine was hosting a great feast in Thunder Bluff to welcome the Highmountain tauren...",starts={{npcID=125285,x=0.38,y=0.81,zoneID=1637},{npcID=133523,x=0.378,y=0.81,zoneID=1637}},ends={{npcID=93844,x=0.612,y=0.518,zoneID=1638}},coords={x=0.38,y=0.81,source="quest_giver",zoneID=1637},questType="standard"},
[48067] = {id=48067,name="Shadow Over Thunder Bluff",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=7503,description="A dark force has descended upon us. I refuse to believe that the Highmountain are behind it. The cacophony out there is disturbingly familiar. Could it be... No! The minions of the Old Gods are attacking! We must fight for Thunder Bluff, !",starts={{npcID=129914,x=0.612,y=0.518,zoneID=1638}},coords={x=0.612,y=0.518,source="quest_giver",zoneID=1638},questType="standard"},
[48069] = {id=48069,name="The Wrench Calls",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,description=", Didi the Wrench is looking for you back in Dalaran. You might want to see what she's working on. Pretty fancy stuff from what I heard.",questType="standard"},
[48070] = {id=48070,name="The Norwington Festival",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="To whomever receives this invitation, You are cordially invited to the 15th annual Norwington Equestrian and Hunt Festival! People of all walks of life from across Kul Tiras shall gather to delight in life's greatest competitions, equestrianism and hunting, while meeting those of like minds and fine tastes. Hunting events shall start first, led by Abbey Watkins in Foxhollow Woods. They shall be followed by equestrian events at the Norwington Estate. We hope to see you there posthaste!",starts={{npcID=281230,x=0.671,y=0.248,zoneID=8567}},ends={{npcID=125309,x=0.554,y=0.246,zoneID=8567}},coords={x=0.671,y=0.248,source="quest_giver",zoneID=8567},questType="standard"},
[48074] = {id=48074,name="Looming Over Me",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="When I rallied to the Xenedar, I left behind a valuable tool. My lightweave loom . Without it, I'm forced to labor for much longer to make garments of power for our allies. But you are powerful, much more so than I. Perhaps you could do me a favor. Should you happen to be in the Arinor Gardens, could you retrieve my loom and return it to me? I'd be more than willing to share my knowledge of sewing lightweave with you.",questType="standard"},
[48075] = {id=48075,name="A Colorful Key",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description=", I hear you're a jewelcrafter. I too am a master cutter, but I fear my designs will be lost to the Legion. I hurried out of my home with the intention of returning, but I fear that may not be a possibility. You see, I left my most prized possession, a book of jewelcrafting designs. But you, you're strong, you could fight your way into my home and recover my book! However, I locked it away in a special chest that requires the gems of this land to unlock. You'll need one of each to open it.",questType="standard"},
[48076] = {id=48076,name="A Crowning Achievement",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="With my book nearly being lost forever, it occurs to me that I shouldn't keep all this knowledge in one place. I would like to pass it along to you, . My most recent designs are ones that I am particularly proud of. I call them Empyrial Crowns . Each one uses a different combination of gems to render different effects of power. Let me show you how to construct one and then I'll show you how different combinations of gems create different results.",questType="standard"},
[48077] = {id=48077,name="The Stoat Hunt",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="One of the greatest hunting sports amongst the nobles of Boralus is the stoat hunt. It is a sport of determination, patience, and skill. Do you think you can rise to the challenge? Stoats are agile, sneaky, and sharp. They're next to impossible to catch out in the forest, so the best way to find one is to find its burrow and scare it out. Find their burrows and bring back their pelts. Their fur is soft and much loved amongst the nobles.",starts={{npcID=125309,x=0.554,y=0.246,zoneID=8567}},ends={{npcID=125309,x=0.554,y=0.246,zoneID=8567}},coords={x=0.554,y=0.246,source="quest_giver",zoneID=8567},questType="standard"},
[48078] = {id=48078,name="Counterbalancing",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="In the past, I was able to make glorious items from the beasts of this land. But then the Legion came and wiped out all those amazing beasts. Now I'm forced to use their polluted hides to craft armor for my allies. I have, however, found a way to remove their taint. The cloth we use is made from special thread infused with Light energy. I devised an oil which when combined with the cloth purifies the leather and makes it usable. Here, take my oil and see for yourself.",questType="standard"},
[48079] = {id=48079,name="Return to Highmountain",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=7731,description="Spiritwalker Ebonhorn remains in great danger. He and Mayla have returned to Highmountain, but I believe they still need our aid. Let us journey to Thunder Totem and do whatever we can to mend Ebonhorn. Perhaps our deeds will strengthen the bond between our peoples.",ends={{npcID=108434,x=0.446,y=0.504,zoneID=7731}},questType="standard"},
[48080] = {id=48080,name="An Element of Danger",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="These nobles really think killing weasels is the mark of a good hunter? Ha! It ain't hunting if there isn't a bit of danger involved. There are boars in these woods. That's more our speed out in the mountains! Why don't you kill some of those, then bring me their tusks as proof?",starts={{npcID=125398,x=0.554,y=0.246,zoneID=8567}},ends={{npcID=125398,x=0.554,y=0.246,zoneID=8567}},coords={x=0.554,y=0.246,source="quest_giver",zoneID=8567},questType="standard"},
[48081] = {id=48081,name="A Floating Ruin",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,description="We knew the Legion to be a formidable foe, but recent events demonstrate that we do not possess the necessary strength to continue. We have come too far to fail at this critical moment. I know of a relic on Eredath , my ancient home, that may be our salvation. We must take the Vindicaar beyond the surface of Argus, to the floating ruin suspended above us. Perhaps there we will find the salvation we so desperately need.",starts={{npcID=126307,x=0.618,y=0.868,zoneID=8574},{npcID=126307,x=0.406,y=0.246,zoneID=8574}},coords={x=0.618,y=0.868,source="quest_giver",zoneID=8574},questType="standard"},
[48082] = {id=48082,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8524,mapID=646,questType="standard"},
[48083] = {id=48083,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8524,mapID=646,questType="standard"},
[48084] = {id=48084,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8524,mapID=646,questType="standard"},
[48085] = {id=48085,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8524,mapID=646,questType="standard"},
[48087] = {id=48087,name="Equine Retrieval",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="I like the cut of your jib, friend! I'll tell you what. The rest of the partygoers should be arriving any time now. Would you do me the honor of retrieving my favorite horse from the estate on the hill? Imagine, our guests' first impression of you to be on the most regal horse in all of Tiragarde! Wondrous!",starts={{npcID=124802,x=0.516,y=0.272,zoneID=8567}},ends={{npcID=127559,x=0.524,y=0.284,zoneID=8567}},coords={x=0.516,y=0.272,source="quest_giver",zoneID=8567},questType="standard"},
[48088] = {id=48088,name="No Party Like a Trogg Party",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="Troggs? At my party? My grandfather pushed them back to that cleft years ago to build this estate. To think that they would attack in such force after all these years? This is just what we needed to make this year's festival the greatest ever! Show us your heroism firsthand, ! Mount Cooper and defeat these troggs! Drag them behind you, jab them with your harpoon... whatever it takes!",starts={{npcID=127559,x=0.524,y=0.284,zoneID=8567}},ends={{npcID=127559,x=0.524,y=0.284,zoneID=8567}},coords={x=0.524,y=0.284,source="quest_giver",zoneID=8567},questType="standard"},
[48089] = {id=48089,name="Mountain Sounds",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="Kul Tirans won't go down without a fight! Take this horn. We use it in the mountains to warn each other of danger and lead the charge into battle. Use it to rally our allies against the troggs!",starts={{npcID=125042,x=0.524,y=0.286,zoneID=8567}},ends={{npcID=125042,x=0.524,y=0.286,zoneID=8567}},coords={x=0.524,y=0.286,source="quest_giver",zoneID=8567},questType="standard"},
[48090] = {id=48090,name="Krag'wa's Chosen",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,description="Dis be a real mess, . Da naga be drainin' da magic of Krag'wa's frogs ta feed demselves! Dere be three frogs, Krag'wa's champions, dat dey be torturin' as we speak. Take dis potion, it be returnin' da power of dem noble frogs. Dey deserve better dan bein' drained by dese snake bastards. I be stayin' here. Da naga got in some lucky hits on me. All me life, I wanted ta see Krag'wa, and I let meself get hurt by some naga!",starts={{npcID=125317,x=0.776,y=0.532,zoneID=8500}},ends={{npcID=125317,x=0.776,y=0.532,zoneID=8500}},coords={x=0.776,y=0.532,source="quest_giver",zoneID=8500},questType="standard"},
[48092] = {id=48092,name="Vengeance of the Frogs",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,description="Da naga here be led by a priestess, Zaldraxia. She be da one dat figured out how ta drain da frogs of their magic. Zaldraxia be stoppin' at nothin' ta drain every frog here. Do what I could not, and kill dis priestess. Show da naga dat Krag'wa ain't a loa ta be takin' lightly. I be prayin' ta Krag'wa for ya success.",starts={{npcID=125317,x=0.776,y=0.532,zoneID=8500}},ends={{npcID=125317,x=0.776,y=0.532,zoneID=8500}},coords={x=0.776,y=0.532,source="quest_giver",zoneID=8500},questType="standard"},
[48107] = {id=48107,name="The Sigil of Awakening",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="This relic is too powerful to keep it out in the open. We must return to the Vindicaar at once. The Prophet will know what to do. I did want to thank you, . Without you this would not be possible. Quoram would have ensured I never got near the Sigil. Perhaps some day I will share that story with you.",starts={{npcID=123413,x=0.632,y=0.398,zoneID=8701}},ends={{npcID=120533,x=0.544,y=0.778,zoneID=8701}},coords={x=0.632,y=0.398,source="quest_giver",zoneID=8701},questType="standard"},
[48108] = {id=48108,name="The Waycrest Daughter",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="You seek House Waycrest? Oh, your timing could not be worse! I had just received a raven regarding Lord Waycrest's daughter, Lucille, shortly before this... curse came upon us. They apprehended her in Fletcher's Hollow and are taking her to trial. They say she is a witch, herself! If she's found guilty, she will surely hang! You must make haste to Hangman's Point. With what you've seen here, maybe you can convince them of her innocence.",starts={{npcID=124417,x=0.558,y=0.35,zoneID=8721}},ends={{npcID=125394,x=0.7,y=0.428,zoneID=8721}},coords={x=0.558,y=0.35,source="quest_giver",zoneID=8721},questType="standard"},
[48109] = {id=48109,name="The Woods Have Eyes",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="The sooner I can return the lady Waycrest to Highroad Gate the better, but I will honor her wishes if we can assure her safety. There are dark things happening in these lands that you don't fully understand. If we must dally, then there are measures that need be taken. First, the wildlife here can serve as eyes to dark powers. Kill them.",starts={{npcID=125385,x=0.696,y=0.432,zoneID=8721}},ends={{npcID=125385,x=0.696,y=0.432,zoneID=8721}},coords={x=0.696,y=0.432,source="quest_giver",zoneID=8721},questType="standard"},
[48110] = {id=48110,name="In Case of Ambush",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="There is more to worry about in these woods than simple beasts. Our enemy employs constructs of wicker and bone that can rip a man apart. Fortunately for us, these constructs are not very perceptive. Take these traps and set them up throughout the woods behind us. If our enemies do seek to ambush us here, at least these will slow their minions down.",starts={{npcID=125385,x=0.696,y=0.432,zoneID=8721}},ends={{npcID=125385,x=0.696,y=0.432,zoneID=8721}},coords={x=0.696,y=0.432,source="quest_giver",zoneID=8721},questType="standard"},
[48111] = {id=48111,name="Trial by Superstition",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="Witchcraft has long lived in the superstitions of the people here. It is only recently that some of these superstitions have become reality. According to tradition, one who is tried for witchcraft is allowed to choose the means by which they are tested from among the requests of her peers. The villagers here no doubt have some strange beliefs of what witches can and cannot do. Speak with them, and see what we can do to prove my innocence.",starts={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},ends={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},coords={x=0.7,y=0.428,source="quest_giver",zoneID=8721},questType="standard"},
[48113] = {id=48113,name="A Pungent Solution",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="The first test should be simple enough. While I may not do so often, I am certainly capable of crying. Though to be honest, I've never had to cry on cue. Maybe you could help with that, though. Nearby there is an onion field that belonged to one of the local farmers. It's abandoned, and most of it is dried up by now, but you might be able to find one onion ripe enough in there to cause some tears.",starts={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},ends={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},coords={x=0.7,y=0.428,source="quest_giver",zoneID=8721},questType="standard"},
[48165] = {id=48165,name="Harmful If Swallowed",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="This last test I am not looking forward to, but it is certainly better than being set on fire. They say that a witch can't get sick. We will prove to them that I can. A venom comes from the saurolisks nearby that is used by our healers when a child swallows something they shouldn't. When ingested, it will make you immediately ill, emptying the contents of the stomach. You'll need several of their venom glands to get enough venom for an appropriate dose. Removing them intact may prove difficult.",starts={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},ends={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},coords={x=0.7,y=0.428,source="quest_giver",zoneID=8721},questType="standard"},
[48170] = {id=48170,name="Once Bitten, Twice Shy",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="I am all too familiar with the bloodfly's bite. We had them all over the fields surrounding Waycrest Manor. Though I'm loath to subject myself to them on purpose, if it will help convince these people, I am willing to deal with that nuisance. Find a jar and collect as many bloodflies as you can. They are common in these parts, and shouldn't be hard to find.",starts={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},ends={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},coords={x=0.7,y=0.428,source="quest_giver",zoneID=8721},questType="standard"},
[48171] = {id=48171,name="The Curse of Fletcher's Hollow",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="It's obvious the constable won't be swayed until we discover what happened at Fletcher's Hollow. I know very little myself--only that the village has been overrun by monstrous creatures. I must ask that you travel there in my stead and try to uncover what befell the village. I'm sure Marshal Reade will prevent the constable from harming me while you're away. Do this for me, and I will help you as I can.",starts={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},ends={{npcID=126310,x=0.7,y=0.602,zoneID=8721}},coords={x=0.7,y=0.428,source="quest_giver",zoneID=8721},questType="standard"},
[48176] = {id=48176,name="Big Trouble in Little Tortolla",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I received a message asking for a sword hand in Little Tortolla. The Tortollan Seekers there are greatly admired by King Rastakhan and have special privileges assigned to them. Go see what they want and you will have the favor of the King. And $p, be respectful. Tortollans live long enough they can hold your children's children accountable for your actions.",questType="standard"},
[48179] = {id=48179,name="Rescue Rangers",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="We're barely holding off those monsters here. If it hadn't been for the Thornspeakers, we'd surely be dead. I was worried Rebecca hadn't made it! You've brought Rebecca's supplies just in time. We have many injured out in the field, Thornspeaker, ranger, and companion alike. I'll hold the line here. Go into the ruins and heal as many of the wounded as you can!",starts={{npcID=139912,x=0.618,y=0.592,zoneID=8721}},ends={{npcID=139912,x=0.618,y=0.592,zoneID=8721}},coords={x=0.618,y=0.592,source="quest_giver",zoneID=8721},questType="standard"},
[48180] = {id=48180,name="Really Big Problem",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="Hey! Mainlander! I know I'm supposed to be trying to knock over cairns and hauling out lost rangers, but d'you see that massive stone monster? I'm thinking that's gonna be a problem. You look like you know how to handle yourself. Think between the two of us we can take it down?",starts={{npcID=140048,x=0.584,y=0.632,zoneID=8721}},ends={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},coords={x=0.584,y=0.632,source="quest_giver",zoneID=8721},questType="standard"},
[48182] = {id=48182,name="Total Cairnage",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="My mentor sensed the activation of ancient powers here. We came to stop them but were too late. We banded together with the rangers for mutual protection, but our task remains unfinished. There is a set of ancient cairns here. These help empower the Drust constructs. Destroying them will also help to settle the undead stirring from the land. Destroy the cairns and we'll be able to bring sanity to this place.",starts={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},ends={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},coords={x=0.618,y=0.594,source="quest_giver",zoneID=8721},questType="standard"},
[48183] = {id=48183,name="The Hills Are Alive",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="The Drust constructs are drawn from the land, but the heart of these constructs is a runic power core . We have been trying to collect and destroy as many of these cores as we can. We know of a way to disrupt the magic in the core. Doing so will prevent more of these monstrosities from being created around the dark hearts and protect the land and all living in this region. Bring me as many Runic Power Cores as you can find and the Thornspeakers will see they are put to good use.",starts={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},ends={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},coords={x=0.618,y=0.594,source="quest_giver",zoneID=8721},questType="standard"},
[48184] = {id=48184,name="Pieces of History",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="There is an opportunity here. Learning more about the Drust can not only help us understand the texts that Lady Lucille found, we might be able to discover greater details about how they and their constructs were finally defeated. Filling in the gaps of history could be key to victory now. This was one of their settlements before it became the place of their final defeat. Let's look for clues in the ruins.",starts={{npcID=129983,x=0.402,y=0.564,zoneID=8721}},ends={{npcID=129983,x=0.402,y=0.564,zoneID=8721}},coords={x=0.402,y=0.564,source="quest_giver",zoneID=8721},questType="standard"},
[48185] = {id=48185,name="Shadow of the Sepulcher",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=7503,description="Ebonhorn spoke of another ward safeguarding the lands of the Skyhorn tribe. Somewhere close to the Sepulcher of the Sky, he said. It was there that this \"Darkness\" once manifested. Meet me there, . I will show you how to walk in the memories of a great Skyhorn hero.",starts={{npcID=125454,x=0.386,y=0.69,zoneID=7503}},ends={{npcID=125459,x=0.57,y=0.462,zoneID=7503}},coords={x=0.386,y=0.69,source="quest_giver",zoneID=7503},questType="standard"},
[48190] = {id=48190,name="Huln's Mountain",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=7503,description="We have made progress reactivating the wards, but more must be done. I sense Ebonhorn's struggle. Though he fights with all his strength, he is slipping away. Should this \"Darkness\" emerge into our realm, I fear our friend will be lost. Ebonhorn spoke of another ward somewhere within Snowblind Mesa. Meet me there, so that I might guide you along another journey into the memories of the past.",starts={{npcID=125459,x=0.57,y=0.462,zoneID=7503}},ends={{npcID=125466,x=0.532,y=0.64,zoneID=7503}},coords={x=0.57,y=0.462,source="quest_giver",zoneID=7503},questType="standard"},
[48195] = {id=48195,name="Troublesome Troglodytes",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="Troggs are base creatures. They barely have any brain process, living mostly on survival instinct alone. They are pests through and through, and need to be dealt with. The fewer of them there are, the better.",starts={{npcID=127144,x=0.544,y=0.194,zoneID=8567}},ends={{npcID=127144,x=0.544,y=0.194,zoneID=8567}},coords={x=0.544,y=0.194,source="quest_giver",zoneID=8567},questType="standard"},
[48196] = {id=48196,name="Following Eddie's Trail",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="My life is equestrian. I'm not a fighter. I could maybe take a trogg or two, but not a whole tribe. Please, go into Mistfall Cleft and see if you can find Eddie. Lord Norwington would be furious if something happened to him, and nobody wants to bear witness to that!",starts={{npcID=127144,x=0.544,y=0.194,zoneID=8567}},ends={{npcID=127091,x=0.556,y=0.146,zoneID=8567}},coords={x=0.544,y=0.194,source="quest_giver",zoneID=8567},questType="standard"},
[48198] = {id=48198,name="The Burden of Proof",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="I think we have everything we need to conduct three of the villagers' tests. Let us hope this is enough to convince them. I'm sure Constable Framer is champing at the bit to proceed with his trial, and I would prefer it if you were the one to administer the tests. I may not know you well, but I trust you farther than the constable. Speak with him when you're ready to begin. ...and do me a favor. Make this quick.",starts={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},ends={{npcID=125380,x=0.7,y=0.428,zoneID=8721}},coords={x=0.7,y=0.428,source="quest_giver",zoneID=8721},questType="standard"},
[48199] = {id=48199,name="The Burning Heart",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="The loss of Xe'ra is a blow, especially to Turalyon. But even the Light Mother could not be allowed to force destiny upon us. I wish Illidan had found another way to refuse her... but I too have had choices imposed upon me by the naaru. This must not distract us from our mission. Now that we have the Army of the Light survivors with us, it is time to press our attack. We need a foothold on the Antoran Wastes from which we can assault the Burning Throne. It is time to deprive Sargeras of his prize!",starts={{npcID=126307,x=0.618,y=0.868,zoneID=8574},{npcID=126307,x=0.406,y=0.246,zoneID=8574}},coords={x=0.618,y=0.868,source="quest_giver",zoneID=8574},questType="standard"},
[48200] = {id=48200,name="Securing a Foothold",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="Alleria and I have scouted this area before, alongside some of our best soldiers. We stationed encampments on either side of our current position, but I fear they will have come under heavy attack. They need reinforcements. Our first order of business is to set up a teleportation beacon directly below the Vindicaar. From there, we will have access to both fronts. Speak to Romuul when you are ready to head down to the surface.",questType="standard"},
[48201] = {id=48201,name="Reinforce Light's Purchase",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="Now that we have established a foothold, we need to rendezvous with our soldiers in the field. We have an Army of the Light encampment to the south, near where the Legion is keeping their strongest warriors in some sort of stasis. Alleria went to scout the area. Find her, and see what information she has gathered.",questType="standard"},
[48202] = {id=48202,name="Reinforce the Veiled Den",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="The foothold you established allows us to check in with our field operatives. On our last mission here, we set up a bastion to the northeast. It should be defensible for now, but that could change at any moment. Illidan has gone ahead to assess the situation. I suggest you go there and see if he needs a hand.",questType="standard"},
[48203] = {id=48203,name="The Burning Throne",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="The time has come, , to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment. We will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion. After all you have done, it is fitting that you have the honor. Activate the Crown of the Triumvirate and let us finish our mission.",starts={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[48230] = {id=48230,name="Fragment of the Past",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,mapID=882,description="Captain Fareeya would be able to tell you more about the crystal.>",questType="standard"},
[48231] = {id=48231,name="The Seat of the Triumvirate: Armor of the Triumvirate",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8910,description="This reforged key will grant entry into the armory inside the Seat of the Triumvirate . Locked away inside is the Armor of the Triumvirate , crafted in the days before Sargeras brought ruin to our world. We cannot let this armor be stolen by the Void's forces. Once the armor is in your possession, please bring it to Archivist Ionaa . He has collected our most sacred relics in the cave just up the path. No doubt he would be very glad to receive it.",starts={{npcID=125246,x=0.568,y=0.686,zoneID=8574}},ends={{npcID=125247,x=0.562,y=0.7,zoneID=8574}},coords={x=0.568,y=0.686,source="quest_giver",zoneID=8574},questType="dungeon"},
[48261] = {id=48261,name="The Power to Reforge",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="I forged the key using a pristine argunite crystal. Unfortunately, the only ones remaining are used by the Army of the Light's defenses. Hmm... dendrite clusters might be an alternative. They were used by the elite of Eredath to power simple devices. If enough of the city ruins are still intact, I'd wager the fallen magi or the broken may still have some in their possession. Of course, I would need a great many clusters to reforge the key. It seems you have your work cut out for you.",starts={{npcID=125246,x=0.568,y=0.686,zoneID=8574}},ends={{npcID=125246,x=0.568,y=0.686,zoneID=8574}},coords={x=0.568,y=0.686,source="quest_giver",zoneID=8574},questType="standard"},
[48271] = {id=48271,name="Recovering the Pieces",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="The fragment you found is only one part of the key. I fear the other pieces have fallen into the hands of these ethereal beings you speak of... the Shadowguard. We must recover them all. The Shadowguard leaders and lieutenants in and around the Seat of the Triumvirate may well have the fragments in their possession. Get those key fragments, ... any way you have to.",starts={{npcID=125246,x=0.568,y=0.686,zoneID=8574}},ends={{npcID=125246,x=0.568,y=0.686,zoneID=8574}},coords={x=0.568,y=0.686,source="quest_giver",zoneID=8574},questType="group"},
[48272] = {id=48272,name="Visions of Fear",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="I've done it, . I've reached him again! Oh, but it's so painful. So painful! He's not doin' well, not one bit! You'll have to listen on in with me to understand.",starts={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},ends={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},coords={x=0.57,y=0.656,source="quest_giver",zoneID=8574},questType="standard"},
[48273] = {id=48273,name="The Speaker Listens",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="Magni has sent for you in Krokul Hovel once more. He seems to have made a new breakthrough in trying to reach Argus. I suggest you find him immediately. His last vision foretold Aggramar's coming, and there is still so much we do not know of Sargeras' plans.",starts={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},ends={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[48277] = {id=48277,name="The Speaker Seeks",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,description="Our forces are ready for battle, but we still do not know where Eonar's spirit lies. You should seek Magni out at once and see if you can find her while we still have a chance. If she falls, nothing we muster will be able stand against Sargeras.",starts={{npcID=124312,x=0.616,y=0.87,zoneID=8574},{npcID=124312,x=0.4,y=0.252,zoneID=8574}},ends={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},coords={x=0.616,y=0.87,source="quest_giver",zoneID=8574},questType="standard"},
[48278] = {id=48278,name="Fate of the Life-Binder",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8574,mapID=830,description="I don't even want to think about what happens if Aggramar can find Eonar's spirit before we do. The fate of far more'n Azeroth may hinge on her safety. Let Turalyon know what we saw right away. We're going to need to bring all we can to bear to save her.",questType="standard"},
[48280] = {id=48280,name="Visions of Another",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8574,description="Whoever's tryin' to reach us now might give us the information we need to find Eonar. We need to see what's goin' on right away!",starts={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},ends={{npcID=124595,x=0.57,y=0.656,zoneID=8574}},coords={x=0.57,y=0.656,source="quest_giver",zoneID=8574},questType="standard"},
[48281] = {id=48281,name="Tracking Quest",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[48283] = {id=48283,name="Standing Accused",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="So you wish to speak with the accused? I see no reason why not. Be quick about it, though. I will not have our trial delayed. This woman will answer for the fate of our village!",starts={{npcID=125394,x=0.7,y=0.428,zoneID=8721}},ends={{npcID=125385,x=0.696,y=0.432,zoneID=8721}},coords={x=0.7,y=0.428,source="quest_giver",zoneID=8721},questType="standard"},
[48288] = {id=48288,name="Antoran High Command",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7834,description="The Legion has spent over 10,000 years planning their invasion of Azeroth. Defeat their leaders so they can never threaten our world again.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
[48292] = {id=48292,name="The Soulhunter",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7834,description="Imonar is the deadliest bounty hunter the Twisting Nether has ever produced. Find a pit to throw him down.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=99179,x=0.528,y=0.596,zoneID=7902},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
[48293] = {id=48293,name="The Burning Coven",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7834,description="Not even a Titan can endure their torture. Bring an end to the Coven of Shivarra.",ends={{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
[48294] = {id=48294,name="The Unmaker",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7834,description="Argus is Sargeras' solution for existence; an end to all things. For everyone that might ever live, bring an end to the Unmaker.",ends={{npcID=96746,x=0.33,y=0.6,zoneID=7745},{npcID=98002,x=0.528,y=0.514,zoneID=7846},{npcID=99179,x=0.528,y=0.596,zoneID=7902},{npcID=103023,x=0.43,y=0.468,zoneID=7877},{npcID=106199,x=0.666,y=0.46,zoneID=7875}},questType="raid"},
