[48715] = {id=48715,name="Akunda Awaits",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,description="I've spoken to every troll out here, asking if they've seen Rakera. As you might have guessed, Akunda is de only name dey know. Let's hope someone within de temple will be able to tell us something useful.",starts={{npcID=127570,x=0.532,y=0.902,zoneID=8501}},ends={{npcID=135066,x=0.536,y=0.916,zoneID=8501}},coords={x=0.532,y=0.902,source="quest_giver",zoneID=8501},questType="standard"},
