[52838] = {id=52838,name="Seal of Wartorn Fate: Piles of Gold",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8670,starts={{npcID=142063,x=0.716,y=0.136,zoneID=8568}},ends={{npcID=142063,x=0.716,y=0.136,zoneID=8568},{npcID=141584,x=0.54,y=0.884,zoneID=8670}},coords={x=0.716,y=0.136,source="quest_giver",zoneID=8568},questType="standard"},
[52839] = {id=52839,name="Seal of Wartorn Fate: Additional Marks of Honor",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8670,starts={{npcID=142063,x=0.716,y=0.136,zoneID=8568}},ends={{npcID=142063,x=0.716,y=0.136,zoneID=8568},{npcID=141584,x=0.54,y=0.884,zoneID=8670}},coords={x=0.716,y=0.136,source="quest_giver",zoneID=8568},questType="standard"},
[52840] = {id=52840,name="Seal of Wartorn Fate: Stashed War Resources",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8670,starts={{npcID=142063,x=0.716,y=0.136,zoneID=8568}},ends={{npcID=142063,x=0.716,y=0.136,zoneID=8568},{npcID=141584,x=0.54,y=0.884,zoneID=8670}},coords={x=0.716,y=0.136,source="quest_giver",zoneID=8568},questType="standard"},
[52851] = {id=52851,name="Mission Report: Mugamba Overlook",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the assault on Mugamba Overlook. It details that victory was hard-fought, but the enemies guarding the outpost have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[52852] = {id=52852,name="Mugamba Overlook",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8499,description="The raid you planned for Mugamba Overlook in Zuldazar was successful. Well done. The outpost is ready to be claimed. Make your way to Mugamba Overlook in Zuldazar and establish fortifications there. Mugamba Overlook will be an essential outpost in our campaign against the Horde. For the Alliance!",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=141949,x=0.448,y=0.274,zoneID=8499}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[52855] = {id=52855,name="Alchemy is an Inexact Science",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Hey, look. It worked, right? Mostly. I mean, it DID get bigger. Don't look at me like that! So there are some... weird side effects going on. When has that ever gotten in the way of science before? Okay, okay, okay! I have an idea. Go and get me everything on this list. And be quick about it! I think these Zandalari might do something to me if you-- if WE-- don't fix this. Do me a solid, eh?",starts={{npcID=122129,x=0.668,y=0.426,zoneID=8499}},ends={{npcID=122129,x=0.668,y=0.426,zoneID=8499}},coords={x=0.668,y=0.426,source="quest_giver",zoneID=8499},questType="standard"},
[52857] = {id=52857,name="Held For Observation",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="That should do it. Go on and get this down your direhorn's gullet. Don't worry, nothing could possibly go wrong with a concoction made under any kind of duress. Also, do I seem like the kind of goblin who would give you something dangerous? On purpose? ... Don't answer that. Hurry, before they stab me.",starts={{npcID=122129,x=0.668,y=0.426,zoneID=8499}},ends={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},coords={x=0.668,y=0.426,source="quest_giver",zoneID=8499},questType="standard"},
[52861] = {id=52861,name="Champion: Lilian Voss",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,mapID=1165,starts={{npcID=141961,x=0.584,y=0.626,mapID=862},{npcID=141961,x=0.514,y=0.994,mapID=1165}},ends={{npcID=141961,x=0.584,y=0.626,mapID=862},{npcID=141961,x=0.514,y=0.994,mapID=1165}},coords={x=0.584,y=0.626,source="quest_giver",mapID=1165},questType="standard"},
[52876] = {id=52876,name="WANTED: War Gore",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,description="By the decree of the Storm's Wake. Scouts have reported that forsaken scientists have created a monster, sewn together from the bodies of our own fallen soldiers. This monstrosity is called, War Gore . The individual that destroys this abomination will earn a fitting reward.",starts={{npcID=293985,x=0.468,y=0.481,zoneID=9042}},ends={{npcID=139635,x=0.466,y=0.478,zoneID=9042}},coords={x=0.468,y=0.481,source="quest_giver",zoneID=9042},questType="group"},
[52886] = {id=52886,name="Mission Report: Verdant Hollow",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the assault on Verdant Hollow. It details that victory was hard-fought, but the enemies guarding the outpost have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[52888] = {id=52888,name="Verdant Hollow",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8499,description="The raid you planned for Verdant Hollow in Zuldazar was successful. Well done. The outpost is ready to be claimed. Make your way to Verdant Hollow in Zuldazar and establish fortifications there. Verdant Hollow will be an essential outpost in our campaign against the Horde. For the Alliance!",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=142101,x=0.548,y=0.256,zoneID=8499}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[52928] = {id=52928,name="Arathi Donations: Coarse Leather",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,starts={{npcID=142970,x=0.534,y=0.926,zoneID=8670}},ends={{npcID=142970,x=0.534,y=0.926,zoneID=8670}},coords={x=0.534,y=0.926,source="quest_giver",zoneID=8670},questType="standard"},
[52929] = {id=52929,name="Arathi Donations: Monelite Ore",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,starts={{npcID=142969,x=0.526,y=0.946,zoneID=8670}},ends={{npcID=142969,x=0.526,y=0.946,zoneID=8670}},coords={x=0.526,y=0.946,source="quest_giver",zoneID=8670},questType="standard"},
[52930] = {id=52930,name="Arathi Donations: Gold",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="Our friends here are accepting all kinds of donations on behalf of the war effort, but if ya ask me, no battle was ever won without proper funding. That's right, bub. I'm talking about money! And lots of it. If you got it, we need it!",ends={{npcID=142157,x=0.516,y=0.952,zoneID=8670}},questType="standard"},
[52942] = {id=52942,name="Restoring Old Bonds",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=9598,description="We must speak to Grommash Hellscream and remind him of his debt to us. Everything rests on this mission, . I hope your skills in diplomacy are greater than mine. Be on your guard; we do not know what to expect on the other side.",starts={{npcID=126066,x=0.378,y=0.806,zoneID=1637},{npcID=126066,x=0.686,y=0.718,zoneID=8670}},ends={{npcID=142422,x=0.448,y=0.53,zoneID=9786}},coords={x=0.378,y=0.806,source="quest_giver",zoneID=1637},questType="standard"},
[52944] = {id=52944,name="Call to Arms: Drustvar",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We've discovered a spike of Horde activity within Drustvar . We cannot allow them to get the upper hand.",starts={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},ends={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[52948] = {id=52948,name="Call to Arms: Tiragarde Sound",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We've discovered a spike of Horde activity within Tiragarde Sound . We cannot allow them to get the upper hand.",starts={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},ends={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[52949] = {id=52949,name="Call to Arms: Nazmir",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="It's time to press the attack within Horde territory, ! Travel to Nazmir and slay as many Horde as you find.",starts={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},ends={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[52950] = {id=52950,name="Call to Arms: Vol'dun",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="It's time to press the attack within Horde territory, ! Travel to Vol'dun and slay as many Horde as you find.",starts={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},ends={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[52951] = {id=52951,name="Call to Arms: Zuldazar",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="It's time to press the attack within Horde territory, ! Travel to Zuldazar and slay as many Horde as you find.",starts={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},ends={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[52952] = {id=52952,name="Call to Arms: Zuldazar",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="We're getting reports of increased Alliance activity within Zuldazar . Head over there and clear them out.",starts={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},ends={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[52953] = {id=52953,name="Call to Arms: Vol'dun",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="We're getting reports of increased Alliance activity within Vol'dun . Head over there and clear them out.",starts={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},ends={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[52954] = {id=52954,name="Call to Arms: Nazmir",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="We're getting reports of increased Alliance activity within Nazmir . Head over there and clear them out.",starts={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},ends={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[52955] = {id=52955,name="Tyranny of the Light",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=1637,description="If it is not an uprising of ogres or the promise of starvation, it's the constant threat of the Lightbound. Should the reports prove true, this is the closest they have dared approach our stronghold in quite some time. Come or stay, but make your decision quickly.",ends={{npcID=143845,x=0.412,y=0.168,zoneID=14},{npcID=143845,x=0.706,y=0.446,zoneID=1637}},questType="standard"},
[52956] = {id=52956,name="Call to Arms: Tiragarde Sound",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Its time to hit the Alliance at the source. Travel to Tiragarde Sound and slay every Alliance you find. It shouldn't be hard to find them in their own territory.",starts={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},ends={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[52957] = {id=52957,name="Call to Arms: Stormsong Valley",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Its time to hit the Alliance at the source. Travel to Stormsong Valley and slay every Alliance you find. It shouldn't be hard to find them in their own territory.",starts={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},ends={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[52958] = {id=52958,name="Call to Arms: Drustvar",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Its time to hit the Alliance at the source. Travel to Drustvar and slay every Alliance you find. It shouldn't be hard to find them in their own territory.",starts={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},ends={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[52962] = {id=52962,name="Mission Report: Mistvine Ledge",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the assault on Mistvine Ledge. It details that victory was hard-fought, but the enemies surrounding the outpost have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[52963] = {id=52963,name="Mistvine Ledge",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8499,description="The raid you planned for Mistvine Ledge in Zuldazar was successful. Well done. The outpost is ready to be claimed. Make your way to Mistvine Ledge in Zuldazar and establish fortifications there. Mistvine Ledge will be an essential outpost in our campaign against the Horde. For the Alliance!",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=142288,x=0.644,y=0.472,zoneID=8499}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[52965] = {id=52965,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[52967] = {id=52967,name="Saurfang Returns",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=1497,description="Saurfang! It's about time. Look around you, hero! What a lovely sight -- the wisps are scattering. One by one, the walls come crashing down. Now is the time. The World Tree is ours for the taking! Find Saurfang. We shall finish this once and for all.",starts={{npcID=134554,x=0.424,y=0.82,zoneID=148},{npcID=134554,x=0.12,y=0.336,zoneID=331},{npcID=134554,x=0.578,y=0.916,zoneID=1497}},ends={{npcID=142310,x=0.522,y=0.224,zoneID=148}},coords={x=0.424,y=0.82,source="quest_giver",zoneID=148},questType="standard"},
[52970] = {id=52970,name="No Small Mercy",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=148,mapID=62,description="I will not slay innocents. If they do not raise arms against us, we shall spare them. Enter Lor'danel and capture any civilians you find there. They shall be questioned and then released.",starts={{npcID=142310,x=0.522,y=0.224,mapID=62}},ends={{npcID=142310,x=0.522,y=0.224,mapID=62}},coords={x=0.522,y=0.224,source="quest_giver",mapID=62},questType="standard"},
[52971] = {id=52971,name="Seaside Rendezvous",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=148,description="Lor'danel has mustered significant reinforcements on its shore. Enough to drive us back. One swift strike and we can end this threat! You will break through their lines and slay the two commanders. Without leadership this force will crumble.",starts={{npcID=142310,x=0.522,y=0.224,zoneID=148}},ends={{npcID=142310,x=0.522,y=0.224,zoneID=148}},coords={x=0.522,y=0.224,source="quest_giver",zoneID=148},questType="standard"},
[52973] = {id=52973,name="A Threat from the North",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1657,description="The Horde must have scaled the mountains of Felwood in the North. The wisp wall is failing, it is only a matter of time before the Horde breaks through. They will attack us from both sides. We must weather this attack together.",starts={{npcID=134578,x=0.584,y=0.894,zoneID=141},{npcID=134578,x=0.504,y=0.196,zoneID=148},{npcID=134578,x=0.358,y=0.504,zoneID=331},{npcID=134578,x=0.398,y=0.504,zoneID=1657}},ends={{npcID=140877,x=0.584,y=0.894,zoneID=141},{npcID=140877,x=0.504,y=0.2,zoneID=148}},coords={x=0.584,y=0.894,source="quest_giver",zoneID=141},questType="standard"},
[52974] = {id=52974,name="Rescue Effort",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1657,description="The suddenness of the Horde's attack gave citizens here little time to flee. Many are hiding in Lor'danel, waiting for help. Locate these civilians and send them to safety. We're counting on you, .",starts={{npcID=140877,x=0.584,y=0.894,zoneID=141},{npcID=140877,x=0.504,y=0.2,zoneID=148}},ends={{npcID=134578,x=0.584,y=0.894,zoneID=141},{npcID=134578,x=0.504,y=0.196,zoneID=148},{npcID=134578,x=0.358,y=0.504,zoneID=331},{npcID=134578,x=0.398,y=0.504,zoneID=1657}},coords={x=0.584,y=0.894,source="quest_giver",zoneID=141},questType="standard"},
[52975] = {id=52975,name="Action This Day",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1657,description="Two of the Horde's strongest warriors have led a charge to try and capture our fleet. We cannot allow this, . If they take our ships, they will use them to sail to Darnassus! Slay the two warriors leading the attack, and the rest of them will give up the fight.",starts={{npcID=134578,x=0.584,y=0.894,zoneID=141},{npcID=134578,x=0.504,y=0.196,zoneID=148},{npcID=134578,x=0.358,y=0.504,zoneID=331},{npcID=134578,x=0.398,y=0.504,zoneID=1657}},ends={{npcID=134578,x=0.584,y=0.894,zoneID=141},{npcID=134578,x=0.504,y=0.196,zoneID=148},{npcID=134578,x=0.358,y=0.504,zoneID=331},{npcID=134578,x=0.398,y=0.504,zoneID=1657}},coords={x=0.584,y=0.894,source="quest_giver",zoneID=141},questType="standard"},
[52977] = {id=52977,name="The Guidance of Our Shan'do",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1657,description="Lor'danel is overrun. The Horde... they -- they just don't relent. There is nothing we can do, . We must find our Shan'do and ask for his guidance. He is the only one who can save us.",starts={{npcID=134578,x=0.584,y=0.894,zoneID=141},{npcID=134578,x=0.504,y=0.196,zoneID=148},{npcID=134578,x=0.358,y=0.504,zoneID=331},{npcID=134578,x=0.398,y=0.504,zoneID=1657}},ends={{npcID=142978,x=0.43,y=0.784,zoneID=1657}},coords={x=0.584,y=0.894,source="quest_giver",zoneID=141},questType="standard"},
[52978] = {id=52978,name="With Prince in Tow",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Let's set sail for Zandalar. In case you hadn't noticed, we've been dealing with a bit of Alliance interference while you were gone.",starts={{npcID=141644,x=0.404,y=0.672,zoneID=9937}},ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},coords={x=0.404,y=0.672,source="quest_giver",zoneID=9937},questType="standard"},
[52981] = {id=52981,name="Killer Queen",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=148,description="Lor'danel is now secure, but something is amiss... there has been no sign of Stormrage. Malfurion would have never let Lor'danel fall without a fight. He must have gone after her. My army has approached from the North, and our reinforcements have arrived from the South -- which means that they are not along any of the roads. Search the forest with me, . We will find them and be done with this once and for all.",starts={{npcID=142310,x=0.522,y=0.224,zoneID=148}},ends={{npcID=144466,x=0.454,y=0.182,zoneID=148}},coords={x=0.522,y=0.224,source="quest_giver",zoneID=148},questType="standard"},
[52990] = {id=52990,name="Return to the Harbor",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,description="With the scepter in hand, let us return to the portal. I believe Stone would agree with me when I say that it is best for us to get away from Kul Tiras for a while.",ends={{npcID=140485,x=0.868,y=0.53,zoneID=8567}},questType="standard"},
[53003] = {id=53003,name="A Cycle of Hatred",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=1637,description="We have raised new champions for the Horde, established footholds on Kul Tiran soil, and stolen one of their precious artifacts. We hold greater power and sway over our enemies than we have before. Sylvanas has great plans for our Horde, . I will allow you the pleasure of reporting our victories to her personally.",starts={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=134711,x=0.484,y=0.714,zoneID=1637}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53006] = {id=53006,name="Mission Report: Grimwatt's Crash",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the rescue mission to Grimwatt's Crash. It details that the supplies were recovered and the enemies surrounding the crash site have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53007] = {id=53007,name="Grimwatt's Crash",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="The rescue that you planned for Grimwatt's Crash in Nazmir was successful. Well done. I believe we should fortify the crash site and turn it into an outpost. Make your way to Grimwatt's Crash and establish fortifications there. Grimwatt's Crash will be an essential outpost in our campaign against the Horde. For the Alliance!",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=142360,x=0.338,y=0.632,zoneID=8500}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53011] = {id=53011,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=1637,mapID=85,starts={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},ends={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[53028] = {id=53028,name="A Dying World",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=1377,description="Champion. Magni Bronzebeard needs your help. Azeroth is dying. Before this war, a massive demon called Sargeras stabbed the planet with a sword. Our planet cries out in pain while the Horde and Alliance fight amongst each other. Magni Bronzebeard believes you can help heal the planet's wounds. Meet him in Silithus. He has set up camp where Sargeras's sword impacted our world.",starts={{npcID=140176,x=0.49,y=0.916,zoneID=1637},{npcID=154464,x=0.748,y=0.15,zoneID=8568},{npcID=154465,x=0.51,y=0.888,zoneID=8670}},ends={{npcID=130216,x=0.422,y=0.442,zoneID=1377}},coords={x=0.49,y=0.916,source="quest_giver",zoneID=1637},questType="standard"},
[53041] = {id=53041,name="Sampling the Goods",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="Bridgeport is a major trade hub for this area. Naturally, Ashvane has offices and workshops here. Check around town and see if you can learn anything about this new material and how they're using it. If you can lift a sample for us to send back to Boralus, even better. I gotta stay here and keep an eye on someone.",starts={{npcID=134166,x=0.758,y=0.49,zoneID=8567}},ends={{npcID=134166,x=0.758,y=0.49,zoneID=8567}},coords={x=0.758,y=0.49,source="quest_giver",zoneID=8567},questType="standard"},
[53043] = {id=53043,name="Mission Report: Vulture's Nest",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the mission to capture Vulture's Nest in Vol'dun. It details that the mission was a success and that the troops holding the outpost have requested reinforcements. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53044] = {id=53044,name="Vulture's Nest",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8501,description="The mission to take Vulture's Nest in Vol'dun was successful. Well done. The outpost is ready to be claimed. Make your way to Vulture's Nest and establish fortifications there. It will be an essential outpost in our campaign against the Horde. For the Alliance!",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=142555,x=0.536,y=0.378,zoneID=8501}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53045] = {id=53045,name="Surveying the Wharf",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,description="Thresher's Wharf is a bustling fishing hub just across the delta from Fort Daelin. It was also in the direct war path of the naga -- who knows what remains now. If you could stop in and check in on its leader, Coxswain Hook , you'd have my gratitude. I must focus on tending to the wounded here and preparing for the naga's next assault.",starts={{npcID=131001,x=0.346,y=0.474,zoneID=9042}},ends={{npcID=133576,x=0.26,y=0.552,zoneID=9042}},coords={x=0.346,y=0.474,source="quest_giver",zoneID=9042},questType="standard"},
[53050] = {id=53050,name="Deeper Into Kul Tiras",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=8499,description="It is time for us to further our hold on Kul Tiras. Return to the Banshee's Wail. From there we shall plan our next course of action.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53052] = {id=53052,name="Deeper Into Zandalar",level=35,requiredLevel=35,faction="alliance",expansion=7,zoneID=8568,description="Our advisors have decided that now is the correct time to further our hold on Zandalar. Return to the Wind's Redemption posthaste. We shall leave for new lands immediately.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53053] = {id=53053,name="To The Mugambala!",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="The Rastari have proven to be formidable allies in combat, and reports are coming in that help explain how they've honed their battle prowess. Je'stry the Untamed has a fighting ring setup at the base of Mount Mugambala that could prove useful for getting ready for war. We've dispatched our troops to take advantage of these training grounds, go and see what High Warlord Volrath has uncovered.",starts={{npcID=138708,x=0.584,y=0.626,zoneID=8499},{npcID=138708,x=0.516,y=0.994,zoneID=8670},{npcID=138708,x=0.512,y=0.21,zoneID=9042}},ends={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53054] = {id=53054,name="Dueler's Guild",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="I figured a war-torn such as your self would find benefit in this Dueler's Guild. Speak with a nearby Rastari Guard to participate in the carnage.",starts={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},ends={{npcID=143536,x=0.516,y=0.582,zoneID=8499}},coords={x=0.516,y=0.582,source="quest_giver",zoneID=8499},questType="standard"},
[53055] = {id=53055,name="Pushing Our Influence",level=35,requiredLevel=35,faction="alliance",expansion=7,zoneID=8568,description="Our scouts have identified a location for a final major foothold in Zandalar. Return to the Wind's Redemption so we can ship out.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53056] = {id=53056,name="Pushing Our Influence",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=8499,description="We have identified a location for a final major foothold in Kul Tiras. Return to the Banshee's Wail to discuss our new mission.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53061] = {id=53061,name="The Azerite Advantage",level=35,requiredLevel=35,faction="alliance",expansion=7,zoneID=8568,description=", we have received intelligence pointing us toward a reliable source of Azerite. We must acquire this precious resource before our enemies in the Horde. Report to the Wind's Redemption as soon as possible to aid in extraction.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53062] = {id=53062,name="The Azerite Advantage",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=8499,description="We have received intelligence pointing us toward a reliable source of Azerite. We must move quickly to acquire these resources for the Horde. Report to the Banshee's Wail to aid in this urgent mission.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53063] = {id=53063,name="A Mission of Unity",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="You have done much for the Alliance during your time here in Kul Tiras, . Today we must ask more of you. Return to the Wind's Redemption when you have the chance so that we can discuss.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53064] = {id=53064,name="A Mission of Unity",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="You have undertaken great journeys during your time here in Zandalar. It is time for your next mission. Report to the Banshee's Wail.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53065] = {id=53065,name="Operation: Grave Digger",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Sylvanas has issued us a mission in Drustvar, where we will find our next target. Report to the Banshee's Wail immediately.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53066] = {id=53066,name="Operation: Water Wise",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Rexxar has reported back with news of a new... ally. Report to the Banshee's Wail for your briefing.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53067] = {id=53067,name="Operation: Bottom Feeder",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="It is time for Zelling to prove his worth to the Horde. Return to the Banshee's Wail. Today, we sail out to open waters.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53068] = {id=53068,name="Operation: Hook and Line",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Thanks to the help of our new allies, we have devised a plan to extract a powerful tidesage artifact from Boralus. I have already sent Valentine to get us started. Report to the Banshee's Wail posthaste.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53069] = {id=53069,name="Operation: Blood Arrow",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We have uncovered the location of a high priority target in Nazmir. Return to the Wind's Redemption for your briefing.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53070] = {id=53070,name="Operation: Cutpurse",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="It is time to reconvene for our next mission, though Shandris and I disagree on what exactly that should entail. Meet us on the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53071] = {id=53071,name="Operation: Gryphon's Claw",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="SI:7 has procured some interesting intel. I request your presence on the Wind's Redemption immediately to help decide our next course of action.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53072] = {id=53072,name="Operation: Heartstrike",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We've taken out quite a number of high priority targets, . All thanks to your help. It is time to strike directly at the heart of the Zandalari empire. Report to the Wind's Redemption as soon as you are able. We will get started from there.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53073] = {id=53073,name="Hook Point Investigation",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="I'm sure you've heard the constant sound of battle coming from Hook Point. We sent scouts over to find out why the fighting never seems to end, and discovered an unexpected training ground. Daniel Poole at Hook Point is running some sort of fight circuit near the Tradewind Market. Seek out Grand Marshal Tremblade at our War Headquarters and find out what they've learned.",starts={{npcID=135614,x=0.704,y=0.27,zoneID=8568}},ends={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},coords={x=0.704,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53074] = {id=53074,name="Reinforcements",level=35,requiredLevel=35,faction="alliance",expansion=7,zoneID=8568,description="The resources you gather can be used to recruit new troops for the war effort. Return to me periodically to issue new recruitment orders for your missions. If you have available resources, you should use them now to issue your first recruitment order. The war effort rages on even as we speak. We have need of fresh recruits.",starts={{npcID=135614,x=0.704,y=0.27,zoneID=8568}},ends={{npcID=135614,x=0.704,y=0.27,zoneID=8568}},coords={x=0.704,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53075] = {id=53075,name="Dueler's Guild",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="I figured a war-torn such as your self would benefit from training in the Dueler's Guild. Speak with a nearby bouncer to participate in the carnage.",starts={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},ends={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},coords={x=0.562,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[53079] = {id=53079,name="Reinforcements",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=9042,description="The resources you gather can be used to recruit new troops for the war effort. Return to me periodically to issue new recruitment orders for your missions. If you have available resources, you should use them now to issue your first recruitment order. The war effort rages on even as we speak. We have need of fresh recruits.",starts={{npcID=138708,x=0.584,y=0.626,zoneID=8499},{npcID=138708,x=0.516,y=0.994,zoneID=8670},{npcID=138708,x=0.512,y=0.21,zoneID=9042}},ends={{npcID=138708,x=0.584,y=0.626,zoneID=8499},{npcID=138708,x=0.516,y=0.994,zoneID=8670},{npcID=138708,x=0.512,y=0.21,zoneID=9042}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53081] = {id=53081,name="Mission Report: Spare Parts",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Your followers have sent a report regarding the mission to collect salvage for Stonefist Watch. It details that the mission was a success and the necessary materials have been collected. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53082] = {id=53082,name="Spare Parts",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,description="An engineer has been assigned to Stonefist Watch to build a scrapping machine. The mission to salvage materials for the machine was a success thanks to your leadership. Make your way to Stonefist Watch in Tiragarde Sound and meet with Grizvek Gearsnap . He has been overseeing the upgrades for the outpost.",starts={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=143015,x=0.528,y=0.622,zoneID=8567}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53095] = {id=53095,name="A Flicker of Hope",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1657,description="Champion, I need your help! We must evacuate Darnassus before it burns to ash! Many of the city's structures have already caught fire. Douse the flames and rescue the trapped civilians within! Please, do all that you can... we must save as many lives as possible.",starts={{npcID=142978,x=0.43,y=0.784,zoneID=1657}},coords={x=0.43,y=0.784,source="quest_giver",zoneID=1657},questType="standard"},
[53097] = {id=53097,name="Despondent Ablutions",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=9042,description="You return. A surprise. Perhaps there is still hope. In victory or defeat, you bear the weight of this place. It hangs on you like a mantle. I see your struggle to bear it. There is, perhaps, a way to shrug off this burden. An altar, to the northwest. Built by the tidesages, seeking to wash away the corruption. Offer yourself to the idol. It will exact a price, as do all things. But in communion you may claw back from the brink.",starts={{npcID=133640,x=0.786,y=0.548,zoneID=9042},{npcID=143565,x=0.786,y=0.548,zoneID=9042}},ends={{npcID=133640,x=0.786,y=0.548,zoneID=9042},{npcID=143565,x=0.786,y=0.548,zoneID=9042}},coords={x=0.786,y=0.548,source="quest_giver",zoneID=9042},questType="standard"},
[53098] = {id=53098,name="Champion: Shandris Feathermoon",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8499,mapID=862,starts={{npcID=141291,x=0.856,y=0.318,mapID=84},{npcID=141291,x=0.348,y=0.764,mapID=862}},ends={{npcID=141291,x=0.856,y=0.318,mapID=84},{npcID=141291,x=0.348,y=0.764,mapID=862}},coords={x=0.856,y=0.318,source="quest_giver",mapID=862},questType="standard"},
[53099] = {id=53099,name="A Mote of Cosmic Truth",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=9042,description="We stand on the brink, you and I. The final act looms over us, casting a terrible shadow. Deep we plumbed, seeking knowledge of the world. Deeper still we delved, until our fate was inevitable. Minds were shattered, my comrades ran screaming into the night. We are all lost, to that terrible Thing... Now, the malformed syzygy beckons. Complete the ritual and bring about the end.",starts={{npcID=133640,x=0.786,y=0.548,zoneID=9042},{npcID=143565,x=0.786,y=0.548,zoneID=9042}},ends={{npcID=133640,x=0.786,y=0.548,zoneID=9042},{npcID=143565,x=0.786,y=0.548,zoneID=9042}},coords={x=0.786,y=0.548,source="quest_giver",zoneID=9042},questType="standard"},
[53100] = {id=53100,name="Mission Report: Giant Slaying",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Your followers have sent a report regarding the mission at Stonetusk Watch. It details that the mission was a success and that one of the ettins is being held captive. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53101] = {id=53101,name="Nettin' Ettin",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="An ettin has been captured by our troops at Stonetusk Watch. Apparently, the creature is being trained to work for the Horde as a beast of burden. Make your way to Stonetusk Watch in Stormsong Valley and meet with Wyna Breezehorn . She has been training the ettin to do her bidding.",starts={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=134844,x=0.388,y=0.666,zoneID=9042}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53102] = {id=53102,name="Mission Report: Nature Calls",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Your followers have sent a report regarding the mission at Swiftwind Post. It details that the mission was a success and the druids there have upgraded their druidic knowledge as a result. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53103] = {id=53103,name="Wicker Magic",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8721,description="It seems that the druids at Swiftwind Post have learned much from the ancient Drust rituals you recovered. The druids are now able to offer improved services at the outpost. Make your way to Swiftwind Post in Drustvar and see what they have to offer.",starts={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=140778,x=0.662,y=0.594,zoneID=8721}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53105] = {id=53105,name="Misplaced Faith",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=9042,description="The air is foul with corruption. It must be dealt with. The tidesages were fools, and I a fool to trust them. Belief in their god to perform miracles and deliver us from our folly. Nevertheless, their methods did serve to drive back the foul presence from these cliffs. A simple censer, loaded with select powders and oils. The vapors produce an effect that expels the miasma, if only for a time. Perhaps their ineffectual gesticulation will finally serve a purpose.",starts={{npcID=133640,x=0.786,y=0.548,zoneID=9042},{npcID=143565,x=0.786,y=0.548,zoneID=9042}},ends={{npcID=133640,x=0.786,y=0.548,zoneID=9042},{npcID=143565,x=0.786,y=0.548,zoneID=9042}},coords={x=0.786,y=0.548,source="quest_giver",zoneID=9042},questType="standard"},
[53109] = {id=53109,name="House Waycrest",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8568,description="You have done much for my home and the people of Drustvar , Tell your allies that House Waycrest will return to Boralus shortly.",starts={{npcID=129642,x=0.368,y=0.5,zoneID=8721},{npcID=142651,x=0.36,y=0.512,zoneID=8721}},ends={{npcID=121235,x=0.68,y=0.22,zoneID=8568}},coords={x=0.368,y=0.5,source="quest_giver",zoneID=8721},questType="standard"},
[53110] = {id=53110,name="The High Thornspeaker",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,description="My teacher, Ulfar , the High Thornspeaker, must be informed of what's been going on here. I can't leave just yet. There are too many wounded and we'll need to handle the last few remaining constructs. You have proven trustworthy, friend. Take a few of these runic cores to Ulfar for me. Arthur will meet you at the head of the path to Ulfar 's den.",starts={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},ends={{npcID=141159,x=0.452,y=0.458,zoneID=8721}},coords={x=0.618,y=0.594,source="quest_giver",zoneID=8721},questType="standard"},
[53112] = {id=53112,name="Azeroth's Tear",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=1377,starts={{npcID=130216,x=0.422,y=0.442,zoneID=1377}},ends={{npcID=130216,x=0.422,y=0.442,zoneID=1377}},coords={x=0.422,y=0.442,source="quest_giver",zoneID=1377},questType="standard"},
[53113] = {id=53113,name="Shimmering Shell",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8501,starts={{npcID=135804,x=0.566,y=0.498,zoneID=8501}},ends={{npcID=135804,x=0.566,y=0.498,zoneID=8501}},coords={x=0.566,y=0.498,source="quest_giver",zoneID=8501},questType="standard"},
[53114] = {id=53114,name="Golden Beetle",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8500,starts={{npcID=120551,x=0.754,y=0.566,zoneID=8500}},ends={{npcID=120551,x=0.754,y=0.566,zoneID=8500}},coords={x=0.754,y=0.566,source="quest_giver",zoneID=8500},questType="standard"},
[53115] = {id=53115,name="Island Flotsam",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,starts={{npcID=126334,x=0.354,y=0.078,zoneID=8670}},ends={{npcID=126334,x=0.354,y=0.078,zoneID=8670}},coords={x=0.354,y=0.078,source="quest_giver",zoneID=8670},questType="standard"},
[53116] = {id=53116,name="Rusted Horde Insignia",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,starts={{npcID=135447,x=0.58,y=0.626,zoneID=8499}},ends={{npcID=135447,x=0.58,y=0.626,zoneID=8499}},coords={x=0.58,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53117] = {id=53117,name="Rusted Alliance Insignia",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=135446,x=0.692,y=0.25,zoneID=8568}},ends={{npcID=135446,x=0.692,y=0.25,zoneID=8568}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=8568},questType="standard"},
[53118] = {id=53118,name="Dented Coin",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=122370,x=0.68,y=0.22,zoneID=8568}},ends={{npcID=122370,x=0.68,y=0.22,zoneID=8568}},coords={x=0.68,y=0.22,source="quest_giver",zoneID=8568},questType="standard"},
