[53120] = {id=53120,name="Exotic Spices",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8721,starts={{npcID=136269,x=0.206,y=0.456,zoneID=8721}},ends={{npcID=136141,x=0.206,y=0.456,zoneID=8721},{npcID=136269,x=0.206,y=0.456,zoneID=8721}},coords={x=0.206,y=0.456,source="quest_giver",zoneID=8721},questType="standard"},
[53121] = {id=53121,name="Siege of Boralus",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9937,mapID=1157,starts={{npcID=141961,x=0.584,y=0.626,mapID=862},{npcID=141961,x=0.514,y=0.994,mapID=1165}},ends={{npcID=141961,x=0.584,y=0.626,mapID=862},{npcID=141961,x=0.514,y=0.994,mapID=1165},{npcID=141654,x=0.414,y=0.666,mapID=1157}},coords={x=0.584,y=0.626,source="quest_giver",mapID=1157},questType="standard"},
[53122] = {id=53122,name="A Season for Celebration",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=13983,description="Well met, . Hallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken. Travel to the Ruins of Lordaeron and speak to Darkcaller Yanka . She can tell you more about the Wickerman ceremony.",starts={{npcID=19169,x=0.542,y=0.508,zoneID=3430},{npcID=19169,x=0.778,y=0.576,zoneID=3487},{npcID=19175,x=0.516,y=0.752,zoneID=1637},{npcID=19176,x=0.402,y=0.488,zoneID=1637},{npcID=19177,x=0.49,y=0.612,zoneID=1637},{npcID=19176,x=0.41,y=0.558,zoneID=1638},{npcID=19178,x=0.632,y=0.48,zoneID=1497},{npcID=20102,x=0.69,y=0.706,zoneID=17},{npcID=20102,x=0.406,y=0.844,zoneID=67},{npcID=20102,x=0.522,y=0.284,zoneID=440},{npcID=20102,x=0.598,y=0.496,zoneID=618},{npcID=20102,x=0.338,y=0.64,zoneID=3523},{npcID=20102,x=0.53,y=0.504,zoneID=3703},{npcID=20102,x=0.416,y=0.742,zoneID=5287}},ends={{npcID=15197,x=0.672,y=0.128,zoneID=1497},{npcID=15197,x=0.62,y=0.678,zoneID=85}},coords={x=0.542,y=0.508,source="quest_giver",zoneID=3430},questType="standard"},
[53125] = {id=53125,name="Mission Report: Into The Wicker",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Your followers have sent a report regarding the mission at Mudfisher Cove. It details that the mission was a success and the druids there have upgraded their druidic knowledge as a result. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53126] = {id=53126,name="The Wicker Totem",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8721,description="The defense of Mudfisher Cove was successful. Well done, . A mysterious totem was found in the aftermath of the battle that may prove useful to you during your adventures in Drustvar. Travel to Mudfisher Cove in Drustvar and see what power this totem contains.",starts={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=140947,x=0.624,y=0.17,zoneID=8721}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53127] = {id=53127,name="The Lord Admiral's Lament",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=1637,description="The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time. Perhaps someone can restore the letter and reveal its contents.",ends={{npcID=139093,x=0.48,y=0.716,zoneID=1637}},questType="standard"},
[53128] = {id=53128,name="The Lord Admiral's Lament",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=1519,description="The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time. Perhaps someone can restore the letter and reveal its contents.",ends={{npcID=143208,x=0.858,y=0.24,zoneID=1519}},questType="standard"},
[53129] = {id=53129,name="Bloodied Sentinel's Glaive",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=1637,description="The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon. Perhaps someone in Orgrimmar can tell you what happened here.",starts={{npcID=296536,x=0.452,y=0.18,zoneID=148}},ends={{npcID=139093,x=0.48,y=0.716,zoneID=1637}},coords={x=0.452,y=0.18,source="quest_giver",zoneID=148},questType="standard"},
[53130] = {id=53130,name="Bloodied Sentinel's Glaive",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=1519,description="The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon. Perhaps someone in Stormwind can tell you what happened here.",starts={{npcID=296536,x=0.452,y=0.18,zoneID=148}},ends={{npcID=143208,x=0.858,y=0.24,zoneID=1519}},coords={x=0.452,y=0.18,source="quest_giver",zoneID=148},questType="standard"},
[53131] = {id=53131,name="Kings' Rest",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9800,mapID=1156,starts={{npcID=142228,x=0.416,y=0.57,mapID=1156}},ends={{npcID=142228,x=0.416,y=0.57,mapID=1156}},coords={x=0.416,y=0.57,source="quest_giver",mapID=1156},questType="standard"},
[53146] = {id=53146,name="Boulderfist Beatdown",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="The Boulderfist ogres have plagued Arathi since the Second War, and they still remain. You know what must be done.",starts={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},ends={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},coords={x=0.216,y=0.648,source="quest_giver",zoneID=45},questType="standard"},
[53148] = {id=53148,name="Boulderfist Beatdown",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi. You know what must be done.",starts={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},ends={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},coords={x=0.272,y=0.298,source="quest_giver",zoneID=45},questType="standard"},
[53149] = {id=53149,name="Wiping Out the Witherbark",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="The Witherbark tribe has a long and bloody history in the highlands of Arathi. Show them how much bloodier it can get.",starts={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},ends={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},coords={x=0.216,y=0.648,source="quest_giver",zoneID=45},questType="standard"},
[53150] = {id=53150,name="Wiping Out the Witherbark",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed. Drive the forest trolls from the Highlands.",starts={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},ends={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},coords={x=0.272,y=0.298,source="quest_giver",zoneID=45},questType="standard"},
[53151] = {id=53151,name="Mission Report: Wolves For The Den",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Your followers have sent a report regarding the mission at Wolf's Den. It details that the mission was a success and that a pack of direwolves now guard the outpost. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.",ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},questType="standard"},
[53152] = {id=53152,name="Wolves for the Den",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,description="The mission at Wolf's Den in Tiragarde Sound was a success. Well done, . A pack of direwolves now patrols the area surrounding the outpost. Travel to Wolf's Den and see that the training of the wolves is up to our standard.",starts={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=139561,x=0.624,y=0.124,zoneID=8567}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53153] = {id=53153,name="Death to The Defilers",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Even with the destruction of Undercity, the Defilers continue to combat our hold on the Arathi Highlands . The farmland at Go'Shek will belong to the Alliance once more. Go, and defeat the Forsaken.",starts={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},ends={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},coords={x=0.216,y=0.648,source="quest_giver",zoneID=45},questType="standard"},
[53154] = {id=53154,name="The League Will Lose",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands. The northern farmland will belong to the Horde. Go, and defeat the humans.",starts={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},ends={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},coords={x=0.272,y=0.298,source="quest_giver",zoneID=45},questType="standard"},
[53155] = {id=53155,name="Notched Coin",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=5785,ends={{npcID=64365,x=0.552,y=0.192,zoneID=5785}},questType="standard"},
[53159] = {id=53159,name="Arathi Donations: Coarse Leather",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come. Let's make sure our allies are well prepared.",ends={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},questType="standard"},
[53160] = {id=53160,name="Ancient Crypt Key",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=9105,mapID=1530,ends={{npcID=61962,x=0.832,y=0.296,mapID=1530},{npcID=156003,x=0.836,y=0.272,mapID=1530}},questType="standard"},
[53161] = {id=53161,name="Ring of the Reefs",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7541,ends={{npcID=106904,x=0.602,y=0.512,zoneID=7541}},questType="standard"},
[53162] = {id=53162,name="Sins of the Syndicate",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="As if the Defilers were not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Alliance farmers. Punish them.",starts={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},ends={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},coords={x=0.216,y=0.648,source="quest_giver",zoneID=45},questType="standard"},
[53163] = {id=53163,name="Bloodwake Drinking Horn",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7541,description="Azerite , but to what end? Other vrykul tribes may know more about the Bloodwake and their motivations.>",ends={{npcID=93231,x=0.684,y=0.542,zoneID=7541}},questType="standard"},
[53164] = {id=53164,name="Sonic Stone",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=5842,ends={{npcID=61584,x=0.394,y=0.62,zoneID=5842}},questType="standard"},
[53167] = {id=53167,name="Icetusk Fur Cloak",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=65,ends={{npcID=26245,x=0.476,y=0.766,zoneID=65}},questType="standard"},
[53168] = {id=53168,name="Magical Spyglass",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=5287,ends={{npcID=2496,x=0.41,y=0.73,zoneID=5287}},questType="standard"},
[53169] = {id=53169,name="Elemental Core",level=10,requiredLevel=10,faction="both",expansion=7,description="Azerite , but why? It might be time to call in an old favor.>",questType="standard"},
