[53171] = {id=53171,name="Battered Twilight Scale",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=4922,ends={{npcID=132888,x=0.202,y=0.546,zoneID=4922}},questType="standard"},
[53172] = {id=53172,name="Venture Co. Business Plan",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=17,ends={{npcID=3658,x=0.668,y=0.726,zoneID=17}},questType="standard"},
[53173] = {id=53173,name="Sins of the Syndicate",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="As if the League of Arathor was not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Horde laborers. Punish them.",starts={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},ends={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},coords={x=0.272,y=0.298,source="quest_giver",zoneID=45},questType="standard"},
[53174] = {id=53174,name="Murloc Eye",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=7503,description="murloc eye appears to have no magical properties of its own, but is still quite damp to the touch. You have seen naga sorcerers use similar objects in their casting rituals, but rarely do they dismember their murloc slaves for this purpose. This is unsettling, even for the naga.>",ends={{npcID=98067,x=0.426,y=0.108,zoneID=7503}},questType="standard"},
[53175] = {id=53175,name="The Warfront Looms",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We cannot myopically focus all our efforts on Zandalar. Horde treachery simmers all across the globe. One particular hot spot lies in the Arathi Highlands, near the storied citadel of Stromgarde. The Horde has set up an encampment nearby, and intends to capture our territory. Speak with Ralston Karn , the recruitment officer for the division in charge of this particular warfront. He could use a good like you.",ends={{npcID=142721,x=0.66,y=0.26,zoneID=8568}},questType="standard"},
[53176] = {id=53176,name="Glittering Scarab",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=5034,ends={{npcID=46134,x=0.588,y=0.462,zoneID=5034}},questType="standard"},
[53177] = {id=53177,name="Broken Compass",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=5287,ends={{npcID=908,x=0.42,y=0.746,zoneID=5287}},questType="standard"},
[53178] = {id=53178,name="Razorfin Hunting Spear",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=6134,ends={{npcID=58278,x=0.296,y=0.39,zoneID=6134}},questType="standard"},
[53179] = {id=53179,name="Executing Exorcisms",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Even in death, the Horde foolishly clings to Alliance territory. Drive their vengeful ghosts from the ruins of Ar'gorok before their foulness spreads.",starts={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},ends={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},coords={x=0.216,y=0.648,source="quest_giver",zoneID=45},questType="standard"},
[53180] = {id=53180,name="Vorus'arak's Carapace",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=65,ends={{npcID=26653,x=0.262,y=0.506,zoneID=65}},questType="standard"},
[53181] = {id=53181,name="Druidic Fur",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=493,ends={{npcID=12042,x=0.524,y=0.404,zoneID=493}},questType="standard"},
[53182] = {id=53182,name="Strangling Root",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=493,ends={{npcID=11832,x=0.362,y=0.418,zoneID=493}},questType="standard"},
[53183] = {id=53183,name="Wriggling Mass",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=1377,description="<The tendril writhes and pulsates in your hand as your mind is assailed by all manner of vicious thoughts. One vision in particular surfaces in your mind again and again. In your mind's eye, you picture a many-eyed goat laying in a pool of black water. As you approach, its eyes burst open, and in an instant you find yourself looking upward at the goat from deep within the puddle. As you sink into the icy darkness, everything goes black. You pocket the mass and shake the thoughts from your head.",ends={{npcID=132886,x=0.4,y=0.766,zoneID=1377}},questType="standard"},
[53184] = {id=53184,name="Weathered Pamphlet",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=440,description="Azerite -buying service. You can make out a few faded but colorful phrases like \"Your fortune awaits in the Great Sea!\" and \"Everyone's getting rich, isn't it your time?\" There is no mention of any of the dangers involved. There is some information about who to contact at the bottom, however.>",ends={{npcID=132832,x=0.52,y=0.3,zoneID=440}},questType="standard"},
[53185] = {id=53185,name="Warfront Contribution",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="A well-trained army will only get us so far, . We also need money, food, and supplies to keep our army funded, fed, and ready to fight. Alliance coffers fund most of the war effort, but the rest is paid for by the hard work of citizens like you and me. Loosen up those purse strings and do what you can. For the Alliance!",starts={{npcID=142721,x=0.66,y=0.26,zoneID=8568}},ends={{npcID=142721,x=0.66,y=0.26,zoneID=8568}},coords={x=0.66,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[53186] = {id=53186,name="Mission Report: Ambush at Grimwatt's Crash",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the mission at Grimwatt''s Crash. It details that the mission was a success and the attacking blood trolls were defeated. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53187] = {id=53187,name="An Unexpected Guest",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="The mission to defend Grimwatt's Crash was a success. Well done, . In addition to successfully holding the outpost, the troops at Grimwatt's Crash have captured a blood crawg. Noella Davenport is handling the beast's training. Make your way to Grimwatt's Crash in Nazmir and check-in with Noella on the crawg training.",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=142478,x=0.342,y=0.632,zoneID=8500}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53190] = {id=53190,name="Executing Exorcisms",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="Even in death, the Alliance foolishly clings to Horde territory. Drive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.",starts={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},ends={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},coords={x=0.272,y=0.298,source="quest_giver",zoneID=45},questType="standard"},
[53192] = {id=53192,name="Twice-Exiled",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Elementals of all sorts are bursting free of their bonds across the Highlands. Return them to the primordial chaos from whence they came.",starts={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},ends={{npcID=143172,x=0.216,y=0.648,zoneID=45},{npcID=143380,x=0.664,y=0.248,zoneID=8568}},coords={x=0.216,y=0.648,source="quest_giver",zoneID=45},questType="standard"},
[53193] = {id=53193,name="Twice-Exiled",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="Elementals of all sorts are bursting free of their bonds across the Highlands. Return them to the primordial chaos from whence they came.",starts={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},ends={{npcID=143381,x=0.272,y=0.298,zoneID=45},{npcID=143388,x=0.518,y=0.944,zoneID=8670}},coords={x=0.272,y=0.298,source="quest_giver",zoneID=45},questType="standard"},
[53194] = {id=53194,name="To the Front",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=45,description="I need you to see the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front. Yvera Dawnwing maintains a portal directly to Stromgarde. She can help you.",starts={{npcID=142721,x=0.66,y=0.26,zoneID=8568}},ends={{npcID=143018,x=0.192,y=0.618,zoneID=45}},coords={x=0.66,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[53195] = {id=53195,name="Arathi Donations: Akunda's Bite",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9391,description="Greetings! With the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you! Now, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.",ends={{npcID=142993,x=0.666,y=0.238,zoneID=8568}},questType="standard"},
[53197] = {id=53197,name="Touring the Front",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=45,description="The Horde haven't attacked for a while now. Neither have we, honestly. It should be safe to head on out and do some scouting. Check in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't off and gotten themselves killed, and the trip should give you a bit of a lay of the land. Speaking of which, you might also talk to Grayson Bell , the flight master, who can give you a quick look at our enemy's base. \"Ar'gorok,\" or some other such orcish nonsense.",starts={{npcID=143018,x=0.192,y=0.618,zoneID=45}},ends={{npcID=143018,x=0.192,y=0.618,zoneID=45}},coords={x=0.192,y=0.618,source="quest_giver",zoneID=45},questType="standard"},
[53198] = {id=53198,name="Back to Boralus",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="That should just about do it for now, then. We'll be in touch if the fighting heats back up again. No doubt it'll be any day now.",starts={{npcID=143018,x=0.192,y=0.618,zoneID=45}},ends={{npcID=142721,x=0.66,y=0.26,zoneID=8568}},coords={x=0.192,y=0.618,source="quest_giver",zoneID=45},questType="standard"},
[53205] = {id=53205,name="Arathi Donations: Monelite Ore",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Ye look like the kind o' that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort. Have ye any ore ta spare?",ends={{npcID=142994,x=0.662,y=0.284,zoneID=8568}},questType="standard"},
[53207] = {id=53207,name="The Warfront Looms",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="Our focus must expand beyond Kul Tiras. The Alliance still presses against our forces in other parts of the globe. We are most interested in the Arathi Highlands, near Stromgarde. We've set up an encampment in the area, with the intent of capturing Stromgarde. Speak with Throk , the recruitment officer for the division in charge of this particular warfront. He could use a good like you.",ends={{npcID=138949,x=0.528,y=0.944,zoneID=8670}},questType="standard"},
[53208] = {id=53208,name="To the Front",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=45,description="We're at war in the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front. Druza Netherfang maintains a portal directly to Ar'gorok. She can help you.",starts={{npcID=138949,x=0.528,y=0.944,zoneID=8670}},ends={{npcID=143019,x=0.26,y=0.356,zoneID=45}},coords={x=0.528,y=0.944,source="quest_giver",zoneID=8670},questType="standard"},
[53209] = {id=53209,name="Warfront Contribution",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="A well-trained army will only get us so far, . We also need money, food, and supplies to keep our army funded, fed, and ready to fight. Show some pride and give what you can. For the Horde!",starts={{npcID=138949,x=0.528,y=0.944,zoneID=8670}},ends={{npcID=138949,x=0.528,y=0.944,zoneID=8670}},coords={x=0.528,y=0.944,source="quest_giver",zoneID=8670},questType="standard"},
[53210] = {id=53210,name="Touring the Front",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=45,description="The Alliance haven't attacked for a while now. Neither have we, actually. It should be safe to head on out and do some scouting. Check in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't gone and gotten themselves killed, and the trip should give you a bit of a lay of the land. Speaking of which, you might also talk to Flightgineer Krazzle . He can give you a quick look at Stromgarde, so you can see what we're up against.",starts={{npcID=143019,x=0.26,y=0.356,zoneID=45}},ends={{npcID=143019,x=0.26,y=0.356,zoneID=45}},coords={x=0.26,y=0.356,source="quest_giver",zoneID=45},questType="standard"},
[53211] = {id=53211,name="Arathi Donations: Coastal Healing Potion",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.",ends={{npcID=142993,x=0.666,y=0.238,zoneID=8568}},questType="standard"},
[53212] = {id=53212,name="Back to Zuldazar",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="That should just about do it for now, then. We'll be in touch if the fighting heats back up again. Should be any day now, honestly.",starts={{npcID=143019,x=0.26,y=0.356,zoneID=45}},ends={{npcID=138949,x=0.528,y=0.944,zoneID=8670}},coords={x=0.26,y=0.356,source="quest_giver",zoneID=45},questType="standard"},
[53213] = {id=53213,name="Arathi Donations: Coastal Mana Potion",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota. You wouldn't happen to know where one can acquire additional mana potions, would you?",ends={{npcID=142993,x=0.666,y=0.238,zoneID=8568}},questType="standard"},
[53216] = {id=53216,name="Arathi Donations: Shimmerscale",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="I'll keep it simple: we need more Shimmerscale ! I apologize for being so forward with you, but there's little time to waste. If you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?",ends={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},questType="standard"},
[53217] = {id=53217,name="Arathi Donations: Coarse Leather Barding",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="It's not just our allies we need to protect in the upcoming battle, but our equine friends as well! Can you lend a hand and ensure our allies receive the best possible armor for the battle ahead?",ends={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},questType="standard"},
[53218] = {id=53218,name="Arathi Donations: Monel-Hardened Hoofplates",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well. If ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.",ends={{npcID=142994,x=0.662,y=0.284,zoneID=8568}},questType="standard"},
[53219] = {id=53219,name="Arathi Donations: Monel-Hardened Stirrups",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction. If yer able ta bring me a few I'll be sure they're put ta good use.",ends={{npcID=142994,x=0.662,y=0.284,zoneID=8568}},questType="standard"},
[53221] = {id=53221,name="Mission Report: Missing Supplies",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the mission at Vulture's Nest. It details that the mission was a success and the lost supply shipment has been recovered. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53222] = {id=53222,name="Necessary Supplies",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8501,description="The mission to recover the supplies was a success. Well done, . The supply shipment in question was ordered by Buzz Crankchug at Vulture's Nest. You should check in with the outpost in Vol'dun and ensure that all of the missing supplies have been accounted for. Make your way to Vulture's Nest in Vol'dun and speak with Buzz Crankchug .",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=138256,x=0.536,y=0.376,zoneID=8501}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53223] = {id=53223,name="Arathi Donations: Grilled Catfish",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Greetings, traveler. I was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?",ends={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},questType="standard"},
[53224] = {id=53224,name="Arathi Donations: Seasoned Loins",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.",ends={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},questType="standard"},
[53225] = {id=53225,name="Arathi Donations: Great Sea Catfish",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,description="Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish. If we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. If you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.",ends={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},questType="standard"},
[53226] = {id=53226,name="Arathi Donations: Tidespray Linen",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},ends={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},coords={x=0.67,y=0.278,source="quest_giver",zoneID=8568},questType="standard"},
[53227] = {id=53227,name="Arathi Donations: Battle Flag: Spirit of Freedom",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},ends={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},coords={x=0.67,y=0.278,source="quest_giver",zoneID=8568},questType="standard"},
[53228] = {id=53228,name="Arathi Donations: Battle Flag: Phalanx Defense",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},ends={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},coords={x=0.67,y=0.278,source="quest_giver",zoneID=8568},questType="standard"},
[53229] = {id=53229,name="Arathi Donations: Enchant Ring - Seal of Critical Strike",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=143007,x=0.664,y=0.252,zoneID=8568}},ends={{npcID=143007,x=0.664,y=0.252,zoneID=8568}},coords={x=0.664,y=0.252,source="quest_giver",zoneID=8568},questType="standard"},
[53230] = {id=53230,name="Arathi Donations: Enchant Ring - Seal of Versatility",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=143007,x=0.664,y=0.252,zoneID=8568}},ends={{npcID=143007,x=0.664,y=0.252,zoneID=8568}},coords={x=0.664,y=0.252,source="quest_giver",zoneID=8568},questType="standard"},
[53231] = {id=53231,name="Arathi Donations: Gloom Dust",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=143007,x=0.664,y=0.252,zoneID=8568}},ends={{npcID=143007,x=0.664,y=0.252,zoneID=8568}},coords={x=0.664,y=0.252,source="quest_giver",zoneID=8568},questType="standard"},
[53232] = {id=53232,name="Arathi Donations: Incendiary Ammunition",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by. Today I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.",ends={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},questType="standard"},
[53233] = {id=53233,name="Arathi Donations: Frost-Laced Ammunition",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Hey there! Transmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected! From what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic! Maybe they'd even let me keep one to examine!",ends={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},questType="standard"},
[53234] = {id=53234,name="Arathi Donations: F.R.I.E.D.",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected! We've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.",ends={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},questType="standard"},
[53235] = {id=53235,name="Arathi Donations: War-Scroll of Intellect",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Enlightenment guides our path to victory. In battle, we fight as one. Share your knowledge and skills with me. Generosity is never forgotten.",ends={{npcID=143005,x=0.674,y=0.24,zoneID=8568}},questType="standard"},
[53236] = {id=53236,name="Arathi Donations: War-Scroll of Fortitude",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=143005,x=0.674,y=0.24,zoneID=8568}},ends={{npcID=143005,x=0.674,y=0.24,zoneID=8568}},coords={x=0.674,y=0.24,source="quest_giver",zoneID=8568},questType="standard"},
[53237] = {id=53237,name="Arathi Donations: War-Scroll of Battle Shout",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=143005,x=0.674,y=0.24,zoneID=8568}},ends={{npcID=143005,x=0.674,y=0.24,zoneID=8568}},coords={x=0.674,y=0.24,source="quest_giver",zoneID=8568},questType="standard"},
