[53264] = {id=53264,name="Arathi Donations: Great Sea Catfish",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10052,starts={{npcID=142973,x=0.538,y=0.942,zoneID=8670}},ends={{npcID=142973,x=0.538,y=0.942,zoneID=8670}},coords={x=0.538,y=0.942,source="quest_giver",zoneID=8670},questType="standard"},
[53265] = {id=53265,name="Arathi Donations: Gold",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We've spent a great deal of time and resources preparing for the battle to come. As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. Would you like to make a donation?",ends={{npcID=142685,x=0.662,y=0.274,zoneID=8568}},questType="standard"},
[53267] = {id=53267,name="Mission Report: Dino Research",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the mission at Verdant Hollow. It details that the mission was a success and a variety of dinasaur specimens have been recovered. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53268] = {id=53268,name="Dino Research",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8499,description="The mission to gather research specimens was a success. Well done, . You should check in with the outpost commander and inspect the specimens yourself. Make your way to Verdant Hollow in Zuldazar and speak with Argrim Stonedeep .",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=142101,x=0.548,y=0.256,zoneID=8499}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53275] = {id=53275,name="Mission Report: Spare Parts",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the mission to collect salvage for Mugamba Overlook. It details that the mission was a success and the necessary materials have been collected. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53276] = {id=53276,name="Spare Parts",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8499,description="An engineer has been assigned to Mugamba Overlook to build a scrapping machine. The mission to salvage materials for the machine was a success thanks to your leadership. Make your way to Mugamba Overlook in Zuldazar and meet with Gilblin Clockspark. He has been overseeing the upgrades for the outpost.",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=143430,x=0.448,y=0.272,zoneID=8499}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53295] = {id=53295,name="Do Your Part",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="The b-b-barber shop? I'm sorry, what? You want to know where the barber shop is? I'm sorry , do you know there is a W-A-R going on right now? Speaking of which, what have you done for the Alliance lately? Get out there and slay some Horde, or I'll shave your head myself.",starts={{npcID=141698,x=0.564,y=0.258,zoneID=8568}},ends={{npcID=141698,x=0.564,y=0.258,zoneID=8568}},coords={x=0.564,y=0.258,source="quest_giver",zoneID=8568},questType="standard"},
[53306] = {id=53306,name="Mission Report: Jungle Escort",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers have sent a report regarding the escort mission to Mistvine Ledge. It details that the mission was a success and the reinforcements arrived safely at their destination. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.",ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},questType="standard"},
[53307] = {id=53307,name="Jungle Escort",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8499,description="There are now healers stationed at Mistvine Ledge. The mission to escort the reinforcements through the jungle was a success thanks to your leadership. Make your way to Mistvine Ledge in Zuldazar and meet with the outpost commander there to ensure she has everything she needs.",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=142288,x=0.644,y=0.472,zoneID=8499}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53310] = {id=53310,name="From the Ashes...",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=141,description="We must return to Stormwind, quickly!",starts={{npcID=107574,x=0.858,y=0.316,zoneID=1519}},ends={{npcID=107574,x=0.858,y=0.316,zoneID=1519}},coords={x=0.858,y=0.316,source="quest_giver",zoneID=1519},questType="standard"},
[53330] = {id=53330,name="WANTED: Razorclaw Alpha",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=9042,description="The Horde requires your contributions! We are in need of materials to craft and repair our arms and armor. There are bountiful resources in this land and they are but ours for the taking. Seek out the largest wolf you can find, slay it, and secure it's pelt so that we may craft a cloak befitting Rexxar! - Centurion Kaga Warmstone",starts={{npcID=297492,x=0.51,y=0.336,zoneID=9042}},ends={{npcID=138886,x=0.52,y=0.336,zoneID=9042}},coords={x=0.51,y=0.336,source="quest_giver",zoneID=9042},questType="group"},
[53332] = {id=53332,name="Time for War",level=35,requiredLevel=35,faction="alliance",expansion=7,zoneID=8568,description="You should return to Commander Wyrmbane to begin working with the 7th Legion.",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53333] = {id=53333,name="Time for War",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=8499,description="You should return to Nathanos Blightcaller to begin working with The Honorbound.",starts={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[53334] = {id=53334,name="Arathi Donations: War Resources",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142700,x=0.662,y=0.27,zoneID=8568}},ends={{npcID=142700,x=0.662,y=0.27,zoneID=8568}},coords={x=0.662,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[53335] = {id=53335,name="Arathi Donations: War Resources",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,starts={{npcID=142158,x=0.516,y=0.95,zoneID=8670}},ends={{npcID=142158,x=0.516,y=0.95,zoneID=8670}},coords={x=0.516,y=0.95,source="quest_giver",zoneID=8670},questType="standard"},
[53336] = {id=53336,name="WANTED: Sabertusk Empress",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8499,description="To any and all brave enough to seek the challenge: Find and defeat a ferocious Sabertusk Empress , the strongest and most vicious of all sabertusks in Zuldazar . They can be found up and down the road from the Village in the Vines. A reward for any that succeed!",starts={{npcID=287189,x=0.517,y=0.454,zoneID=8499}},ends={{npcID=141949,x=0.448,y=0.274,zoneID=8499}},coords={x=0.517,y=0.454,source="quest_giver",zoneID=8499},questType="group"},
[53337] = {id=53337,name="WANTED: Prime Thumpknuckle",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8499,description="To any and all brave enough to seek the challenge: Find and defeat a Prime Thumpknuckle , the largest and most dangerous of all the wild gorillas. They can be found up and down the road from the Village in the Vines. A reward for any that succeed!",starts={{npcID=287189,x=0.517,y=0.454,zoneID=8499}},ends={{npcID=141949,x=0.448,y=0.274,zoneID=8499}},coords={x=0.517,y=0.454,source="quest_giver",zoneID=8499},questType="group"},
[53338] = {id=53338,name="Prove your Worth",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="See many Alliance out there, ? We're getting reports of more and more Alliance showing up here on Zandalar. Don't forget that this is a W-A-R. Prove your worth, and get out there and slay as many of them as you can. For the Horde!",starts={{npcID=143551,x=0.514,y=0.58,zoneID=8499}},ends={{npcID=143551,x=0.514,y=0.58,zoneID=8499}},coords={x=0.514,y=0.58,source="quest_giver",zoneID=8499},questType="standard"},
[53342] = {id=53342,name="Molten Core",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=1519,description="We'll need a fragment o' the core tae repair the Black Anvil an' who knows how much dark iron tae achieve the necessary purity. Thaelin can figure that part out. In fact, I think he oughta go with ye tae get yerself a Fragment o' the Molten Core . It's too dangerous tae go deep via mole machine, but he's got a hardy tank that can get ye the rest o' the way from the top. Talk tae me when yer ready.",starts={{npcID=133197,x=0.52,y=0.138,zoneID=1519}},ends={{npcID=133197,x=0.52,y=0.138,zoneID=1519}},coords={x=0.52,y=0.138,source="quest_giver",zoneID=1519},questType="standard"},
[53347] = {id=53347,name="Bumbles the Bee",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,description="Hey $p, thanks for delivering Mom's letter. I was really starting to worry about her! Dad and I have been having a few problems running the farm after she left on her trip. If you didn't show up when you did, we'd still be in real trouble! I was hoping you would be willing to help Bumbles out too. He was hurt when his hive was destoyed. If we feed him some of Dad's special formula, hopefully he will heal up faster. First we need to find the secret ingredient, try looking around at his other lab.",starts={{npcID=131793,x=0.688,y=0.652,zoneID=9042},{npcID=132647,x=0.71,y=0.692,zoneID=9042}},ends={{npcID=132647,x=0.71,y=0.692,zoneID=9042}},coords={x=0.688,y=0.652,source="quest_giver",zoneID=9042},questType="standard"},
[53348] = {id=53348,name="WANTED: Thundersnout",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=9042,description="Thundersnout is the largest of the boars in the valley. She poses a serious threat to our troop movements in the south. As such, Centurion Kaga Warmstone has issued a bounty for proof of her demise. Thundersnout's location is near the Briarback kraul, so beware the local quilboar!",starts={{npcID=297492,x=0.51,y=0.336,zoneID=9042}},ends={{npcID=138886,x=0.52,y=0.336,zoneID=9042}},coords={x=0.51,y=0.336,source="quest_giver",zoneID=9042},questType="group"},
[53351] = {id=53351,name="The MOTHERLODE!!: Ironfoe",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8064,description="Mogul Razdunk has always been a jealous sort, wishin' he was Gallywix or better. But he's the worst sort o' greedy. He won't stop at anythin' tae achieve his ends, nae matter the cost. It was a bold move even fer him tae strike at us in Blackrock Depths. He should've knaewn he was goin' too far. Kill that covetous wretch an' bring the hammer back where it belongs. You'll find him in Kezan. Somewhere he calls \"The Motherlode,\" likely with too many exclamation points.",starts={{npcID=133197,x=0.52,y=0.138,zoneID=1519},{npcID=140309,x=0.57,y=0.306,zoneID=1584}},ends={{npcID=133197,x=0.52,y=0.138,zoneID=1519}},coords={x=0.52,y=0.138,source="quest_giver",zoneID=1519},questType="dungeon"},
[53352] = {id=53352,name="Firelands",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=1519,description="Alright, the hard part should be behind us, . Now, we just need tae take that Molten Core fragment ye recovered into Firelands an' charge it up by Ragnaros' old swimmin' pool. Dinna worry! I'm sendin' Anvil-Thane Thurgaden with ye. Just give me a nudge when ye're ready.",starts={{npcID=133197,x=0.52,y=0.138,zoneID=1519}},ends={{npcID=133197,x=0.52,y=0.138,zoneID=1519}},coords={x=0.52,y=0.138,source="quest_giver",zoneID=1519},questType="standard"},
[53353] = {id=53353,name="Echo of Warlord Zaela",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=5841,description="Warlord Zaela... another name that stains the tongue just to speak it... She was instrumental in freeing Garrosh during his trial when she and her Dragonmaw clan attacked the Temple of the White Tiger. I am ashamed to say that the dragon Kairozdormu was also involved. We will speak of this no more. The temple in Kun Lai Summit is our next destination.",starts={{npcID=143692,x=0.544,y=0.502,zoneID=4},{npcID=143692,x=0.688,y=0.44,zoneID=5841}},ends={{npcID=143692,x=0.544,y=0.502,zoneID=4},{npcID=143692,x=0.688,y=0.44,zoneID=5841}},coords={x=0.544,y=0.502,source="quest_giver",zoneID=4},questType="standard"},
[53354] = {id=53354,name="Echo of Gul'dan",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=5841,description="To attune this shard to the place you wish to go, we must follow some of its history. The first location we will visit is the Dark Portal in the Blasted Lands. It was there that Gul'dan used a piece of the Vision of Time to travel between realities. Join me there when you are ready.",ends={{npcID=143692,x=0.544,y=0.502,zoneID=4},{npcID=143692,x=0.688,y=0.44,zoneID=5841}},questType="standard"},
[53355] = {id=53355,name="Echo of Garrosh Hellscream",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=14,description="Our final destination will take us to the depths beneath your city of Orgrimmar. The way there is barred, but I can get us inside. Meet me outside the gates of Orgrimmar and we will descend together.",starts={{npcID=143692,x=0.544,y=0.502,zoneID=4},{npcID=143692,x=0.688,y=0.44,zoneID=5841}},ends={{npcID=131443,x=0.656,y=0.742,zoneID=8670},{npcID=131443,x=0.656,y=0.742,zoneID=9598}},coords={x=0.544,y=0.502,source="quest_giver",zoneID=4},questType="standard"},
[53358] = {id=53358,name="Test of Hyphen Tech",level=10,requiredLevel=10,faction="none",expansion=7,questType="standard"},
[53359] = {id=53359,name="Arathi Donations: Steelskin Potion",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,starts={{npcID=142159,x=0.512,y=0.954,zoneID=8670}},ends={{npcID=142159,x=0.512,y=0.954,zoneID=8670}},coords={x=0.512,y=0.954,source="quest_giver",zoneID=8670},questType="standard"},
