[53361] = {id=53361,name="Arathi Donations: Meaty Haunch",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.",ends={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},questType="standard"},
[53362] = {id=53362,name="Arathi Donations: Meaty Haunch",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,starts={{npcID=142973,x=0.538,y=0.942,zoneID=8670}},ends={{npcID=142973,x=0.538,y=0.942,zoneID=8670}},coords={x=0.538,y=0.942,source="quest_giver",zoneID=8670},questType="standard"},
