[53368] = {id=53368,name="Arathi Donations: Organic Discombobulation Grenade",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},ends={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},coords={x=0.664,y=0.254,source="quest_giver",zoneID=8568},questType="standard"},
[53369] = {id=53369,name="Make Loh Go",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,description="Hello, ! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure. Care to give it a try?",starts={{npcID=135795,x=0.402,y=0.376,zoneID=9042}},ends={{npcID=137453,x=0.356,y=0.312,zoneID=9042}},coords={x=0.402,y=0.376,source="quest_giver",zoneID=9042},questType="standard"},
[53370] = {id=53370,name="Battle for Azeroth: Hour of Reckoning",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1519,description="Champions of the Alliance, At last the time has come for us to reclaim what is rightfully ours! Our final push to retake Lordaeron Keep shall commence at dawn. The Horde and their Warchief must answer for their crimes!",ends={{npcID=144095,x=0.224,y=0.326,zoneID=1519}},questType="standard"},
[53371] = {id=53371,name="Let's Bee Friends",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,description="We just need to collect some slime from the animated honey creatures that are still roaming around the farm. If you can bring back a few vials of that, we can put all our ingredients together and give the mixture to Bumbles. We should only feed him once a day, or he might get sick like some of the other bees. We're gonna have him all healed up in no time!",starts={{npcID=131793,x=0.688,y=0.652,zoneID=9042},{npcID=132647,x=0.71,y=0.692,zoneID=9042}},ends={{npcID=132647,x=0.71,y=0.692,zoneID=9042}},coords={x=0.688,y=0.652,source="quest_giver",zoneID=9042},questType="standard"},
