[53414] = {id=53414,name="Warfront: The Battle for Stromgarde",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall! Prepare yourself for battle.",starts={{npcID=142721,x=0.66,y=0.26,zoneID=8568}},ends={{npcID=142721,x=0.66,y=0.26,zoneID=8568}},coords={x=0.66,y=0.26,source="quest_giver",zoneID=8568},questType="standard"},
[53416] = {id=53416,name="Warfront: The Battle for Stromgarde",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="Our enemies are relentless in their quest to seize Arathi for themselves. We will never allow it to fall into their hands! We must stop them before the keep is rebuilt! Take up arms. The Alliance is upon us.",starts={{npcID=138949,x=0.528,y=0.944,zoneID=8670}},ends={{npcID=138949,x=0.528,y=0.944,zoneID=8670}},coords={x=0.528,y=0.944,source="quest_giver",zoneID=8670},questType="standard"},
[53430] = {id=53430,name="Order of Embers Crossbow",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,mapID=896,starts={{npcID=297939,x=0.426,y=0.251,mapID=896}},ends={{npcID=297939,x=0.426,y=0.251,mapID=896}},coords={x=0.426,y=0.251,source="quest_giver",mapID=896},questType="standard"},
