[54346] = {id=54346,name="Darkshore Donations: Gold",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="Our friends here are accepting all kinds of donations on behalf of the war effort, but if ya ask me, no battle was ever won without proper funding. That's right, bub. I'm talking about money! And lots of it. If you got it, we need it!",ends={{npcID=142157,x=0.516,y=0.952,zoneID=8670}},questType="standard"},
