[54367] = {id=54367,name="Darkshore Donations: Platinum Ore",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142994,x=0.662,y=0.284,zoneID=8568}},ends={{npcID=142994,x=0.662,y=0.284,zoneID=8568}},coords={x=0.662,y=0.284,source="quest_giver",zoneID=8568},questType="standard"},
[54368] = {id=54368,name="Darkshore Donations: Unstable Temporal Time Shifter",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come. Let's make sure our allies are well prepared.",ends={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},questType="standard"},
[54369] = {id=54369,name="Darkshore Donations: Electroshock Mount Motivator",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="I'll keep it simple: we need more Shimmerscale! I apologize for being so forward with you, but there's little time to waste. If you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?",ends={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},questType="standard"},
[54370] = {id=54370,name="Darkshore Donations: XA-1000 Surface Skimmer",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Ye look like the kind o' that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort. Have ye any ore ta spare?",ends={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},questType="standard"},
[54371] = {id=54371,name="Darkshore Donations: Thermo-Accelerated Plague Spreader",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="It's not just our allies we need to protect in the upcoming battle, but our equine friends as well! Can you lend a hand and ensure our allies receive the best possible armor for the battle ahead?",ends={{npcID=143008,x=0.664,y=0.254,zoneID=8568}},questType="standard"},
[54372] = {id=54372,name="Darkshore Donations: Umbra Shard",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=143007,x=0.664,y=0.252,zoneID=8568}},ends={{npcID=143007,x=0.664,y=0.252,zoneID=8568}},coords={x=0.664,y=0.252,source="quest_giver",zoneID=8568},questType="standard"},
