[54376] = {id=54376,name="Darkshore Donations: Potion of Replenishment",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142993,x=0.666,y=0.238,zoneID=8568}},ends={{npcID=142993,x=0.666,y=0.238,zoneID=8568}},coords={x=0.666,y=0.238,source="quest_giver",zoneID=8568},questType="standard"},
[54377] = {id=54377,name="Darkshore Donations: Crimson Ink",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Enlightenment guides our path to victory. In battle, we fight as one. Share your knowledge and skills with me. Generosity is never forgotten.",ends={{npcID=143005,x=0.674,y=0.24,zoneID=8568}},questType="standard"},
[54378] = {id=54378,name="Darkshore Donations: Potion of Bursting Blood",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142993,x=0.666,y=0.238,zoneID=8568}},ends={{npcID=142993,x=0.666,y=0.238,zoneID=8568}},coords={x=0.666,y=0.238,source="quest_giver",zoneID=8568},questType="standard"},
[54379] = {id=54379,name="Darkshore Donations: Contract: 7th Legion",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Greetings! With the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you! Now, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.",ends={{npcID=143005,x=0.674,y=0.24,zoneID=8568}},questType="standard"},
[54380] = {id=54380,name="Darkshore Donations: Gold",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We've spent a great deal of time and resources preparing for the battle to come. As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. Would you like to make a donation?",ends={{npcID=142685,x=0.662,y=0.274,zoneID=8568}},questType="standard"},
[54381] = {id=54381,name="Darkshore Donations: Ultramarine Ink",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Greetings, traveler. I was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?",ends={{npcID=143005,x=0.674,y=0.24,zoneID=8568}},questType="standard"},
[54382] = {id=54382,name="Darkshore Donations: Deep Sea Satin",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish. If we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. If you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.",ends={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},questType="standard"},
[54383] = {id=54383,name="Darkshore Donations: Shimmerscale Diving Suit",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Hey there! Transmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected! From what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic! Maybe they'd even let me keep one to examine!",ends={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},questType="standard"},
[54384] = {id=54384,name="Darkshore Donations: Tidespray Linen Net",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by. Today I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.",ends={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},questType="standard"},
[54385] = {id=54385,name="Darkshore Donations: Tidespray Linen Bandage",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},ends={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},coords={x=0.67,y=0.278,source="quest_giver",zoneID=8568},questType="standard"},
[54386] = {id=54386,name="Darkshore Donations: Deep Sea Bandage",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected! We've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.",ends={{npcID=142998,x=0.67,y=0.278,zoneID=8568}},questType="standard"},
[54387] = {id=54387,name="Darkshore Donations: Blood-Stained Bone",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},ends={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},coords={x=0.67,y=0.29,source="quest_giver",zoneID=8568},questType="standard"},
[54388] = {id=54388,name="Darkshore Donations: Shimmerscale Diving Helmet",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},ends={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},coords={x=0.67,y=0.29,source="quest_giver",zoneID=8568},questType="standard"},
[54389] = {id=54389,name="Darkshore Donations: Mistscale",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},ends={{npcID=142995,x=0.67,y=0.29,zoneID=8568}},coords={x=0.67,y=0.29,source="quest_giver",zoneID=8568},questType="standard"},
[54390] = {id=54390,name="Darkshore Donations: Masterful Kubiline",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.",ends={{npcID=143004,x=0.674,y=0.24,zoneID=8568}},questType="standard"},
[54391] = {id=54391,name="Darkshore Donations: Quick Golden Beryl",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.",ends={{npcID=143004,x=0.674,y=0.24,zoneID=8568}},questType="standard"},
[54392] = {id=54392,name="Darkshore Donations: Sand Shifter",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction. If yer able ta bring me a few I'll be sure they're put ta good use.",ends={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},questType="standard"},
[54393] = {id=54393,name="Darkshore Donations: Scarlet Diamond",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well. If ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.",ends={{npcID=143004,x=0.674,y=0.24,zoneID=8568}},questType="standard"},
[54394] = {id=54394,name="Darkshore Donations: Stringy Loins",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota. You wouldn't happen to know where one can acquire additional mana potions, would you?",ends={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},questType="standard"},
[54395] = {id=54395,name="Darkshore Donations: Seasoned Steak and Potatoes",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.",ends={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},questType="standard"},
[54396] = {id=54396,name="Darkshore Donations: Wild Berry Bread",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,starts={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},ends={{npcID=142997,x=0.668,y=0.272,zoneID=8568}},coords={x=0.668,y=0.272,source="quest_giver",zoneID=8568},questType="standard"},
[54402] = {id=54402,name="Shifting Gears",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,description="! The Alliance has made a new request for Gnomeregan's might. Captain Sparknozzle wishes for your expert assistance in the matter. He'll be waiting for you in New Tinkertown, outside of Gnomeregan.",starts={{npcID=147939,x=0.546,y=0.184,zoneID=1519}},ends={{npcID=147943,x=0.418,y=0.314,zoneID=6457}},coords={x=0.546,y=0.184,source="quest_giver",zoneID=1519},questType="standard"},
[54404] = {id=54404,name="Dark Iron Machinations",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="We have some additional support for our plan to deceive the Horde and assault the Blood Gates, but we need your help. The Dark Iron dwarves have several mole machines waiting to erupt and supply fresh troops. I've determined several spots within Zalamar that would be perfect for them to use. Take this device and plant it in the following areas. It will send a message to the Dark Iron dwarves to erupt from there. They will stay safely in their machines until our army arrives.",starts={{npcID=147843,x=0.504,y=0.842,zoneID=8500}},ends={{npcID=147844,x=0.442,y=0.786,zoneID=8500}},coords={x=0.504,y=0.842,source="quest_giver",zoneID=8500},questType="standard"},
[54407] = {id=54407,name="Lurking in the Swamp",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="We have Zalamar, and we've got our fog. Now, we have to take the attack to the Horde. Our goal is to take as much land in Nazmir as possible to make the Horde think our main fleet is here. The first target is Zul'jan ruins, one of the Horde's main bases in Nazmir. We'll have to make our way through the swamps to our attack position. Meet us there.",starts={{npcID=147842,x=0.336,y=0.476,zoneID=8500}},ends={{npcID=147842,x=0.336,y=0.476,zoneID=8500}},coords={x=0.336,y=0.476,source="quest_giver",zoneID=8500},questType="standard"},
[54412] = {id=54412,name="Zul'jan Deluge",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="Through the mists is Zul'jan ruins, a major Horde outpost in Nazmir. We need to take it over to help our forces push forward. The Horde needs to believe a large Alliance army is here, so we're going to throw everything we've got at taking the ruins. Our army will charge forward to attack, while you join them using my water elemental . Meet me outside of the ruins when you're done, we'll need to keep pushing forward.",starts={{npcID=147842,x=0.336,y=0.476,zoneID=8500}},ends={{npcID=147842,x=0.336,y=0.476,zoneID=8500}},coords={x=0.336,y=0.476,source="quest_giver",zoneID=8500},questType="standard"},
[54416] = {id=54416,name="Warfront Preparations",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="We must make our preparations. Return to Zandalar immediately and rally our forces. Any contributions to our cause must be made. Go. We will hold for now.",starts={{npcID=146323,x=0.518,y=0.216,zoneID=10226}},ends={{npcID=138949,x=0.528,y=0.944,zoneID=8670}},coords={x=0.518,y=0.216,source="quest_giver",zoneID=10226},questType="standard"},
[54417] = {id=54417,name="Showing Our Might",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="We are within reach of the Blood Gate in Zandalar. Once we take that, the Horde and Zandalari will believe our full invasion has begun. Our forces have already engaged the Zandalari within the Fallen Outpost. We'll need your help to push them back. I'll be focusing on finishing off what remains of the Horde and Zandalari back in Zul'jan ruins.",starts={{npcID=147842,x=0.336,y=0.476,zoneID=8500}},ends={{npcID=147842,x=0.336,y=0.476,zoneID=8500}},coords={x=0.336,y=0.476,source="quest_giver",zoneID=8500},questType="standard"},
[54418] = {id=54418,name="The Mech of Death",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="We have reports of a goblin machine causing havoc among our troops up ahead. They call it the A.M.O.D. It is a crude machine compared to what the Lightforged have aboard the Vindicaar. Together, you and I will bring down this machine. Go, I will await for you near the machine and engage it when you are ready.",starts={{npcID=147844,x=0.442,y=0.786,zoneID=8500}},ends={{npcID=147844,x=0.442,y=0.786,zoneID=8500}},coords={x=0.442,y=0.786,source="quest_giver",zoneID=8500},questType="standard"},
[54419] = {id=54419,name="Quelling the Masses",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=8726,description="One of my own in de Rastari has seen fit to rile de drudges and guards in de Zocalo. They threaten de stability of our empire with this foolishness. If they are angry, we can address it. But this wanton destruction will not stand. Go down into de market of de Zocalo and bring about calm however you can. Choose de method that works for you. I care only for de result: Peace, so Talanji can finally be crowned.",starts={{npcID=145360,x=0.404,y=0.122,zoneID=8670}},ends={{npcID=145359,x=0.404,y=0.12,zoneID=8670}},coords={x=0.404,y=0.122,source="quest_giver",zoneID=8670},questType="standard"},
[54421] = {id=54421,name="Taming their Beasts",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="Our goal is to assault the Blood Gate, but to be blunt, we don't have the force necessary for this. That's why we have gnomish technology. The Zandalari have battle beasts, direhorns mounted with powerful weapons. Several of these beasts are resting within the Fallen Outpost. This device, the Re-Discombobulator , will give us control over these animals. Take this device and use it on these battle beasts. We'll assault the Blood Gates once we have them under our control.",starts={{npcID=147843,x=0.504,y=0.842,zoneID=8500}},ends={{npcID=147843,x=0.504,y=0.842,zoneID=8500}},coords={x=0.504,y=0.842,source="quest_giver",zoneID=8500},questType="standard"},
[54424] = {id=54424,name="A Shady Character",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your followers tell of a smuggler of wit and guile, who was able to charm them with stories of lands far and wide. Though it cost a fair sum to retrieve, they managed to obtain a token which when displayed to the smuggler, will allow the bearer to purchase his wares.",ends={{npcID=148024,x=0.696,y=0.182,zoneID=8568}},questType="standard"},
[54433] = {id=54433,name="Orders from Azshara",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="This medallion is inscribed with orders commanding the naga to invade our shores and seize artifacts of power. I've heard tales of a priest who used a horrifying dagger to fight the Burning Legion. It is said this blade... Xal'atath ... whispers secrets of the deep. It might be our best chance of uncovering what the naga seek. I recently came upon a makeshift naga altar in Atal'Gral. If you take Xal'atath there, the dagger may reveal crucial information.",starts={{npcID=134345,x=0.714,y=0.302,zoneID=8499}},ends={{npcID=311885,x=0.78,y=0.367,zoneID=8499},{npcID=311885,x=0.342,y=0.318,zoneID=9042}},coords={x=0.714,y=0.302,source="quest_giver",zoneID=8499},questType="standard"},
[54436] = {id=54436,name="Wisp'd Into Shape",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10058,description="We're off to a good start, but we're going to need more wood if we want to win this battle! The Horde has set up a lumber mill to the north of Bashal'Aran, past Forlorn Crossing. If we take it, we can stop them from destroying the forest while also getting the wisps to help us out. It's a two-for-one!",starts={{npcID=145770,x=0.51,y=0.568,zoneID=10058}},ends={{npcID=144759,x=0.56,y=0.444,zoneID=10058},{npcID=145770,x=0.51,y=0.568,zoneID=10058}},coords={x=0.51,y=0.568,source="quest_giver",zoneID=10058},questType="standard"},
[54438] = {id=54438,name="Crucible of Storms: Relics of Shadow",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Your intention to stop the naga attacks was noble, . But that shadowy dagger tricked you into delivering powerful relics into the hands of a great enemy. No doubt those artifacts will be well defended. Gather your allies, , and return to the Crucible of Storms. Defeat any opponents that stand in your way. Ensure the relics cannot be used against the Alliance. The naga cannot be allowed to summon their storm... or to call forth something even worse.",starts={{npcID=146902,x=0.674,y=0.21,zoneID=8568}},ends={{npcID=146902,x=0.674,y=0.21,zoneID=8568}},coords={x=0.674,y=0.21,source="quest_giver",zoneID=8568},questType="raid"},
[54439] = {id=54439,name="Crucible of Storms: Relics of Shadow",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9598,description="Your intention to stop de naga attacks was noble, . But de talking dagger tricked you into delivering powerful relics into de hands of our enemies. No doubt dese artifacts will be well defended. Gather your allies, , and return to de Crucible of Storms. Defeat any opponents dat stand in your way. Ensure dese relics cannot be used against de Horde. And if any shadowy weapons ask you to do favors for dem in de future... I suggest you decline.",starts={{npcID=133050,x=0.498,y=0.422,zoneID=8670},{npcID=146335,x=0.498,y=0.464,zoneID=8670},{npcID=133050,x=0.396,y=0.692,zoneID=8670}},ends={{npcID=133050,x=0.498,y=0.422,zoneID=8670},{npcID=146335,x=0.498,y=0.464,zoneID=8670},{npcID=133050,x=0.396,y=0.692,zoneID=8670}},coords={x=0.498,y=0.422,source="quest_giver",zoneID=8670},questType="raid"},
[54441] = {id=54441,name="Taking the Blood Gate",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8500,description="We have our forces spread out throughout Nazmir, but we need to do something that will force Rastakhan into action. We must personally march into Zuldazar and take the Blood Gate. This will cause them to throw their full army at us. As you can see, we're the only ones left that can assault the Blood Gate. Shaw and Telaamon will stay behind to help the rest of the army move up. You and I will ride the battle beast into the Blood Gate and take it by force.",starts={{npcID=147842,x=0.336,y=0.476,zoneID=8500}},ends={{npcID=147843,x=0.504,y=0.842,zoneID=8500}},coords={x=0.336,y=0.476,source="quest_giver",zoneID=8500},questType="standard"},
[54447] = {id=54447,name="A Shady Character",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description="Your followers tell of a smuggler of wit and guile, who was able to charm them with stories of lands far and wide. Though it cost a fair sum to retrieve, they managed to obtain a token which when displayed to the smuggler, will allow the bearer to purchase his wares.",ends={{npcID=148080,x=0.456,y=0.864,zoneID=8670}},questType="standard"},
[54453] = {id=54453,name="Supplies from Magni",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=1377,description="Champion of Azeroth, I appreciate all the help you've given us. Please take these supplies as a token of my gratitude, and a promise of more to come, should you continue to help.",ends={{npcID=130216,x=0.422,y=0.442,zoneID=1377}},questType="standard"},
[54454] = {id=54454,name="Supplies from the 7th Legion",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description=", thanks to your efforts against the Horde, our forces have been able to secure additional resources from the battlefield. The more you continue to dominate the battlefield the more resources our forces can spare.",ends={{npcID=135446,x=0.692,y=0.25,zoneID=8568}},questType="standard"},
[54455] = {id=54455,name="Supplies from the Honorbound",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description=", thanks to your efforts against the Alliance, our forces have been able to secure additional resources from the battlefield. The more you continue to dominate the battlefield the more resources our forces can spare.",ends={{npcID=135447,x=0.58,y=0.626,zoneID=8499}},questType="standard"},
[54456] = {id=54456,name="Supplies from the Order of Embers",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8721,description="The Order of Embers appreciate all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",ends={{npcID=135815,x=0.378,y=0.49,zoneID=8721}},questType="standard"},
[54457] = {id=54457,name="Supplies from Storm's Wake",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="We appreciate all the help you've given us, may the tides watch over you. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",ends={{npcID=135800,x=0.592,y=0.694,zoneID=9042}},questType="standard"},
[54458] = {id=54458,name="Supplies from the Proudmoore Admiralty",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="The Proudmoore Admiralty appreciates all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",ends={{npcID=135808,x=0.676,y=0.218,zoneID=8568}},questType="standard"},
[54459] = {id=54459,name="He Who Walks in the Light",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Shaw reports that Zandalari scouts have been dispatched to alert of our \"full assault\". We did it, . The Horde and Zandalari will throw their armies at our forces within Nazmir. We cannot let their sacrifice be in vain. We must get back to Boralus and let Halford know it's time to strike. Come, I'll create a portal for us to leave, once we say one final word to Telaamon.",starts={{npcID=147842,x=0.336,y=0.476,zoneID=8500}},ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},coords={x=0.336,y=0.476,source="quest_giver",zoneID=8500},questType="standard"},
[54460] = {id=54460,name="Supplies from Talanji's Expedition",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8500,description="Thanks mon, de expedition appreciates all de help you've given us. Take dese supplies as a token of our thanks, and a promise of more to come, if you continue to help us.",ends={{npcID=135459,x=0.39,y=0.794,zoneID=8500}},questType="standard"},
[54461] = {id=54461,name="Supplies from the Voldunai",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8501,description="Thanks for all the help around Vol'dun , . Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help.",ends={{npcID=135804,x=0.566,y=0.498,zoneID=8501}},questType="standard"},
[54462] = {id=54462,name="Supplies from the Zandalari Empire",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9598,description="De Zandalari Empire appreciates all your help. Please take dese supplies as a token of our gratitude, and a promise of more to come, should you continue to help.",questType="standard"},
[54463] = {id=54463,name="Alchemical Equations",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,starts={{npcID=132228,x=0.742,y=0.066,mapID=1161}},ends={{npcID=132228,x=0.742,y=0.066,mapID=1161}},coords={x=0.742,y=0.066,source="quest_giver",mapID=1161},questType="standard"},
[54464] = {id=54464,name="Alchemical Equations",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,starts={{npcID=122703,x=0.422,y=0.38,mapID=1165}},ends={{npcID=122703,x=0.422,y=0.38,mapID=1165}},coords={x=0.422,y=0.38,source="quest_giver",mapID=1165},questType="standard"},
[54465] = {id=54465,name="Blacksmithing Plans",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,starts={{npcID=133536,x=0.736,y=0.086,mapID=1161}},ends={{npcID=133536,x=0.736,y=0.086,mapID=1161}},coords={x=0.736,y=0.086,source="quest_giver",mapID=1161},questType="standard"},
[54466] = {id=54466,name="Blacksmithing Plans",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,starts={{npcID=127112,x=0.436,y=0.384,mapID=1165}},ends={{npcID=127112,x=0.436,y=0.384,mapID=1165}},coords={x=0.436,y=0.384,source="quest_giver",mapID=1165},questType="standard"},
