[54484] = {id=54484,name="Tailored Training",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,starts={{npcID=122700,x=0.444,y=0.338,mapID=1165}},ends={{npcID=122700,x=0.444,y=0.338,mapID=1165}},coords={x=0.444,y=0.338,source="quest_giver",mapID=1165},questType="standard"},
[54485] = {id=54485,name="Battle of Dazar'alor",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10076,description="Our naval forces are ready to sail for Zuldazar. By the time we're there, the Horde and Zandalari forces should be in Nazmir. Keeshan and Kelsey checked on the bombs placed within Zuldazar harbor. They're primed and ready to destroy the Zandalari fleet. Gather any of your allies and prepare to set sail for Zuldazar. We will strike down the Zandalari and remove the Horde's most powerful ally from this war.",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="raid"},
[54494] = {id=54494,name="Expanding our Influence",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="As we expand the War Effort on the enemy continent we are finding ideal locations to establish new outposts, and even upgrade our current ones. Once secure, these outposts will allow us to utilize a new flight network to quickly and easily navigate the area.",ends={{npcID=135447,x=0.58,y=0.626,zoneID=8499}},questType="standard"},
[54495] = {id=54495,name="Expanding our Influence",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="As we expand the War Effort on the enemy continent we are finding ideal locations to establish new outposts, and even upgrade our current ones. Once secure, these outposts will allow us to utilize a new flight network to quickly and easily navigate the area.",starts={{npcID=135446,x=0.692,y=0.25,zoneID=8568}},ends={{npcID=135446,x=0.692,y=0.25,zoneID=8568}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=8568},questType="standard"},
[54510] = {id=54510,name="Mischief Managed",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Thank you for returning this artifact to us, . Now that we have the Abyssal Scepter, the fleet can advance without fear of the seas being turned against us. Please report our success to High Commander Wyrmbane.",starts={{npcID=146982,x=0.406,y=0.706,zoneID=8499}},ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},coords={x=0.406,y=0.706,source="quest_giver",zoneID=8499},questType="standard"},
[54518] = {id=54518,name="Zero Zeppelins",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="The Horde zeppelins proved to be problematic for our forces here. I tried to construct something quickly, but while the weapon had power, it didn't have the range necessary to take them out. The Lord Admiral has provided us with an expedient solution to the problem! Use this jury-rigged hand cannon on the zeppelins. A quick application of high energy and heat will cause thermal shock and critical failure! To simplify, blow them up while they're grounded!",starts={{npcID=145632,x=0.414,y=0.27,zoneID=8567}},ends={{npcID=145632,x=0.414,y=0.27,zoneID=8567}},coords={x=0.414,y=0.27,source="quest_giver",zoneID=8567},questType="standard"},
[54519] = {id=54519,name="Squad Goals",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="My patrol squad fought off the Horde so Galeheart and I could fly free. I have to stay with the Lord Admiral, so I can't look for them on my own. With any luck, they're out there fighting and waiting for reinforcements. Well, we're here to help save them. Would you find the rest of my patrol squad for me?",starts={{npcID=148015,x=0.422,y=0.298,zoneID=8567}},ends={{npcID=145593,x=0.374,y=0.248,zoneID=8567}},coords={x=0.422,y=0.298,source="quest_giver",zoneID=8567},questType="standard"},
[54559] = {id=54559,name="Free Plumeria!",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="My poor Plumeria has been captured by an exceptionally brutal villain. He has been overseeing the spread of pestilence along the wharf. Rosaline needs my mechanical expertise in fixing our weapons. Would you free my poor Plumeria and slay the vile knight tormenting her?",starts={{npcID=145632,x=0.414,y=0.27,zoneID=8567}},ends={{npcID=145632,x=0.414,y=0.27,zoneID=8567}},coords={x=0.414,y=0.27,source="quest_giver",zoneID=8567},questType="standard"},
[54576] = {id=54576,name="Gnomeregan's Finest",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=3537,description="The leaders of the Alliance have agreed to fund an elite gnomish aerial task force. And you have been chosen to lead the test team for the Gnomish Elite Aerial Rangers. I have assembled some of the finest tinkers and soldiers from Gnomeregan, who are now under your command. The three of them are already here in New Tinkertown. Introduce yourself and assemble them.",starts={{npcID=147943,x=0.418,y=0.314,zoneID=6457}},ends={{npcID=147943,x=0.418,y=0.314,zoneID=6457}},coords={x=0.418,y=0.314,source="quest_giver",zoneID=6457},questType="standard"},
[54577] = {id=54577,name="Shadowed Halls and Dusty Cogs",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,description="An elite aerial unit wouldn't be complete without the newest innovations in flying machine technology. There's just one small problem. The innovative new engine we built was left behind when we evacuated Gnomeregan. We need that prototype if we want these bombers to safely get off the ground!",starts={{npcID=147943,x=0.418,y=0.314,zoneID=6457}},ends={{npcID=147943,x=0.418,y=0.314,zoneID=6457}},coords={x=0.418,y=0.314,source="quest_giver",zoneID=6457},questType="standard"},
[54579] = {id=54579,name="The Gnome Behind the Trogg",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,description="If I just attach the core of this to the input module here... Amplify the matched frequency here... Flip the switch, Commander! Just make sure it's the right one. The left one is the self-destruct switch. Or was that reversed...",starts={{npcID=147952,x=0.554,y=0.19,zoneID=3537},{npcID=147952,x=0.38,y=0.34,zoneID=6457}},ends={{npcID=147952,x=0.554,y=0.19,zoneID=3537},{npcID=147952,x=0.38,y=0.34,zoneID=6457}},coords={x=0.554,y=0.19,source="quest_giver",zoneID=3537},questType="standard"},
[54580] = {id=54580,name="A Tundra Conundrum",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=3537,description="While you were in Gnomeregan, we received a distress signal from Fizzcrank Airstrip in Borean Tundra. This seems like the perfect opportunity to show off what G.E.A.R. can do! I've sent the rest of your squad ahead. Meet them out there.",starts={{npcID=147943,x=0.418,y=0.314,zoneID=6457}},ends={{npcID=147950,x=0.402,y=0.378,zoneID=6457},{npcID=147950,x=0.376,y=0.602,zoneID=67},{npcID=147950,x=0.552,y=0.188,zoneID=3537}},coords={x=0.418,y=0.314,source="quest_giver",zoneID=6457},questType="standard"},
[54581] = {id=54581,name="Now With More Mechanical Fowl",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,description="The gnomes here report that troggs came down from the north and started attacking everygnome and everything. So now it's our job to fix this situation! And luckily, I have the perfect plan for it. We need to calibrate the bomber's gun, and doing so on the ground is much less risky than up in the air. Give it a go, Commander!",starts={{npcID=147952,x=0.554,y=0.19,zoneID=3537},{npcID=147952,x=0.38,y=0.34,zoneID=6457}},coords={x=0.554,y=0.19,source="quest_giver",zoneID=3537},questType="standard"},
[54582] = {id=54582,name="Smarter Than Your Average Trogg",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,description="One of the recon pilots did a scouting run over the station. She reported that there seems to be a trogg on the top level that is larger and smarter than the others. He's somehow managed to get one of the Defendo-Tanks for the station working in his favor. Take him out!",ends={{npcID=147952,x=0.554,y=0.19,zoneID=3537},{npcID=147952,x=0.38,y=0.34,zoneID=6457}},questType="standard"},
[54610] = {id=54610,name="Paragon of the Tortollan Seekers",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=9042,description="Your allies among the Tortollan Seekers have requested your presence. They wish to reward you for your continued efforts on their behalf.",ends={{npcID=134345,x=0.714,y=0.302,zoneID=8499},{npcID=135793,x=0.404,y=0.364,zoneID=9042}},questType="standard"},
[54611] = {id=54611,name="Paragon of the Champions of Azeroth",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=1377,description="A grateful Magni Bronzebeard has requested your presence. He wishes to reward you for your exceptional aid.",ends={{npcID=130216,x=0.422,y=0.442,zoneID=1377}},questType="standard"},
[54618] = {id=54618,name="Paragon of the 7th Legion",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="Commanders of the 7th Legion forces have requested your presence. They wish to reward you for your exceptional efforts.",ends={{npcID=135446,x=0.692,y=0.25,mapID=1161}},questType="standard"},
[54626] = {id=54626,name="Paragon of the Honorbound",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Commanders of the Honorbound forces have requested your presence. They wish to reward you for your exceptional efforts.",ends={{npcID=135447,x=0.58,y=0.626,zoneID=8499}},questType="standard"},
[54627] = {id=54627,name="Paragon of the Order of Embers",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8721,mapID=896,questType="standard"},
[54628] = {id=54628,name="Paragon of the Storm's Wake",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="The grateful Storm's Wake forces have requested your presence. They wish to reward you for your continued efforts on their behalf.",ends={{npcID=135800,x=0.592,y=0.694,zoneID=9042}},questType="standard"},
[54629] = {id=54629,name="Paragon of the Proudmoore Admiralty",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="The grateful leaders of the Proudmoore Admiralty have requested your presence. They wish to reward you for your continued aid to their house.",ends={{npcID=135808,x=0.676,y=0.218,mapID=1161}},questType="standard"},
[54630] = {id=54630,name="Paragon of Talanji's Expedition",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8500,description="Your allies among Talanji's Expedition have requested your presence. They wish to reward you for your continued efforts on their behalf.",ends={{npcID=135459,x=0.39,y=0.794,zoneID=8500}},questType="standard"},
[54631] = {id=54631,name="Paragon of the Voldunai",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8501,description="Your allies among the Voldunai have requested your presence. They wish to reward you for your continued efforts on their behalf.",ends={{npcID=135804,x=0.566,y=0.498,zoneID=8501}},questType="standard"},
[54632] = {id=54632,name="Paragon of the Zandalari Empire",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="The grateful leaders of the Zandalari Empire have requested your presence. They wish to reward you for your exceptional aid.",questType="standard"},
[54635] = {id=54635,name="Mekkatorque's Battle Plans",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8501,description="So we almost got everythin' we need, except for where that airship went! My insurance pals found out where they're hidin' that primo-info. Go and get me Mekkatorque's battle plans , then we can begin the REALLY fun part!",starts={{npcID=146073,x=0.546,y=0.646,zoneID=8567}},ends={{npcID=146073,x=0.546,y=0.646,zoneID=8567}},coords={x=0.546,y=0.646,source="quest_giver",zoneID=8567},questType="standard"},
[54639] = {id=54639,name="A Signal in Storm Peaks",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=67,description="It looks like the signal is being transmitted from Storm Peaks. Time to put these flying machines to work! I'll keep tracking the signal en route in order to get a cleaner read.",starts={{npcID=147952,x=0.554,y=0.19,zoneID=3537},{npcID=147952,x=0.38,y=0.34,zoneID=6457}},ends={{npcID=147950,x=0.552,y=0.188,zoneID=3537},{npcID=147950,x=0.402,y=0.378,zoneID=6457},{npcID=147950,x=0.376,y=0.602,zoneID=67}},coords={x=0.554,y=0.19,source="quest_giver",zoneID=3537},questType="standard"},
[54640] = {id=54640,name="Gnomercy!",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,description="We need to give Tinkerbow some cover while she figures out our new trajectory. It may not look like much, but this is a fully functional spider tank. You'll just need to de-shrinkify it. Use it to distract the troggs down below by thinning their numbers.",starts={{npcID=147950,x=0.376,y=0.602,zoneID=67},{npcID=147950,x=0.552,y=0.188,zoneID=3537},{npcID=147950,x=0.402,y=0.378,zoneID=6457}},ends={{npcID=147950,x=0.376,y=0.602,zoneID=67},{npcID=147950,x=0.552,y=0.188,zoneID=3537},{npcID=147950,x=0.402,y=0.378,zoneID=6457}},coords={x=0.376,y=0.602,source="quest_giver",zoneID=67},questType="standard"},
[54641] = {id=54641,name="For Gnomeregan!",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=67,description="It's time to bring down Sparkspanner, Commander. Just give me the word, and I'll turn this machine straight towards the Halls of Stone!",starts={{npcID=149503,x=0.394,y=0.268,zoneID=67}},ends={{npcID=149503,x=0.394,y=0.268,zoneID=67}},coords={x=0.394,y=0.268,source="quest_giver",zoneID=67},questType="standard"},
[54642] = {id=54642,name="G.E.A.R. Up",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,mapID=27,description="That was a close one, but we managed to defeat Sparkspanner! Gnomanity and Azeroth are saved from a threat they didn't even know about. Hopefully, that's the last time we'll hear from any of Thermaplugg's old goons. We should return to Captain Sparknozzle. He will want a full report.",starts={{npcID=149503,x=0.394,y=0.268,mapID=120}},ends={{npcID=147943,x=0.418,y=0.314,mapID=27}},coords={x=0.394,y=0.268,source="quest_giver",mapID=27},questType="standard"},
[54652] = {id=54652,name="The War Chest",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="Welcome to the warfront, . I am glad we have you fighting on our side. First things first: We need to collect resources in order to strengthen our hold on Bashal'Aran and bolster our troops. Any resources that we collect will go to the War Chest. Open the chest and see what you can use.",starts={{npcID=148479,x=0.514,y=0.562,zoneID=10084}},ends={{npcID=148479,x=0.514,y=0.562,zoneID=10084}},coords={x=0.514,y=0.562,source="quest_giver",zoneID=10084},questType="standard"},
[54654] = {id=54654,name="An Explosive Situation",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="We have some iron available, but we could always use more. Get down to the mine at the Ruins of Lornesta. Seize it from any enemies, and get those goblins to do their job. Giving them something suitably destructive should do the trick.",starts={{npcID=148479,x=0.514,y=0.562,zoneID=10084}},ends={{npcID=144764,x=0.562,y=0.652,zoneID=10084},{npcID=148479,x=0.514,y=0.562,zoneID=10084}},coords={x=0.514,y=0.562,source="quest_giver",zoneID=10084},questType="standard"},
[54655] = {id=54655,name="Lumbering Along",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="We will need more lumber if we're going to build up Bashal'Aran into a proper fortress. You should find an axe in the supplies we brought in for the effort. Grab it, and see what you can do with it to help us get our base rebuilt.",starts={{npcID=148479,x=0.514,y=0.562,zoneID=10084}},ends={{npcID=148479,x=0.514,y=0.562,zoneID=10084}},coords={x=0.514,y=0.562,source="quest_giver",zoneID=10084},questType="standard"},
[54656] = {id=54656,name="Darkshore Recruits",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="We will not win unless we have the power of numbers on our side. First, we need the Barracks restored so Signe can do her work. Signe is one of the Dark Lady's val'kyr, and she can raise forces for us. Once the Barracks is built, talk to Signe and recruit a troop. I'm sure they could learn a lot from fighting alongside you.",starts={{npcID=148479,x=0.514,y=0.562,zoneID=10084}},ends={{npcID=148479,x=0.514,y=0.562,zoneID=10084}},coords={x=0.514,y=0.562,source="quest_giver",zoneID=10084},questType="standard"},
[54657] = {id=54657,name="Arms and Armor",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="Keever knows troops need weapons. And armor. Armor and weapons. Keever wants Archibald to make armor and weapons for troops. You listen to Keever and talk to Archibald .",starts={{npcID=148482,x=0.518,y=0.582,zoneID=10084}},ends={{npcID=148482,x=0.518,y=0.582,zoneID=10084}},coords={x=0.518,y=0.582,source="quest_giver",zoneID=10084},questType="standard"},
[54658] = {id=54658,name="The Altar of Storms",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="The Altar of Storms has been rebuilt. It is a unique kind of altar. The goblin kind. Keever is pleased. Keever wishes to wield that kind of power. Go, listen to Keever, talk to little goblin Mizzyk and find what the Altar can do.",starts={{npcID=148482,x=0.518,y=0.582,zoneID=10084}},ends={{npcID=148482,x=0.518,y=0.582,zoneID=10084}},coords={x=0.518,y=0.582,source="quest_giver",zoneID=10084},questType="standard"},
[54659] = {id=54659,name="An Alchemist for Everything",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="When we first conquered Darkshore, we set up an Alchemy Lab on the shore at Gloomtide Strand to tap into this area's latent power. Unfortunately, things did not go so well and the Alliance have overrun the lab. Would you see them off, and then speak with Professor Blightwell to see what he can do for you?",starts={{npcID=148478,x=0.52,y=0.59,zoneID=10084}},ends={{npcID=148478,x=0.52,y=0.59,zoneID=10084},{npcID=148806,x=0.458,y=0.478,zoneID=10084}},coords={x=0.52,y=0.59,source="quest_giver",zoneID=10084},questType="standard"},
[54660] = {id=54660,name="Throwing Blight",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="We need more firepower, and the goblins are oh so obliging, aren't they. Zarvik in particular has honed his craft ever since our conquest of Darkshore. Why don't you talk to him and see what he's got going at the Workshop?",starts={{npcID=146590,x=0.516,y=0.58,zoneID=10084}},ends={{npcID=146590,x=0.516,y=0.58,zoneID=10084}},coords={x=0.516,y=0.58,source="quest_giver",zoneID=10084},questType="standard"},
[54661] = {id=54661,name="Echolocation",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="Glad you're here! These bats have got to get up and start giving us some more air support. I've got a draft of a flight plan here in Darkshore. It's helped by the fact that our bats can see in the dark, when most of us can't. Talk to Avery and she'll make sure you get safely back to Bashal'Aran.",starts={{npcID=145554,x=0.494,y=0.35,zoneID=10058}},ends={{npcID=146676,x=0.51,y=0.566,zoneID=10084}},coords={x=0.494,y=0.35,source="quest_giver",zoneID=10058},questType="standard"},
[54682] = {id=54682,name="The Missing Blade",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=1519,ends={{npcID=107574,x=0.858,y=0.316,zoneID=1519}},questType="standard"},
[54683] = {id=54683,name="The Black Blade",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=1637,ends={{npcID=134711,x=0.484,y=0.714,zoneID=1637}},questType="standard"},
[54703] = {id=54703,name="Express Delivery",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="The Horde appears to have misplaced some of its Azerite . It would be rude of us not to return it, don't you think? The most efficient way is for me to teleport it back. I've enchanted the harpoons in that launcher over there. Fire them onto the Horde ships in the bay. I can use them as beacons to return the Azerite to the Horde... and send its ships on their way.",starts={{npcID=145580,x=0.362,y=0.298,zoneID=8567}},ends={{npcID=145580,x=0.362,y=0.298,zoneID=8567}},coords={x=0.362,y=0.298,source="quest_giver",zoneID=8567},questType="standard"},
[54706] = {id=54706,name="Made in Kul Tiras",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="Are you curious about how the Kul Tirans joined the Alliance? It was assumed that Kul Tiras would rejoin the Alliance after everything that was done to stabilize their nation. Lady Jaina Proudmoore wanted to cement the allegiance by building King Anduin a ship worthy of the Kul Tiran navy. She wished for help in finding the best shipwright in Kul Tiras, Dorian Atwater. It wouldn't be easy, as Dorian was retired. It all began with a trip to see Cyrus in Boralus Harbor...",starts={{npcID=126332,x=0.522,y=0.136,zoneID=1519},{npcID=148798,x=0.522,y=0.136,zoneID=1519},{npcID=148798,x=0.678,y=0.22,zoneID=8568},{npcID=148798,x=0.712,y=0.44,zoneID=9042}},ends={{npcID=122370,x=0.68,y=0.22,zoneID=8568}},coords={x=0.522,y=0.136,source="quest_giver",zoneID=1519},questType="standard"},
[54708] = {id=54708,name="Home, Home On the Range",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8567,description="Hmm... Along the road to Fort Daelin... to the north... somewhere in the Deadwash. I've marked a spot on your map that seems likely. I think that will get you close enough. I'll report back to the Lord Admiral with what we've learned. Good luck, and I hope our shipwright is willing.",starts={{npcID=150515,x=0.586,y=0.704,zoneID=9042}},ends={{npcID=148870,x=0.502,y=0.498,zoneID=9042},{npcID=148870,x=0.67,y=0.124,zoneID=8567}},coords={x=0.586,y=0.704,source="quest_giver",zoneID=9042},questType="standard"},
[54709] = {id=54709,name="Candy Bucket",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,starts={{npcID=316754,x=0.5,y=0.815,mapID=1165}},ends={{npcID=316754,x=0.5,y=0.815,mapID=1165}},coords={x=0.5,y=0.815,source="quest_giver",mapID=1165},questType="standard"},
[54710] = {id=54710,name="Candy Bucket",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,starts={{npcID=316755,x=0.737,y=0.124,mapID=1161}},ends={{npcID=316755,x=0.737,y=0.124,mapID=1161}},coords={x=0.737,y=0.124,source="quest_giver",mapID=1161},questType="standard"},
[54721] = {id=54721,name="I'm Too Old for This Ship",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="If I understood this correctly, the Lord Admiral of the Kul Tiran navy wants me to come out of retirement specifically to build a ship for the king of Stormwind. Can't say I've had THAT request before. I'm getting too old for this nonsense. Go on out back and saddle Hurricane for me while I pack my things. We will meet you at Port Fogtide. We're going to need a slip.",starts={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},ends={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},coords={x=0.67,y=0.124,source="quest_giver",zoneID=8567},questType="standard"},
[54723] = {id=54723,name="Covering Our Masts",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="When I was younger, I hid my ships out of vanity. I often went through a number of designs before I was satisfied. I didn't want anyone to see that. It might ruin the mystique, I reasoned. Now... I think it best to hide this ship from the likes of those tentacle-faced creeps. I don't think they intend to let us build unchallenged. Go into the port and place my wards around the main slip. You'll see what they do.",starts={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},ends={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},coords={x=0.67,y=0.124,source="quest_giver",zoneID=8567},questType="standard"},
[54725] = {id=54725,name="The Deep Ones",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="I've spent my whole life on and around the sea. Until very recently I feel like I've always had one foot in the water. I knew there were... things... best left untouched. Now they're here. In Stormsong Valley. Occupying the slip I need to build your ship. Do I really need to tell you what to do about it?",starts={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},ends={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},coords={x=0.67,y=0.124,source="quest_giver",zoneID=8567},questType="standard"},
[54726] = {id=54726,name="Frame Work",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="Now that I have a slip to work in, I'm going to need lumber. Lots of lumber. The only lumber mill that could handle this kind of volume at such short notice would be the Algerson Lumber Yard outside of Boralus. I know this because I've made this exact request of them before. I will meet you there. Algerson might need a little persuasion.",starts={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},ends={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},coords={x=0.67,y=0.124,source="quest_giver",zoneID=8567},questType="standard"},
[54727] = {id=54727,name="Team Carry",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="Algerson is about as useful as a legless horse. We're going to do this ourselves. The mill is overrun with bizarre creatures. I'll handle those. You and these hearty volunteers will need to be the muscle of this operation. Don't look at me like that, . It's just a little lifting. Once we have enough lumber, Sal will meet us for a pick up. Just stay close to me and focus on not dropping my wood, yes?",starts={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},ends={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},coords={x=0.67,y=0.124,source="quest_giver",zoneID=8567},questType="standard"},
[54728] = {id=54728,name="This Lumber is Haunted",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8721,description="I don't much believe in ghosts, or hauntings for that matter. That said, there is something wrong with this lumber. I can feel it in my bones. They're achier than normal. I only know of one group that would know what to do. They're reclusive, but we share a love of nature. Seek out Thornspeaker Birchgrove in Drustvar. I trust no one else with this.",starts={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},ends={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},coords={x=0.67,y=0.124,source="quest_giver",zoneID=8567},questType="standard"},
[54729] = {id=54729,name="The Bleak Hills",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8721,description="While you are visiting Drustvar, I need you to run another errand for me. The Wright family owned a mine up near Corlain. Years past, they supplied all the metal ore I used to build my ships. I can't imagine they're faring too well, based on what we've seen here. Find Chelsea Wright , the foreman's daughter, and see what they need to get another ore shipment together. Just tell her Dorian sent you.",starts={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},ends={{npcID=150884,x=0.332,y=0.304,zoneID=8721}},coords={x=0.67,y=0.124,source="quest_giver",zoneID=8567},questType="standard"},
[54730] = {id=54730,name="Gorak Tul's Influence",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8721,description="Long have the Thornspeakers struggled against such magics. It is a conflict as old as the Drust themselves. Gorak Tul's influence, however, has vastly shifted the balance toward that of decay and death. It corrupts what would be an ordinary curse. I believe Ulfar can correct this. Go into Gol Koval. Slay our enemies, destroy their cairns, and collect their magics into this vessel. With it, Ulfar may be able to find a way to cleanse your materials.",starts={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},ends={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},coords={x=0.618,y=0.594,source="quest_giver",zoneID=8721},questType="standard"},
[54731] = {id=54731,name="Balance in All Things",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8721,description="The confluence of energies around that vessel is truly disturbing. My skin crawls with the wrongness of it. We have reached the limit of my ability to help you, . Go to Ulfar , the High Thornspeaker. Arthur will carry you, if you wish it. Only he knows enough about these ancient magics to undo the corruption that taints your materials. Go quickly. You do not want to hold that vessel longer than you must.",starts={{npcID=139926,x=0.618,y=0.594,zoneID=8721}},ends={{npcID=141159,x=0.452,y=0.458,zoneID=8721}},coords={x=0.618,y=0.594,source="quest_giver",zoneID=8721},questType="standard"},
[54732] = {id=54732,name="Drop It!",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8721,description="You must be the person Dorian sent to collect the ore. I got a message a short while ago requesting a rather large shipment, which in itself is a feat given the state of this place. I was on my way to our storehouse when that... beast!... cornered me. It took my keys. I can't get you that shipment without them. Find out where that mongrel took them and bring them back. Let it be known I wouldn't do this for anyone else.",starts={{npcID=150884,x=0.332,y=0.304,zoneID=8721}},ends={{npcID=150885,x=0.366,y=0.288,zoneID=8721}},coords={x=0.332,y=0.304,source="quest_giver",zoneID=8721},questType="standard"},
[54733] = {id=54733,name="Make it Wright",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8721,description="I don't know how this happened, or why... but I know this beast. I've unlocked our storage chest. Thank you. Thank you so much. Tell Dorian she can call upon us at any time.",starts={{npcID=150884,x=0.332,y=0.304,zoneID=8721}},ends={{npcID=322651,x=0.331,y=0.304,zoneID=8721}},coords={x=0.332,y=0.304,source="quest_giver",zoneID=8721},questType="standard"},
[54734] = {id=54734,name="Summons from Dorian",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="HHsssssss. HHHHSSSSSSsssshh.",starts={{npcID=149252,x=0.33,y=0.304,zoneID=8721}},ends={{npcID=148870,x=0.67,y=0.124,zoneID=8567},{npcID=148870,x=0.502,y=0.498,zoneID=9042}},coords={x=0.33,y=0.304,source="quest_giver",zoneID=8721},questType="standard"},
[54735] = {id=54735,name="A Worthy Crew",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8567,description="If Dorian really can build this ship before the day is out, we need to find a crew for the new vessel. This crew should represent the best of Kul Tiran society, the highest naval prowess, and the faith of our people as we present this gift to Anduin. I have a captain in mind, but you'll want to speak to him yourself. I will let him decide who else he wants aboard. Seek out my brother, Tandred Proudmoore , in Boralus. He will help you fill out the ranks from there.",starts={{npcID=148798,x=0.522,y=0.136,zoneID=1519},{npcID=148798,x=0.678,y=0.22,zoneID=8568},{npcID=148798,x=0.712,y=0.44,zoneID=9042}},ends={{npcID=148798,x=0.522,y=0.136,zoneID=1519},{npcID=148798,x=0.678,y=0.22,zoneID=8568},{npcID=148798,x=0.712,y=0.44,zoneID=9042}},coords={x=0.522,y=0.136,source="quest_giver",zoneID=1519},questType="standard"},
[54741] = {id=54741,name="Honor the Flame",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=9042,mapID=942,starts={{npcID=148932,x=0.358,y=0.512,mapID=942}},ends={{npcID=148932,x=0.358,y=0.512,mapID=942}},coords={x=0.358,y=0.512,source="quest_giver",mapID=942},questType="standard"},
[54748] = {id=54748,name="Quest",level=1,requiredLevel=1,faction="none",expansion=7,questType="standard"},
[54751] = {id=54751,name="Soggy Page",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=8499,starts={{npcID=135793,x=0.404,y=0.364,zoneID=9042}},ends={{npcID=135793,x=0.404,y=0.364,zoneID=9042},{npcID=134345,x=0.714,y=0.302,zoneID=8499}},coords={x=0.404,y=0.364,source="quest_giver",zoneID=9042},questType="standard"},
[54754] = {id=54754,name="For the Queen",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=1637,ends={{npcID=134711,x=0.484,y=0.714,zoneID=1637}},questType="standard"},
[54755] = {id=54755,name="Not My Table",level=50,requiredLevel=50,faction="horde",expansion=7,questType="standard"},
[54756] = {id=54756,name="Garbage for the Garbage God",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,description="Richmon, you found a thing I been looking for for a long time. Bring it to me in the Port of Zandalar, and I will grant you my favor.",ends={{npcID=149006,x=0.456,y=0.944,zoneID=8670}},questType="standard"},
[54757] = {id=54757,name="The Loa of Scavengers",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,description="Richmon, you bring me many shiny things. You helped some of those that no one else would. And ya dumb enough to keep comin' back to me trash piles. I like ya style. Now for da big one. Go to the steps of Dazar'alor, and find the Chronicler Ash'tari . Her chisel makes da shrines there. Tell her to build me a shrine and I will grant you my boon. Unlike the flappy Pa'ku or running Gonk, I just gonna let ya scrap your trash in my pile and I'll give ya stuff back. Anywhere my trash piles be.",starts={{npcID=149006,x=0.456,y=0.944,zoneID=8670}},ends={{npcID=137510,x=0.506,y=0.352,zoneID=8670}},coords={x=0.456,y=0.944,source="quest_giver",zoneID=8670},questType="standard"},
[54759] = {id=54759,name="When Spirits Whisper",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=1638,description="Ah, ! I have a message for you. Baine Bloodhoof asks that you join him in Thunder Bluff at once. I suggest you hurry.",starts={{npcID=149088,x=0.392,y=0.79,zoneID=1637}},ends={{npcID=36648,x=0.598,y=0.516,zoneID=1638}},coords={x=0.392,y=0.79,source="quest_giver",zoneID=1637},questType="standard"},
[54760] = {id=54760,name="The Spiritwalkers",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=6452,description="As you know, the spiritwalkers commune with our ancestors and maintain balance within the spirit realm. It is a sacred duty that links our present to our past. But lately the spiritwalkers have been troubled by visions of chaos and turmoil. Of a rising darkness. They tell me that the spirits have whispered your name. We are unsure why, but Spiritwalker Ussoh means to find out. Seek Ussoh on Fargaze Mesa to the south. Good luck, . I believe you may need it.",starts={{npcID=36648,x=0.598,y=0.516,zoneID=1638}},ends={{npcID=149084,x=0.584,y=0.516,zoneID=1638},{npcID=149084,x=0.468,y=0.154,zoneID=14},{npcID=149084,x=0.124,y=0.31,zoneID=6452}},coords={x=0.598,y=0.516,source="quest_giver",zoneID=1638},questType="standard"},
[54761] = {id=54761,name="Spirit Guide",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=6452,description="The ancestors have whispered your name, . Now it is time for you to reach out to them. Here in this sacred place, we spiritwalkers commune with those who came before us. Sit within the circle and light the incense. If you open your heart, a spirit guide will present itself to you. Let us hope it will lead you to the answers we seek.",starts={{npcID=149084,x=0.468,y=0.154,zoneID=14},{npcID=149084,x=0.584,y=0.516,zoneID=1638},{npcID=149084,x=0.124,y=0.31,zoneID=6452}},ends={{npcID=149084,x=0.468,y=0.154,zoneID=14},{npcID=149084,x=0.584,y=0.516,zoneID=1638},{npcID=149084,x=0.124,y=0.31,zoneID=6452}},coords={x=0.468,y=0.154,source="quest_giver",zoneID=14},questType="standard"},
[54762] = {id=54762,name="A Small Retreat",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=406,description="I believe your guide was delivering a warning. The unrest within the spirit realm may be even more dire than first feared. We must cross over at once, from a place with a strong bond to the spirit realm. In ages past, tauren made pilgrimages to Sun Rock Retreat to engage in such a ritual. It is said that long ago, An'she himself kissed the mountain where the retreat now stands. Meet me there and we will begin the crossing.",starts={{npcID=149084,x=0.468,y=0.154,zoneID=14},{npcID=149084,x=0.584,y=0.516,zoneID=1638},{npcID=149084,x=0.124,y=0.31,zoneID=6452}},ends={{npcID=149529,x=0.492,y=0.61,zoneID=406}},coords={x=0.468,y=0.154,source="quest_giver",zoneID=14},questType="standard"},
[54765] = {id=54765,name="Thank Your Guide",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=215,description="The balance has been restored, and Thunder Bluff is safe. Thank you. We owe our victory to your spirit's guidance. We must honor the old ways by giving thanks to the ones who came before us. To the southwest lies a beautiful vista where my father once took me. It would be a fitting place to reflect upon all that has transpired. Please take this offering there to honor our ancestors.",starts={{npcID=36648,x=0.598,y=0.516,zoneID=1638}},ends={{npcID=322737,x=0.34,y=0.387,zoneID=215}},coords={x=0.598,y=0.516,source="quest_giver",zoneID=1638},questType="standard"},
[54766] = {id=54766,name="Answer the Call",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=1638,description="It is fortunate that Spiritwalker Ussoh passed along your spirit guide's warning. We were able to evacuate most of the citizens. This cursed spirit is full of malevolence and hatred. It must be destroyed, ! We attack on your command.",starts={{npcID=149528,x=0.582,y=0.522,zoneID=1638}},ends={{npcID=36648,x=0.598,y=0.516,zoneID=1638}},coords={x=0.582,y=0.522,source="quest_giver",zoneID=1638},questType="standard"},
[54787] = {id=54787,name="Masking For a Friend",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="The Outriggers have fought some pretty tough monsters and Horde savages aren't so much different. The Blight Specialists they brought weren't especially tough, but they were the most dangerous. Kill a few of them and bring back their face masks. Okri can work his mechanical wizardry and build us better masks of our own in case any Horde scum dare show their blight-spreading faces around here again.",starts={{npcID=145593,x=0.374,y=0.248,zoneID=8567}},ends={{npcID=145593,x=0.374,y=0.248,zoneID=8567}},coords={x=0.374,y=0.248,source="quest_giver",zoneID=8567},questType="standard"},
[54843] = {id=54843,name="Remaining Threats",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10084,description="Though our forces maintain a steady hold on Darkshore , this land still festers with enemies at every turn. Do what you can to keep them at bay, and you will be well rewarded.",starts={{npcID=149410,x=0.47,y=0.354,zoneID=148}},ends={{npcID=149410,x=0.47,y=0.354,zoneID=148}},coords={x=0.47,y=0.354,source="quest_giver",zoneID=148},questType="group"},
[54844] = {id=54844,name="Tapping the Breach",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=148,description="Darkshore is home to several elemental breaches which hold massive amounts of power. The remnants of the Twilight's Hammer know this. While we were preoccupied with the Kaldorei, their elementalists have moved to exploit these locations of power, calling forth massive elementals to do their bidding. Their actions must not go unchecked.",starts={{npcID=149411,x=0.478,y=0.362,zoneID=148}},ends={{npcID=149411,x=0.478,y=0.362,zoneID=148}},coords={x=0.478,y=0.362,source="quest_giver",zoneID=148},questType="standard"},
[54845] = {id=54845,name="Buzzkill",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=148,description="Some gnome's been goin about planting these strange machines in the woods here. I don't know what they do, but I'll be dead before I let gnomish machines sully goblin territory! Find these \"buzzboxes\" and reduce them to scrap. I'll make sure you're compensated for your troubles.",starts={{npcID=149412,x=0.464,y=0.35,zoneID=148}},ends={{npcID=149412,x=0.464,y=0.35,zoneID=148}},coords={x=0.464,y=0.35,source="quest_giver",zoneID=148},questType="standard"},
[54850] = {id=54850,name="Operation: Troggageddon",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,description="Tinkerbow has finished installing the guns on our flying machines, so it's time to give them a trial by fire. We've got confirmation that our target is in fact within the Halls of Stone. Let's start clearing out the forces out in front. We'll take the earliest opportunity to bring the fight to Sparkspanner!",starts={{npcID=147950,x=0.376,y=0.602,zoneID=67},{npcID=147950,x=0.552,y=0.188,zoneID=3537},{npcID=147950,x=0.402,y=0.378,zoneID=6457}},coords={x=0.376,y=0.602,source="quest_giver",zoneID=67},questType="standard"},
[54851] = {id=54851,name="Blessing of the Tides",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="Dorian certainly lives up to her reputation, . This magnificent vessel is complete and now it has a crew. Two pieces remain. First, we must give the ship a name. Then it falls to Brother Pike to bless this vessel. As is tradition, a tidesage's blessing fortifies the ship against storms and encourages fair weather and smooth seas. It is as much ceremonial as it is practical. Once that is done, we will set sail for Stormwind.",starts={{npcID=148798,x=0.522,y=0.136,zoneID=1519},{npcID=148798,x=0.678,y=0.22,zoneID=8568},{npcID=148798,x=0.712,y=0.44,zoneID=9042}},ends={{npcID=148798,x=0.522,y=0.136,zoneID=1519},{npcID=148798,x=0.678,y=0.22,zoneID=8568},{npcID=148798,x=0.712,y=0.44,zoneID=9042}},coords={x=0.522,y=0.136,source="quest_giver",zoneID=1519},questType="standard"},
[54871] = {id=54871,name="We Are Coming",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We must press our advantage before the Horde can further its hold on Darkshore. The kaldorei stand ready to fight for our home, and the Gilneans stand alongside us. We will show our enemies our fury. They will learn to fear us. Rally any you can. We march at once.",starts={{npcID=149612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=142721,x=0.66,y=0.26,zoneID=8568}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[54875] = {id=54875,name="Remaining Threats",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10084,description="We have managed to route the Horde presence in Darkshore , but several threats remain throughout the countryside. If we wish to hold this land, they must be eliminated.",starts={{npcID=149623,x=0.468,y=0.354,zoneID=148}},ends={{npcID=149623,x=0.468,y=0.354,zoneID=148}},coords={x=0.468,y=0.354,source="quest_giver",zoneID=148},questType="group"},
[54876] = {id=54876,name="Tapping the Breach",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=148,description="We had thought the Twilight's Hammer's presence in Darkshore was snuffed out with the defeat of Deathwing. Apparently, we were mistaken. Remnants of their cult have used the conflict in Darkshore as an opportunity to re-establish their presence here. Darkshore is home to several breaches of elemental power, and it looks like they aim to use these to unleash powerful elementals to devastate the land. This must not stand.",starts={{npcID=149624,x=0.464,y=0.366,zoneID=148}},ends={{npcID=149624,x=0.464,y=0.366,zoneID=148}},coords={x=0.464,y=0.366,source="quest_giver",zoneID=148},questType="standard"},
[54878] = {id=54878,name="Buzzkill",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=148,description="Some nefarious no-goodnik is tampering with my Buzzboxes! I've been trying to get the Buzzbox network back online since we were able to drive the Horde out of Darkshore , but I'm getting no reading from boxes 456, 627, 111, and 854! I'd be willing to bet that some stragglers from the Bilgewater Cartel are to blame! See if you can get those Buzzboxes back online, will you? We'll need their readings if we ever want to permanently fix the corruption problem here.",starts={{npcID=149631,x=0.464,y=0.352,zoneID=148}},ends={{npcID=149631,x=0.464,y=0.352,zoneID=148}},coords={x=0.464,y=0.352,source="quest_giver",zoneID=148},questType="standard"},
[54913] = {id=54913,name="Spark of Genius",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=67,description=", I have wondrous news! A recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras. I require further data to know for certain, but initial diagnostics suggest that these energies are coming from Hati! We might still be able to save him! Hati's spirit is still bound to your own, so I'll need your help. Meet me at my library in the Storm Peaks right away!",starts={{npcID=152002,x=0.728,y=0.14,zoneID=8568},{npcID=152002,x=0.478,y=0.892,zoneID=8670}},ends={{npcID=149736,x=0.376,y=0.464,zoneID=67}},coords={x=0.728,y=0.14,source="quest_giver",zoneID=8568},questType="standard"},
[54915] = {id=54915,name="Telemetry Online",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=67,description="When Titanstrike's power was expended in Silithus, Hati's essence managed to sever itself from the Thunderspark just in time to avoid destruction. The only problem is that his essence was then scattered across Azeroth, and we don't know where. Now that we've locked onto his energy signature, we should be able to triangulate Hati's position!",starts={{npcID=149736,x=0.376,y=0.464,zoneID=67}},ends={{npcID=149799,x=0.374,y=0.464,zoneID=67}},coords={x=0.376,y=0.464,source="quest_giver",zoneID=67},questType="standard"},
[54916] = {id=54916,name="The Huntsman's Creed",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=67,description="Through the glorious wonder of science, I have managed to keep the Thunderspark powered precisely for this purpose. All you need to do is get to the Temple of Storms and absorb Hati's essence into it. Just... kind of point it in his general direction. Oh, and do keep in mind that this is only one part of Hati. You may run into a few... technical difficulties before he's subdued enough for the absorption protocol.",starts={{npcID=149736,x=0.376,y=0.464,zoneID=67}},ends={{npcID=149870,x=0.336,y=0.586,zoneID=67}},coords={x=0.376,y=0.464,source="quest_giver",zoneID=67},questType="standard"},
[54917] = {id=54917,name="Paid in Blood",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=1377,description="If Mimiron's fancy gadgets be right, then the other half o' Hati is near the wound in Silithus. We'll have tae move quickly. Even with part o' his essence contained, I can feel him fadin' away fast! 'Tis a long trip, . Let's get movin'!",starts={{npcID=149870,x=0.336,y=0.586,zoneID=67}},ends={{npcID=150391,x=0.392,y=0.716,zoneID=1377}},coords={x=0.336,y=0.586,source="quest_giver",zoneID=67},questType="standard"},
[54918] = {id=54918,name="Spark of Imagination",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8161,description="I've diverted all non-essential power to prepare for Hati's reformation, so I cannot teleport you to Ulduar from here. Be extremely careful with the Thunderspark on your way. It is charged with highly volatile energy. One wrong bump could lead to serious complications!",starts={{npcID=150391,x=0.392,y=0.716,zoneID=1377}},coords={x=0.392,y=0.716,source="quest_giver",zoneID=1377},questType="standard"},
[54919] = {id=54919,name="Bonds of Thunder",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8161,description="While you infused Hati's essence into the Thunderspark, I have concocted a flawless plan the likes of which the scientific world has never seen! I'll spare you the technical details. Just follow my instructions and Hati will be back in one piece in no time at all! ...Or we will all explode. But risks must be taken in the pursuit of knowledge and the well-being of our furry companions, wouldn't you agree?",questType="standard"},
[54920] = {id=54920,name="Homeward Bound",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=67,description="The reformation procedure went positively flawlessly! Most excellent results indeed--and plenty of data to analyze! I'm not sure what it is Thorim has to show you, but I suggest you get to the Temple of Storms right away. He gets a bit destructive when he's kept waiting. Take my teleporter pad directly out of Ulduar. I'm afraid the normal route to the entrance is... inoperable at the moment.",ends={{npcID=29445,x=0.334,y=0.58,zoneID=67}},questType="standard"},
[54922] = {id=54922,name="The Nuts and Bolts of It",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="I started working on the leg gearing. Most the gearing around here is built from spare parts we find in the scrap heaps. We're going to need a lot of spare parts to fix this thing. See what you can find.",starts={{npcID=150573,x=0.714,y=0.386,zoneID=10290}},ends={{npcID=150573,x=0.714,y=0.386,zoneID=10290}},coords={x=0.714,y=0.386,source="quest_giver",zoneID=10290},questType="standard"},
[54925] = {id=54925,name="Heresy!",level=40,requiredLevel=40,faction="horde",expansion=7,zoneID=8726,description="My own prelates are among them that revolted against Talanji. This is an unspeakable heresy. I will not tolerate it! This one has wisely told me who is to blame. My second, Kaj'ra. I would have heard her, had she used any other means to make her concerns known. Now she must be disposed of. You will find her in de Terrace of de Chosen.",starts={{npcID=148096,x=0.426,y=0.226,zoneID=8670},{npcID=148096,x=0.502,y=0.49,zoneID=8726},{npcID=148096,x=0.644,y=0.306,zoneID=8726}},ends={{npcID=148096,x=0.426,y=0.226,zoneID=8670},{npcID=148096,x=0.502,y=0.49,zoneID=8726},{npcID=148096,x=0.644,y=0.306,zoneID=8726}},coords={x=0.426,y=0.226,source="quest_giver",zoneID=8670},questType="standard"},
[54929] = {id=54929,name="Ready to Rumble",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="We're going to need a new Sixteen-Servo-Actuator if we're going to fix the controls on this thing. Bondo's gang at the yard probably has one, but they usually aren't too helpful. Talk to Bondo, see if you can get us one.",starts={{npcID=150573,x=0.714,y=0.386,zoneID=10290}},ends={{npcID=150573,x=0.714,y=0.386,zoneID=10290}},coords={x=0.714,y=0.386,source="quest_giver",zoneID=10290},questType="standard"},
[54930] = {id=54930,name="Mechanical Liberation",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8501,description="Since you successfully interrupted my nap, my defenses are obviously lacking to say the least. That's because the sethrak, in addition to stealing my gadgets and gizmos, stole my mechs! Those morons don't even have the keys! Here, take my keys and get my mechs back.",starts={{npcID=145131,x=0.262,y=0.474,zoneID=8501}},ends={{npcID=145131,x=0.262,y=0.474,zoneID=8501}},coords={x=0.262,y=0.474,source="quest_giver",zoneID=8501},questType="standard"},
[54933] = {id=54933,name="Freeing the Light",level=6,requiredLevel=6,faction="both",expansion=7,zoneID=10424,description="Ah... you are not in league with the ogres. Please, you must aid me. I have been bound against my will by dark magic. I ask only that you free me. Take a piece of my light. Use it to dispel the shadow energies that are keeping me captive.",starts={{npcID=157114,x=0.58,y=0.502,zoneID=10424}},ends={{npcID=157114,x=0.58,y=0.502,zoneID=10424}},coords={x=0.58,y=0.502,source="quest_giver",zoneID=10424},questType="standard"},
[54938] = {id=54938,name="A Brother's Help",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8500,description="We're gonna need all the help we can get te save the planet. I've got an idea. Meet me in Nazmir, outside the Heart of Darkness. Together, we'll seek guidance from someone who may be able to help.",starts={{npcID=130216,x=0.422,y=0.442,zoneID=1377},{npcID=136907,x=0.5,y=0.616,zoneID=9667},{npcID=152206,x=0.502,y=0.584,zoneID=9667}},ends={{npcID=149867,x=0.578,y=0.504,zoneID=8500}},coords={x=0.422,y=0.442,source="quest_giver",zoneID=1377},questType="standard"},
[54939] = {id=54939,name="Stubborn as a Bronzebeard",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8500,description="It's kind o' Brann tae offer, but his flying machine would drop like a rock with me aboard. Best if it carry just the two of ye. Brann will fly ye down to Uldir. I'll find me own way and meet ye inside.",starts={{npcID=149867,x=0.578,y=0.504,zoneID=8500}},coords={x=0.578,y=0.504,source="quest_giver",zoneID=8500},questType="standard"},
[54941] = {id=54941,name="Scouting The Strand",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=10052,mapID=1355,description="It has been a long time since we have heard from our scouts at the outpost. They may have been cut off from us due to the naga attack. I need to check in with them and get an update on the movements of the naga forces. You should come with me, this will be a good opportunity for you to meet more of the clan and get a closer look at our operation.",questType="standard"},
[54943] = {id=54943,name="The Dark Ranger's Pupil",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8317,description="Thank the abyss you're here, Huntmaster ! I'm concerned about Dark Ranger Velonara. We have become good friends during our time together in the Trueshot Lodge, and I fear she is in peril. She's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him. I have a bad feeling about all this. Could you check on her safety?",questType="standard"},
[54944] = {id=54944,name="The Dark Ranger's Pupil",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8317,description="Thank the abyss you're here, fellow hunter! I'm concerned about Dark Ranger Velonara, who frequents the Trueshot Lodge. Velonara is a good friend, and I fear she is in peril. She's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him. I have a bad feeling about all this. Would you be willing to check on her safety?",questType="standard"},
[54945] = {id=54945,name="Let's Get It Started",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="I theorize this to be a communication relay. It is non-operational, but gnomish ingenuity and your strong back shall soon solve that problem! I need you to help get this device functional.",starts={{npcID=149877,x=0.658,y=0.664,zoneID=8567}},ends={{npcID=149877,x=0.658,y=0.664,zoneID=8567}},coords={x=0.658,y=0.664,source="quest_giver",zoneID=8567},questType="standard"},
[54946] = {id=54946,name="Report to Gila",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="I was quite fortunate that King Mechagon found me worthy! I will send my assistant Gila Crosswires ahead to Boralus to gather a new team. Meet up with her and help out as you can. I will join both of you shortly.",starts={{npcID=152864,x=0.658,y=0.664,zoneID=8567}},ends={{npcID=151100,x=0.672,y=0.158,zoneID=8568}},coords={x=0.658,y=0.664,source="quest_giver",zoneID=8567},questType="standard"},
[54947] = {id=54947,name="A Small Team",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="I've determined the single attribute that is most important for a team member to survive an expedition to Mechagon. That attribute is...being a gnome! Gather these gnomes and meet Tinkmaster Overspark and myself at the departure point.",starts={{npcID=151100,x=0.672,y=0.158,zoneID=8568}},ends={{npcID=150145,x=0.432,y=0.318,zoneID=8568}},coords={x=0.672,y=0.158,source="quest_giver",zoneID=8568},questType="standard"},
[54951] = {id=54951,name="Emergency First Aid",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,description="We have to patch everyone up before we can begin the search for the missing expedition. Take this first aid kit and tend to the wounded.",starts={{npcID=156626,x=0.618,y=0.828,zoneID=10424}},ends={{npcID=156626,x=0.618,y=0.828,zoneID=10424}},coords={x=0.618,y=0.828,source="quest_giver",zoneID=10424},questType="standard"},
[54952] = {id=54952,name="Finding the Lost Expedition",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,description="Captain Garrick went ahead to find survivors. It looks like she lit a fire. Meet her up ahead to see what she found. I'll look further within the island for survivors... and the source of the magic that attacked us.",starts={{npcID=156626,x=0.618,y=0.828,zoneID=10424}},ends={{npcID=156607,x=0.582,y=0.746,zoneID=10424},{npcID=156651,x=0.582,y=0.746,zoneID=10424}},coords={x=0.618,y=0.828,source="quest_giver",zoneID=10424},questType="standard"},
[54958] = {id=54958,name="Ships in the Night",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,description="Sylvanas has gone too far this time. We may be at war with the Alliance, but there are certain lines we cannot cross. I must right this situation, but I need your assistance. Derek Proudmoore is being held on the Swift Vengeance, which is moored in the harbor here for supplies. We must take him and bring him back to his family. Are you with me?",starts={{npcID=150309,x=0.766,y=0.43,zoneID=15},{npcID=150309,x=0.872,y=0.496,zoneID=8567}},ends={{npcID=149842,x=0.866,y=0.452,zoneID=8567}},coords={x=0.766,y=0.43,source="quest_giver",zoneID=15},questType="standard"},
[54959] = {id=54959,name="Under Lock and Keys",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,description="Three keys? It seems Sylvanas didn't trust any one member of this crew to have access to Proudmoore. We won't be able to rescue Derek Proudmoore if we can't get his cage open. We'll need to keep an eye out for keys while we clear the ship.",starts={{npcID=149842,x=0.866,y=0.452,zoneID=8567}},ends={{npcID=149842,x=0.866,y=0.452,zoneID=8567}},coords={x=0.866,y=0.452,source="quest_giver",zoneID=8567},questType="standard"},
[54960] = {id=54960,name="A Bitter Reunion",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=15,description="We've done it! Zelling will guide the ship to Theramore, and we can put an end to this foul business once and for all. Speak to Zelling when you are ready to leave, and we will set sail.",starts={{npcID=149842,x=0.866,y=0.452,zoneID=8567}},ends={{npcID=150309,x=0.872,y=0.496,zoneID=8567},{npcID=150309,x=0.766,y=0.43,zoneID=15}},coords={x=0.866,y=0.452,source="quest_giver",zoneID=8567},questType="standard"},
[54961] = {id=54961,name="Righting Wrongs",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Champion! I come with an urgent request from Baine Bloodhoof . He asks that you meet him at Plunder Harbor to help him with a... sensitive situation. You must tell no one of this request, . Ancestors watch over you.",starts={{npcID=150433,x=0.498,y=0.96,zoneID=8670}},ends={{npcID=150309,x=0.766,y=0.43,zoneID=15},{npcID=150309,x=0.872,y=0.496,zoneID=8567}},coords={x=0.498,y=0.96,source="quest_giver",zoneID=8670},questType="standard"},
[54964] = {id=54964,name="A One-Way Ticket to the Heart",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=9667,description="These titan facilities never cease tae amaze me. I can only imagine how many of their secrets Brann has yet tae uncover. I just hope that one o' them holds the answer tae saving Azeroth. It's time tae bring MOTHER tae the Chamber of Heart. Be prepared for anythin', champion. Ye can never be quite sure what will happen when ye activate a titan machine.",ends={{npcID=136907,x=0.5,y=0.616,zoneID=9667},{npcID=152206,x=0.502,y=0.584,zoneID=9667}},questType="standard"},
[54969] = {id=54969,name="Descent",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="We've lost the bulk of our forces already; any more and we won't have enough to make a stand. This wreckage won't keep the naga at bay, so we must find safety elsewhere. You will have to trust me here, $p. Leap off the falls and you will descend safely.",starts={{npcID=150101,x=0.402,y=0.552,mapID=1355}},ends={{npcID=150101,x=0.402,y=0.552,mapID=1355}},coords={x=0.402,y=0.552,source="quest_giver",mapID=1355},questType="standard"},
[54972] = {id=54972,name="A Way Home",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,description="We are only alive thanks to the ankoan and Azshara's desire to toy with us. We will learn more of Okani's people in the times ahead, I am sure. For now, we must establish a portal home. While Azshara is blocking our traditional methods of magical travel, I can sense a powerful convergence of energies nearby. I believe we can use it to open a way home.",starts={{npcID=150101,x=0.402,y=0.552,zoneID=10052}},ends={{npcID=150101,x=0.402,y=0.552,zoneID=10052}},coords={x=0.402,y=0.552,source="quest_giver",zoneID=10052},questType="standard"},
[54975] = {id=54975,name="A Brief Respite",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,description="We have much to do, . However, we are all weary and require rest. Decisions made while fatigued are almost always the wrong ones to make. The Ankoan have offered their home to us, yet they are barely holding on themselves. We should do what we can to support them while we think about our next move. See what you can do to aid their hunting parties, it may be the only way we survive in this place.",starts={{npcID=150101,x=0.402,y=0.552,zoneID=10052}},ends={{npcID=150101,x=0.402,y=0.552,zoneID=10052}},coords={x=0.402,y=0.552,source="quest_giver",zoneID=10052},questType="standard"},
[54976] = {id=54976,name="The Shadow of Gilneas",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=1519,description="Champion of Gilneas! I have a letter for you from Princess Tess Greymane . She requests your presence in Stormwind Keep.",starts={{npcID=150200,x=0.548,y=0.184,zoneID=1519}},ends={{npcID=155313,x=0.824,y=0.28,zoneID=1519}},coords={x=0.548,y=0.184,source="quest_giver",zoneID=1519},questType="standard"},
[54977] = {id=54977,name="Into Duskwood",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10,description="There is a night elf I met in Teldrassil, Vassandra Stormclaw , who may be able to teach Tess without resorting to such an extreme measure. She is the one who originally helped our people with their affliction. Vassandra is currently in Duskwood, assisting the residents of Raven Hill with their attempts to cure the feral worgen in the area. If anyone knows about the curse, it is her. As a more personal request, do not let my daughter do anything too rash. She takes after her father in that way.",starts={{npcID=151784,x=0.824,y=0.28,zoneID=1519}},ends={{npcID=151761,x=0.182,y=0.572,zoneID=10}},coords={x=0.824,y=0.28,source="quest_giver",zoneID=1519},questType="standard"},
[54978] = {id=54978,name="Against Overwhelming Odds",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="We've received numerous reports of the Horde overwhelming our forces within both Kul Tiras and Zandalar. Brute forcing the Alliance with sheer numbers is an age-old tactic of the Horde, but we can't allow them to get the upper hand. Venture forth throughout and thin their numbers the best you can. I recommend bringing reinforcements.",starts={{npcID=135614,x=0.704,y=0.27,zoneID=8568}},ends={{npcID=143559,x=0.562,y=0.26,zoneID=8568}},coords={x=0.704,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[54979] = {id=54979,name="Against Overwhelming Odds",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="It appears we've allowed the Alliance forces to fester. If these reports are correct, they're outnumbering us in nearly every bastion we hold. Arm yourself, grab a few of your most trusted allies and put them into the ground, !",starts={{npcID=138708,x=0.584,y=0.626,zoneID=8499},{npcID=138708,x=0.516,y=0.994,zoneID=8670},{npcID=138708,x=0.512,y=0.21,zoneID=9042}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[54980] = {id=54980,name="Bane of the Nightbane",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10,description="Princess Greymane has informed me of the situation and I do have an idea of how to help. But first, a favor for a favor. The residents of Duskwood have been plagued recently by a particularly ferocious member of the Nightbane pack that they call 'Bloodeyes'. Take Master Harris's sedative and bring the worgen back to me alive. She will be a perfect subject to test cures on.",starts={{npcID=151761,x=0.182,y=0.572,zoneID=10}},ends={{npcID=151761,x=0.182,y=0.572,zoneID=10}},coords={x=0.182,y=0.572,source="quest_giver",zoneID=10},questType="standard"},
[54981] = {id=54981,name="Cry to the Moon",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10,description="Duskwood has a direct connection to the Emerald Dream. Through this connection, I may be able to call forth the Ancient Goldrinn. He will be able to give the princess a taste of the curse she so dangerously chases. A rare bloom grows on the east side of the woods, gather its bloom and meet me in Twilight Grove. It will help me with this ritual.",starts={{npcID=151761,x=0.182,y=0.572,zoneID=10}},ends={{npcID=151761,x=0.182,y=0.572,zoneID=10}},coords={x=0.182,y=0.572,source="quest_giver",zoneID=10},questType="standard"},
[54982] = {id=54982,name="The Spirit of the Hunter",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10,description="The other thing I may need for this ritual are the fangs of a wolf. There is a pack that has newly settled in around Manor Mistmantle. Bring me their fangs. I will await your return at Twilight Grove.",starts={{npcID=151761,x=0.182,y=0.572,zoneID=10}},ends={{npcID=151761,x=0.182,y=0.572,zoneID=10}},coords={x=0.182,y=0.572,source="quest_giver",zoneID=10},questType="standard"},
[54983] = {id=54983,name="Waking a Dreamer",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10,description="This should be all I need to call upon the Ancient. Some unwanted visitors may answer the call first. Protect me as I perform the ritual!",starts={{npcID=151761,x=0.182,y=0.572,zoneID=10}},ends={{npcID=150106,x=0.466,y=0.37,zoneID=10}},coords={x=0.182,y=0.572,source="quest_giver",zoneID=10},questType="standard"},
[54984] = {id=54984,name="Let Sleeping Wolves Lie",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10,description="Tess's essence now wanders a section of the Emerald Dream I have twisted into her thoughts. And I have given her my gift, but she could still use a guide. Enter the Dream through the portal behind me. It will place you near where she sleeps. See if you can help show her how rage may blind a mortal.",starts={{npcID=150106,x=0.466,y=0.37,zoneID=10}},ends={{npcID=150115,x=0.464,y=0.37,zoneID=10}},coords={x=0.466,y=0.37,source="quest_giver",zoneID=10},questType="standard"},
[54986] = {id=54986,name="Vision of N'zoth Reward",level=50,requiredLevel=50,faction="none",expansion=7,questType="standard"},
[54990] = {id=54990,name="The New Guard",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=1519,description="I need to speak with my parents again. I think my father and I have a bit to discuss. Meet me back at Stormwind Keep. I would like to thank you in a more formal manner.",starts={{npcID=150115,x=0.464,y=0.37,zoneID=10}},ends={{npcID=155313,x=0.824,y=0.28,zoneID=1519}},coords={x=0.464,y=0.37,source="quest_giver",zoneID=10},questType="standard"},
[54992] = {id=54992,name="The Start of Something Bigger",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=10290,description="We have coordinates locked into the gyrocopters. You and Captain Winklespring will fly the lead. If we run into any trouble, Tinkmaster Overspark wants the most experienced pilots out front. Board whenever you are ready to go.",starts={{npcID=150145,x=0.432,y=0.318,zoneID=8568}},ends={{npcID=152484,x=0.776,y=0.404,zoneID=10290}},coords={x=0.432,y=0.318,source="quest_giver",zoneID=8568},questType="standard"},
[54996] = {id=54996,name="Remembrance",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=6452,description="You may remember the day Thunder Bluff was attacked. It was your efforts and your guide who saved us. Now we take time to honor our ancestors and give thanks for the path they have set for us. Bring this offering to the cliffs overlooking Thunder Bluff and give thanks to your guide and all our ancestors. A simple gesture to commemorate our past. This is our way.",starts={{npcID=149084,x=0.468,y=0.154,zoneID=14},{npcID=149084,x=0.584,y=0.516,zoneID=1638},{npcID=149084,x=0.124,y=0.31,zoneID=6452}},ends={{npcID=36648,x=0.598,y=0.516,zoneID=1638}},coords={x=0.468,y=0.154,source="quest_giver",zoneID=14},questType="standard"},
[54997] = {id=54997,name="Dead in the Water",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,description="Once Proudmoore is freed, we will need to commandeer this ship to transport him to Theramore, where his sister awaits us. Zelling's magic can guide the ship there, but first we'll need to take care of the crew.",starts={{npcID=149842,x=0.866,y=0.452,zoneID=8567}},ends={{npcID=149842,x=0.866,y=0.452,zoneID=8567}},coords={x=0.866,y=0.452,source="quest_giver",zoneID=8567},questType="standard"},
[54999] = {id=54999,name="Under False Colors",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. I will take the ship near Chandlery Wharf, which has recently been taken by Irontide pirates. There, I will leave it under the guise of a pirate raid gone wrong. Your task will be to ensure that Sylvanas' forces find this ship. You must report to Nathanos that you spotted a stolen Forsaken vessel in that area. You have no connection to Derek Proudmoore, so it should raise no suspicions.",starts={{npcID=150311,x=0.764,y=0.428,zoneID=15},{npcID=150311,x=0.86,y=0.456,zoneID=8567}},ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},coords={x=0.764,y=0.428,source="quest_giver",zoneID=15},questType="standard"},
[55002] = {id=55002,name="Murder at the Brawlpub",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="The Brawlpub quartermaster lies dead in front of you. He was murdered in broad daylight! He must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights. Perhaps there are some clues nearby as to who might have killed him.",questType="standard"},
[55003] = {id=55003,name="Put Up Your Dukes",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="You know what? I COULD use a good on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get. But first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?",questType="standard"},
[55004] = {id=55004,name="Undercover Agent: Ann Dennyson",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Lord Winifred Browne is one of our primary suspects in this case. Browne is an infamously aggressive speculator, and has a list of debts a mile long. He may be in need of money, which is consistent with the evidence you found earlier. My associate Ann has taken point on the case. I'd like you to assist her. I think you'll work well together.",questType="standard"},
[55005] = {id=55005,name="The Financial Participation Incentive",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="I see Lord Browne running some sort of game over there. Getting people to guess the fight's winner in exchange for Brawler's Gold. See if you can figure out how his game works. If you win enough money from him, he might start talking...",questType="standard"},
[55006] = {id=55006,name="A Favor for Your Old Chum Winifred",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="A moment of your time, . It's about all that money you won from me. Interestingly enough, that may have been slightly more money than I actually have, and now it would appear that some very powerful people want to break my elbows and my knees. I cannot pay them! I am quite broke! Ha ha! All I need to get back above water is for you to lose your next fight. Flop like a fish, as they say. Please.",questType="standard"},
[55007] = {id=55007,name="Lord Browne's Debts",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="I've always said that I'm not too proud to commit a few acts of violence to set a wrong right. And you know what's wrong? I'm out of money! Only one person's won more gold from me than you have, and his name's Lord Sylysthrel. Quite the scoundrel, that one. I believe he was cheating. It sure would be nice if I could get that gold back...",questType="standard"},
[55008] = {id=55008,name="Evidence Packet: Lord Winifred Browne",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="I heard everything. That guy sure does talk loudly about his crimes and debts, doesn't he? It sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Daalo to review. Good job out there.",questType="standard"},
[55009] = {id=55009,name="Undercover Agent: Saralara Fizzlesprang",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="I believe you've met one of my other agents: Saralara Fizzlesprang . She's investigating our second suspect: Shadowmaster O'Flannerty. You'll find Saralara near the scene of the crime.",questType="standard"},
[55010] = {id=55010,name="Soul Splinters",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Achh, what a mess... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses... Oh! Ahoy there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!",questType="standard"},
[55011] = {id=55011,name="Super Soul Splinters",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Will these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a void apocalypse in the middle of Stormwind. Oh dear, oh dear... Oh! The is still here! Heh heh. Never mind me! Nothing evil going on here!!",questType="standard"},
[55012] = {id=55012,name="Cause for Concern",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,mapID=500,description="Shadowmaster O'Flannerty's behavior was unusual. His repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation. You should report back to Saralara Fizzlesprang .",questType="standard"},
[55013] = {id=55013,name="The Precious 13-Tooth Gogglegear",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes. That's right, I'm talking about goggles. I already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Leila has their challenge card.",questType="standard"},
[55014] = {id=55014,name="The Fizzlesprang Goggle Experiment",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Okay, before we start, I've got a few rules: First, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them. Second rule: if you feel something starting to explode, try to blink real hard. Lastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence. Alright, go get in that arena and try them out!",questType="standard"},
[55015] = {id=55015,name="Evidence Packet: Shadowmaster O'Flannerty",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Sounds like we've found our perp, . This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier. Bring this packet to Daalo, and we can bring him in. Good work out there!",questType="standard"},
[55016] = {id=55016,name="Undercover Agent: Silent Jussho",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="I've got one more suspect I'm investigating: Grant Lazarby. He's a wealthy worgen death knight socialite who spends most of his time spectating the arena from the VIP area. I've got my best agent on the case: Silent Jussho . Check in with him to see how his report is coming along.",questType="standard"},
[55017] = {id=55017,name="Flaunt It If You Got It",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Sigh... so dull... Oh, it's you! , was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately. Let's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns at the combatants?",questType="standard"},
[55018] = {id=55018,name="Simply Dying of Boredom",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Bizmo can be so stingy with his invitations, can't he? I've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house in the Trade District...",questType="standard"},
[55019] = {id=55019,name="Evidence Packet: Grant Lazarby",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Good work. I never expected Lazarby to be so... self-incriminating. You may bring the packet to Commander. I'm going to go buy some expensive snacks at the VIP bar.",questType="standard"},
[55020] = {id=55020,name="The Brawlpub Trial",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="I've issued three warrants. Jussho, Saralara, and Anne are apprehending the suspects as we speak. It's time to go to court. You may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.",questType="standard"},
[55021] = {id=55021,name="A Clue from Area 52",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=3523,description="We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in the Brawlpub\". They don't say more than that. I'm tied to my paperwork here. Go check out this lead and see if anything turns up.",ends={{npcID=150320,x=0.312,y=0.664,zoneID=3523}},questType="standard"},
[55022] = {id=55022,name="Solving the Mystery",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,description="Bizmo produces a challenge card from his pocket.> I grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!",starts={{npcID=150320,x=0.312,y=0.664,zoneID=3523}},coords={x=0.312,y=0.664,source="quest_giver",zoneID=3523},questType="standard"},
[55023] = {id=55023,name="Bizmo's Brawlpub Awaits!",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,mapID=500,description="Tired of standing around in the boring old Trade District? Come on over to Bizmo's Brawlpub, and fight for the amusement of others! You might win, or you might get killed, but either way, you're going to have a great time. Grab an invitation and bring it to Han Heavypaw , near the front door. The Brawlpub awaits!",questType="standard"},
[55028] = {id=55028,name="It's Scrap Work...",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description=", I'm glad you stopped by. The Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap. You'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open! Up for some treasure huntin'?",starts={{npcID=136059,x=0.774,y=0.142,zoneID=8568}},ends={{npcID=136059,x=0.774,y=0.142,zoneID=8568}},coords={x=0.774,y=0.142,source="quest_giver",zoneID=8568},questType="standard"},
[55030] = {id=55030,name="Blueprint: Scrap Trap",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Pascal-K1N6 's database in Rustbolt.>",ends={{npcID=150359,x=0.714,y=0.324,zoneID=10290}},questType="standard"},
[55031] = {id=55031,name="It's Scrap Work...",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8670,description=", I'm glad you stopped by. The Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap. You'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open! Up for some treasure huntin'?",starts={{npcID=131840,x=0.45,y=0.404,zoneID=8670}},ends={{npcID=131840,x=0.45,y=0.404,zoneID=8670}},coords={x=0.45,y=0.404,source="quest_giver",zoneID=8670},questType="standard"},
[55033] = {id=55033,name="Ashes to Ashvane",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="This place is just crawling with Ashvane loyalists, . How about we do the Kul Tirans a favor and get rid of some of them. I got a head start on the way here, but there's plenty to go around!",starts={{npcID=150796,x=0.8,y=0.75,zoneID=8567}},ends={{npcID=150796,x=0.8,y=0.75,zoneID=8567}},coords={x=0.8,y=0.75,source="quest_giver",zoneID=8567},questType="standard"},
[55034] = {id=55034,name="Under False Colors",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. You'll need to have your men take the ship to Chandlery Wharf, where they can disguise it as a pirate's bounty. Your task will be to ensure that Sylvanas' forces find the ship there. You must report to Nathanos that you spotted a stolen Forsaken vessel in that area. You have no connection to Derek Proudmoore, so it should raise no suspicions.",starts={{npcID=150311,x=0.764,y=0.428,zoneID=15},{npcID=150311,x=0.86,y=0.456,zoneID=8567}},ends={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},coords={x=0.764,y=0.428,source="quest_giver",zoneID=15},questType="standard"},
[55036] = {id=55036,name="A Terrible Place",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=10348,questType="standard"},
[55039] = {id=55039,name="The Master Shipwright",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="Now I am starting to remember... Dorian Atwater was a very secretive builder. Their slips were famously warded against prying eyes until the vessel was complete. It made something of a stir any time one of their works was revealed. Last I heard, they retired in Stormsong Valley. I am not certain how reliable that information is. Hm. We should head to Brennadam. It is a crossroads of sorts. If anyone knows where to find our shipwright, they will be there.",starts={{npcID=122370,x=0.68,y=0.22,zoneID=8568}},ends={{npcID=150515,x=0.586,y=0.704,zoneID=9042}},coords={x=0.68,y=0.22,source="quest_giver",zoneID=8568},questType="standard"},
[55040] = {id=55040,name="Looking Inside",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="This vault screams of ancient gnomish tech! I believe this could be the key that leads us to King Mechagon! I can't risk putting myself in danger though, so you will lead the way into the vault. Well, what are we waiting for? Let's see what's inside!",starts={{npcID=149864,x=0.656,y=0.65,zoneID=8567}},ends={{npcID=149877,x=0.658,y=0.664,zoneID=8567}},coords={x=0.656,y=0.65,source="quest_giver",zoneID=8567},questType="standard"},
[55043] = {id=55043,name="Fish Tales and Distant Sails",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=9042,description="I have an idea where to start, but it couldn't hurt to ask the locals. I hope it goes without saying that you shouldn't believe everything you hear, . My people are very fond of embellishing the truth. I will meet you in The Golden Flagon when you've had a chance to ask around .",starts={{npcID=150515,x=0.586,y=0.704,zoneID=9042}},ends={{npcID=150515,x=0.586,y=0.704,zoneID=9042}},coords={x=0.586,y=0.704,source="quest_giver",zoneID=9042},questType="standard"},
[55044] = {id=55044,name="Don't Shoot the Messenger",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=15,description="While he was the gladiator known as Lo'Gosh, King Varian fought beside Valeera Sanguinar . He trusted her and that allowed SI:7 to have a... cordial relationship with her. Valeera's loyalty has carried on to King Anduin. During the fight with the Legion, I came to know her as a capable if... independent operative. She can go where even some of my agents cannot. We should listen to whatever message she brings. I imagine the source will be interesting.",starts={{npcID=135614,x=0.704,y=0.27,zoneID=8568}},ends={{npcID=150574,x=0.694,y=0.27,zoneID=8568},{npcID=150574,x=0.7,y=0.416,zoneID=15}},coords={x=0.704,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[55045] = {id=55045,name="My Brother's Keeper",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="While I trust Valeera believes she is not leading us into a trap, I do not trust this isn't a Horde manipulation. , I want you to come with me. I will meet with Baine, but I will not do so alone.",starts={{npcID=150574,x=0.7,y=0.416,zoneID=15},{npcID=150574,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},coords={x=0.7,y=0.416,source="quest_giver",zoneID=15},questType="standard"},
[55047] = {id=55047,name="Securing Warfang Hold",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="The Dark Lady has important work for you, . Preparations are beginning for a meeting of the Horde's leadership at Warfang Hold. I trust I don't need to emphasize that security is of the highest import for this gathering. The goblin, Gallywix, has sent his underlings to make sure the area is swept of any... unwanted guests. I need you to make sure they succeed in their task.",starts={{npcID=146013,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=150690,x=0.51,y=0.328,zoneID=9042}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[55048] = {id=55048,name="Spy Games",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="The Alliance must've got wind of this meeting and they've sent SI:7 spies to try to listen in. The problem is, they're using some kind of gnomish tech to sneak past our detectors. One of our techs was able to put together something that should be able to neutralize whatever they're using, but the range is short. I'll need you to take it out into the field and look for evidence of SI:7 activity. Just mash the button on that thing when you think they're close, and it should zap 'em back into view.",starts={{npcID=150690,x=0.51,y=0.328,zoneID=9042}},ends={{npcID=150690,x=0.51,y=0.328,zoneID=9042}},coords={x=0.51,y=0.328,source="quest_giver",zoneID=9042},questType="standard"},
[55049] = {id=55049,name="Communication Breakdown",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="It looks like the stealth generators aren't the only tech that SI:7 is bringing into the field. Our scouts have reported what look like listening devices set up at key points around Warfang. Obviously, these things have to go, but the goons haven't been able to get close to them on account of the hidden spies. While you're out there, make sure to trash 'em.",starts={{npcID=150690,x=0.51,y=0.328,zoneID=9042}},ends={{npcID=150690,x=0.51,y=0.328,zoneID=9042}},coords={x=0.51,y=0.328,source="quest_giver",zoneID=9042},questType="standard"},
[55050] = {id=55050,name="Tickets, Please?",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="There's another problem we could use your help with, . Gallywix knew this meeting was going to be a big deal, so naturally he decided to sell tickets. The thing is, I've done a headcount here, and we've got a lot more people here than tickets sold, so some of these spectators are trying to pull a fast one. Most of our muscle is out in the Clearcut getting killed by spies, so we could use the help. Care to make an honest wage?",starts={{npcID=150691,x=0.51,y=0.328,zoneID=9042}},ends={{npcID=150691,x=0.51,y=0.328,zoneID=9042}},coords={x=0.51,y=0.328,source="quest_giver",zoneID=9042},questType="standard"},
[55051] = {id=55051,name="A Display of Power",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="It looks like all the big players are here. This thing's gonna be starting any moment now. You'll probably want to get a good seat.",starts={{npcID=150690,x=0.51,y=0.328,zoneID=9042}},ends={{npcID=150678,x=0.506,y=0.322,zoneID=9042}},coords={x=0.51,y=0.328,source="quest_giver",zoneID=9042},questType="standard"},
[55052] = {id=55052,name="Securing Warfang Hold",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description=", the Dark Lady has need of your services once more. The traitor, Baine, is being brought before the leaders of the Horde at Warfang Hold. Preparations are underway as we speak to secure the area. The efforts are headed up by Gallywix's minions, who I wouldn't trust to secure a kennel. You will need to go to Warfang Hold and make sure the area is locked down. We are counting on you, .",starts={{npcID=135691,x=0.584,y=0.626,zoneID=8499}},ends={{npcID=150690,x=0.51,y=0.328,zoneID=9042}},coords={x=0.584,y=0.626,source="quest_giver",zoneID=8499},questType="standard"},
[55053] = {id=55053,name="A Way Home",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10052,description="We can harness the power within this place to open a portal home. I will require your assistance. Isn't this fun? You get to be my assistant! Ah, yes. Just come with me and all you have to do is wave that Heart of Azeroth of yours around. I'll handle the rest.",starts={{npcID=151851,x=0.484,y=0.624,zoneID=10052}},ends={{npcID=151851,x=0.484,y=0.624,zoneID=10052}},coords={x=0.484,y=0.624,source="quest_giver",zoneID=10052},questType="standard"},
[55054] = {id=55054,name="Upheaval",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10052,description="We're surrounded by the dead, dying, and other detritus. Feels like war, does it not? Oculeth and others have gone ahead to see to the soldiers. Perhaps you ought to see to them as well?",starts={{npcID=150187,x=0.368,y=0.936,zoneID=10052}},ends={{npcID=150206,x=0.366,y=0.868,zoneID=10052}},coords={x=0.368,y=0.936,source="quest_giver",zoneID=10052},questType="standard"},
[55055] = {id=55055,name="Build A Bigger Fish Trap",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="With those minnows and some spare parts, you should be able to build a Hundred-Fathom Lure . Visit Pascal-K1N6 in Rustbolt and build one. Then come back here, and we'll catch a huge fish!",starts={{npcID=151462,x=0.37,y=0.472,zoneID=10290}},ends={{npcID=151462,x=0.37,y=0.472,zoneID=10290}},coords={x=0.37,y=0.472,source="quest_giver",zoneID=10290},questType="standard"},
[55056] = {id=55056,name="Blueprint: Mechanocat Laser Pointer",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Pascal-K1N6 's database in Rustbolt.>",ends={{npcID=150359,x=0.714,y=0.324,zoneID=10290}},questType="standard"},
