[55084] = {id=55084,name="Blueprint: Encrypted Black Market Radio",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Pascal-K1N6 's database in Rustbolt.>",ends={{npcID=150359,x=0.714,y=0.324,zoneID=10290}},questType="standard"},
[55087] = {id=55087,name="The Gathering Storm",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="While I deal with the naga incursions, Lady Proudmoore is going to take on handling the Horde in Stormsong Valley and figuring out what happened to our spies there. You'll find her near Proudmoore Keep.",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=150633,x=0.694,y=0.27,zoneID=8568}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[55088] = {id=55088,name="Lost in the Field",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="When Shaw and I got here we discovered most of our operatives were dead. Most, but not all. Go into the field and get any of our operatives out of there. They might have more intel on what the Horde are planning here in Warfang Hold.",starts={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},ends={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},coords={x=0.482,y=0.414,source="quest_giver",zoneID=9042},questType="standard"},
[55089] = {id=55089,name="Shaw's Shank Redemption",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="Hmm. Shaw said he'd check in when we got communications back but he hasn't. He's probably run into the same trouble the rest of our spies did. I'll stay here and guard the listening post. You find Shaw. He was headed for the cliff above Warfang Hold near the top of the waterfall. The peons called that area \"The Screaming Pit\" for some reason. I bet it's a real pleasant place. Stab whatever he's fighting for me, okay?",starts={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},ends={{npcID=150640,x=0.488,y=0.326,zoneID=9042}},coords={x=0.482,y=0.414,source="quest_giver",zoneID=9042},questType="standard"},
[55090] = {id=55090,name="A Gathering of Foes",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Before I was distracted, I was able to find out more about this Horde gathering. Sylvanas has summoned the leaders of the Horde and its allies. For what purpose, I cannot say. We aren't in a position to strike her down--she is too well-protected. But perhaps we can learn something that will prove useful in the ongoing war. Keep your head low and take a look. I'll keep an eye out for more guards.",starts={{npcID=150640,x=0.488,y=0.326,zoneID=9042}},ends={{npcID=150633,x=0.694,y=0.27,zoneID=8568}},coords={x=0.488,y=0.326,source="quest_giver",zoneID=9042},questType="standard"},
[55092] = {id=55092,name="Disruption of Power",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10052,description="The naga tap into the power within nearby ley lines and have found a way to harness it. Destroy their devices before they can put that power to use against us.",starts={{npcID=150196,x=0.42,y=0.806,zoneID=10052}},ends={{npcID=150196,x=0.42,y=0.806,zoneID=10052}},coords={x=0.42,y=0.806,source="quest_giver",zoneID=10052},questType="standard"},
[55094] = {id=55094,name="Stay Low, Stay Fast!",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10052,description="It's a straight shot home. We just need to be careful. Neri's rule of survival number six: always be prepared! Let's go!",starts={{npcID=150209,x=0.372,y=0.674,zoneID=10052}},ends={{npcID=151849,x=0.484,y=0.624,zoneID=10052}},coords={x=0.372,y=0.674,source="quest_giver",zoneID=10052},questType="standard"},
[55095] = {id=55095,name="Upheaval",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,description="So many lives lost... And the attacks from the naga are relentless! I apologize, $p. This attitude is unbecoming of a king. We have no time to lose musing of our own plight. Let us meet with Jaina and descend from this perilous place into the unknown.",starts={{npcID=150087,x=0.482,y=0.926,zoneID=10052}},ends={{npcID=150101,x=0.402,y=0.552,zoneID=10052}},coords={x=0.482,y=0.926,source="quest_giver",zoneID=10052},questType="standard"},
[55096] = {id=55096,name="Send My Father a Message",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="My people are once again safe... for now. King Mechagon won't stop sending his armies at us as long as he does not fear us. We must send him a message. Climb to the top of the ramparts, and hack one of my father's projectors to proudly shine the banner of the Rustbolt Resistance big enough for the whole island to see. I'm sure that'll attract the attention of my father, King Mechagon .",starts={{npcID=153670,x=0.53,y=0.556,zoneID=10290}},ends={{npcID=151947,x=0.712,y=0.36,zoneID=10290}},coords={x=0.53,y=0.556,source="quest_giver",zoneID=10290},questType="standard"},
[55099] = {id=55099,name="TBD NOT USED",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=10290,mapID=1462,description="The fabled workbench of Rustbolt - MY workbench - has fallen into disrepair! This tragedy was no doubt caused by the same ruffians and miscreants who kidnapped me and Princess Wiggles. The VERY same ruffians and miscreants, in fact, who still show their faces in this very town on the regular. Their presence here is a veritable slap to our collective faces! Dispatch the snatchers quickly and recover my binder of blueprints. We may then commence crafting what we shall need to repair this.",questType="standard"},
[55101] = {id=55101,name="Junkyard Tinkering and You",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Behold, the fabled Pascal Workshop of Rustbolt -- MY workshop! Countless inventions have sprung forth into existence on this very spot, including my very finest invention, Pascal -K1N6! Pascal -K1N6 can craft anything... as long as you have the blueprints for it. And since I have you to thank for the K1N6's safe return to Rustbolt, would you like to learn how to access his blueprints database?",starts={{npcID=152295,x=0.712,y=0.324,zoneID=10290}},ends={{npcID=152295,x=0.712,y=0.324,zoneID=10290}},coords={x=0.712,y=0.324,source="quest_giver",zoneID=10290},questType="standard"},
[55103] = {id=55103,name="Ideas Can Come from Anywhere",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="I didn't notice the tinkerer's spark in you when we first met. But look at all of the blueprints you've recovered and uploaded to Pascal -K1N6's database. I was wrong. And happily so, my budding junkyard tinkering apprentice! But this is a dangerous moment in your creative development. You must avoid complacency! Take time off to find new ideas. Speak with builders that inspire you, reverse-engineer bots on the island, and be open to new ideas - no matter where they come from!",starts={{npcID=152295,x=0.712,y=0.324,zoneID=10290}},ends={{npcID=152295,x=0.712,y=0.324,zoneID=10290}},coords={x=0.712,y=0.324,source="quest_giver",zoneID=10290},questType="standard"},
[55111] = {id=55111,name="Creature Study: Zanj'ir Naga",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=10052,mapID=1355,questType="standard"},
[55116] = {id=55116,name="Getting a Clue",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="I'm betting that one page of jibberish is a coded message. We can send it back to Stormwind to be cracked by our codebreakers or we could break some heads and find the cipher here. I'm thinking we'll just save some time and do that. The guy in charge here probably has what we're looking for. Why don't you take him out and see if you can't find it. Even if you don't, without a leader the loyalists won't be much trouble. It's a win-win! Well, for us I guess.",starts={{npcID=150796,x=0.8,y=0.75,zoneID=8567}},ends={{npcID=150796,x=0.8,y=0.75,zoneID=8567}},coords={x=0.8,y=0.75,source="quest_giver",zoneID=8567},questType="standard"},
[55117] = {id=55117,name="Correspondence Conundrum",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="I think Ashvane has been in contact with her loyalists, but I don't know what their orders are. Go into their camp and see if you can't read their mail. We might find something that leads back to where Lady Ashvane is hiding or what their next move is going to be.",starts={{npcID=150796,x=0.8,y=0.75,zoneID=8567}},ends={{npcID=150796,x=0.8,y=0.75,zoneID=8567}},coords={x=0.8,y=0.75,source="quest_giver",zoneID=8567},questType="standard"},
[55118] = {id=55118,name="Loose Ends",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8567,description="Our campaign against the Horde is going strong, but there are some loose threads to take care of. Lady Ashvane was broken out of Tol Dagor - by the Horde. We don't know where she's gone or what she is planning. I sent Kelsey out to track down some Ashvane Loyalists to get answers. She found them and has requested backup. She's waiting for you in Freehold.",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=150796,x=0.8,y=0.75,zoneID=8567}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[55119] = {id=55119,name="Reporting In!",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Well it looks like Ashvane's been out of contact for some time but this 'Patron' thing could be a problem. You did excellent work today, . Those Loyalists aren't going to be thinking about causing trouble for awhile, heh. I'll make my way back. You take the letter to the High Commander.",starts={{npcID=150796,x=0.8,y=0.75,zoneID=8567}},ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},coords={x=0.8,y=0.75,source="quest_giver",zoneID=8567},questType="standard"},
[55121] = {id=55121,name="The Laboratory of Mardivas",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=10052,description="At last, my research into the base elements has begun to bear fruit! With careful application of the right base reagents and some arcane power I've managed to combine the essence of the elements in such a way as to create life! Further investigation will be needed to determine what the various mixes of the elements will yield.",starts={{npcID=322533,x=0.606,y=0.333,zoneID=10052}},ends={{npcID=322533,x=0.606,y=0.333,zoneID=10052}},coords={x=0.606,y=0.333,source="quest_giver",zoneID=10052},questType="standard"},
[55122] = {id=55122,name="Murloc Mania",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,description="I'm glad you made it out in one piece. Judging by the nearby shipwrecks, I think it's safe to say the missing expedition ran aground here, too. We can't move until we've got the remaining survivors back on their feet. Unfortunately, our remaining supplies have been stolen by murlocs! I need you to recover enough first aid supplies for the wounded. Then we can begin searching for the missing expedition.",starts={{npcID=156626,x=0.618,y=0.828,zoneID=10424}},ends={{npcID=156626,x=0.618,y=0.828,zoneID=10424}},coords={x=0.618,y=0.828,source="quest_giver",zoneID=10424},questType="standard"},
[55123] = {id=55123,name="Hunting Season",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=7503,mapID=650,questType="standard"},
[55124] = {id=55124,name="Righting Wrongs",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,description="Champion! I come with an urgent request from Baine Bloodhoof . He asks that you meet him at Plunder Harbor to help him with a... sensitive situation. You must tell no one of this request, . Ancestors watch over you.",starts={{npcID=150433,x=0.498,y=0.96,zoneID=8670}},ends={{npcID=150309,x=0.766,y=0.43,zoneID=15},{npcID=150309,x=0.872,y=0.496,zoneID=8567}},coords={x=0.498,y=0.96,source="quest_giver",zoneID=8670},questType="standard"},
[55125] = {id=55125,name="Hunting Season",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=7503,mapID=650,questType="standard"},
[55136] = {id=55136,name="Her Dog Days Are Over",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=8721,description="Wicker Beast gently nudges the dog's body with its snout. The creature whines plaintively and moves to your side. It gives a hopeful twitch of its bony tail.>",starts={{npcID=150885,x=0.366,y=0.288,zoneID=8721}},ends={{npcID=150884,x=0.332,y=0.304,zoneID=8721}},coords={x=0.366,y=0.288,source="quest_giver",zoneID=8721},questType="standard"},
[55137] = {id=55137,name="For the Horde",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=1637,description="Thank you for meeting me upon my throne, . With our recent partnerin' with de Horde, I need worthy champions to represent the might of the Zandalari. I have chosen you to be among their ranks, . Go and meet with the ambassador in Orgrimmar. We have prepared a portal just behind you. When you are ready, step through to a new world. Remember, you bow only to the throne of Zandalar. Hold your head high, .",starts={{npcID=146335,x=0.498,y=0.464,zoneID=8670}},ends={{npcID=133407,x=0.394,y=0.792,zoneID=1637}},coords={x=0.498,y=0.464,source="quest_giver",zoneID=8670},questType="standard"},
[55138] = {id=55138,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=1519,description="Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, . As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.",starts={{npcID=133407,x=0.394,y=0.792,zoneID=1637}},ends={{npcID=150909,x=0.496,y=0.766,zoneID=1637}},coords={x=0.394,y=0.792,source="quest_giver",zoneID=1637},questType="standard"},
[55142] = {id=55142,name="For the Alliance",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1519,description="Thank you for meeting with me, . I need representatives to go to Stormwind to represent our loyalty and commitment to our newly forged bond with the Alliance. I've had Yvia and her magi prepare a portal to the city for you in the Sanctum of the Sages. Once there, go to the Stormwind Embassy and meet with Ambassador Moorgard . You will face many challenges on the long journey ahead. Remember where you came from and make your people proud!",starts={{npcID=150941,x=0.678,y=0.218,zoneID=8568}},ends={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},coords={x=0.678,y=0.218,source="quest_giver",zoneID=8568},questType="standard"},
[55146] = {id=55146,name="Stranger in a Strange Land",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1637,description="Welcome to Stormwind, . I invite you to explore our fair city. Since you hail from Kul Tiras, might I suggest visiting our lovely docks? They are home to our majestic fleet. I would be shocked if you were not impressed! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of Kul Tiras is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay.",starts={{npcID=133362,x=0.532,y=0.152,zoneID=1519}},ends={{npcID=150947,x=0.624,y=0.3,zoneID=1519}},coords={x=0.532,y=0.152,source="quest_giver",zoneID=1519},questType="standard"},
[55148] = {id=55148,name="Reclamation Rig",level=0,requiredLevel=0,faction="none",expansion=7,zoneID=10290,mapID=1462,questType="standard"},
[55153] = {id=55153,name="Collaborative Construction",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Construction projects can be found all over the island. You'll be able to build some of 'em yourself, but you're gonna need help with the bigger projects. Ask around and see what others are already working on, or just head out on your own and find a project you're interested in. Construction projects move around and even change day-to-day, so keep an eye out for new ones while you're exploring. If you're ever curious what construction projects are available on a given day, just ask me!",starts={{npcID=150555,x=0.73,y=0.334,zoneID=10290}},ends={{npcID=150555,x=0.73,y=0.334,zoneID=10290}},coords={x=0.73,y=0.334,source="quest_giver",zoneID=10290},questType="standard"},
[55171] = {id=55171,name="Spy Versus Spy",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Naga attacks are on the rise, but that isn't all we have to deal with. We've received word of increased Horde activity near Warfang Hold in Stormsong Valley. Send some of our operatives to investigate what they are doing.",starts={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=135612,x=0.694,y=0.27,zoneID=8568}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[55173] = {id=55173,name="Northbound",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,description="The quilboar kidnapped the rest of the expedition and took them to the north. I heard mention of needing more sacrifices for some sort of ritual... Please, you must rescue them!",starts={{npcID=175031,x=0.582,y=0.746,zoneID=10424}},ends={{npcID=154327,x=0.626,y=0.698,zoneID=10424}},coords={x=0.582,y=0.746,source="quest_giver",zoneID=10424},questType="standard"},
[55174] = {id=55174,name="Cooking Meat",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,description="Alaria is nearly starved to death. We need to get her something to eat! Slay some of the nearby wildlife for their meat. Bring whatever you find here to cook. If we can help Alaria regain her strength, she might be able to tell us what happened to the others. I'll stay here and help stabilize her wounds.",starts={{npcID=156651,x=0.582,y=0.746,zoneID=10424}},ends={{npcID=156607,x=0.582,y=0.746,zoneID=10424}},coords={x=0.582,y=0.746,source="quest_giver",zoneID=10424},questType="standard"},
[55175] = {id=55175,name="Where the Road Leads",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,description="My people know many secrets about this place. If you prove yourselves worthy allies, you will be privy to them. First, we must regroup in Mezzamere. There, we at least have a foothold against the tide.",starts={{npcID=151000,x=0.39,y=0.546,zoneID=10052}},ends={{npcID=150101,x=0.402,y=0.552,zoneID=10052}},coords={x=0.39,y=0.546,source="quest_giver",zoneID=10052},questType="standard"},
[55177] = {id=55177,name="Tearing at the Seams",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="I feel odd... weak. As though something is affecting my very existence. Would you come with me, ? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.",ends={{npcID=151134,x=0.716,y=0.398,zoneID=65},{npcID=151134,x=0.64,y=0.694,zoneID=7637},{npcID=151134,x=0.766,y=0.118,zoneID=8568},{npcID=151134,x=0.434,y=0.346,zoneID=8670},{npcID=151134,x=0.072,y=0.244,zoneID=9042}},questType="standard"},
[55179] = {id=55179,name="Retaliation Coordination",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="Master Shaw deployed a number of Alliance spies near a base the Horde have made in Stormsong Valley. When our spies stopped checking in, he took Kelsey Steelspark and went to investigate. Now Master Shaw is the one who hasn't checked in. I need someone to go in and find our missing people and give them whatever help they clearly need.",starts={{npcID=150633,x=0.694,y=0.27,zoneID=8568}},ends={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},coords={x=0.694,y=0.27,source="quest_giver",zoneID=8568},questType="standard"},
[55182] = {id=55182,name="Reassembly Required",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="Master Shaw wanted me to rebuild the listening posts the Horde destroyed when they started to clear the area in preparation for whatever they are planning. I managed to salvage most of the parts for one, but I'm missing a few. Fortunately for us, I've been watching the workers and they've been picking up the pieces of the destroyed machines. Go get our tech back and I can take care of the rest.",starts={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},ends={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},coords={x=0.482,y=0.414,source="quest_giver",zoneID=9042},questType="standard"},
[55183] = {id=55183,name="Seeking Higher Ground",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="We've only got one shot at reestablishing our communication network, so we've got to pick the right spot and I found just the right place! While you've been busy down here, I set up some camouflage and hauled the bulk of the machinery up there. What? Did you think I was just sitting here polishing my knives while you were gone? Well, okay I did that too. Anyway, I'll meet you up the hill!",starts={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},ends={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},coords={x=0.482,y=0.414,source="quest_giver",zoneID=9042},questType="standard"},
[55184] = {id=55184,name="Quilboar Shadow Magic",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,mapID=1409,description="Quilboar are primitive and savage. They rarely practice any magic other than geomancy. But these particular quilboar seem to be dabbling in shadow magic. They must be stopped. Slay the quilboar in the den. They cannot spread this magic in the island!",starts={{npcID=154327,x=0.626,y=0.698,mapID=1409}},ends={{npcID=149915,x=0.562,y=0.59,mapID=1409}},coords={x=0.626,y=0.698,source="quest_giver",mapID=1409},questType="standard"},
[55185] = {id=55185,name="Listen Up!",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9042,description="Okay! Once we get this up and running we should be able to send messages! In the valley at least. It's gonna be a little bit tricky, but I've read the manual for these things cover to cover. I'm gonna put this thing back together. You watch out for the Horde.",starts={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},ends={{npcID=150637,x=0.482,y=0.414,zoneID=9042}},coords={x=0.482,y=0.414,source="quest_giver",zoneID=9042},questType="standard"},
[55186] = {id=55186,name="Down with the Quilboar",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,description="From what I can gather, the quilboar are performing a shadow ritual on one of the expedition members. Their chief is Geolord Grek'og . He is the one who seeks to drain the life from our friend. Slay Grek'og and save the captive member of the expedition. He may know where the others were taken.",starts={{npcID=154327,x=0.626,y=0.698,zoneID=10424}},ends={{npcID=149899,x=0.562,y=0.59,zoneID=10424}},coords={x=0.626,y=0.698,source="quest_giver",zoneID=10424},questType="standard"},
[55188] = {id=55188,name="Tearing at the Seams",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,description="I feel odd... weak. As though something is affecting my very existence. Would you come with me, ? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.",ends={{npcID=151134,x=0.716,y=0.398,zoneID=65},{npcID=151134,x=0.64,y=0.694,zoneID=7637},{npcID=151134,x=0.766,y=0.118,zoneID=8568},{npcID=151134,x=0.434,y=0.346,zoneID=8670},{npcID=151134,x=0.072,y=0.244,zoneID=9042}},questType="standard"},
[55193] = {id=55193,name="The Scout-o-Matic 5000",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,description="You look like a that needs help finding the scattered members of our alliance expedition! Luckily, you have happened to rescue the one and only Lindie Springstock , inventor extraordinaire! I've got my Scout-o-Matic 5000 all set to go. It'll fly up in the air and let you scout the entire area. I'll give you the honors. Use my Scout-o-Matic 5000 to find the rest of the expedition.",starts={{npcID=149899,x=0.562,y=0.59,zoneID=10424}},ends={{npcID=149899,x=0.562,y=0.59,zoneID=10424}},coords={x=0.562,y=0.59,source="quest_giver",zoneID=10424},questType="standard"},
[55194] = {id=55194,name="Stocking Up on Supplies",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,description="Quartermaster Richter was able to scavenge supplies from the wreckages on this island. Why don't you visit her and see if she has anything that you need? You'll want to be well equipped for whatever we encounter next.",starts={{npcID=156807,x=0.522,y=0.552,zoneID=10424},{npcID=245394,x=0.522,y=0.556,zoneID=10424}},ends={{npcID=156807,x=0.522,y=0.552,zoneID=10424},{npcID=245394,x=0.522,y=0.556,zoneID=10424}},coords={x=0.522,y=0.552,source="quest_giver",zoneID=10424},questType="standard"},
[55195] = {id=55195,name="Reverberation",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=67,description="Hati's spirit is bound to yours forevermore, hunter. But it also now carries a link to the Temple of Storms--as well as Silithus, I fear. The Thunderspark shares these same bonds. By physically linking it here, you can call upon the different aspects of Hati's spirit and bind them to yourself as well. Do not worry. Skoll and I will guard the Thunderspark with our very lives! It will be safe.",starts={{npcID=29445,x=0.334,y=0.58,zoneID=67}},ends={{npcID=29445,x=0.334,y=0.58,zoneID=67}},coords={x=0.334,y=0.58,source="quest_giver",zoneID=67},questType="standard"},
[55196] = {id=55196,name="The Harpy Problem",level=6,requiredLevel=6,faction="alliance",expansion=7,zoneID=10424,description="We need to find the remaining survivors of my expedition before the ogres sacrifice them for their dark ritual! I saw one of the survivors being dragged away by some harpies. They have a roost to the north. Kee-La and I will meet you up there with a scouting report.",starts={{npcID=156833,x=0.534,y=0.524,zoneID=10424}},ends={{npcID=156859,x=0.568,y=0.462,zoneID=10424}},coords={x=0.534,y=0.524,source="quest_giver",zoneID=10424},questType="standard"},
[55210] = {id=55210,name="Batteries Not Included",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="You will not be sorry that you rescued my dear sister and me, $p. We are the vanguard of a new technological revolution, creating opportunities for all to enhance their lives with incredible technology! But, before we can do that, we need our laboratory to be fully powered. Those ruffians from Mechagon really did a number on our equipment. Fully charged energy cells are exceptionally rare around here, but I can make do with broken ones. Check around town, in the wreckage from the last attack.",starts={{npcID=150630,x=0.708,y=0.39,zoneID=10290}},ends={{npcID=150630,x=0.708,y=0.39,zoneID=10290}},coords={x=0.708,y=0.39,source="quest_giver",zoneID=10290},questType="standard"},
[55211] = {id=55211,name="Recharging Rustbolt",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Our personal generator is worthless until we recharge its empty energy cells . As my dear brother says, energy cells are the lifeblood of innovation. Everything in Mechagon needs power, and energy cells deliver that power in a wonderfully universal format. But, once they're drained of power, most people toss the empty cells away. Most people are fools, dear test subject. We have perfected the technology to recharge small numbers of energy cells back to full power. Will you help us test it?",starts={{npcID=150631,x=0.708,y=0.384,zoneID=10290}},ends={{npcID=150631,x=0.708,y=0.384,zoneID=10290}},coords={x=0.708,y=0.384,source="quest_giver",zoneID=10290},questType="standard"},
[55213] = {id=55213,name="Energy Cells for Everyone",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="The wondrous scuttlebutt around town is that the charging station in Bondo's Yard is going to be repaired today! That charging station is the best way to recharge all the Empty Energy Cells that've been piling up in your bag. Or in other people's bag. Or inside the mechanical innards of robots you don't own but are legally allowed to destroy. After you've acquired Empty Energy Cells, help build the charging station in Bondo's Yard and charge all of your Empty Energy Cells!",starts={{npcID=150631,x=0.708,y=0.384,zoneID=10290}},ends={{npcID=150631,x=0.708,y=0.384,zoneID=10290}},coords={x=0.708,y=0.384,source="quest_giver",zoneID=10290},questType="standard"},
[55214] = {id=55214,name="Seam Stress",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=9042,description="I...I need a moment, . There are gaps in my memories. Things important to me, lost now. We must stop her at all costs, .",starts={{npcID=151134,x=0.716,y=0.398,zoneID=65},{npcID=151134,x=0.64,y=0.694,zoneID=7637},{npcID=151134,x=0.766,y=0.118,zoneID=8568},{npcID=151134,x=0.434,y=0.346,zoneID=8670},{npcID=151134,x=0.072,y=0.244,zoneID=9042}},ends={{npcID=151134,x=0.716,y=0.398,zoneID=65},{npcID=151134,x=0.64,y=0.694,zoneID=7637},{npcID=151134,x=0.766,y=0.118,zoneID=8568},{npcID=151134,x=0.434,y=0.346,zoneID=8670},{npcID=151134,x=0.072,y=0.244,zoneID=9042}},coords={x=0.716,y=0.398,source="quest_giver",zoneID=65},questType="standard"},
[55216] = {id=55216,name="The Audition",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,description="Xanjo has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you. If you are willing, I would like to provide you with a test to see how well you can work leather. Bring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency. If your work is up to par, I will inform you of my plan.",starts={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},ends={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},coords={x=0.534,y=0.926,source="quest_giver",zoneID=8670},questType="standard"},
[55217] = {id=55217,name="Repaying the Life Debt",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=1638,description="When I heard that the Alliance attacked Dazar'alor, I couldn't help but think of those lost when they attacked Camp Taurajo. No longer can I sit idly while they continue to slaughter us! I need you to go to Thunder Bluff, find Sheza Wildmane on the Elder Rise, and ask for some of her personal collection. I won't go into detail, but she owes me a life debt, and seeing her would... bring back too many painful memories... for both of us. Find her, tell her I sent you, and that this absolves her debt.",starts={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},ends={{npcID=3037,x=0.696,y=0.27,zoneID=1638}},coords={x=0.534,y=0.926,source="quest_giver",zoneID=8670},questType="standard"},
[55218] = {id=55218,name="Sheza's Prized Leather",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=215,description="I have a stash of extremely rare leathers, or... rather, I did. I don't know how, but the Venture Company must have heard how valuable my collection was because they stole it! And THEN they had the audacity to leave a note offering to sell it back to me for 1,000 gold! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\" The note states they'll be in the bluffs to the East until someone buys them. However you get the skins, consider them yours.",starts={{npcID=3037,x=0.696,y=0.27,zoneID=1638}},ends={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},coords={x=0.696,y=0.27,source="quest_giver",zoneID=1638},questType="standard"},
[55219] = {id=55219,name="Dropping by the Base",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=7731,description="When the Legion was attacking, I met with a member of the Highmountain Tauren who had a knack for making and playing drums. Torv usually keeps to himself, but he is as brilliant as he is insane. If there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him. Head to Thunder Totem, and ask Torv Dubstomp if he can think of a suitable source of scales. Preferably something still living, so its power is still fresh.",starts={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},ends={{npcID=108017,x=0.446,y=0.564,zoneID=7731}},coords={x=0.534,y=0.926,source="quest_giver",zoneID=8670},questType="standard"},
[55220] = {id=55220,name="Bass Fishing",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,description="Have you heard of people taking small golden carp as pets? Well, if it is kept in a pond free of predators, over time it can grow enormous, only limited by the food present. Centuries ago, one of these fish lived in the pond atop a mountain. It ate everything and began to starve, so my people dug a river that connected the pond to the ocean so the fish could be free. Now, fishermen talk of being attacked by an enormous golden fish in the Rockaway Shelf. Kill it. Take his scales back to Atikka.",starts={{npcID=108017,x=0.446,y=0.564,zoneID=7731}},ends={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},coords={x=0.446,y=0.564,source="quest_giver",zoneID=7731},questType="standard"},
[55221] = {id=55221,name="Picking Bones",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,description="When I was sailing in, I noticed the remains of an unbelievably large beast on the nearby peninsula. Whatever it was, it must have been strong, making it the perfect source for the bone elements of the drums. Go to the peninsula, 'Xibala' I've heard it called, and fill a bag with the bones you find. If you come across any of those damned Alliance, show them no mercy. They did this to themselves.",starts={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},ends={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},coords={x=0.534,y=0.926,source="quest_giver",zoneID=8670},questType="standard"},
[55222] = {id=55222,name="Make Some Noise",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,description="We have everything we need to craft the drum, except the Earth Mother's blessing. The drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink. It will not be easy to convince her to assist us in creating a weapon of war, but I will implore her to protect her children. While I'm doing that, you will need to craft the drum itself. Not too big, though. The larger the vessel, the more power it can hold, but the harder it becomes to carry.",starts={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},ends={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},coords={x=0.534,y=0.926,source="quest_giver",zoneID=8670},questType="standard"},
[55223] = {id=55223,name="Instruments of Destruction",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8567,description="Our work is almost finished. These drums, while powerful, are practically useless here in port. If you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Kul Tiras, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines. Look for someplace centralized in each territory to place drums. Once you return, I'll show you how to make the mallet needed to utilize the drums.",starts={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},ends={{npcID=151162,x=0.534,y=0.926,zoneID=8670}},coords={x=0.534,y=0.926,source="quest_giver",zoneID=8670},questType="standard"},
[55224] = {id=55224,name="Rank 2 - Poen test",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=10052,mapID=1355,description="Gather corrupted ink sacs from the Nazothian Brain squids. The naga use them to control us, let's see if it works the other way.",questType="standard"},
[55225] = {id=55225,name="Special Juices",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=10052,mapID=1355,questType="standard"},
[55226] = {id=55226,name="Drive the Enemy",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=10052,mapID=1355,questType="standard"},
[55227] = {id=55227,name="The Aeonian Artisan",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,description="Good day, friend! A Night Elf woman stopped by and asked who was the best leatherworker I knew who didn't mind getting their hands dirty. I gave her your name, and she asked me to ask you to find her in Boralus Harbor. She didn't say what she needed my best student for, but the way she acted makes me think that it is for something big. Head on down to the docks and look for her. She has white hair, purple tattoos, and a pet turtle named \"Gouge\". Show her what I've taught you!",starts={{npcID=136063,x=0.756,y=0.126,zoneID=8568}},ends={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},coords={x=0.756,y=0.126,source="quest_giver",zoneID=8568},questType="standard"},
[55228] = {id=55228,name="The Audition",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="Cassandra has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you. If you are willing, I would like provide you with a test to see how well you can work leather. Bring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency. If your work is up to par, I will inform you of my plan.",starts={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},ends={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},coords={x=0.696,y=0.298,source="quest_giver",zoneID=8568},questType="standard"},
[55229] = {id=55229,name="Repaying the Debt",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=1519,description="I was in Teldrassil when it was set alight. Through the panic and chaos, I knew I could not rest as long as those who did this were unpunished. I need you to go to Stormwind, find Telonis near the Lion's Rest, and ask for some of his personal collection. I managed to save him from the fires, so he owes me a great deal. I would go myself, but the loss of Teldrassil is still a fresh wound. I still need to give it time to heal. Find him, tell him I sent you, and that this will absolve his debt to me.",starts={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},ends={{npcID=151287,x=0.424,y=0.604,zoneID=1519}},coords={x=0.696,y=0.298,source="quest_giver",zoneID=8568},questType="standard"},
[55230] = {id=55230,name="Telonis' Prized Leather",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=12,description="I have a stash of extremely rare leathers, or... rather, I did. A group of thieves must have heard how valuable my collection was because they stole it! And THEN they had the audacity to leave a note offering to sell it back to me! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\" The note states they'll be waiting in the foothills behind the castle, to the east, until they find another buyer. However you get the skins, consider them yours.",starts={{npcID=151287,x=0.424,y=0.604,zoneID=1519}},ends={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},coords={x=0.424,y=0.604,source="quest_giver",zoneID=1519},questType="standard"},
[55231] = {id=55231,name="The Other Ghostdancer",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=7558,description="When the Legion was attacking, my partner went to Val'sharah to fight the demons. Mevris may be cold and headstrong, but he's goal oriented, and willing to sacrifice to achieve them. That's part of why I fell in love with him. If there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him. Head to Val'sharah, and look for him in the Temple of Elune. Tell him of our plan, and that we need his help securing scales.",starts={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},ends={{npcID=151285,x=0.536,y=0.544,zoneID=7558}},coords={x=0.696,y=0.298,source="quest_giver",zoneID=8568},questType="standard"},
[55232] = {id=55232,name="Mevris' Menace",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="There is a hydra that has been something of a nuisance for us as of late. It lives out on the Gloaming Reef, almost directly due west of here. It's been attacking ships that pass by, making it difficult to get supplies to and from Bradensbrook. I sent a team to handle it, but they haven't returned. Go out there, kill it, and take its scales to Daniss. And when you see her, tell her that I said... Nothing.",starts={{npcID=151285,x=0.536,y=0.544,zoneID=7558}},ends={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},coords={x=0.536,y=0.544,source="quest_giver",zoneID=7558},questType="standard"},
[55233] = {id=55233,name="Picking Bones",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,description="When I was sailing in, I heard some of the sailors talking about the Horde presence here in Tiragarde Sound. Apparently they're scrounging around the remains of a massive creature that has washed ashore. Whatever it was, if the Horde wants it, we need to make sure they don't get it. Find the Horde, keep them from taking anything, and see if there are any bones from the creature we can use for our drums. Show them no mercy, .",starts={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},ends={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},coords={x=0.696,y=0.298,source="quest_giver",zoneID=8568},questType="standard"},
[55234] = {id=55234,name="Make Some Noise",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,description="We have everything we need to craft the drum, except Elune's blessing. The drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink. With Tyrande donning the mantle of the Night Warrior, much of Elune's power is taxed. Asking for another favor is not insignificant, but I must try. While I'm doing that, I need you to craft the drum. Try to keep it small. The larger the vessel, the more power it can hold, but the harder it becomes to move.",starts={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},ends={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},coords={x=0.696,y=0.298,source="quest_giver",zoneID=8568},questType="standard"},
[55235] = {id=55235,name="Instruments of Destruction",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8500,description="There is one last thing we need to do. These drums, while powerful, are practically useless here in town. If you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Zandalar, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines. Look for someplace centralized in each territory to place drums. Once you return, I'll show you how to make the mallet needed to utilize the drums.",starts={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},ends={{npcID=151173,x=0.696,y=0.298,zoneID=8568}},coords={x=0.696,y=0.298,source="quest_giver",zoneID=8568},questType="standard"},
[55242] = {id=55242,name="A Goblin in Need",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=7503,mapID=650,questType="standard"},
[55243] = {id=55243,name="A Daughter of Torcali",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors. In this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time. Best find her before she gets hurt.",starts={{npcID=151319,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=152258,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55244] = {id=55244,name="Away From the Herd",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns. Perhaps she could use a distraction.>",starts={{npcID=152258,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=152258,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55245] = {id=55245,name="Eat Like a Direhorn",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>",starts={{npcID=152258,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=152258,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55246] = {id=55246,name="Even Greener Pastures",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Ever since Torcali gave her boon to de little one, she has been growing like a weed. Dat makes her very hungry. She got out again to look for more things to eat. Before you ask, it is not my role to stop her from doing what she wants. Only to ensure she is safe. She is probably fine. Bring her home, and if you have trouble bringing her home, you might try a bribe.",starts={{npcID=151319,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=152258,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55247] = {id=55247,name="The Trust You've Earned",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="I believe my loa will agree with me when I say that you have proven yourself worthy of this one's companionship. She is large enough now that she can bear you wherever it is that you wish to go. I had de Beastlord craft a saddle for you. Go and get it and I will help you put it on your new steed's back. Congratulations, .",starts={{npcID=151319,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=154673,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55248] = {id=55248,name="Greener Pastures",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="You have done an adequate job keeping de little one fed, but sometimes they just want something else. I did not see where de hatchling went, but you should start where de grass is real green. You will likely find her eating it. If you have trouble bringing her home, you might try a bribe.",starts={{npcID=151319,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55249] = {id=55249,name="Away From the Herd",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns. Perhaps she could use a distraction.>",starts={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55250] = {id=55250,name="A Growing Appetite",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>",starts={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55251] = {id=55251,name="A Daughter of Torcali",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors. In this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time. Best find her before she gets hurt.",starts={{npcID=151319,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55252] = {id=55252,name="A Loa Without a Temple",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="I have given some thought about your situation, . It is not your fault dat de goblin deceived us. I followed along with his scheme as well. From today, you have my forgiveness. But dat cannot help de little one. I fear we may lose it, if we do not act. We must ask de wanderer's loa, de mountain dat moves, de great bulwark, de greatmother of direhorns, to save her child. Take dis offering to her shrine and ask for her boon... and her forgiveness.",starts={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},ends={{npcID=151257,x=0.684,y=0.294,zoneID=8499}},coords={x=0.668,y=0.424,source="quest_giver",zoneID=8499},questType="standard"},
[55253] = {id=55253,name="A Show of Faith",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Torcali 's voice enters your mind.> I have watched your efforts from afar, small thing. You have made mistakes, and one of my young has suffered for it. I do not forget, but I can forgive. As my people place faith in me, I place my faith in you. Take my blessing to my child and she will wake.",starts={{npcID=151257,x=0.684,y=0.294,zoneID=8499}},ends={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},coords={x=0.684,y=0.294,source="quest_giver",zoneID=8499},questType="standard"},
[55254] = {id=55254,name="An Unending Sleep",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="direhorn hatchling continues to sleep soundly, despite any efforts on your part to wake it. It's probably been too long. You should speak to Beastlord L'kala .>",starts={{npcID=151283,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=121706,x=0.668,y=0.424,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55258] = {id=55258,name="Sleep, Eat, Repeat",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,description="Child of Torcali pushes the sack of herbs around with her snout. She then looks to you and stomps eagerly in place.>",starts={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},ends={{npcID=151286,x=0.682,y=0.418,zoneID=8499}},coords={x=0.682,y=0.418,source="quest_giver",zoneID=8499},questType="standard"},
[55298] = {id=55298,name="Fishing For Something Bigger",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="There's a huge fish lurking these waters, and it's been causing lots of problems! It eats other fish, fishermen, and a lot of expensive gear. I saw it swallow a beautiful Zigby 300 Fishing Rod along with its owner just the other day! I've got a plan, but I've lost a lot of my equipment in the waters around here. Can you help fish up some of these items for me?",starts={{npcID=151462,x=0.37,y=0.472,zoneID=10290}},ends={{npcID=151462,x=0.37,y=0.472,zoneID=10290}},coords={x=0.37,y=0.472,source="quest_giver",zoneID=10290},questType="standard"},
[55299] = {id=55299,name="Bottom Feeding Stinkfish",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Danielle Anglers may be interested in this fish.>",ends={{npcID=151462,x=0.37,y=0.472,zoneID=10290}},questType="standard"},
