[55319] = {id=55319,name="Tonk the Terrible",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=10290,mapID=1462,questType="standard"},
[55339] = {id=55339,name="Tidying Up",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Ionized Minnows are a scourge of these waters. They strip the ocean floors of any food, making it difficult for other species to survive. These fish have little to offer other than being a food source for larger fish. I want to see these larger fish, so I have a plan to clear the waters of these minnows and lure the bigger fish out from its hiding place. Let's start by using my Minnow Vac to catch Ionized Minnows for me.",starts={{npcID=151462,x=0.37,y=0.472,zoneID=10290}},ends={{npcID=151462,x=0.37,y=0.472,zoneID=10290}},coords={x=0.37,y=0.472,source="quest_giver",zoneID=10290},questType="standard"},
[55348] = {id=55348,name="Supplies from the Rustbolt Resistance",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=10290,description="The Resistance appreciates all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.",ends={{npcID=149816,x=0.74,y=0.368,zoneID=10290}},questType="standard"},
[55373] = {id=55373,name="Knock 'Em Out The Box",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=10290,description="Steelarm Pillagers have been taking all our parts and selling them to Bondo's gang. Last night they stole all our Spiderspring Gears . The parts are in a bunch of crates they're guarding. We need you to get our gears back, and show those Steelarm Pillagers they should pick on someone else.",starts={{npcID=150573,x=0.714,y=0.386,zoneID=10290}},ends={{npcID=150573,x=0.714,y=0.386,zoneID=10290}},coords={x=0.714,y=0.386,source="quest_giver",zoneID=10290},questType="standard"},
[55374] = {id=55374,name="A Disturbance Beneath the Earth",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=7503,description="Manifestation of dragon essence detected. Location: Highmountain. Assuming successful retrieval, calculations indicate 92.7 percent probability of empowering Heart of Azeroth. Theory: By combining dragon essence with sufficient quantities of Azerite within Heart Forge, previously undiscovered abilities may manifest within Heart. As Speaker Magni would say: \"Get to work, champion.\"",starts={{npcID=152194,x=0.482,y=0.71,zoneID=9667}},ends={{npcID=151641,x=0.494,y=0.682,zoneID=7503}},coords={x=0.482,y=0.71,source="quest_giver",zoneID=9667},questType="standard"},
[55378] = {id=55378,name="Rustbolt Requisitions: Shimmerscale",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=10290,starts={{npcID=149813,x=0.776,y=0.406,zoneID=10290}},ends={{npcID=149813,x=0.776,y=0.406,zoneID=10290}},coords={x=0.776,y=0.406,source="quest_giver",zoneID=10290},questType="standard"},
